INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '577d5a47-5591-59c9-b25e-8c735759a8b0','Noise regulation','Noise regulation is the body of legal and administrative rules that control unwanted or harmful sound from workplaces, venues, transport, construction, industry, and public events. It works through statutes, directives, municipal codes, permits, licence conditions, and enforceable exposure or emission limits, typically expressed with acoustic descriptors such as LAeq, Lmax, Lden, or Lnight. Regulation may target the source (equipment emission, sound-system output), the receiver (property-line or residential limits), or the exposed worker (occupational dose). What is permitted varies substantially by country, city, venue licence, permit, time of day, receiver location, and the prescribed measurement method, so no single figure is universal.','Noise regulation is the set of rules that control unwanted sound. Laws set who may make noise, how loud, and when. They cover job sites, venues, roads, building work, and events. Some rules protect workers, others protect neighbours. Limits change by country, city, licence, and time of day. How the sound is measured also matters a lot.','It exists to balance economic and cultural activity that makes sound against public health, worker safety, and the right of people to reasonable peace. It gives authorities a lawful basis to set limits, require assessment, issue permits, and act against excessive or hazardous sound.','A touring or compliance technician uses the applicable regulation to decide which descriptor and limit apply at a given site, to plan system levels and monitoring, and to keep records that show a show or worksite stayed within the controlling permit, occupational rule, or municipal code.','Sound Law — Legal & Regulatory Framework',ARRAY['Noise ordinance','Permissible noise level','Noise limit value','Environmental noise','Occupational noise exposure','Environmental Noise Directive (2002/49/EC)']::text[],ARRAY['Assuming one national or global decibel limit applies everywhere, when limits vary by jurisdiction, licence, receiver, and time of day.','Confusing rules that protect the public or neighbours with rules that protect workers'' hearing; they use different descriptors and thresholds.','UNSAFE: Treating compliance with a community or property-line noise rule as proof that workers or performers are protected from hearing damage, when occupational exposure limits are a separate and stricter regime.']::text[],ARRAY['A touring production advancing an international run checks each city''s regulation to see which limits and descriptors govern each venue.','A local authority officer relies on regulation to require noise assessment before granting an outdoor event permit.','A factory safety manager applies occupational noise regulation to schedule hearing tests and provide protectors.']::text[],'beginner',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise regulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '577d5a47-5591-59c9-b25e-8c735759a8b0','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='577d5a47-5591-59c9-b25e-8c735759a8b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='577d5a47-5591-59c9-b25e-8c735759a8b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9a4bec5a-45f9-5d27-93d9-201046451088','Noise ordinance','A noise ordinance is a local (municipal or county) law that sets enforceable limits on sound within a jurisdiction, commonly in the United States but paralleled by local by-laws elsewhere. It typically fixes maximum levels at the property line or a receiving residence, often varying by zoning (residential, commercial, industrial) and by daytime versus night-time periods, and may also prohibit specific sources such as amplified music, construction outside set hours, or plainly audible sound at a stated distance. Numeric limits, quiet hours, descriptors, and enforcement mechanisms differ from one municipality to another, so the exact figures and measurement method must be read from the specific ordinance.','A noise ordinance is a local law made by a town, city, or county. It sets how much sound is allowed near homes and property lines. Limits often change between day and night. Many ordinances ban loud music or building work at certain hours. The exact numbers and quiet hours differ from place to place. Police or council officers usually enforce them.','It gives a community a clear, locally tailored tool to protect residents from disturbance while allowing normal business and events. It sets predictable rules that people, venues, and enforcement officers can follow and apply on the ground.','An event producer reads the host city''s ordinance to learn the property-line limit, permitted hours, and any curfew, then sets sound-system levels and stage times so a show stays compliant and avoids fines or shutdown.','Sound Law — Legal & Regulatory Framework',ARRAY['Noise regulation','Permissible noise level','Community noise','Noise nuisance','Noise limit value','Curfew']::text[],ARRAY['Assuming ordinances are identical across nearby cities, when limits, quiet hours, and enforcement often differ block to block.','Believing a curfew or quiet-hours rule only concerns loudness, when many ordinances also forbid sound that is plainly audible at a set distance regardless of level.','Thinking a stage-position reading equals the regulated level, when ordinances are usually assessed at the property line or a neighbour''s home.']::text[],ARRAY['A club owner facing repeat complaints reviews the city ordinance to see the night-time property-line limit and adjusts the system.','A festival promoter applies for a permit that must satisfy the town''s amplified-sound ordinance and curfew.','A code-enforcement officer measures at a complainant''s boundary to check an ordinance breach.']::text[],'beginner',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise ordinance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9a4bec5a-45f9-5d27-93d9-201046451088','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9a4bec5a-45f9-5d27-93d9-201046451088') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9a4bec5a-45f9-5d27-93d9-201046451088');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '64ad4aa9-85d2-5c39-b696-b5efe29fd22b','Environmental noise','Environmental noise is unwanted or harmful outdoor sound affecting the general public, created by human activities including road, rail and air traffic, industrial sites, and outdoor entertainment. In EU law the Environmental Noise Directive (2002/49/EC) formalises the concept and requires member states to assess it using harmonised long-term indicators, chiefly Lden (a day-evening-night level with penalties added to evening and night hours) and Lnight, to produce strategic noise maps for major agglomerations, roads, railways and airports, and to draw up action plans. The directive generally excludes noise from the exposed person''s own activity, domestic noise, neighbour noise, workplace noise, and military-area noise; thresholds and mapping duties vary by member state.','Environmental noise is outdoor sound that reaches the wider public. It comes from roads, trains, planes, industry, and events. It is judged where people live, not at work. EU law tracks it with two ratings called Lden and Lnight. Lden is a day-evening-night level; Lnight is the night level. Governments must map it and make plans to reduce it.','The concept lets governments measure, compare, and manage large-scale community sound exposure in a consistent way. It underpins noise mapping, public information, and action plans aimed at protecting health and quiet areas.','A local authority acoustician uses the environmental-noise framework to build a strategic noise map, identify hotspots above a chosen threshold, and prioritise mitigation such as low-noise road surfaces or barriers in an action plan.','Sound Law — Legal & Regulatory Framework',ARRAY['Community noise','Noise pollution','Environmental Noise Directive (2002/49/EC)','Lden','Lnight','Strategic noise map']::text[],ARRAY['Confusing environmental noise with occupational noise; the Environmental Noise Directive expressly excludes workplace exposure, which OSHA or EU 2003/10/EC covers.','Assuming Lden and Lnight are single instantaneous readings, when they are long-term averaged indicators with time-of-day weighting.','Treating the EU indicators as global; many countries use different descriptors, thresholds, and mapping rules.']::text[],ARRAY['A city environmental team maps road and rail noise to meet Environmental Noise Directive duties and inform residents.','An airport operator models Lden and Lnight contours around the site for an action plan.','A planning authority checks predicted environmental noise before approving housing near a motorway.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Environmental noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '64ad4aa9-85d2-5c39-b696-b5efe29fd22b','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='64ad4aa9-85d2-5c39-b696-b5efe29fd22b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='64ad4aa9-85d2-5c39-b696-b5efe29fd22b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fa195e7b-0f5a-58ee-8a3d-4aef4a6b13af','Community noise','Community noise (also called residential or neighbourhood noise) is sound evaluated from the standpoint of nearby residents or other sensitive receivers rather than from the source or an audience position. It is the framing used to control disturbance from concerts, clubs, festivals, stadiums, industry, airports, and highways at the point where people are exposed in their homes and gardens. Assessment usually relies on descriptors such as LAeq over a defined period, background-comparison methods (for example, the approach in BS 4142 for industrial and commercial sound), and time-of-day weighting. Acceptable levels depend on the receiver''s location, area character, time, licence conditions, and the measurement method, so limits are not universal.','Community noise is sound judged from the point of view of nearby residents. It looks at how a concert, club, or factory affects neighbours. The listener''s home matters, not just the source. Time of day and the type of area both count. Some methods compare the noise with the normal background level. Limits change by place, time, and local rules.','It shifts assessment to where harm actually occurs, the exposed community, so rules protect sleep, rest, and enjoyment of the home. It provides a consistent basis for complaints handling, permits, and mitigation decisions.','A live-sound compliance officer places a monitoring microphone at the nearest affected residence or an agreed representative point, logs LAeq against the licence limit, and adjusts front-of-house or delay levels to keep the community level within condition.','Sound Law — Legal & Regulatory Framework',ARRAY['Environmental noise','Noise nuisance','Noise pollution','Property-line limit','LAeq','BS 4142']::text[],ARRAY['Judging compliance from a mixing-desk or on-stage reading rather than at the receiver''s location, which is where community limits apply.','Assuming a fixed decibel number always applies, when many methods compare the sound against local background and area character.','UNSAFE: Believing that meeting a community limit set to prevent annoyance also protects performers or crew from hearing damage; on-stage exposure is governed by separate occupational limits.']::text[],ARRAY['A festival acoustician monitors at the closest homes to keep the show within a community-noise licence condition.','A council officer investigates a nightclub complaint by measuring at the resident''s window.','A stadium operator models community levels before scheduling amplified events near housing.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Community noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fa195e7b-0f5a-58ee-8a3d-4aef4a6b13af','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fa195e7b-0f5a-58ee-8a3d-4aef4a6b13af') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fa195e7b-0f5a-58ee-8a3d-4aef4a6b13af');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39715959-8c1c-5c29-b580-6fa023ea38fb','Noise pollution','Noise pollution is the broad public-health framing of harmful or excessive sound in the human environment, treated as an environmental pollutant alongside air and water pollution. It captures the cumulative burden of transport, industrial, entertainment, and neighbourhood sound on populations, associated in the literature with sleep disturbance, annoyance, cardiovascular effects, cognitive impairment, and hearing damage from high exposure. The term is descriptive and policy-oriented rather than a single enforceable limit; specific control comes through instruments such as the EU Environmental Noise Directive, WHO guidance, national occupational rules, and local ordinances, whose thresholds and methods vary by jurisdiction.','Noise pollution means harmful or excess sound in daily life. Health bodies treat it like dirty air, as a pollutant. It can disturb sleep, raise stress, and harm the heart. Very loud exposure can also damage hearing. It is a broad idea, not one fixed legal limit. Different laws and places set the actual controls.','The concept exists to frame sound as a health and environmental hazard, justifying assessment, guidance, and regulation. It links scattered rules to a shared public-health goal and supports the case for limits and mitigation.','A policy analyst or public-health officer uses noise-pollution evidence to justify a noise-mapping programme, a night-time curfew, or investment in barriers and low-noise surfaces, citing exposure-response data rather than a single legal number.','Sound Law — Legal & Regulatory Framework',ARRAY['Environmental noise','Community noise','Noise nuisance','Guideline value','Environmental Noise Directive (2002/49/EC)','WHO Environmental Noise Guidelines']::text[],ARRAY['Treating noise pollution as one legally binding limit, when it is a broad public-health concept enforced through many separate instruments.','Assuming only very loud sound counts; moderate, persistent night-time noise is strongly linked to sleep and health harm.','UNSAFE: Dismissing lower-level chronic noise as harmless because it does not feel painful, when health guidance links long-term exposure to real cardiovascular and sleep effects.']::text[],ARRAY['A city health department cites noise-pollution research to support a new night-noise policy.','An environmental NGO campaigns on traffic noise pollution near schools.','A transport agency evaluates noise pollution impacts in an environmental assessment for a new road.']::text[],'beginner',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise pollution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39715959-8c1c-5c29-b580-6fa023ea38fb','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39715959-8c1c-5c29-b580-6fa023ea38fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39715959-8c1c-5c29-b580-6fa023ea38fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '66a860c4-c895-5233-b302-b69745c039d3','Noise nuisance','Noise nuisance is a legal and planning concept for sound that unreasonably disturbs others, where the wrong is the unreasonable interference itself rather than exceedance of a single decibel figure. Assessment is qualitative and contextual, weighing the level, character (tonal, impulsive, bass-heavy), duration, frequency of occurrence, time of day, and the character of the locality. Because it turns on reasonableness, a sound can be a nuisance even when below a numeric limit, or acceptable above one, depending on circumstances. It underpins both statutory schemes (for example UK Environmental Protection Act 1990 statutory nuisance) and common-law actions; the precise test and remedies vary by jurisdiction.','A noise nuisance is sound that unfairly disturbs other people. The test is about being reasonable, not just a decibel number. Time of day, how long it lasts, and the area all count. Bass, tones, or bangs can make a sound worse. A noise can be a nuisance even below a set limit. Councils and courts weigh the whole picture.','It lets the law address disturbance that fixed limits miss, capturing character, timing, and persistence. This gives residents and authorities a flexible route to stop genuinely intrusive noise even when a meter reading alone looks acceptable.','A council environmental-health officer builds a nuisance case using complaint diaries, witnessed observations, and sometimes measurements, judging whether the disturbance is unreasonable before deciding on informal action or a formal notice.','Sound Law — Legal & Regulatory Framework',ARRAY['Statutory nuisance','Private nuisance','Public nuisance','Community noise','Noise regulation','Abatement notice']::text[],ARRAY['Believing that staying under a decibel limit is a complete defence, when nuisance also depends on character, timing, and locality.','Assuming a nuisance needs a meter reading, when diaries and witnessed disturbance can establish it.','Thinking a single loud event is required, when persistent moderate noise is often the stronger nuisance case.']::text[],ARRAY['A resident logs a noise diary of late-night bar music to support a nuisance complaint.','An environmental-health officer assesses whether a workshop''s daytime noise is a legal nuisance.','A promoter negotiates set times after neighbours raise a nuisance concern about bass carrying at night.']::text[],'beginner',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise nuisance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '66a860c4-c895-5233-b302-b69745c039d3','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='66a860c4-c895-5233-b302-b69745c039d3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='66a860c4-c895-5233-b302-b69745c039d3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b0eecab4-b681-5437-a77a-250e392e937f','Statutory nuisance','Statutory nuisance is a defined legal category, notably under Part III of the UK Environmental Protection Act 1990, under which noise emitted from premises, or from vehicles, machinery or equipment in a street, can be legally actionable. A matter qualifies where it is prejudicial to health or amounts to a nuisance. A local authority that is satisfied a statutory nuisance exists or is likely to recur must serve an abatement notice under section 80; failing to comply with the notice, without reasonable excuse, is a criminal offence carrying a fine, and a defence of best practicable means may apply to some sources. Other jurisdictions operate analogous but distinct statutory schemes with their own tests and penalties.','Statutory nuisance is a legal class of noise under UK law. It applies when sound harms health or badly disturbs a home. A council must serve an abatement notice to stop it. The notice can ban the noise or limit its hours. Ignoring the notice is an offence and can bring a fine. Other countries have their own similar laws.','It gives local authorities a fast, enforceable statutory route to stop harmful or seriously disturbing noise without a full private lawsuit. It sets a clear duty to act and a criminal backstop for non-compliance.','An environmental-health officer, once satisfied a statutory nuisance exists, serves an abatement notice specifying what must stop or be limited; a venue operator then complies by cutting levels, reducing bass, or restricting hours to avoid prosecution.','Sound Law — Legal & Regulatory Framework',ARRAY['Noise nuisance','Private nuisance','Public nuisance','Abatement notice','Best practicable means','Noise regulation']::text[],ARRAY['Assuming a fixed decibel breach is required, when statutory nuisance turns on being prejudicial to health or a nuisance in context.','Believing an abatement notice can simply be ignored, when non-compliance without reasonable excuse is a criminal offence.','Treating UK statutory nuisance as universal, when other countries use different statutory schemes, tests, and penalties.']::text[],ARRAY['A council serves an abatement notice on a bar after sustained late-night music complaints.','A landlord receives a notice over tenants'' amplified noise and must act to abate it.','An enforcement officer weighs a best-practicable-means defence raised by an industrial premises.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Statutory nuisance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b0eecab4-b681-5437-a77a-250e392e937f','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b0eecab4-b681-5437-a77a-250e392e937f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b0eecab4-b681-5437-a77a-250e392e937f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f5c3d261-877e-5d47-a48c-ac378445f579','Public nuisance','Public nuisance is a legal concept covering conduct, including noise, that endangers or materially affects the reasonable comfort and convenience of a class of the public or a community, rather than only a single occupier. Historically a common-law offence and tort, in England and Wales it was placed on a statutory footing as a criminal offence by section 78 of the Police, Crime, Sentencing and Courts Act 2022, while remaining a distinct doctrine in other common-law jurisdictions. It is distinguished from private nuisance, which protects an individual''s use and enjoyment of land; the exact definition, remedies, and whether it is criminal or civil vary by jurisdiction.','Public nuisance is harm that affects a whole community, not one person. Loud noise over a public space or a wide area can count. In England and Wales it is now a statutory crime. Older cases treated it as a common-law wrong. It differs from private nuisance, which protects one home. The rules and remedies vary between countries.','It lets the law address harm spread across many people, where no single victim may sue effectively in private nuisance. It supports public authorities acting on behalf of a community against widespread disturbance.','A prosecutor or local authority may rely on public-nuisance powers where amplified sound or a disruptive event affects a broad section of the public, using it alongside statutory-nuisance and licensing tools to require abatement.','Sound Law — Legal & Regulatory Framework',ARRAY['Private nuisance','Statutory nuisance','Noise nuisance','Noise regulation','Abatement notice','Licensing conditions']::text[],ARRAY['Confusing public nuisance with private nuisance; public nuisance affects a class of people, not just one landholder.','Assuming it is always a civil claim, when in England and Wales it is now a statutory criminal offence.','Treating one jurisdiction''s rule as global, when the definition and remedies differ across common-law systems.']::text[],ARRAY['Authorities consider public-nuisance powers over an unlicensed rave affecting many residents.','A prosecutor assesses whether sustained street amplification harmed a section of the public.','A council combines public-nuisance and licensing action against a persistently disruptive venue.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Public nuisance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f5c3d261-877e-5d47-a48c-ac378445f579','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f5c3d261-877e-5d47-a48c-ac378445f579') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f5c3d261-877e-5d47-a48c-ac378445f579');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '32bf7e66-3adf-5176-b28f-d1283e15bfa4','Private nuisance','Private nuisance is a tort in common-law systems that protects an occupier''s use and enjoyment of land against unreasonable interference, including interference by noise. Liability turns on the reasonableness of the interference, judged by factors such as the level and character of the sound, its duration and frequency, the time of day, and the character of the locality, rather than by a fixed decibel threshold. Remedies typically include an injunction to restrain the noise and damages for past interference. It is distinct from public nuisance (which affects a community) and from statutory nuisance regimes; the precise test and available remedies vary by jurisdiction.','Private nuisance is noise that spoils one owner''s use of their land. It protects the quiet use and enjoyment of a home. The court asks if the interference was unreasonable. Level, timing, how long it lasts, and the area all count. A neighbour can seek an injunction or damages. The exact test depends on the country and case.','It gives an individual occupier a direct civil remedy to stop or be compensated for unreasonable noise crossing onto their land. It fills gaps that fixed public limits leave for one-to-one disputes between neighbours.','A property owner troubled by a neighbouring venue may bring a private-nuisance claim seeking an injunction limiting hours or levels; the venue then documents its noise management to argue the interference is reasonable.','Sound Law — Legal & Regulatory Framework',ARRAY['Public nuisance','Statutory nuisance','Noise nuisance','Injunction','Community noise','Noise regulation']::text[],ARRAY['Assuming a claim needs a numeric limit breach, when private nuisance turns on unreasonable interference in context.','Confusing it with public nuisance; private nuisance protects one occupier''s land, not the wider public.','Believing planning permission or a licence automatically defeats a private-nuisance claim, when it usually does not by itself.']::text[],ARRAY['A homeowner sues a nearby club for an injunction over persistent late-night bass.','A tenant seeks damages for a neighbour''s ongoing amplified noise.','A venue''s lawyer prepares a noise-management record to rebut a private-nuisance claim.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Private nuisance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '32bf7e66-3adf-5176-b28f-d1283e15bfa4','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='32bf7e66-3adf-5176-b28f-d1283e15bfa4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='32bf7e66-3adf-5176-b28f-d1283e15bfa4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ff9bf050-33c8-588e-8de1-add932c776cf','Permissible noise level','A permissible noise level is the maximum sound level allowed for a given situation under a regulation, permit, standard, or licence condition. It may be an occupational exposure limit protecting workers'' hearing, or a community/emission limit protecting neighbours, and the two serve different purposes and use different descriptors. For example, under US OSHA 29 CFR 1910.95 the permissible exposure limit is 90 dB(A) as an 8-hour time-weighted average using a 5 dB exchange rate, with an 85 dB(A) action level triggering a hearing conservation programme; community permissible levels are typically lower and set by local ordinance or licence. The controlling figure, averaging time, and measurement method vary by jurisdiction and context, so a number must always be attributed to its source.','A permissible noise level is the most sound a rule allows. It can come from a law, permit, standard, or licence. Some limits protect workers'' hearing; others protect neighbours. For example, US OSHA allows 90 dB(A) over an eight-hour work shift. Community limits protect against disturbance and are often lower. Always check which rule and place a number comes from.','It converts a policy goal into a concrete, checkable threshold that operators and inspectors can act on. It defines the line between compliant and non-compliant operation for hearing protection or neighbour protection.','A safety officer compares measured worker exposure against the applicable permissible exposure limit to decide on hearing protection and monitoring; a compliance tech compares measured community levels against the licensed permissible level to set system output.','Sound Law — Legal & Regulatory Framework',ARRAY['Noise limit value','Occupational exposure limit','Action level','Exchange rate','LAeq','Noise ordinance']::text[],ARRAY['Quoting a permissible level without naming its source, so an occupational figure gets misapplied to community limits or vice versa.','Ignoring exchange rate and averaging time, which change how a level over time is judged against the limit.','UNSAFE: Assuming that staying just under an occupational permissible exposure limit guarantees no hearing risk, when limits carry residual risk, individuals differ, and impulsive or peak sound needs separate control.']::text[],ARRAY['A factory safety manager checks worker exposure against the OSHA permissible exposure limit.','A concert compliance officer sets levels to the venue licence''s permissible community level.','A regulator investigates whether a worksite exceeded its jurisdiction''s permissible occupational level.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Permissible noise level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ff9bf050-33c8-588e-8de1-add932c776cf','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ff9bf050-33c8-588e-8de1-add932c776cf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ff9bf050-33c8-588e-8de1-add932c776cf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8f362951-b97f-5e0a-b8f7-0bb9d1a0e7e7','Noise limit value','A noise limit value is a formal, enforceable threshold expressed in decibels, usually tied to a specified acoustic descriptor and averaging period such as LAeq, Lmax, L10, L90, Lden, or Lnight. It appears in occupational rules, environmental regulations, permits, and licences, and functions as the value that must not be exceeded (sometimes with defined tolerances or measurement uncertainty). For example, under EU Directive 2003/10/EC the daily occupational exposure limit value is 87 dB(A) LEX,8h (taking into account hearing-protector attenuation), with upper and lower exposure action values of 85 and 80 dB(A); environmental and community limit values use different descriptors and are set nationally or locally. The applicable descriptor, figure, and method vary by jurisdiction and instrument.','A noise limit value is a formal cap written in decibels. It is tied to a rating such as LAeq or Lden. It is the level that must not be passed. For example, EU job rules set an 87 dB(A) daily limit. Community limits use other ratings and lower numbers. The right value depends on the law, the place, and the method.','It provides an objective pass/fail criterion so operators, regulators, and courts can judge compliance consistently. Tying the number to a named descriptor and period removes ambiguity about how the sound is measured.','An acoustic consultant selects the correct descriptor and limit value for a project, then designs mitigation or sets operating conditions so predicted or measured levels stay at or below that value, and documents the assessment method.','Sound Law — Legal & Regulatory Framework',ARRAY['Permissible noise level','Target value','Guideline value','Lden','LAeq','Exposure action value']::text[],ARRAY['Comparing a measurement to a limit value using the wrong descriptor or averaging time, which invalidates the comparison.','Quoting a single figure as universal instead of attributing it to the standard or jurisdiction it comes from.','UNSAFE: Assuming an 87 dB(A) occupational limit value at the ear is safe without hearing protection, when that EU limit value already assumes protector attenuation is applied.']::text[],ARRAY['A consultant checks predicted plant noise against a permit''s LAeq limit value.','A safety officer verifies worker exposure against the EU 2003/10/EC exposure limit value.','A licensing authority sets a night-time Lnight limit value as a condition for a venue.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise limit value');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8f362951-b97f-5e0a-b8f7-0bb9d1a0e7e7','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8f362951-b97f-5e0a-b8f7-0bb9d1a0e7e7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8f362951-b97f-5e0a-b8f7-0bb9d1a0e7e7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e60b1528-2674-5b8b-98bc-f46baf4d6dae','Target value','A target value is a recommended or planning objective for noise, expressed as a level to aim for rather than an absolute, immediately enforceable limit. It is common in land-use planning, environmental policy, and standards guidance, where it steers design of new roads, railways, housing, or venues toward desirable outcomes. Because it is aspirational, failing to meet a target value is not automatically unlawful in the way that exceeding a hard limit value is, though it may trigger further assessment, mitigation, or conditions. Whether a figure is treated as a target or a binding limit, and its numeric value, depends on the specific policy, standard, and jurisdiction.','A target value is a goal to aim for, not a hard cap. Planners use it to guide design and land use. Missing it is not automatically illegal. That is different from breaking a firm limit. It helps set direction for new roads or housing. Its status and number depend on local policy.','It gives policy and design a direction of travel toward better acoustic outcomes without the rigidity of a strict limit. This supports good planning while leaving room for judgement where a target cannot be fully met.','A planning acoustician designs a scheme to meet a target value where feasible, and where it cannot be met, records the shortfall and proposes mitigation or conditions, showing decision-makers the trade-offs.','Sound Law — Legal & Regulatory Framework',ARRAY['Guideline value','Noise limit value','Permissible noise level','Environmental noise','Community noise','Action plan']::text[],ARRAY['Treating a target value as an enforceable limit, when missing it is usually not automatically unlawful.','Assuming a target and a limit are interchangeable, when they carry different legal weight and consequences.','Reading one policy''s target as universal, when values and their status differ by jurisdiction and document.']::text[],ARRAY['A planner designs a housing layout to meet an internal-noise target value near a railway.','A council sets a target value guiding new-development acoustic design.','A consultant records why a scheme narrowly misses a target and what mitigation follows.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Target value');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e60b1528-2674-5b8b-98bc-f46baf4d6dae','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e60b1528-2674-5b8b-98bc-f46baf4d6dae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e60b1528-2674-5b8b-98bc-f46baf4d6dae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ae1dbc9c-9c08-5d4e-b96e-164250f25f8f','Guideline value','A guideline value is a health- or policy-based recommended level, typically issued by an expert or health body, that governments may adopt, adapt, or use to inform their own binding rules. It is advisory rather than automatically enforceable. For example, the WHO Night Noise Guidelines for Europe (2009) recommend an Lnight,outside of 40 dB to protect health, with a 55 dB interim target, and the WHO Environmental Noise Guidelines for the European Region (2018) give exposure-response-based recommended levels by source (for road traffic, for example, 53 dB Lden and 45 dB Lnight). Guideline values are not laws in themselves; their adoption, exact figures, and legal status vary by country and instrument.','A guideline value is a health-based level that experts recommend. Governments may adopt it, adapt it, or set their own. It is advice, not a binding law by itself. For example, WHO advises night noise near 40 dB outside. WHO also gives recommended levels for road and rail. Countries turn this advice into rules in their own way.','It distils health evidence into clear reference levels that policymakers can use when writing binding rules. This helps align national and local limits with the best available understanding of health effects.','A regulator drafting or reviewing noise policy compares proposed limits against WHO guideline values to justify thresholds, while a consultant may benchmark predicted exposure against guideline values to flag health-relevant hotspots.','Sound Law — Legal & Regulatory Framework',ARRAY['Target value','Noise limit value','Environmental noise','Noise pollution','Lnight','Lden']::text[],ARRAY['Treating a WHO guideline value as a legally binding limit, when it is advisory until a government enacts it.','Quoting a guideline number without its source and averaging basis, which changes what it means.','UNSAFE: Assuming that meeting a night-noise guideline value guarantees no sleep or health effect for everyone, when guidelines reflect population risk and sensitive individuals may still be affected.']::text[],ARRAY['A health ministry cites WHO guideline values when setting new night-noise policy.','A consultant benchmarks predicted road-traffic levels against WHO guideline values.','An NGO compares a city''s limits with WHO guideline values to argue for stricter rules.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Guideline value');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ae1dbc9c-9c08-5d4e-b96e-164250f25f8f','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ae1dbc9c-9c08-5d4e-b96e-164250f25f8f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ae1dbc9c-9c08-5d4e-b96e-164250f25f8f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2873ca86-5b26-5a4d-916b-d596494288e7','Action level','An action level is an exposure threshold defined in occupational noise law that, once reached or exceeded, obligates an employer to begin specified protective measures such as noise assessment, worker information and training, provision of hearing protection, health surveillance, or enrollment in a hearing conservation program. It is normally expressed as a daily A-weighted noise exposure (a time-weighted average). The figure and the duties it triggers vary by jurisdiction: for example, under US OSHA (29 CFR 1910.95) the action level is 85 dBA as an 8-hour time-weighted average, while under EU Directive 2003/10/EC the lower exposure action value is 80 dB(A) and the upper exposure action value is 85 dB(A), each with an associated C-weighted peak. Exact thresholds, averaging method, and required responses differ by country, standard, and measurement protocol.','An action level is a noise dose that forces the employer to act. When workplace noise reaches it, the law requires safety steps. These steps can include testing noise, training staff, and offering ear protection. The exact number changes by country and rule. For example, US OSHA sets its action level at 85 dBA over 8 hours. Europe uses two triggers, at 80 and 85 dB(A). Always check the local law and how noise is measured.','It exists to convert a continuous hazard into a clear legal trigger, so protection is not left to discretion. By fixing a measurable threshold, it tells employers exactly when specific duties become mandatory, creating an escalating tier of controls as exposure rises and making compliance auditable by regulators.','A safety officer measures worker exposure with a dosimeter or sound level meter, computes the 8-hour time-weighted average, and compares it against the applicable action level; crossing it obligates them to enroll affected workers, document the assessment, and issue and fit hearing protection under the relevant standard.','Sound Law — Legal & Regulatory Framework',ARRAY['Exposure limit value','Hearing conservation program','Permissible exposure limit (PEL)','Time-weighted average (TWA)','Exchange rate','Audiometric testing']::text[],ARRAY['UNSAFE: Assuming that staying below the action level means noise is harmless — action levels are administrative triggers, not guarantees of safety, and hearing damage can still occur below them over a long career.','UNSAFE: Treating the action level as the maximum allowed exposure; it is only where duties begin, and separate limit values (e.g., OSHA''s 90 dBA permissible exposure limit) sit above it.','Believing a single global action level exists — the figure and its duties differ across OSHA, the EU, and national schemes.','Confusing the action level with a peak or instantaneous reading, when it is normally a time-weighted daily average.']::text[],ARRAY['A touring monitor engineer''s daily dosimetry reads 86 dBA at a European venue, crossing the upper action value, so the production must provide hearing protection and information under 2003/10/EC.','A US factory''s industrial hygienist finds several press operators at 85 dBA time-weighted average and enrolls them in a hearing conservation program per OSHA 1910.95.','A compliance auditor reviews exposure records to confirm that workers above the action level received training and audiometric testing.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Action level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2873ca86-5b26-5a4d-916b-d596494288e7','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2873ca86-5b26-5a4d-916b-d596494288e7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2873ca86-5b26-5a4d-916b-d596494288e7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3eb43f4a-ac1c-5a8f-bf6a-40a5ca1e85b7','Exposure limit value','An exposure limit value (ELV) is the maximum permitted level of occupational noise exposure that must not be exceeded, distinguished from action values by the fact that it may be assessed taking into account the attenuation of hearing protectors actually worn. Under EU Directive 2003/10/EC (and the UK Control of Noise at Work Regulations 2005), the ELV is a daily exposure of 87 dB(A) with a C-weighted peak of 200 Pa (140 dB(C)); the corresponding exposure action values (80 and 85 dB(A)) are assessed at the ear without regard to protection. If an ELV is exceeded, the employer must immediately reduce exposure below it and identify why it happened. Exact values, whether protector attenuation is counted, and enforcement differ by jurisdiction and measurement method.','An exposure limit value is the top noise dose the law allows. A worker''s exposure must not go above it. Under EU and UK rules, this limit is 87 dB(A) over 8 hours. That limit may count the ear protection a worker wears. Action values, set lower, do not count that protection. If the limit is passed, the employer must cut noise at once. The exact numbers and methods change by country.','It sets an absolute ceiling on harmful exposure so that, even with hearing protection factored in, a worker''s effective dose cannot lawfully exceed a level tied to unacceptable hearing-damage risk. It anchors the top of the tiered control system and forces immediate corrective action when breached.','An occupational hygienist calculates a worker''s protected exposure (measured level minus realistic protector attenuation) and checks it against the 87 dB(A) ELV; if exceeded, they must lower exposure, investigate the cause, and revise controls, recording the finding for the regulator such as the UK HSE.','Sound Law — Legal & Regulatory Framework',ARRAY['Action level','Permissible exposure limit (PEL)','Recommended Exposure Limit (REL)','Hearing protector attenuation','LEX,8h','Peak sound pressure level']::text[],ARRAY['UNSAFE: Assuming the 87 dB(A) ELV is a safe target to sit at — it is a legal maximum, not a comfort or safety goal, and prolonged exposure near it still risks hearing loss.','UNSAFE: Applying assumed real-world protector attenuation as if it equals the laboratory rating; over-crediting protectors can leave the true exposure above the limit.','Confusing the ELV with the action values — only the ELV may account for hearing protection under the EU/UK scheme.','Assuming every country uses 87 dB(A); the concept and figure vary, and some systems such as OSHA frame limits differently.']::text[],ARRAY['A festival''s stage crew records 90 dBA; the safety lead confirms that with fitted earplugs the protected exposure stays under the 87 dB(A) ELV of 2003/10/EC.','A UK foundry breaches the ELV despite protectors, so the employer must immediately reduce exposure and report the cause under the 2005 Regulations.','A cross-border touring tech compares EU ELV duties with US OSHA limits to plan hearing protection for a mixed itinerary.']::text[],'advanced',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Exposure limit value');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3eb43f4a-ac1c-5a8f-bf6a-40a5ca1e85b7','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3eb43f4a-ac1c-5a8f-bf6a-40a5ca1e85b7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3eb43f4a-ac1c-5a8f-bf6a-40a5ca1e85b7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f7044d48-84a7-5a3c-a156-be6bf51ecd7f','Recommended Exposure Limit (REL)','A Recommended Exposure Limit is a non-regulatory, advisory exposure ceiling published by NIOSH (the US National Institute for Occupational Safety and Health) to protect nearly all workers over a working lifetime. For occupational noise, NIOSH recommends a REL of 85 dBA as an 8-hour time-weighted average, combined with a 3-dB exchange rate (halving the allowed time for each 3-dB increase). Unlike OSHA''s enforceable permissible exposure limit, the REL carries no direct legal force; it is a health-based recommendation that is often stricter than the enforceable limit. Employers may adopt it voluntarily or where best practice or contracts require it.','A Recommended Exposure Limit is advice from NIOSH, a US health agency. It says how much noise a worker should get at most. For noise, NIOSH advises 85 dBA over 8 hours. It uses a 3-dB rule for shorter or longer shifts. The REL is not a law by itself. It is often stricter than the legal limit. Employers can choose to follow it as good practice.','It provides a health-based benchmark grounded in hearing-loss risk research, giving employers, standards writers, and physicians a protective target that is independent of, and often more conservative than, legally enforceable limits, and that can drive voluntary best practice.','An industrial hygienist benchmarking a plant''s hearing conservation efforts compares measured 8-hour time-weighted averages to the 85 dBA NIOSH REL, using a 3-dB exchange rate, rather than only OSHA''s 90 dBA permissible exposure limit, and tightens controls where the stricter recommendation is not met.','Sound Law — Legal & Regulatory Framework',ARRAY['Permissible exposure limit (PEL)','Action level','Exposure limit value','Exchange rate','Time-weighted average (TWA)','Hearing conservation program']::text[],ARRAY['UNSAFE: Treating a pass against OSHA''s enforceable limit as equivalent to being safe, when NIOSH''s stricter 85 dBA REL and 3-dB exchange rate imply meaningful risk remains at higher exposures.','Assuming the REL is legally enforceable — it is advisory guidance, not a regulation, though it can inform standards and contracts.','Mixing up NIOSH''s 3-dB exchange rate with OSHA''s 5-dB rate, which changes calculated exposures.','Confusing the REL (a recommendation) with a permissible exposure limit (an enforceable limit).']::text[],ARRAY['A US safety manager adopts the 85 dBA NIOSH REL as an internal target, stricter than OSHA''s enforceable limit, to reduce future hearing-loss claims.','An acoustics researcher cites the NIOSH REL and 3-dB exchange rate when evaluating a musician''s cumulative exposure.','A tour production writing a hearing-safety policy references the REL as the health-based goal for crew exposure.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Recommended Exposure Limit (REL)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f7044d48-84a7-5a3c-a156-be6bf51ecd7f','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f7044d48-84a7-5a3c-a156-be6bf51ecd7f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f7044d48-84a7-5a3c-a156-be6bf51ecd7f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '72a89c30-c496-58db-acf9-4064b3b7aaa4','Hearing conservation program','A hearing conservation program is a structured, legally mandated set of employer measures to prevent occupational noise-induced hearing loss, triggered when worker noise exposure reaches a defined threshold. Under US OSHA 1910.95 it becomes mandatory at or above an 85 dBA 8-hour time-weighted average and must include exposure monitoring, audiometric testing (baseline and annual), provision and fitting of hearing protectors, worker training, and recordkeeping. Analogous programs exist under other regimes, for example the health-surveillance duties of EU Directive 2003/10/EC and AS/NZS 1269 in Australia and New Zealand. Exact triggering levels, required elements, and record-retention periods vary by jurisdiction and standard.','A hearing conservation program is a plan to stop work noise harming hearing. The law makes an employer run it when noise gets high. In the US, OSHA requires it at 85 dBA over 8 hours. The plan checks noise levels and tests workers'' hearing each year. It also gives out ear protection and trains staff. Records are kept to prove the steps were done. The exact rules change by country.','It exists to systematically detect and prevent hearing loss before it becomes disabling, combining early detection through audiometry, exposure reduction, protection, and education into an auditable cycle so risk is managed continuously rather than reactively.','When monitoring shows workers at or above the trigger, a safety manager formally enrolls them: scheduling baseline and annual audiograms, issuing suitable hearing protectors, delivering annual training, and maintaining exposure and test records that an inspector can review.','Sound Law — Legal & Regulatory Framework',ARRAY['Action level','Audiometric testing','Standard threshold shift','Hearing protector attenuation','Permissible exposure limit (PEL)','Exposure limit value']::text[],ARRAY['UNSAFE: Believing that handing out earplugs alone satisfies the program — monitoring, audiometry, fitting, training, and records are all required, and skipping audiometry hides developing hearing loss.','UNSAFE: Assuming the program is optional above the trigger; enrollment is mandatory where the standard applies.','Thinking the program only applies to heavy industry, when live sound, hospitality, and entertainment workers can also exceed triggers.','Assuming one global standard defines the program, when OSHA, the EU, and AS/NZS differ in details.']::text[],ARRAY['A concert venue exceeding 85 dBA for bar and stage staff establishes a hearing conservation program with annual audiograms and fitted protectors.','A US manufacturer''s OSHA inspection checks that its 1910.95 program includes monitoring, audiometry, training, and records.','An Australian workshop builds a program aligned with AS/NZS 1269 after a noise assessment shows high exposures.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hearing conservation program');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '72a89c30-c496-58db-acf9-4064b3b7aaa4','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='72a89c30-c496-58db-acf9-4064b3b7aaa4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='72a89c30-c496-58db-acf9-4064b3b7aaa4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '71486c4b-980c-5c61-91f7-380bfd37ee59','Audiometric testing','Audiometric testing is the periodic measurement of a worker''s hearing thresholds, usually by pure-tone air-conduction audiometry across standard frequencies (such as 500 to 8000 Hz), to detect changes attributable to noise exposure within a hearing conservation program. Programs typically require a baseline audiogram followed by annual tests; results are compared to identify a standard threshold shift, which under OSHA 1910.95 is an average change of 10 dB or more at 2000, 3000, and 4000 Hz in either ear. It provides early warning of hearing loss and drives follow-up such as protector refitting, retraining, or medical referral. Required frequencies, shift definitions, and follow-up duties vary by jurisdiction and standard.','Audiometric testing measures how well a worker can hear. A trained tester plays tones at different pitches and volumes. The first test sets a baseline for that worker. Later tests each year are compared to it. A big drop in hearing is called a threshold shift. Under OSHA, that is a 10 dB average loss at key pitches. The result triggers follow-up, like new ear protection. The exact rules change by country.','It functions as the early-detection engine of a hearing conservation program: by tracking each worker''s hearing over time, it reveals damage while it is still mild and largely preventable, letting employers intervene before loss becomes permanent, and providing evidence for compliance and workers'' compensation.','An occupational health provider records a baseline audiogram for a newly exposed worker, repeats it annually, and flags any standard threshold shift; the safety officer then refits or upgrades hearing protection, retrains the worker, and documents the shift as the standard requires.','Sound Law — Legal & Regulatory Framework',ARRAY['Hearing conservation program','Standard threshold shift','Baseline audiogram','Action level','Hearing protector attenuation','Noise-induced hearing loss']::text[],ARRAY['UNSAFE: Treating a threshold shift as unimportant and taking no action, when it may be the first sign of preventable, progressing hearing loss.','UNSAFE: Testing without a proper quiet or rest period after noise, so a temporary shift masks or mimics a real one and misleads follow-up.','Assuming audiometry restores or protects hearing — it only detects change and must be paired with exposure control.','Believing a single test suffices, when trend comparison against a baseline is what reveals damage.']::text[],ARRAY['A festival production schedules annual audiograms for full-time crew and detects an early threshold shift in a monitor engineer.','A US plant''s provider confirms a standard threshold shift per OSHA 1910.95 and the employer refits protection and retrains the worker.','An Australian employer arranges audiometric testing for staff frequently required to wear hearing protection, following WHS guidance.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audiometric testing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '71486c4b-980c-5c61-91f7-380bfd37ee59','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='71486c4b-980c-5c61-91f7-380bfd37ee59') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='71486c4b-980c-5c61-91f7-380bfd37ee59');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '23a853ee-4638-5afb-8e76-d21e82f16f2c','Noise permit','A noise permit is an authorization issued by a public authority or licensing body that legally allows an activity expected to generate significant noise, such as an outdoor concert, festival, or construction project, under specified conditions. Conditions commonly fix permitted hours, maximum sound levels at defined receiver or boundary points, monitoring locations and methods, control measures, and complaint-handling requirements. It is the mechanism by which a normally restricted or nuisance-prone activity is permitted temporarily and controlled. The existence, form, thresholds, and issuing body vary widely by country, city, and local ordinance; for example, many US municipalities issue special-event or construction noise permits or variances.','A noise permit is official permission to make loud noise. A city or authority grants it for events or building work. The permit sets rules the holder must follow. These often include allowed hours and top sound levels. It may say where and how noise is measured. It can also require a plan for handling complaints. Permit rules differ by city and country. Breaking the conditions can end the permit.','It exists to balance an activity''s benefits against protection of neighbours and the environment: instead of a blanket ban, the authority grants controlled, time-limited permission with enforceable conditions, giving organizers legal certainty while giving regulators a lever to require mitigation and to withdraw consent if conditions are breached.','An event producer applies for a noise permit weeks ahead, submitting predicted levels, a site plan, and control measures; once granted, the production must operate within the permitted hours and limits, keep the permit on site, and provide monitoring records to the authority on request.','Sound Law — Legal & Regulatory Framework',ARRAY['Sound management plan','Noise impact assessment','Compliance monitoring','Abatement notice','Enforcement officer','Boundary noise limit']::text[],ARRAY['Assuming a permit lets you make any amount of noise, when it only allows noise within its stated limits, hours, and locations.','Thinking a permit overrides all complaints, when authorities can still act if conditions are breached or a nuisance arises.','Believing one permit covers every jurisdiction, when requirements and thresholds vary by city and country.','Confusing the permit itself with the underlying noise limits, which are set by ordinance or licence conditions.']::text[],ARRAY['A festival promoter applies to the local council for an outdoor event noise permit, agreeing to a boundary limit and a curfew.','A construction manager obtains a permit allowing extended working hours only within stated daytime noise limits.','An enforcement officer inspects an event and checks the permit''s conditions against measured levels at the boundary.']::text[],'beginner',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise permit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '23a853ee-4638-5afb-8e76-d21e82f16f2c','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='23a853ee-4638-5afb-8e76-d21e82f16f2c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='23a853ee-4638-5afb-8e76-d21e82f16f2c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '342eff28-3240-5b14-915a-99b61b55193c','Sound management plan','A sound management plan is a formal document, often required as a permit or licence condition for events and venues, that sets out how sound will be predicted, controlled, monitored, and managed to keep noise within agreed limits and to handle complaints. It typically specifies the sound system design and orientation, predicted levels at sensitive receivers, agreed noise limits and reference points, monitoring procedures and personnel, escalation and response actions if limits are approached, and a complaints procedure. It is a live operational tool used before and during an event. Contents and required detail vary by jurisdiction, venue licence, and the authority''s guidance.','A sound management plan is a written plan to control event noise. It shows how loud the event will be at nearby homes. It lists the noise limits that must be met. It explains how sound will be measured during the event. It names who watches the levels and what they do. It also sets out how complaints are handled. Authorities often require it before an event. Its detail changes by venue and country.','It exists to turn abstract permit limits into concrete, accountable operating procedures, so everyone from the mix engineer to the promoter knows the limits, how they are checked, who intervenes, and what happens if levels rise, reducing nuisance, protecting the licence, and giving regulators confidence the event will self-manage.','A production''s noise consultant drafts the plan to satisfy a licence condition, agreeing limits and monitoring points with the authority; on show day the appointed noise controller measures against those points, radios the front-of-house engineer to pull levels if a limit is approached, and logs readings and any complaints.','Sound Law — Legal & Regulatory Framework',ARRAY['Noise permit','Noise impact assessment','Compliance monitoring','Acoustic assessment report','Boundary noise limit','Enforcement officer']::text[],ARRAY['Treating the plan as a paperwork formality rather than a live operational tool used throughout the event.','Assuming the plan sets the limits, when the limits come from the permit, licence, or ordinance and the plan explains how to meet them.','Omitting a clear escalation step, so no one knows who reduces levels when a limit is approached.','Believing one template fits everywhere, when required content varies by authority and venue licence.']::text[],ARRAY['A festival''s noise consultant submits a sound management plan as a licence condition, agreeing monitoring points and a curfew with the council.','A stadium concert''s plan assigns a noise controller who can instruct the front-of-house engineer to reduce level near the boundary limit.','After complaints at a prior event, a venue revises its sound management plan to add tighter monitoring and response steps.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound management plan');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '342eff28-3240-5b14-915a-99b61b55193c','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='342eff28-3240-5b14-915a-99b61b55193c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='342eff28-3240-5b14-915a-99b61b55193c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4bd318a9-269a-527a-9279-4c7a039e819e','Noise impact assessment','A noise impact assessment is a predictive or measurement-based evaluation of how a proposed or existing source, such as a development, event, venue, road, or industrial site, affects noise levels at nearby receivers, judged against relevant criteria. It typically establishes the existing background and ambient environment, predicts or measures the source''s contribution (often using propagation modelling per ISO 9613-2 or rating methods such as BS 4142 for industrial and commercial sound), and assesses the change against limits or guidance (for example WHO guidelines, ISO 1996, or planning conditions), then recommends mitigation. It underpins planning decisions and permit conditions. Methods, metrics, and acceptability criteria vary by jurisdiction, guidance, and land use.','A noise impact assessment predicts how a source will affect nearby people. The source can be a venue, road, factory, or event. First, the study measures the current background noise. Then it predicts or measures the new noise the source adds. It compares the result against limits or guidance. It also suggests ways to reduce the noise. Planners use it to decide and set conditions. Methods and limits differ by country and use.','It exists to inform decisions before harm occurs, letting authorities, developers, and communities understand a project''s acoustic consequences in advance, compare them against protective criteria, and require mitigation or refuse consent, rather than discovering nuisance or health effects after a source is already operating.','An acoustic consultant commissioned for a planning application measures baseline levels, models the proposed venue or road using standard propagation methods, compares predicted levels at the nearest dwellings against the applicable criteria, and recommends barriers, orientation, or limits that feed directly into the planning conditions.','Sound Law — Legal & Regulatory Framework',ARRAY['Acoustic assessment report','Sound management plan','Background noise level','BS 4142','ISO 1996','Noise permit']::text[],ARRAY['Confusing the assessment (the analysis) with the report (the document that presents it).','Assuming a single decibel limit applies everywhere, when criteria depend on land use, time of day, and local guidance.','Ignoring the existing background level, which is central to judging whether a new source is intrusive.','Treating modelled predictions as exact, when they carry uncertainty and depend on assumptions and method.']::text[],ARRAY['A developer''s planning application for a live-music venue includes a noise impact assessment predicting levels at neighbouring flats.','A highway authority commissions an assessment of traffic noise on nearby homes under environmental-review rules.','An industrial site facing complaints has an assessment done using BS 4142 to rate its sound against the background.']::text[],'advanced',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise impact assessment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4bd318a9-269a-527a-9279-4c7a039e819e','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4bd318a9-269a-527a-9279-4c7a039e819e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4bd318a9-269a-527a-9279-4c7a039e819e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '637cb5d7-e804-570c-985a-d8dd6330a2da','Acoustic assessment report','An acoustic assessment report is the formal written deliverable, usually prepared by a qualified acoustician, that documents a noise study''s scope, the standards and criteria applied, instrumentation and calibration, measurement or modelling methodology, results, comparison against limits, conclusions on compliance, and any recommended mitigation. It is the evidentiary record submitted to a planning authority, regulator, licensing body, or court to demonstrate that an assessment was carried out competently and to support a decision. Its required structure and content follow the governing standard or authority guidance (for example ISO 1996-2 measurement or BS 4142 rating), and expectations vary by jurisdiction and purpose.','An acoustic assessment report is the written record of a noise study. An acoustician usually prepares and signs it. It states the standards and limits that were used. It describes the meters, calibration, and methods applied. It gives the results and whether they meet the limits. It also lists any steps to reduce noise. Authorities and courts rely on it as evidence. Its required content changes by country and purpose.','It exists to make an assessment transparent, reproducible, and defensible, capturing exactly what was measured or modelled, how, and against which criteria, so a regulator, licensing panel, or court can trust the finding, challenge it if needed, and attach or enforce conditions on a documented evidential basis.','After completing measurements, a consultant compiles the report, including calibration certificates, measurement positions, weather conditions, and results tables, and submits it with a planning or licence application; the authority''s officer reviews it to decide compliance and to frame or verify permit conditions.','Sound Law — Legal & Regulatory Framework',ARRAY['Noise impact assessment','Compliance monitoring','ISO 1996','BS 4142','Sound management plan','Sound level meter calibration']::text[],ARRAY['Confusing the report (the document) with the assessment (the underlying analysis and measurements).','Assuming any noise measurement can stand as a report, when a defensible report requires stated methods, calibration, and criteria.','Overlooking calibration and measurement-condition records, whose absence undermines the report''s evidential weight.','Believing a single format applies everywhere, when structure follows the governing standard and authority.']::text[],ARRAY['A licensing hearing reviews an acoustician''s acoustic assessment report to decide a late-night venue''s conditions.','A council enforcement team relies on a report documenting ISO 1996-2 measurements to support an abatement case.','A developer submits an acoustic assessment report with a planning application to show predicted compliance at nearby homes.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic assessment report');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '637cb5d7-e804-570c-985a-d8dd6330a2da','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='637cb5d7-e804-570c-985a-d8dd6330a2da') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='637cb5d7-e804-570c-985a-d8dd6330a2da');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2409069e-1e2f-5738-9819-4d9aa89d09a8','Compliance monitoring','Compliance monitoring is the scheduled or continuous measurement of sound to demonstrate that a source stays within legally or contractually required limits, at a venue boundary, a receiver, or a work position. It uses calibrated instruments (Class 1 or 2 sound level meters per IEC 61672, field-checked with a calibrator per IEC 60942) and appropriate metrics such as LAeq over a period, LA90 background, or C-weighted peaks, recorded against agreed reference points and times. It may be real-time, with a controller watching a display and acting, or periodic, using spot checks and logged data, and it provides the evidence trail for permits, licences, and enforcement. Metrics, positions, and duties vary by jurisdiction and permit.','Compliance monitoring means measuring sound to prove it stays legal. It checks a source against its agreed noise limits. It uses calibrated meters at set points and times. The meters are checked before use with a calibrator. Monitoring can run live during an event or as spot checks. The records show the authority that limits were met. Someone may watch the levels and act if they rise. The exact metrics and points vary by permit.','It exists to convert a limit on paper into demonstrable fact, providing the objective, calibrated evidence that a source complied or did not, enabling operators to self-regulate in real time, regulators to verify, and both to resolve disputes and enforcement on measured data rather than subjective complaint.','A noise controller sets up a calibrated Class 1 meter at the agreed boundary point, verifies calibration with an acoustic calibrator, logs LAeq at the required interval, and instructs the front-of-house engineer to reduce level if readings approach the permit limit, retaining the logged data as compliance evidence.','Sound Law — Legal & Regulatory Framework',ARRAY['Sound management plan','Noise permit','Sound level meter','IEC 61672','LAeq','Enforcement officer']::text[],ARRAY['Skipping field calibration before and after monitoring, which can invalidate the readings as evidence.','Using the wrong metric or averaging time, so results cannot be compared with the permit''s stated limit.','Measuring at a convenient spot instead of the agreed reference point, producing non-comparable data.','Assuming monitoring alone reduces noise, when it only measures and control still requires action on the source.']::text[],ARRAY['A festival''s noise controller logs boundary LAeq every 15 minutes to prove compliance with the permit.','A council officer conducts independent compliance monitoring at a complainant''s home during a venue''s event.','An industrial site runs continuous monitoring at its boundary to demonstrate it meets its permit limits.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compliance monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2409069e-1e2f-5738-9819-4d9aa89d09a8','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2409069e-1e2f-5738-9819-4d9aa89d09a8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2409069e-1e2f-5738-9819-4d9aa89d09a8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0726437d-c746-5feb-a5f9-acf5c7b8927a','Enforcement officer','An enforcement officer, often an authorized or environmental health officer, is a public-authority official empowered by statute to investigate, measure, and act on noise that breaches law, permit conditions, or nuisance provisions. Depending on jurisdiction and their powers, they may enter premises, take measurements, gather evidence, issue warnings, serve abatement or statutory notices, seize noise-making equipment, impose fixed penalties, or require an event to reduce level or stop. Their authority derives from specific legislation, for example environmental health officers acting under the UK Environmental Protection Act 1990, or local ordinance officers elsewhere. Exact titles, powers, and procedures vary by country and local law.','An enforcement officer is an official who acts on illegal noise. The law gives them power to check and measure noise. They can enter a site and take readings as evidence. They may give warnings or serve legal notices. In some cases they can seize equipment or issue fines. They can order an event to turn down or stop. Their title and powers depend on local law. They work for a council or government body.','They exist to give noise law practical force, providing a trained, legally empowered person who can respond to complaints, gather admissible evidence, and apply graduated sanctions, so limits and permit conditions are not merely advisory but are actively investigated and enforced.','Responding to a resident complaint about a venue, an environmental health officer attends, measures the sound at the affected dwelling, checks it against permit or nuisance criteria, and, if breached, advises the operator to reduce level, serves an abatement notice, or escalates to seizure or prosecution.','Sound Law — Legal & Regulatory Framework',ARRAY['Abatement notice','Cease-and-desist order','Statutory nuisance','Compliance monitoring','Noise permit','Environmental health officer']::text[],ARRAY['Assuming any complaint automatically forces a shutdown, when the officer must gather evidence and follow legal procedure first.','Believing officers have identical powers everywhere, when their authority and titles vary by jurisdiction and statute.','Confusing the officer (the person) with the notice (the legal instrument they may serve).','Thinking a valid permit blocks all enforcement, when officers can still act on breaches or a resulting nuisance.']::text[],ARRAY['An environmental health officer responds to a late-night complaint and measures levels at the neighbour''s home.','During a festival, an authorized officer inspects the permit and can require levels reduced if conditions are breached.','A local-authority officer gathers evidence over several nights before serving an abatement notice on a noisy bar.']::text[],'beginner',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Enforcement officer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0726437d-c746-5feb-a5f9-acf5c7b8927a','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0726437d-c746-5feb-a5f9-acf5c7b8927a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0726437d-c746-5feb-a5f9-acf5c7b8927a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ba47e40e-a156-59c0-a7c2-1de5d1bd2865','Abatement notice','An abatement notice is a legal instruction served by a competent authority requiring the recipient to stop, reduce, or prevent the recurrence of a noise (or other) statutory nuisance, typically specifying what must be done and by when. Under the UK Environmental Protection Act 1990 (section 80), a local authority satisfied that a statutory noise nuisance exists or is likely must serve such a notice; failure to comply without reasonable excuse is a criminal offence, though the recipient may appeal within a set period. Equivalent instruments exist in other jurisdictions. Grounds, procedure, appeal rights, and penalties vary by country and local law.','An abatement notice is a legal order to stop a noise nuisance. An authority serves it when noise unreasonably harms neighbours. The notice says what to fix and by when. In the UK, councils serve it under the Environmental Protection Act 1990. Ignoring it without good reason is a crime. The person served can usually appeal in time. Similar orders exist in other countries. The exact rules and penalties vary by law.','It exists to give authorities a direct, enforceable remedy against an established nuisance, compelling the responsible party to act under threat of criminal penalty, and thereby protecting affected residents without requiring each of them to bring a private legal action.','After gathering evidence that a venue''s noise amounts to a statutory nuisance, a council''s environmental health officer serves an abatement notice specifying the required reduction and deadline; the operator must comply or appeal, and continued breach can lead to prosecution and fines or equipment seizure.','Sound Law — Legal & Regulatory Framework',ARRAY['Statutory nuisance','Enforcement officer','Cease-and-desist order','Noise permit','Compliance monitoring','Environmental Protection Act 1990']::text[],ARRAY['Assuming a notice takes effect instantly and finally, when the recipient usually has a right to appeal within a set time.','Confusing a statutory abatement notice with an informal warning letter, which carries no criminal sanction.','Believing a valid permit or licence blocks a notice, when a statutory nuisance can still be actionable.','Thinking the notice sets a decibel limit, when it requires abating the nuisance, which is defined more broadly than a single number.']::text[],ARRAY['A council serves an abatement notice on a bar after repeated, evidenced late-night noise nuisance to neighbours.','A promoter appeals an abatement notice, arguing the event used best practicable means to control noise.','An environmental health officer warns a venue that continued breaches will lead to an abatement notice.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Abatement notice');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ba47e40e-a156-59c0-a7c2-1de5d1bd2865','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ba47e40e-a156-59c0-a7c2-1de5d1bd2865') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ba47e40e-a156-59c0-a7c2-1de5d1bd2865');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f0a1525f-a689-5d39-8567-9d1853926e8e','Cease-and-desist order','A cease-and-desist order is a directive, issued by a court, regulator, or authority (or, in its informal form, a letter from an aggrieved party or their lawyer), demanding that the recipient immediately stop an activity alleged to be unlawful, here a noise activity that violates rules, permit conditions, or nuisance law. An official order carries legal force and penalties for non-compliance; an informal cease-and-desist letter is a formal demand and a warning of potential legal action but is not itself binding. It is used to halt ongoing violations quickly. Its legal weight, issuer, and procedure vary by jurisdiction and by whether it is a court or agency order or a private letter.','A cease-and-desist order tells someone to stop an activity now. Here, it targets noise that breaks rules or permit terms. A court or authority can issue one with legal force. Then ignoring it brings penalties. A private cease-and-desist letter is different. It is a formal demand and a warning of legal action. But a letter alone is not legally binding. Its power depends on who issues it and the law.','It exists to stop an alleged violation quickly, either as a binding order compelling immediate cessation under penalty, or as a documented warning that puts the recipient on notice and creates a record before escalation to court, giving a fast route to halt ongoing harm.','A regulator or court issues a cease-and-desist order requiring a venue to stop unpermitted amplified sound immediately, with penalties for defiance; alternatively, an affected neighbour''s solicitor sends a cease-and-desist letter demanding the noise stop and warning that litigation will follow if it continues.','Sound Law — Legal & Regulatory Framework',ARRAY['Abatement notice','Enforcement officer','Statutory nuisance','Injunction','Noise permit','Cease-and-desist letter']::text[],ARRAY['Assuming every cease-and-desist demand is legally binding, when a private letter is only a demand until a court or agency acts.','Confusing a cease-and-desist order with an abatement notice, which is a specific statutory nuisance instrument.','Believing compliance admits legal fault, when stopping the activity does not by itself concede liability.','Thinking it permanently resolves the dispute, when it may be a first step before an injunction or prosecution.']::text[],ARRAY['A city agency issues a cease-and-desist order halting an unpermitted warehouse party generating complaints.','A neighbour''s lawyer sends a cease-and-desist letter to a venue demanding it stop late-night amplified music.','A court orders a persistent offender to cease noisy operations pending a full nuisance hearing.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cease-and-desist order');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f0a1525f-a689-5d39-8567-9d1853926e8e','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f0a1525f-a689-5d39-8567-9d1853926e8e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f0a1525f-a689-5d39-8567-9d1853926e8e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '150febb4-4066-5616-9c6e-de76759a4d00','License condition','A licence condition is a legally binding requirement attached to a permission an operator holds to run a venue or event — such as a liquor licence, place-of-public-entertainment licence, planning approval, or one-off event permit — that regulates the sound it may produce. Noise-related conditions commonly cap emitted or received levels, fix a measurement position and descriptor, restrict the hours of amplified music, mandate a limiter or acoustic report, or set complaint-response duties. Exact limits and descriptors vary by jurisdiction, licence type, venue, permit, time of day, receiver location, and measurement method; for example, some Australian liquor-licence conditions have used an LA10 criterion referenced to background at the nearest affected residence.','A licence lets a business run a venue or event. The licence can carry rules about noise. These rules are called licence conditions. A condition may cap how loud the sound can be. It may set where and how to measure. It may limit late-night amplified music. It may force the use of a sound limiter. The exact rules change by place, venue and time of day. Breaking a condition can bring fines or licence loss.','It lets an authority permit an activity while controlling its noise impact on neighbours. By tying the ongoing right to trade to measurable, enforceable sound limits, it gives regulators leverage short of shutdown and gives affected neighbours a defined standard to rely on.','A sound tech reads the licence conditions before a show to learn the cap, the measurement point, the curfew, and whether a specific limiter set-point is mandated, then sets front-of-house and limiter levels to stay within them. A compliance officer logs readings as documentary evidence of compliance and to defend against complaints.','Sound Law — Legal & Regulatory Framework',ARRAY['Development consent condition','Property-line limit','Receiver-location limit','Quiet hours','Noise immission limit','Special entertainment precinct']::text[],ARRAY['Treating a licence condition as advice — it is legally binding, and breach can lead to fines, prosecution or revocation.','Assuming one numeric limit applies everywhere — conditions are set case by case and vary by licence, venue and jurisdiction.','UNSAFE: Believing that meeting an external neighbour-focused licence limit also protects staff and audience hearing — occupational and audience-exposure limits (for example under EU 2003/10/EC or DIN 15905-5) are separate and can be exceeded even when the neighbour limit is met.']::text[],ARRAY['A touring engineer at an unfamiliar club reads the venue''s entertainment licence to find the amplified-music curfew and the mandated limiter set-point.','A council licensing officer adds a noise condition to a new bar''s liquor licence after objections from upstairs residents.','A festival producer negotiates event-permit conditions setting a boundary limit and a complaints hotline.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='License condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '150febb4-4066-5616-9c6e-de76759a4d00','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='150febb4-4066-5616-9c6e-de76759a4d00') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='150febb4-4066-5616-9c6e-de76759a4d00');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a9c6b1f7-cff8-5842-9b64-718007327f5e','Development consent condition','A development consent condition is a noise-related requirement imposed when a planning or zoning authority approves a development — a venue, mixed-use building, or industrial site. Attached to the consent, it can fix emission or received-level limits, mandate acoustic treatment or speaker placement, require a limiter, restrict operating hours for amplified sound, or require an acoustic compliance report before occupation. Unlike a personal licence, it runs with the land and use and typically persists for the life of the development, binding successive operators. Limits, descriptors and assessment points vary by jurisdiction, consent and local policy; for example, NSW consents have used LA10(15 min) criteria at the nearest affected receiver.','To build or change a venue you often need planning approval. The approval can carry noise rules. These are development consent conditions. A rule may cap sound at nearby homes. It may set speaker spots or force a limiter. It may limit hours for amplified music. The rules stay with the site, not the owner. They last for the life of the building''s use. Exact limits change by place and local policy.','It lets planners approve a use while protecting neighbouring land uses from noise. Mitigation is baked into the approval up front, so conflict is designed out rather than litigated later, and the obligations bind whoever operates the site over time.','A venue''s acoustic consultant designs treatment and limiter settings to meet the consent''s numeric limit at the identified receiver, then produces the required compliance report before occupation. An operator checks the consent conditions before extending hours or adding outdoor sound to confirm it stays within scope.','Sound Law — Legal & Regulatory Framework',ARRAY['License condition','Receiver-location limit','Sensitive receptor','Property-line limit','Special entertainment precinct','Noise immission limit']::text[],ARRAY['Confusing it with a licence condition — consent conditions come from planning law and attach to the land and use, not the operator''s licence.','Assuming a new owner starts fresh — the conditions run with the development and bind whoever operates it.','Thinking conditions can be ignored once built — they are enforceable for the life of the use and breach can trigger planning enforcement.']::text[],ARRAY['A developer of an apartment block beside a live-music pub faces a consent condition requiring glazing that protects future residents.','A nightclub adding a rooftop bar must satisfy a consent condition capping level at the nearest residential facade.','A council enforcement officer checks whether an operating venue still meets the acoustic conditions of its original approval.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Development consent condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a9c6b1f7-cff8-5842-9b64-718007327f5e','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a9c6b1f7-cff8-5842-9b64-718007327f5e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a9c6b1f7-cff8-5842-9b64-718007327f5e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '82bdf26f-2cf1-5b68-8876-f29280eaf124','Special entertainment precinct','A special entertainment precinct (SEP) is a designated geographic area — an Australian/NSW mechanism — where the normal noise-regulation regime for licensed live-entertainment venues is replaced by a locally tailored framework. A local council declares the precinct and adopts a precinct management plan setting area-specific sound levels, trading hours and management processes; within it, certain state noise controls and inconsistent development-consent or licence noise conditions cease to have effect, and complaints are assessed against the plan rather than general nuisance or POEO Act rules. The aim is to sustain nightlife and live music while giving venues clearer, more stable sound obligations. The mechanism and its details are jurisdiction-specific (NSW Liquor & Gaming; Protection of the Environment Operations Act 1997).','A special entertainment precinct is a marked nightlife area. A local council sets it up in New South Wales. The council writes a plan for the whole area. The plan sets sound levels and trading hours. Inside the area, the plan replaces the usual noise rules. Some old licence or planning noise rules stop applying. Complaints are judged against the plan, not general law. The goal is to protect live music and give venues clarity. These details apply to NSW in Australia.','It resolves the recurring conflict between nightlife venues and encroaching residents by moving from case-by-case, complaint-driven limits to a shared area plan. This gives venues certainty and protects cultural and live-music activity while still bounding noise for the surrounding community.','A venue operator inside a declared precinct manages sound to the precinct plan''s levels and hours rather than an older licence LA10 condition. A council officer administers the plan and, when a complaint arises, assesses whether the venue exceeds the plan''s criteria using acoustic testing.','Sound Law — Legal & Regulatory Framework',ARRAY['License condition','Development consent condition','Quiet hours','Receiver-location limit','Agent of change','Property-line limit']::text[],ARRAY['Thinking a precinct removes all noise limits — it replaces them with the precinct plan''s own levels and hours, which still bind venues.','Assuming it is a nationwide rule — it is a NSW/Australian mechanism and equivalents elsewhere differ.','Believing residents lose all recourse — complaints still work but are assessed against the precinct plan''s criteria.']::text[],ARRAY['A council declares a live-music street a special entertainment precinct and publishes a management plan with later hours and agreed sound levels.','A venue inside the precinct references the plan, not its old consent condition, when setting its limiter.','A resident''s noise complaint is assessed by measuring against the precinct plan''s criteria rather than general nuisance law.']::text[],'advanced',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Special entertainment precinct');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '82bdf26f-2cf1-5b68-8876-f29280eaf124','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='82bdf26f-2cf1-5b68-8876-f29280eaf124') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='82bdf26f-2cf1-5b68-8876-f29280eaf124');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6df47e8f-7b74-525e-9eda-5811cea1b592','Quiet hours','Quiet hours (night-time or restricted periods) are legally defined intervals, usually overnight, during which stricter noise controls apply — lower permitted levels, tighter descriptors, or an outright prohibition on certain noisy activities. They appear in local ordinances, licences, consents and construction permits. Definitions vary widely: many regimes treat night as roughly 23:00–07:00, some municipal codes drop the permitted level by around 10 dB at night, and the EU Environmental Noise Directive and WHO use a distinct night indicator (Lnight). Exact hours and limits depend on jurisdiction, day of week, receiver and land use.','Quiet hours are set times when noise rules get stricter. They usually cover the night. During these hours the allowed sound level drops. Some rules ban noisy work at night altogether. Many places treat night as about 11 pm to 7 am. Some codes drop the night cap by about 10 dB. The exact hours and limits change by city and land use. Weekend hours can differ from weekdays. Always check the local rule for the real times.','It protects sleep and rest when people are most sensitive and background sound is lowest. A fixed time window gives enforcement a bright line and recognises that the same level is more intrusive at night than by day.','An event producer schedules load-out and amplified sound to finish before quiet hours begin, or drops to the night limit at the curfew time. A construction manager stops percussive work at the ordinance''s night boundary to avoid breaching the permit.','Sound Law — Legal & Regulatory Framework',ARRAY['License condition','Receiver-location limit','Lnight','Curfew','Sensitive receptor','Noise immission limit']::text[],ARRAY['Thinking quiet hours are the same everywhere — start and end times and limits vary by city, day and land use.','Assuming quiet hours mean silence — usually a lower level applies, not a total ban.','UNSAFE: Believing that respecting neighbourhood quiet hours means the audience is safe — quiet hours protect neighbours'' sleep, not the hearing of people inside the show, which needs separate exposure limits.']::text[],ARRAY['A promoter sets the outdoor-stage curfew to match the city''s night quiet-hours start.','A resident logs a late-night complaint that is judged against the night limit, not the daytime one.','A construction site pauses piling at the quiet-hours boundary to stay within its permit.']::text[],'beginner',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quiet hours');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6df47e8f-7b74-525e-9eda-5811cea1b592','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6df47e8f-7b74-525e-9eda-5811cea1b592') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6df47e8f-7b74-525e-9eda-5811cea1b592');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '99403260-c4a0-526f-ba6b-e855c71b3436','Sensitive receptor','A sensitive receptor (noise-sensitive receiver) is a location whose occupants or function are especially vulnerable to noise and are therefore given protection in noise law and assessment — typically dwellings, hospitals, schools, childcare centres, aged-care, places of worship and hotels, and sometimes wildlife habitat or precision laboratories. Limits and assessment points are commonly defined relative to the nearest or most-affected sensitive receptor rather than the source. What counts as sensitive, and the applicable limit, varies by jurisdiction, land-use zone, time of day and framework (for example airport noise contours, END strategic mapping, or EPA and ISO 1996 assessments).','A sensitive receptor is a place that needs extra noise protection. Homes, hospitals, schools and childcare are common examples. Aged-care, hotels and places of worship often count too. Noise limits are often set at the nearest such place. The rule protects the people or work inside it. What counts as sensitive changes by area and land use. The limit can also change by time of day. Airport and mapping rules use these receptors too.','It focuses regulation on the receiving end, where harm actually occurs, and lets rules target protection to vulnerable uses and quiet times. It also anchors the assessment point for limits and modelling.','A consultant identifies the nearest sensitive receptor and predicts or measures the level there to test compliance with a limit. A planner uses receptor locations to route a road or site a stage, and an assessor places the microphone at the receptor facade.','Sound Law — Legal & Regulatory Framework',ARRAY['Receiver-location limit','Facade level','Noise immission limit','Development consent condition','Quiet hours','Property-line limit']::text[],ARRAY['Thinking only homes count — hospitals, schools, childcare, aged-care and places of worship are commonly protected too.','Assuming the source location matters most — limits are usually assessed at the receptor, not the source.','Believing the list is fixed — which uses count as sensitive varies by jurisdiction and zoning.']::text[],ARRAY['An acoustic consultant maps nearby homes and a childcare centre as the sensitive receptors governing a festival''s limit.','An airport authority draws noise contours around schools and hospitals as sensitive receptors.','A road-project assessor sets predicted-level limits at residential facades treated as sensitive receptors.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sensitive receptor');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '99403260-c4a0-526f-ba6b-e855c71b3436','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='99403260-c4a0-526f-ba6b-e855c71b3436') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='99403260-c4a0-526f-ba6b-e855c71b3436');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '948c9df4-ebaf-524b-89b1-ed419994d522','Property-line limit','A property-line (boundary or emission-point) limit caps the sound level measured at the boundary of the source property, regardless of where receivers are located. Common in municipal noise ordinances and industrial or construction permits, it gives an objective, source-controlled compliance point. Descriptor and value vary; for example, some US city codes set fixed dB(A) caps at the property line that differ by zoning and by day or night. Because it is measured at the emitter''s boundary, a property-line limit is not the same as a receiver-location limit, and the two can give different results depending on distance, height and terrain.','A property-line limit caps sound at the edge of the source site. It is measured at the boundary, not at a home. Many city and industry rules use this point. It gives a clear, fixed place to check. The value often changes by zoning and by day or night. It is not the same as a limit measured at a home. Distance and terrain can make the two differ. Always check which point your rule uses.','It gives a simple, source-side enforcement point that does not depend on who lives nearby, so it is easy to measure and apply uniformly across a zone. By bounding what leaves the site, it protects neighbours indirectly.','A plant or venue sets and verifies levels at its own boundary to prove compliance, and a designer positions loud plant away from the closest boundary. An enforcement officer measures at the property line during a complaint.','Sound Law — Legal & Regulatory Framework',ARRAY['Receiver-location limit','Noise emission limit','Noise immission limit','Sensitive receptor','Facade level','Free-field level']::text[],ARRAY['Assuming a property-line pass means neighbours are fine — a distant or shielded receiver may hear less, while an elevated one may hear more.','Confusing it with a receiver-location limit — one is measured at the source boundary, the other at the affected home.','Thinking one value fits all — property-line caps usually differ by zone and by day or night.']::text[],ARRAY['A factory demonstrates compliance by logging levels at its site boundary.','A city officer measures at the club''s property line after a neighbour''s complaint.','A construction permit sets a daytime dB(A) cap at the site boundary.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Property-line limit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '948c9df4-ebaf-524b-89b1-ed419994d522','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='948c9df4-ebaf-524b-89b1-ed419994d522') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='948c9df4-ebaf-524b-89b1-ed419994d522');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3b867937-6773-5429-9e87-a97b462aac00','Receiver-location limit','A receiver-location limit caps the sound level at the affected receiver — a residence, facade, window, or outdoor amenity or living area — rather than at the source. It targets the actual exposure of people and usually specifies the exact position (for example 1 m from a facade, or free-field in the yard) and the descriptor. It underpins most residential-amenity licence and consent conditions (for example LA10 or LAeq criteria at the nearest dwelling, often referenced to background). Because propagation, distance, shielding and reflections change the level between source and receiver, a receiver limit differs from a property-line limit, so the specified position and method matter.','A receiver-location limit caps sound at the affected home. It is measured where people are, not at the source. The rule may name the exact spot to measure. It may say 1 metre from the wall or in the yard. Most home-protection limits work this way. The level changes as sound travels from the source. So this limit differs from one taken at the source edge. The named spot and method really matter. Check both before you measure.','It ties the limit to real human exposure at the receiving end, which is fairer to both sides because it reflects what the neighbour actually experiences. This anchors amenity protection to the place harm is felt.','A consultant measures or predicts at the nominated receiver position to test a consent or licence limit. A tech adjusts level knowing the governing point is a neighbour''s window, not the mixer, and an officer sets the meter at the specified receiver spot.','Sound Law — Legal & Regulatory Framework',ARRAY['Property-line limit','Facade level','Free-field level','Sensitive receptor','Noise immission limit','Immission']::text[],ARRAY['Thinking the source level equals the receiver level — distance, shielding and reflections change it.','Ignoring the specified position — facade and free-field can differ by about 3 dB and change a pass into a fail.','Confusing it with a property-line limit — this one is measured at the affected home, not the source boundary.']::text[],ARRAY['A consultant measures at the complainant''s bedroom window to test the venue''s consent limit.','A licence sets an LAeq limit in the neighbour''s backyard living area.','An officer places the meter at the nominated facade position during a night complaint.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Receiver-location limit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3b867937-6773-5429-9e87-a97b462aac00','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3b867937-6773-5429-9e87-a97b462aac00') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3b867937-6773-5429-9e87-a97b462aac00');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2a12e36-88e7-5623-bc69-e0c607575340','Facade level','A facade level is a sound level measured or predicted close to a building facade, where reflection from the facade itself raises the reading above the equivalent free-field (incident) level — typically by up to about 3 dB when the microphone is roughly 1–2 m from a hard facade. Environmental noise mapping and many limits reference a facade position; for example, EU strategic noise mapping under Directive 2002/49/EC uses the most-exposed facade at about 4 m height and defines an incident (free-field) indicator for it. Because a facade level includes reflection, it is not interchangeable with a free-field level, so the framework must state which is meant and any correction applied.','A facade level is sound measured right next to a building''s wall. The wall reflects sound and adds to the reading. Close to a hard wall this can add up to about 3 dB. Noise maps and many limits use a facade point. For example, EU mapping uses the most-exposed facade. Because of the reflection, it is not a free-field value. The rule must say which type it means. Always apply the right correction between them. Mixing the two can flip a pass or fail.','It gives a repeatable position tied to where people are exposed at home and standardises mapping and comparison across sites. But because reflection biases it upward, the framework must be explicit about the correction.','A consultant states whether a measured level is facade or free-field and applies the roughly 3 dB correction to compare against a limit defined the other way. A noise-mapper assigns facade levels to dwellings for exposure statistics.','Sound Law — Legal & Regulatory Framework',ARRAY['Free-field level','Receiver-location limit','Immission','Sensitive receptor','Lden','Noise immission limit']::text[],ARRAY['Treating facade and free-field readings as the same — a hard facade can add up to about 3 dB.','Forgetting to state or correct for the reflection when comparing to a limit.','Assuming all frameworks use the same facade height and distance — END, national codes and ISO 1996 differ.']::text[],ARRAY['A strategic noise-mapping team assigns facade levels to each dwelling for an END exposure map.','A consultant converts a facade measurement to free-field to match a limit written as free-field.','An assessor documents the microphone at 1 m from the facade and notes the reflection correction.']::text[],'advanced',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Facade level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2a12e36-88e7-5623-bc69-e0c607575340','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2a12e36-88e7-5623-bc69-e0c607575340') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2a12e36-88e7-5623-bc69-e0c607575340');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e5a177a6-8c38-5f7a-b2aa-8bcdee20745d','Free-field level','A free-field level is a sound level measured or predicted away from reflecting surfaces (other than the ground), so it represents the sound incident at a point without facade or nearby-object reflections. It is the reference condition for many source specifications and some limits, and for comparability it requires either an open measurement position or a correction that removes facade reflection (about 3 dB). Free-field and facade levels are not interchangeable; standards such as ISO 1996-2 and the EU Environmental Noise Directive framework distinguish them and specify how to convert between them or which one applies.','A free-field level is sound measured away from walls and objects. Only the ground reflection is present. It shows the sound arriving at a point on its own. Many source specs and some limits use this reference. To get it you measure in the open or correct for reflection. A hard wall adds about 3 dB, so you subtract it. Free-field and facade values are not the same. Standards say which one a limit uses. Always match the limit''s reference before you judge.','It provides a reflection-free reference so measurements are comparable across sites and match source data. Using it avoids overstating exposure by wrongly including facade reflection.','A tech measures in an open position, away from walls, to get a free-field value, or subtracts the facade correction. A consultant checks that a source''s rated free-field emission is compared like-for-like with a free-field limit.','Sound Law — Legal & Regulatory Framework',ARRAY['Facade level','Receiver-location limit','Immission','Noise emission limit','Sound power level','Property-line limit']::text[],ARRAY['Comparing a free-field limit to a facade measurement without correcting the roughly 3 dB reflection.','Thinking free-field means no ground reflection — the ground is normally still present.','Assuming any open measurement is truly free-field — nearby hard objects also reflect and must be avoided.']::text[],ARRAY['A consultant records a free-field level in the middle of a yard to match a free-field consent limit.','An engineer compares a loudspeaker''s rated free-field output with an on-site free-field reading.','An assessor removes a facade reflection correction to report an equivalent free-field value.']::text[],'advanced',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Free-field level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e5a177a6-8c38-5f7a-b2aa-8bcdee20745d','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e5a177a6-8c38-5f7a-b2aa-8bcdee20745d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e5a177a6-8c38-5f7a-b2aa-8bcdee20745d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9758e54e-ea71-52e3-a17b-792efa727248','Immission','Immission is the sound received at a given location — the counterpart to emission, which is the sound radiated by a source. The term is standard in European and international acoustics and law (German Immission, as framed in TA Lärm under the Federal Immission Control Act, BImSchG), and it frames limits and assessments at the receiver end: an immission point is where the received level is evaluated against a limit. Distinguishing immission from emission is fundamental, because propagation, distance, shielding and meteorology change the level between source and receiver. Immission limits and points vary by jurisdiction, land use and time.','Immission is the sound that arrives at a place. It is the opposite of emission, which is sound leaving a source. The word is common in European noise law. It puts the focus on the receiver''s location. An immission point is where you judge the received level. This matters because sound changes as it travels. Distance, barriers and weather all change the level. Limits at the receiver are called immission limits. They vary by place, land use and time.','It separates how much a source makes from how much a receiver gets, which is essential for correct assessment and fair limits. This centres protection on the people at the receiving end.','A consultant computes the immission level at a dwelling from source emission plus propagation, then compares it with the immission limit for that period. A regulator specifies the immission point used to judge a complaint.','Sound Law — Legal & Regulatory Framework',ARRAY['Emission','Noise immission limit','Noise emission limit','Receiver-location limit','Sensitive receptor','Sound propagation']::text[],ARRAY['Confusing immission with emission — immission is received sound, emission is radiated sound.','Assuming the emission level equals the immission level — propagation changes it with distance and shielding.','Thinking the term is only academic — many European limits are legally written as immission values.']::text[],ARRAY['A German assessment predicts the immission level at the nearest dwelling under TA Lärm.','A consultant separates a plant''s emission from the immission received at homes 200 m away.','A regulator names the immission point for judging a wind-farm complaint.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Immission');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9758e54e-ea71-52e3-a17b-792efa727248','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9758e54e-ea71-52e3-a17b-792efa727248') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9758e54e-ea71-52e3-a17b-792efa727248');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7d4b1f46-dcd6-58f2-941d-bb257baca64d','Noise emission limit','A noise emission limit caps the sound radiated by a source — equipment, machinery, vehicles, outdoor plant, or a venue''s output — usually expressed as a sound power level or a level at a fixed distance, and often certified by type-testing rather than measured at a receiver. It controls the source itself; for example, EU Directive 2000/14/EC sets guaranteed sound-power limits for outdoor equipment, and vehicle type-approval regulations cap pass-by levels. Emission limits differ from immission limits: meeting an emission cap does not guarantee an acceptable received level, which also depends on the number of sources, distance and environment.','A noise emission limit caps the sound a source puts out. It controls the machine or venue, not the neighbour''s home. It is often given as sound power or level at a set distance. Many products are tested to this limit before sale. For example, EU rules cap outdoor equipment power output. Meeting it does not promise a quiet neighbour. The received level also depends on distance and source count. Emission limits and receiver limits are different things. Check which one your rule sets.','It controls noise at the design and source stage, so problems are prevented before deployment and products can be compared and market-regulated. It complements receiver-based limits rather than replacing them.','A hire firm or producer selects generators and equipment rated within the emission limit, and a manufacturer certifies a product''s guaranteed sound power. A designer sums source emissions to predict site impact before an event.','Sound Law — Legal & Regulatory Framework',ARRAY['Noise immission limit','Emission','Sound power level','Immission','Property-line limit','Type approval']::text[],ARRAY['Thinking an emission-compliant source guarantees a compliant received level — many together, or one placed close by, can still exceed a receiver limit.','Confusing emission limits (at the source) with immission limits (at the receiver).','Assuming emission limits are measured on site — many are type-tested sound-power ratings.']::text[],ARRAY['A festival hires generators whose guaranteed sound power meets EU Directive 2000/14/EC.','A manufacturer type-tests a compressor to certify its emission rating.','A designer adds up equipment emissions to estimate the level at nearby homes.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise emission limit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7d4b1f46-dcd6-58f2-941d-bb257baca64d','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7d4b1f46-dcd6-58f2-941d-bb257baca64d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7d4b1f46-dcd6-58f2-941d-bb257baca64d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5f840bda-ef67-5d1e-b345-fa84e6cb928d','Noise immission limit','A noise immission limit caps the sound level received at a receptor — a dwelling, facade or amenity area — and is the receiver-end counterpart to an emission limit. It is typically written as a time-descriptor (LAeq, LA10, Lden or Lnight) with a value that varies by land use, time of day and framework; for example WHO and END use guideline values, while national codes such as Germany''s TA Lärm set differing day and night immission values by area type. Compliance depends on the cumulative received sound from all relevant sources at the specified point and method, not on any single source''s rating.','A noise immission limit caps sound at the receiver''s location. It is the received-end partner to an emission limit. It is usually written as an average or percentile level. The value changes by land use and time of day. For example, night limits are lower than day limits. It covers the total sound arriving from all sources. So one quiet source can still push the total over. The exact spot and method are set by the rule. Guideline values differ between WHO, EU and national codes.','It protects people where they live by bounding the total received noise, and it lets rules reflect land use and time of day. It is the enforceable target for amenity complaints.','A consultant compares the predicted or measured received level at the dwelling against the immission limit for that period. A regulator uses it as the pass or fail threshold when judging a complaint.','Sound Law — Legal & Regulatory Framework',ARRAY['Noise emission limit','Immission','Receiver-location limit','Sensitive receptor','Facade level','Quiet hours']::text[],ARRAY['Thinking it applies to one source — it usually caps the total received from all relevant sources.','Confusing immission limits (received) with emission limits (radiated).','Assuming one number applies all day — day and night immission limits usually differ.']::text[],ARRAY['A consultant tests whether the total received level at a home meets the night immission limit.','A regulator judges a complaint against the area''s day and night immission values.','A planner sets an immission limit at future apartments near an industrial site.']::text[],'intermediate',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise immission limit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5f840bda-ef67-5d1e-b345-fa84e6cb928d','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5f840bda-ef67-5d1e-b345-fa84e6cb928d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5f840bda-ef67-5d1e-b345-fa84e6cb928d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a048c034-3223-54bb-9643-684a4b9e17b7','Best practicable means (BPM)','Best practicable means (BPM) is a UK statutory concept (Environmental Protection Act 1990, Part III, s.79(9), with roots in earlier alkali and Control of Pollution legislation) that provides both a mitigation standard and a defence in noise statutory-nuisance cases: a defendant may show they used all reasonably practicable methods to prevent or minimise the nuisance. ''Practicable'' is judged having regard to local conditions and circumstances, the current state of technical knowledge, and financial implications, and it applies to the design, installation, maintenance and operation of plant and structures. It is a flexible, case-specific standard rather than a fixed numeric limit, and its availability and scope depend on the statutory context.','Best practicable means is a UK noise-law idea. It sets a mitigation standard and a legal defence. A person can show they took all reasonable steps to cut the noise. Practicable weighs local conditions and current know-how. It also weighs the cost of the steps. It covers how plant and buildings are run and kept. It is not a fixed number to hit. It is judged case by case. Its use depends on the exact law that applies.','It lets enforcement demand reasonable mitigation without setting an unattainable or one-size numeric cap, balancing protection against cost and feasibility. It gives operators both a route to compliance and a defence if they have done what is reasonable.','A venue facing a noise abatement notice records the mitigation it applied — acoustic treatment, a limiter, revised operations — to argue best practicable means. An environmental health officer assesses whether cheaper or better-known measures were reasonably available.','Sound Law — Legal & Regulatory Framework',ARRAY['Statutory nuisance','License condition','Noise abatement notice','Development consent condition','Immission','Best available techniques']::text[],ARRAY['Thinking BPM is a fixed dB limit — it is a case-specific reasonableness test, not a number.','Assuming cost is irrelevant — financial implications are explicitly part of what is ''practicable''.','Believing BPM excuses any noise — it only covers what is reasonably practicable given current knowledge and conditions.']::text[],ARRAY['A pub served an abatement notice shows it fitted a limiter and lobby doors to argue best practicable means.','An environmental health officer weighs whether affordable extra treatment was reasonably available.','A contractor documents quieter methods used to defend a construction-noise complaint.']::text[],'advanced',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Best practicable means (BPM)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a048c034-3223-54bb-9643-684a4b9e17b7','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a048c034-3223-54bb-9643-684a4b9e17b7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a048c034-3223-54bb-9643-684a4b9e17b7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '69cf2ba3-51da-5be2-a87a-681d0fb4d1b0','As low as reasonably practicable (ALARP)','A risk-management principle used in safety and noise regulation requiring that a risk be reduced to a level at which the cost, time and effort of any further reduction would be grossly disproportionate to the safety benefit gained. It originates in UK health-and-safety law. In Edwards v National Coal Board (1949) the duty to do what is ''reasonably practicable'' was interpreted as a balance between the quantum of risk and the sacrifice needed to avert it, and the principle underpins general duties such as those in the Health and Safety at Work etc. Act 1974. In noise practice it frames the obligation to control worker noise exposure and, in some regimes, community or event noise: controls are pursued down a hierarchy until further action becomes grossly disproportionate. The exact wording, the burden of proof, and how ''gross disproportion'' is judged vary by jurisdiction, and analogous but distinct standards (for example ''best practicable means'') apply elsewhere.','ALARP means making a risk as low as is reasonably practicable. You weigh the risk against the time, money, and effort to reduce it. You keep cutting the risk until more effort would be far too costly. The cost must be very large next to the safety gain. In UK law this idea comes from the Health and Safety at Work Act. Judges shaped the test in a 1949 court case. For noise, employers must cut worker noise in this way. Rules differ by country and by how a court reads them.','It gives regulators and duty-holders a workable standard between doing nothing and eliminating a risk at any cost. Rather than fixing one universal numeric limit, it forces a proportionate, documented judgement: the greater the risk, the more expenditure and effort must be justified before further control can be declined. In noise contexts this drives the noise-control hierarchy (eliminate, engineer out at source, organise work, then protect the individual) and prevents duty-holders from treating a numeric action or limit value as a licence to stop.','A compliance officer uses ALARP to justify and record why noise controls were or were not taken, keeping a risk assessment that shows measured exposure, options considered, their cost, and why any rejected option was grossly disproportionate. On a factory floor an employer might install quieter machinery, add enclosures, rotate staff, and only then rely on hearing protection, documenting each step so the residual risk is demonstrably ALARP to an inspector.','Sound Law — Legal & Regulatory Framework',ARRAY['Best practicable means (BPM)','Hierarchy of noise controls','Control of Noise at Work Regulations 2005','Health and Safety at Work etc. Act 1974','Risk assessment','Best available techniques (BAT)']::text[],ARRAY['Thinking ALARP simply means ''do whatever is cheap'' — the test is gross disproportion, so a high risk demands large spending before further control can be refused.','Assuming meeting a numeric noise limit automatically proves ALARP; a measured value at or below an action level can still require further reasonably practicable reduction.','UNSAFE: Believing that issuing hearing protection alone discharges the duty — protection sits at the bottom of the control hierarchy and does not replace reducing noise at source where that is reasonably practicable.','Confusing ALARP with a purely financial cost-benefit calculation based on the organisation''s ability to pay, which UK guidance rejects.']::text[],ARRAY['A safety officer at a bottling plant documents machine enclosures, damping and job rotation to show a court that residual worker noise exposure has been driven ALARP.','A touring production manager justifies stage-monitor and side-fill changes as reasonably practicable steps to lower crew exposure without stopping the show.','An HSE-style inspector reviews a workshop''s noise risk assessment and challenges whether a rejected engineering control was truly grossly disproportionate.','A venue operator weighs the cost of an acoustic barrier against neighbour complaint risk when deciding what noise control is reasonably practicable.']::text[],'advanced',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='As low as reasonably practicable (ALARP)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '69cf2ba3-51da-5be2-a87a-681d0fb4d1b0','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='69cf2ba3-51da-5be2-a87a-681d0fb4d1b0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='69cf2ba3-51da-5be2-a87a-681d0fb4d1b0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '67ef4c3f-83cc-5f61-b551-f64492b474f3','Best available techniques (BAT)','A regulatory benchmark at the heart of EU integrated pollution prevention and control. It identifies the most capable, currently proven methods available — both the technology and how a plant is run — for cutting emissions and limiting their overall environmental impact. Under Directive 2010/75/EU (the Industrial Emissions Directive), ''techniques'' covers the technology plus how an installation is designed, built, maintained, operated and decommissioned; ''available'' means proven at a scale that is economically and technically workable for the sector, weighing costs against benefits; and ''best'' means most effective at delivering a high overall level of environmental protection. BAT is set out in sector reference documents (BREFs) and made partly binding through BAT conclusions, which fix BAT-associated emission levels used to set permit limit values — including, where relevant, limits on industrial-plant noise. Legal force and the treatment of noise vary by jurisdiction, and related ideas such as ''best available technology'' or ''best practicable means'' exist under other regimes.','BAT stands for best available techniques. It means the best methods to prevent or cut pollution from industry. Regulators pick these methods and write them into permits. The methods must work well and cost a fair amount. They must be ready to use in that industry. In the EU this comes from the Industrial Emissions Directive. Noise can count as a form of pollution here. So a plant may need quieter machines or barriers. Rules and the exact limits differ by country and permit.','BAT exists to set a moving, technically grounded benchmark for permitting industrial installations, so limits reflect what current, viable methods can actually achieve rather than an arbitrary fixed number. It levels the playing field across operators, drives continual improvement as techniques advance, and gives regulators a defensible basis for emission limit values. For noise, it lets authorities require realistic source-control and mitigation measures for plant, infrastructure and industrial sites as part of a whole-environment permit.','An environmental permitting officer consults the relevant BREF and BAT conclusions to set or review permit conditions, including noise-management measures such as low-noise plant selection, enclosures, screening or restricted operating hours, and checks the installation against BAT-associated levels. An operator''s environmental consultant uses the same documents to demonstrate in a permit application that proposed noise and other emission controls meet BAT.','Sound Law — Legal & Regulatory Framework',ARRAY['Industrial Emissions Directive (2010/75/EU)','BAT reference document (BREF)','Emission limit value','Best practicable means (BPM)','As low as reasonably practicable (ALARP)','Environmental permit','Integrated pollution prevention and control (IPPC)']::text[],ARRAY['Reading ''best available'' as ''the single most advanced technology at any cost'' — ''available'' requires the technique to be economically and technically viable considering costs and advantages.','Assuming BAT is purely voluntary guidance; under the EU Industrial Emissions Directive, BAT conclusions are binding and drive permit emission limit values.','Thinking BAT covers only air or water emissions and never noise — BREFs and permits can address noise as part of protecting the environment as a whole.','Treating BAT as a fixed once-and-for-all standard, when it is periodically reviewed and updated as techniques develop.']::text[],ARRAY['A permitting authority sets noise conditions for a new energy-from-waste plant by referencing the applicable BREF and BAT conclusions.','An industrial operator''s consultant prepares a permit variation showing that new acoustic enclosures meet BAT for plant noise.','An environmental regulator audits a factory against BAT-associated emission levels after neighbour noise complaints.','A policy analyst compares the EU BAT regime with a national ''best practicable means'' noise standard for a cross-border project.']::text[],'advanced',NULL,NULL,'2082cf46-6898-40aa-bdb6-03373c9444a2' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Best available techniques (BAT)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '67ef4c3f-83cc-5f61-b551-f64492b474f3','2082cf46-6898-40aa-bdb6-03373c9444a2',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='67ef4c3f-83cc-5f61-b551-f64492b474f3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='67ef4c3f-83cc-5f61-b551-f64492b474f3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e71ca44a-ef46-5658-b0aa-6452f2f2ad3e','dB(A)','The A-weighted decibel: a sound pressure level measured through the A-frequency weighting network standardised in IEC 61672-1 (and ANSI S1.4/S1.43). The A-weighting attenuates low frequencies and very high frequencies to approximate the relative sensitivity of average human hearing at moderate levels, following roughly the inverse of how sensitive the ear is at moderate levels (the 40-phon equal-loudness contour). Because it correlates reasonably with perceived loudness and hearing-damage risk for broadband noise, dB(A) is the dominant metric written into occupational, environmental and entertainment noise law worldwide. A single dB(A) number is only meaningful when its time weighting or averaging (for example Fast, Slow, LAeq or LAmax) and measurement position are also stated, and the specific limits expressed in dB(A) vary by country, city, venue licence, permit, time of day and receiver location.','dB(A) is a way to measure sound. It uses a filter called A-weighting. This filter copies how human ears hear loudness. It cuts very low and very high sounds a bit. So the number reflects what people actually notice. Most noise laws set their limits in dB(A). A dB(A) figure only makes sense with a time rule too. You also need to know where the meter stood. Exact limits differ by country, venue, permit, and time of day.','It exists to turn a physical pressure measurement into a single number that tracks how loud and how harmful broadband sound is to people. By baking human hearing sensitivity into the meter, regulators can write one comparable figure into permits, workplace rules and community-noise standards instead of citing a full frequency spectrum. This makes limits enforceable with an ordinary sound level meter and lets different sites and events be compared on a common scale.','A live-sound or compliance technician sets a class 1 or class 2 sound level meter to A-weighting to log front-of-house or boundary levels against a venue''s licensed dB(A) limit, and an occupational hygienist uses A-weighted readings to decide whether a workplace crosses an action value. The same setting drives limiter thresholds, permit reporting and noise-complaint measurements.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['dB(C)','dB(Z)','LAeq,T','LEX,8h','Lmax','IEC 61672']::text[],ARRAY['Thinking dB(A) measures the ''true'' loudest sound — the A filter deliberately discounts low-frequency energy, so bass-heavy music can feel far louder than its dB(A) number suggests.','Assuming a bare dB(A) value is complete; without a time weighting or averaging period and a stated position it cannot be compared to a legal limit.','UNSAFE: Believing that staying within a dB(A) limit alone rules out hearing risk from concerts or plant — high-energy low-frequency or impulsive peaks can still injure hearing even when the A-weighted average looks acceptable.','Confusing the A-weighting filter with the meter''s Fast/Slow time weighting; they are independent settings.']::text[],ARRAY['A festival compliance officer logs A-weighted levels at the nearest residential boundary to show the licensing authority the event stayed within its permitted dB(A).','A factory hygienist takes A-weighted spot readings to screen which work areas need a full noise-exposure assessment.','A touring engineer aligns the desk output to a venue''s A-weighted limiter so the show does not trip the house cut-off.','An enforcement officer responding to a night complaint records dB(A) at the complainant''s window against the local limit.']::text[],'intermediate','L_A = 10·log10( Σ_i 10^((L_i + A_i)/10) )  dB re 20 µPa','The A-weighted level equals ten times the base-ten logarithm of the sum, taken over frequency bands, of ten raised to the power of each band''s unweighted level plus its A-weighting correction, all divided by ten; levels are referenced to 20 micropascals.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='dB(A)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e71ca44a-ef46-5658-b0aa-6452f2f2ad3e','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e71ca44a-ef46-5658-b0aa-6452f2f2ad3e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e71ca44a-ef46-5658-b0aa-6452f2f2ad3e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3b71ba88-fa8e-57ee-9292-60983662f702','dB(C)','The C-weighted decibel: a sound pressure level measured through the C-frequency weighting network of IEC 61672-1. C-weighting is much flatter than A-weighting across the audible range and rolls off only gently at the extremes, so it retains far more low-frequency energy. It is used where bass content matters or where high peak pressures must be captured — for example the LCpeak descriptor for impulsive and impact noise, and dual A/C limits for amplified music. The difference dB(C) minus dB(A) is a quick indicator of low-frequency content. France''s framework for venues broadcasting amplified sound, for instance, pairs an A-weighted average limit with a separate C-weighted limit to control bass, and the exact figures and averaging periods vary by jurisdiction, venue licence and measurement method.','dB(C) is another sound measurement setting. It uses the C-weighting filter. This filter is much flatter than the A filter. It keeps most of the low, bass sound in the number. So it is good for measuring heavy bass and sharp peaks. Many music-venue rules set a dB(C) limit as well as a dB(A) one. The gap between dB(C) and dB(A) shows how much bass there is. Exact limits and time rules differ by country and venue.','It exists to capture the low-frequency and peak energy that A-weighting deliberately discards. Bass from sound systems and the sharp pressure spikes from pyrotechnics or impacts can be a nuisance or a hazard even when the A-weighted number looks modest, so regulators add a C-weighted limit to close that gap. C-weighting also underpins the standard way of expressing peak sound pressure level for impulsive noise.','A live-sound engineer watches dB(C) alongside dB(A) to keep bass within a venue''s dual-limit licence and to stop sub-bass complaints, while a health-and-safety officer uses LCpeak to check impulsive-noise peaks from tools, pyrotechnics or weapons against a peak limit. The dB(C) minus dB(A) difference is used on site to judge whether low-frequency management is needed.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['dB(A)','dB(Z)','Peak sound pressure level','Lmax','LAeq,T','IEC 61672']::text[],ARRAY['Treating dB(C) as interchangeable with dB(A); at the same source a bass-heavy signal reads substantially higher in dB(C), so the two are not one number offset by a fixed amount.','Assuming C-weighting is ''flat'' or unfiltered — it still rolls off at the frequency extremes and is not the same as Z-weighting.','UNSAFE: Ignoring a venue''s or standard''s C-weighted peak limit because the A-weighted average passes — high LCpeak impulses from pyrotechnics or effects can damage hearing regardless of the average.','Believing the dB(C)-minus-dB(A) difference gives an exact bass spectrum; it is only a coarse indicator of low-frequency content.']::text[],ARRAY['A club engineer keeps sub-bass within a venue''s C-weighted licence limit while still hitting the target A-weighted level for the mix.','A safety officer measures LCpeak from a stage pyrotechnic cue to verify it stays under the impulsive-noise peak limit.','An environmental officer uses the dB(C) minus dB(A) gap in a complaint report to argue that low-frequency noise is the real problem.','A promoter in France configures a limiter to respect both the A-weighted and C-weighted maxima set for amplified-music venues.']::text[],'intermediate','L_C = 10·log10( Σ_i 10^((L_i + C_i)/10) )  dB re 20 µPa;  low-freq indicator = L_C − L_A','The C-weighted level equals ten times the base-ten logarithm of the sum, over frequency bands, of ten raised to each band''s unweighted level plus its C-weighting correction divided by ten; subtracting the A-weighted level from the C-weighted level gives a coarse indicator of low-frequency content.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='dB(C)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3b71ba88-fa8e-57ee-9292-60983662f702','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3b71ba88-fa8e-57ee-9292-60983662f702') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3b71ba88-fa8e-57ee-9292-60983662f702');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d2d71b2-2532-5279-8e88-26e22b1958f9','dB(Z)','The Z-weighted (zero-weighting) decibel: a sound pressure level with essentially flat frequency response, standardised in IEC 61672-1 with a tolerance band nominally spanning 10 Hz to 20 kHz. Unlike A- and C-weighting, Z-weighting applies no intentional frequency shaping, so the reading reflects the unweighted physical level within the meter''s bandwidth. It is valuable for engineering diagnostics, octave-band analysis and reproducible measurements, but is comparatively rare as a headline public legal limit because it does not track perceived loudness or hearing-damage risk as directly as A-weighting. Where it appears in regulation it is usually alongside spectral or band-limited analysis, and any bandwidth, tolerance and use depend on the standard and instrument class.','dB(Z) means zero weighting. The meter uses no loudness filter here. It reports the raw sound level across its full range. This makes it useful for testing and for band-by-band analysis. Engineers like it because it is repeatable and clean. But laws rarely set a public limit in dB(Z). That is because it does not match how ears sense loudness. It usually appears with detailed frequency analysis instead. The exact range depends on the standard and the meter.','It exists to give an unshaped, reproducible reference measurement before any hearing-based weighting is applied. Because Z-weighting is defined only by a flat tolerance band, it lets engineers and standards compare instruments, analyse spectra and derive other weightings from a common baseline. It removes the ambiguity of older ''linear'' or ''flat'' settings that differed between makers by fixing the bandwidth in the standard.','An acoustic consultant selects Z-weighting for octave- or third-octave-band analysis of a noise source, to design silencers or barriers from the true spectrum rather than a loudness-shaped number, and instrument makers use it as the defined flat reference for calibration and type testing. It is chosen when the task needs the physical spectrum, not a perceived-loudness figure.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['dB(A)','dB(C)','IEC 61672','LAeq,T','Peak sound pressure level','Lmax']::text[],ARRAY['Assuming dB(Z) and dB(C) are the same; C-weighting still rolls off at the extremes, whereas Z-weighting is defined as flat across its band.','Treating old ''Lin'' or ''flat'' settings as identical to Z-weighting — Z-weighting has a standardised bandwidth and tolerance that legacy linear settings did not.','Expecting a dB(Z) reading to predict loudness or hearing risk; without weighting it overstates the perceptual and hazard contribution of inaudible or very low frequencies.','Thinking Z-weighting captures all frequencies without limit, when it is bounded by the instrument''s defined bandwidth and class tolerances.']::text[],ARRAY['A consultant runs Z-weighted third-octave measurements of a chiller plant to size an acoustic enclosure from its true spectrum.','A calibration lab type-tests a sound level meter against the Z-weighting tolerance band from IEC 61672.','A live-sound designer inspects the unweighted low-frequency spectrum of a subwoofer array during system tuning.','A researcher records Z-weighted data so colleagues can later re-derive A- and C-weighted results from the same file.']::text[],'intermediate','L_Z = 20·log10( p / p0 ),  p0 = 20 µPa  (no frequency weighting within the defined band)','The Z-weighted level equals twenty times the base-ten logarithm of the measured sound pressure divided by the reference pressure of twenty micropascals, with no frequency weighting applied inside the instrument''s defined bandwidth.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='dB(Z)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d2d71b2-2532-5279-8e88-26e22b1958f9','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d2d71b2-2532-5279-8e88-26e22b1958f9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d2d71b2-2532-5279-8e88-26e22b1958f9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4115ee4a-39fd-5de9-adad-c90a4067e9da','LAeq,T','The equivalent continuous A-weighted sound pressure level over a stated period T: the constant A-weighted level that would contain the same total sound energy as the actual, fluctuating sound over that period. It integrates the A-weighted mean-square pressure across T and expresses it as a single level, so it is an energy average, not an arithmetic one. The averaging period T must always be stated (for example LAeq,15min, LAeq,1h, LAeq,8h or an event period) because the same source yields different LAeq values over different windows. LAeq,T is the backbone descriptor for occupational exposure, environmental noise mapping under ISO 1996 and the EU Environmental Noise Directive, and amplified-music limits, though the exact period, limit and measurement method vary by jurisdiction and licence.','LAeq,T is an energy average of sound over a time T. It is the steady level with the same energy as the real changing sound. Loud short bursts count a lot because energy adds up. You must always state the time period T. The same source gives a different LAeq over a different window. Rules use it for work noise, maps, and music limits. A short-time and a full-day LAeq are not the same. Exact periods and limits differ by country and permit.','It exists to reduce noise that varies moment to moment into one fair, energy-based number that can be compared to a limit. A simple peak or average would either overreact to one spike or hide sustained loudness; the equal-energy integral captures total dose over the chosen window. This makes it the natural basis for exposure limits, noise maps and event conditions, and it lets short and long periods be combined correctly.','A compliance officer measures LAeq over a defined window — a 15-minute sample at a boundary, an hour of plant operation, or a full show — and compares it to the value in a licence, permit or standard. Occupational assessors build a worker''s daily exposure from LAeq of each task, and festival teams log rolling LAeq to keep an event within its condition and to evidence compliance afterward.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['dB(A)','LAeq,8h','LEX,8h','Lmax','3 dB exchange rate','Peak sound pressure level']::text[],ARRAY['Reading LAeq as a simple arithmetic average of decibel readings; it is an energy average, so a few loud moments raise it far more than quiet ones lower it.','Quoting an LAeq without its period T — LAeq,15min and LAeq,8h from the same source can differ by many decibels.','UNSAFE: Assuming a passing LAeq guarantees safe exposure while ignoring high individual peaks; short impulsive spikes can injure hearing even when the energy average is within a limit.','Believing you can average two LAeq values by adding and halving them, instead of combining them on an energy (logarithmic) basis weighted by duration.']::text[],ARRAY['A festival team logs rolling LAeq,15min at the mix position to hold a show within its licensed music limit.','An occupational assessor measures LAeq for each noisy task on a stage build to compute a crew member''s daily exposure.','An environmental consultant reports LAeq over day and night periods for a noise map under the EU Environmental Noise Directive.','An enforcement officer captures a 15-minute LAeq at a complainant''s facade to compare with the local standard.']::text[],'intermediate','L_Aeq,T = 10·log10( (1/T) ∫_0^T ( p_A(t)^2 / p0^2 ) dt ),  p0 = 20 µPa','The equivalent continuous A-weighted level over period T equals ten times the base-ten logarithm of the time average, over that period, of the squared A-weighted sound pressure divided by the squared reference pressure of twenty micropascals.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LAeq,T');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4115ee4a-39fd-5de9-adad-c90a4067e9da','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4115ee4a-39fd-5de9-adad-c90a4067e9da') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4115ee4a-39fd-5de9-adad-c90a4067e9da');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b8a00d6-8b64-5201-bef7-98ebac133bcd','LAeq,8h','The equivalent continuous A-weighted sound pressure level determined over, or normalised to, an eight-hour period — the energy-average A-weighted level representing a nominal working day. It is the exposure descriptor used in several occupational-noise regimes: for example Australian model WHS law (aligned with AS/NZS 1269) sets an exposure standard of LAeq,8h of 85 dB(A) together with a peak limit of LC,peak 140 dB(C). Where a shift is not exactly eight hours, measured LAeq over the actual working time is normalised to the eight-hour reference so different shift patterns can be compared on one scale. The precise limit value, peak criterion and the way partial exposures are combined vary by jurisdiction and standard.','LAeq,8h is the energy-average A-weighted level for a work day. It represents eight hours of exposure. If a shift is not eight hours, the value is scaled to eight. This lets different shift lengths be compared fairly. Some countries set the limit at 85 dB(A) for LAeq,8h. Australia, for example, pairs it with a peak limit of 140 dB(C). Crossing these values triggers controls and hearing checks. Exact numbers and rules differ by country and standard.','It exists to express a whole day''s noise exposure as one level tied to a standard eight-hour reference, so occupational limits can be set and enforced consistently. By normalising real shifts to eight hours it removes the confusion of comparing exposures of different lengths, and by pairing with a peak criterion it guards against both sustained energy and dangerous impulses. It is the trigger quantity for engineering controls, hearing protection and audiometry.','An occupational hygienist measures noisy tasks, converts the results to LAeq,8h, and compares them with the jurisdiction''s exposure standard to decide whether controls, hearing protection zones or health monitoring are required. For a touring crew, an assessor might combine soundcheck, show and load-out noise into an eight-hour figure to document each role against the workplace limit.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['LAeq,T','LEX,8h','LEP,d','dB(A)','Peak sound pressure level','3 dB exchange rate']::text[],ARRAY['Confusing LAeq,8h with the instantaneous level during work; it is an energy average across the day, not the loudest moment.','Assuming a short but very loud task cannot breach an eight-hour limit — normalising to eight hours can still push a brief high exposure over the standard.','UNSAFE: Treating an LAeq,8h at the limit as fully protective; some workers still suffer hearing loss at 85 dB(A), which is why regimes require protection and monitoring rather than exposure right up to the number.','Believing the 85 dB(A) figure is universal; it is the exposure standard in some regimes such as Australia''s model WHS law, while other systems use different values or descriptors.']::text[],ARRAY['An Australian WHS officer computes crew LAeq,8h and LC,peak on a concert build to check against the 85 dB(A) / 140 dB(C) exposure standard.','A hygienist normalises a 10-hour shift''s measured noise to an eight-hour reference to compare with the workplace limit.','A production manager uses LAeq,8h estimates to plan job rotation so no crew member exceeds the daily exposure standard.','An inspector reviews a venue''s records of LAeq,8h to confirm a hearing-conservation program was correctly triggered.']::text[],'intermediate','L_Aeq,8h = L_Aeq,Te + 10·log10( Te / 8h ),  Te = actual exposure duration','The eight-hour equivalent level equals the equivalent continuous A-weighted level measured over the actual exposure duration, plus ten times the base-ten logarithm of that duration divided by eight hours.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LAeq,8h');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b8a00d6-8b64-5201-bef7-98ebac133bcd','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b8a00d6-8b64-5201-bef7-98ebac133bcd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b8a00d6-8b64-5201-bef7-98ebac133bcd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3ab15de9-ff9c-5f75-a4f4-734389b4ffc9','LEX,8h','The daily noise exposure level: a worker''s A-weighted equivalent continuous level normalised to a nominal eight-hour working day, combining all noise exposures during the day regardless of the shift''s actual length. It is the core exposure descriptor in EU Directive 2003/10/EC and its national transpositions (for example the UK Control of Noise at Work Regulations 2005). Those rules attach action and limit values to it: for instance under 2003/10/EC a lower exposure action value of 80 dB(A), an upper exposure action value of 85 dB(A), and an exposure limit value of 87 dB(A) — the limit value applying with account taken of hearing-protector attenuation. Exact figures, how protector attenuation is credited, and enforcement all depend on the transposing national law.','LEX,8h is a worker''s daily noise exposure. It scales the day''s noise to an eight-hour value. It adds up all noise from every task in the day. The EU noise directive builds its rules around it. For example, 80 dB(A) is the lower action value. 85 dB(A) is the upper action value. 87 dB(A) is the exposure limit value. The limit counts the protection that ear defenders give. Exact figures and rules depend on national law.','It exists to give one enforceable daily figure that folds every noisy task into a fair, energy-based whole-day exposure. By fixing an eight-hour reference and attaching tiered action values, the law can require escalating controls: information and hearing protection availability at the lower value, protection use and zoning at the upper value, and a hard ceiling at the limit value that must not be exceeded at the ear. It standardises how varied jobs and shift lengths are compared.','A noise assessor following ISO 9612 measures each task, combines them into LEX,8h, and places a worker against the lower action, upper action and limit values to decide what the employer must do — provide protectors, mandate their use, mark hearing-protection zones, or reduce exposure. For a sound crew, the assessor documents each role''s LEX,8h and, when checking the limit value, credits the real-world attenuation of the hearing protection worn.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['LEP,d','LEP,w','LAeq,8h','3 dB exchange rate','dB(A)','Peak sound pressure level']::text[],ARRAY['Thinking LEX,8h is the level during work; it is the day''s total exposure scaled to eight hours, so a 4-hour job at a high level and an 8-hour job at a lower level can give the same LEX,8h.','Assuming the 87 dB(A) exposure limit value is measured at the ear without protection — under 2003/10/EC the limit value is assessed taking hearing-protector attenuation into account, while action values are not.','UNSAFE: Believing exposure is safe as long as it sits just under the upper action value; the directive still requires reducing risk to a minimum, because hearing damage can occur below the limit value.','Treating the EU action/limit values as global; the US OSHA system uses different descriptors, a 90 dB(A) PEL and a 5 dB exchange rate instead.']::text[],ARRAY['A UK safety adviser calculates a stagehand''s LEX,8h across soundcheck, show and load-out to test it against the Control of Noise at Work action values.','An EU factory assessor combines several machine tasks into one daily exposure and issues mandatory hearing protection above the upper action value.','A touring compliance officer credits measured earplug attenuation when checking a monitor engineer''s LEX,8h against the 87 dB(A) limit value.','A labour inspector audits an employer''s LEX,8h assessments after a worker files a noise-induced hearing-loss claim.']::text[],'intermediate','L_EX,8h = L_Aeq,Te + 10·log10( Te / T0 ),  T0 = 8 h','The daily noise exposure level equals the equivalent continuous A-weighted level over the effective daily exposure time, plus ten times the base-ten logarithm of that exposure time divided by the eight-hour reference duration.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LEX,8h');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3ab15de9-ff9c-5f75-a4f4-734389b4ffc9','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3ab15de9-ff9c-5f75-a4f4-734389b4ffc9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3ab15de9-ff9c-5f75-a4f4-734389b4ffc9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '04493373-8909-5081-a3aa-d15b2d13b0ef','LEP,d','Daily personal noise exposure: the A-weighted equivalent continuous level to which a worker is exposed over the working day, normalised to a nominal eight hours. LEP,d is an older notation for the same quantity now commonly written LEX,8h; UK guidance and the Control of Noise at Work Regulations 2005 use daily personal noise exposure with action values expressed against it. It combines all of a day''s noise exposures into one figure and, like LEX,8h, is compared to tiered action and limit values — for example, in the EU/UK scheme a lower action value of 80 dB(A), an upper action value of 85 dB(A) and an exposure limit value of 87 dB(A) (the limit taking protector attenuation into account). The exact numbers and method depend on the transposing law.','LEP,d is a worker''s daily personal noise exposure. It is the day''s noise scaled to eight hours. LEP,d is an older name for the same idea as LEX,8h. UK noise rules still use this label. It adds all the day''s noisy tasks into one number. That number is checked against action and limit values. In the EU/UK scheme these are 80, 85 and 87 dB(A). Exact figures and methods depend on national law.','It exists to express one worker''s whole-day noise dose as a single comparable level, so employers can be held to tiered duties. It is functionally identical to LEX,8h and survives mainly as legacy notation; keeping the two names linked prevents confusion when reading older assessments, instruments and guidance against current standards. It drives the same escalating controls once action or limit values are crossed.','A UK-based assessor reports a worker''s LEP,d and maps it to the action values to decide on hearing protection, zoning and health surveillance, and recognises LEP,d and LEX,8h as the same quantity when reconciling older dosimeter outputs with newer software. On a production, the figure documents each crew role''s daily exposure for the noise risk assessment.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['LEX,8h','LEP,w','LAeq,8h','3 dB exchange rate','dB(A)','Peak sound pressure level']::text[],ARRAY['Thinking LEP,d and LEX,8h are different metrics; they denote the same daily-exposure quantity, just in older versus current notation.','Assuming LEP,d is a measured level rather than a day''s exposure normalised to eight hours, so a short loud job can give a high LEP,d.','UNSAFE: Treating an LEP,d just below the upper action value as automatically safe; the law still requires reducing exposure so far as is reasonably practicable because harm can occur below the limit.','Reading the 87 dB(A) limit value as an unprotected level, when in the EU/UK scheme it is assessed taking hearing-protector attenuation into account.']::text[],ARRAY['A UK noise consultant records LEP,d for a road crew and issues mandatory hearing protection where it exceeds the upper action value.','An assessor reconciles a legacy dosimeter''s LEP,d output with new software that labels the same result LEX,8h.','A venue''s safety officer documents each stagehand''s LEP,d in the noise risk assessment for an inspector.','An occupational-health nurse uses LEP,d records to decide which workers need audiometric surveillance.']::text[],'intermediate','L_EP,d = L_Aeq,Te + 10·log10( Te / T0 ),  T0 = 8 h  (≡ L_EX,8h)','Daily personal noise exposure equals the equivalent continuous A-weighted level over the effective daily exposure time plus ten times the base-ten logarithm of that time divided by the eight-hour reference; it is the same quantity as LEX,8h.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LEP,d');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '04493373-8909-5081-a3aa-d15b2d13b0ef','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='04493373-8909-5081-a3aa-d15b2d13b0ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='04493373-8909-5081-a3aa-d15b2d13b0ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'abf14c2f-91d8-57e0-9c7f-669d69a1f99d','LEP,w','Weekly personal noise exposure: the A-weighted noise exposure of a worker averaged, on an energy basis, over a nominal working week of five eight-hour days. It is used where daily exposure varies substantially from day to day, so a single day''s LEP,d or LEX,8h would misrepresent the real risk. EU Directive 2003/10/EC and the UK Control of Noise at Work Regulations 2005 allow the weekly value to be used in place of the daily value in such cases, with the same action and limit values applied on a weekly basis. It is computed by energy-combining each day''s normalised daily exposure across the week. When a weekly value may be used, and how it is calculated, depend on the transposing national law.','LEP,w is a worker''s weekly noise exposure. It energy-averages the daily exposures over a week. A week is treated as five eight-hour days. It is used when daily noise varies a lot. One busy day and several quiet days can then be judged fairly. The EU and UK rules allow this weekly figure. The same action and limit values then apply weekly. When you may use it depends on national law.','It exists to handle jobs where noise is very uneven across the week — one loud day and several quiet ones. Judging such work by a single day would overstate or understate the risk, so the law permits an energy-weighted weekly average instead. This keeps exposure limits fair for irregular patterns while preserving the equal-energy principle, and it lets planners spread noisy work to stay within limits.','An assessor uses LEP,w when a worker''s days differ greatly — for example a live-sound tech with one festival day and several quiet office days — energy-combining each day''s exposure into a weekly figure to compare with the action and limit values. Production planners also use it to schedule occasional very noisy days without breaching the weekly exposure standard.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['LEP,d','LEX,8h','LAeq,8h','3 dB exchange rate','dB(A)','Peak sound pressure level']::text[],ARRAY['Assuming the weekly value may always replace the daily one; regimes permit it only where daily exposure varies markedly from day to day.','Averaging daily exposures arithmetically; LEP,w is an energy (logarithmic) combination of each day''s exposure across the week.','UNSAFE: Using a weekly average to justify one extremely loud day; a single day''s very high exposure or peak can still injure hearing even if the weekly figure passes.','Forgetting that peak sound pressure limits still apply independently of any daily or weekly averaging.']::text[],ARRAY['An assessor computes LEP,w for a freelance engineer whose one festival day dwarfs the rest of the week''s noise.','A UK employer justifies using the weekly value for a maintenance crew with highly irregular noisy shifts.','A production planner schedules an occasional pyrotechnic-heavy show so a crew member''s weekly exposure stays within the limit.','An inspector checks whether an employer correctly qualified to use LEP,w instead of the daily value.']::text[],'advanced','L_EP,w = 10·log10( (1/5) · Σ_{i=1}^{m} 10^(0.1·L_EX,8h,i) )','Weekly personal noise exposure equals ten times the base-ten logarithm of one fifth of the sum, over the working days of the week, of ten raised to one tenth of each day''s eight-hour daily noise exposure level.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LEP,w');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'abf14c2f-91d8-57e0-9c7f-669d69a1f99d','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='abf14c2f-91d8-57e0-9c7f-669d69a1f99d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='abf14c2f-91d8-57e0-9c7f-669d69a1f99d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bf34498e-3003-5d90-a98f-50205da722e2','Dose exchange rate','The exchange rate (also called the trading ratio or time-intensity trade-off) is the increase in sound level, in decibels, that is treated as equivalent to halving the permitted exposure time in a noise-dose calculation. It sets how a dosimeter converts fluctuating levels into a cumulative percentage dose, and therefore how quickly allowable time falls as level rises. Regulators differ: the US OSHA occupational scheme uses a 5 dB exchange rate, while NIOSH and the EU/UK and most international occupational schemes use a 3 dB (equal-energy) exchange rate. Because the choice materially changes the computed dose and TWA, the exchange rate must be stated with any dose figure, and which rate applies depends on the governing standard and jurisdiction.','The exchange rate links loudness to allowed time. It is the dB rise that means you halve the safe time. It controls how a dosimeter builds up a percentage dose. A smaller exchange rate cuts allowed time faster as sound rises. The US OSHA rule uses 5 dB. NIOSH, the EU and the UK use 3 dB. So the same noise can give a different dose under each rule. Always state which exchange rate was used.','It exists to define the trade-off between how loud a noise is and how long a person may be exposed to it before reaching a full dose. Without a fixed rule, a fluctuating level could not be reduced to one comparable dose figure. The exchange rate encodes an assumption about how hearing risk accumulates, which is why the science-favoured equal-energy 3 dB rate and the historical US 5 dB rate can disagree markedly for intermittent noise.','A hygienist sets the dosimeter''s exchange rate to match the governing law — 5 dB for US OSHA compliance, 3 dB for NIOSH best practice or EU/UK and international work — before measuring, because the same shift can pass under one rate and fail under another. When reporting results across jurisdictions, the tech records the exchange rate alongside the dose and TWA so figures are not misread.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['3 dB exchange rate','5 dB exchange rate','LEX,8h','LAeq,8h','LEP,d','Peak sound pressure level']::text[],ARRAY['Assuming there is one universal exchange rate; the US OSHA scheme uses 5 dB while NIOSH, the EU and the UK use 3 dB, and the choice changes the result.','Believing the exchange rate and the criterion level (the level equal to 100% dose) are the same setting; they are independent dosimeter parameters.','UNSAFE: Using the 5 dB rate to argue that brief very loud bursts are harmless; the equal-energy 3 dB rate, best supported by evidence, counts that energy far more heavily.','Comparing dose figures from two jurisdictions without checking that the same exchange rate and criterion level were used.']::text[],ARRAY['A hygienist configures a dosimeter to 5 dB for a US OSHA compliance survey and to 3 dB for a parallel NIOSH-based risk assessment.','A touring compliance officer explains why a crew member''s dose differs between a US and an EU dataset for the same show.','An expert witness reviews whether the correct exchange rate was applied in a hearing-loss claim.','A safety manager standardises on the 3 dB rate for international tours to keep exposure records comparable.']::text[],'advanced','T(L) = T0 / 2^((L − L0)/q),  q = exchange rate (dB);  Dose% = 100·Σ (C_i / T_i)','The allowed time at a level equals the reference time divided by two raised to the level minus the criterion level, divided by the exchange rate in decibels; total dose in percent is one hundred times the sum over levels of the time spent at each level divided by its allowed time.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dose exchange rate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bf34498e-3003-5d90-a98f-50205da722e2','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bf34498e-3003-5d90-a98f-50205da722e2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bf34498e-3003-5d90-a98f-50205da722e2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd0227c7a-0514-5b07-9f9c-808191ead882','3 dB exchange rate','The 3 dB exchange rate applies the equal-energy principle: a 3 dB increase in sound level exactly doubles sound energy, so it is treated as halving the permitted exposure time, and a 3 dB decrease doubles the allowable time. It is the exchange rate recommended by NIOSH and used in EU Directive 2003/10/EC, the UK Control of Noise at Work Regulations, ISO 1999 and most international occupational schemes, because it matches the physical fact that equal acoustic energy is assumed to carry equal hearing-damage risk. Under it, for example, NIOSH pairs an 85 dB(A) eight-hour recommended exposure limit with halving of allowed time for each further 3 dB. The action and limit values combined with it vary by standard and jurisdiction.','The 3 dB exchange rate follows the equal-energy rule. A 3 dB rise doubles the sound energy. So it halves the safe exposure time. A 3 dB drop doubles the allowed time. It matches real physics: same energy, same assumed risk. NIOSH, the EU, the UK and ISO all use it. NIOSH sets an 85 dB(A) limit for eight hours. Then each extra 3 dB halves the safe time. The paired limits differ by standard and country.','It exists to make exposure trading match the physics of sound energy, so a dosimeter or assessment reflects the total energy a worker actually receives. Because doubling energy is exactly 3 dB, the rule counts loud, short bursts at their true weight rather than discounting them. This is why it is the science-preferred basis for occupational limits and international harmonisation of exposure assessment.','An assessor working to NIOSH, EU, UK or ISO rules sets the dosimeter to a 3 dB exchange rate and, from an eight-hour reference at the criterion level, halves the allowed time for every 3 dB above it — for instance treating a level 3 dB over as permissible for only half the time. It underpins LEX,8h and LAeq calculations, which are inherently equal-energy.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Dose exchange rate','5 dB exchange rate','LEX,8h','LAeq,T','LEP,d','LAeq,8h']::text[],ARRAY['Thinking 3 dB is a small, negligible change; it doubles sound energy and therefore halves the safe exposure time.','Assuming the 3 dB rate is interchangeable with the 5 dB rate; for intermittent noise they give materially different doses.','UNSAFE: Believing that because the average passes, brief 3 dB-plus increases don''t matter — under equal energy each doubling of energy halves the time you can safely spend there.','Confusing the equal-energy exchange rate with the criterion level or action value, which are set separately.']::text[],ARRAY['A NIOSH-based risk assessment for a stage crew uses the 3 dB rate to halve allowed time for each 3 dB above 85 dB(A).','An EU factory hygienist sets dosimeters to 3 dB to compute LEX,8h for a compliance report.','A touring safety manager adopts the 3 dB rate worldwide so exposure data stays consistent across countries.','An acoustics student compares 3 dB and 5 dB results for the same intermittent-noise task to see the divergence.']::text[],'intermediate','T(L) = T0 / 2^((L − L0)/3);  equivalently LEX,8h uses equal-energy (q = 3)','With a 3 dB exchange rate the allowed time equals the reference time divided by two raised to the level minus the criterion level divided by three; equivalently, every 3 dB increase doubles the energy and halves the permitted exposure time.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='3 dB exchange rate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd0227c7a-0514-5b07-9f9c-808191ead882','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d0227c7a-0514-5b07-9f9c-808191ead882') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d0227c7a-0514-5b07-9f9c-808191ead882');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7f463e07-cbaa-5e63-b604-10e2a1c5271e','5 dB exchange rate','The 5 dB exchange rate treats a 5 dB increase in sound level as equivalent to halving the permitted exposure time (and a 5 dB decrease as doubling it). It is the rate used in US occupational-noise regulation under OSHA 29 CFR 1910.95, where a 90 dB(A) eight-hour permissible exposure limit corresponds to 4 hours at 95 dB(A), 2 hours at 100 dB(A), and so on, with dose and TWA computed on that basis. The 5 dB rule assumes intermittent quiet periods allow some hearing recovery, so it discounts short loud bursts more than the equal-energy 3 dB rate does; NIOSH and most international standards reject it in favour of 3 dB. Which rate applies depends entirely on the governing jurisdiction and standard.','The 5 dB exchange rate is a time-loudness trade rule. A 5 dB rise halves the allowed exposure time. A 5 dB drop doubles it. The US OSHA rule uses this rate. Under it, 90 dB(A) is allowed for eight hours. Then 95 dB(A) is allowed for four hours, and 100 for two. It assumes quiet gaps let hearing recover a little. So it counts short loud bursts less than the 3 dB rule. NIOSH and most other standards prefer 3 dB instead.','It exists as the historical basis of the US OSHA dose and TWA calculation, encoding an older assumption that intermittent noise is less harmful than its raw energy suggests. It lets US dosimeters convert a shift into a single dose and TWA against the 90 dB(A) limit. Understanding it matters because a measurement made under the 5 dB rule cannot be compared directly with a 3 dB result without recalculation.','A hygienist doing a US OSHA compliance survey sets the dosimeter to a 5 dB exchange rate, a 90 dB(A) criterion level and (for the action level) 85 dB(A), then reads dose and TWA against those. When the same worker''s exposure must also satisfy NIOSH or an EU client, the tech re-runs the analysis at 3 dB, because the 5 dB rate will report a lower dose for the same intermittent noise.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Dose exchange rate','3 dB exchange rate','LAeq,8h','LEX,8h','Peak sound pressure level','dB(A)']::text[],ARRAY['Assuming the 5 dB rate is the worldwide standard; it is specific to US OSHA occupational rules, while NIOSH, the EU and most countries use 3 dB.','Believing 5 dB and 3 dB rates give similar doses; for intermittent loud noise the 5 dB rate reports a substantially lower dose.','UNSAFE: Relying on the 5 dB rate''s discounting of short loud bursts as proof they are safe; the equal-energy 3 dB rate, better supported by evidence, treats that energy as fully hazardous.','Mixing up the 5 dB exchange rate with the 5 dB difference between OSHA''s 90 dB(A) PEL and 85 dB(A) action level; they are unrelated coincidences of number.']::text[],ARRAY['A US hygienist configures a dosimeter to 5 dB and 90 dB(A) criterion for an OSHA 1910.95 compliance measurement.','A touring compliance officer explains why a crew member''s US dose looks lower than the EU figure for the same show.','An expert reviews whether an employer correctly used the 5 dB rate for a US noise-exposure record.','A safety trainer demonstrates how 90/95/100 dB(A) map to 8/4/2 hours under the 5 dB rule.']::text[],'intermediate','T(L) = 8 / 2^((L − 90)/5) hours;  Dose% = 100·Σ (C_i / T_i);  TWA = 16.61·log10(Dose/100) + 90','Under the 5 dB exchange rate the allowed hours at a level equal eight divided by two raised to the level minus ninety, divided by five; percent dose is one hundred times the sum of time spent at each level divided by its allowed time; and the eight-hour average equals 16.61 times the base-ten logarithm of dose over one hundred, plus ninety.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='5 dB exchange rate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7f463e07-cbaa-5e63-b604-10e2a1c5271e','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7f463e07-cbaa-5e63-b604-10e2a1c5271e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7f463e07-cbaa-5e63-b604-10e2a1c5271e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ac3531a-64af-5664-a67c-0d699395beb8','Peak sound pressure level','Peak sound pressure level is the highest instantaneous sound pressure reached during a measurement, expressed as a level relative to 20 µPa, and captured with a true peak (not RMS, not time-weighted) detector. It is normally measured with C-weighting (LCpeak) so that the low-frequency energy of transients is retained. It is the controlling metric for impulsive and impact noise — pyrotechnics, firearms, cartridge tools, hammering — where a very brief spike can injure hearing before any average responds. Regulators set explicit peak limits: for example EU Directive 2003/10/EC gives a peak exposure limit value of 140 dB(C) (with upper and lower action values of 137 and 135 dB(C)), and US OSHA states impulsive or impact noise should not exceed 140 dB peak. The exact limit, weighting and detector depend on the standard.','Peak sound pressure level is the single highest pressure in a measurement. It is caught by a true peak detector, not an average. It is usually measured with C-weighting, written LCpeak. It matters for sharp bursts like pyrotechnics, guns, and hammering. Such a spike can hurt hearing before any average reacts. The EU sets a peak limit value of 140 dB(C). OSHA says impulse noise should not exceed 140 dB peak. So peaks are limited on top of daily average limits. Exact figures depend on the standard.','It exists because averaged metrics like LAeq or dose can completely miss a single dangerous transient. A pyrotechnic report or gunshot lasting milliseconds may sit below the average limit yet exceed a safe instantaneous pressure and cause immediate, permanent damage. A separate peak criterion guards against this acute mechanism of hearing injury, independent of how long the noise lasts, and forces controls for impulsive sources.','A safety officer uses a meter with a true C-weighted peak detector to check pyrotechnic cues, cartridge tools or firearms against the peak limit, and requires hearing protection or distance whenever LCpeak approaches it. On a show, the pyro and audio teams verify that effect-driven peaks at crew and audience positions stay below the applicable peak exposure value, separately from the event''s average-level compliance.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['dB(C)','Lmax','LAeq,T','LAeq,8h','Dose exchange rate','dB(Z)']::text[],ARRAY['Confusing peak level with Lmax; Lmax is the maximum of a time-weighted (Fast/Slow) level, whereas peak is the true instantaneous maximum and is always higher for transients.','Measuring peaks with A-weighting or an RMS detector, which understates impulsive pressure; peak is normally C-weighted with a true peak detector.','UNSAFE: Assuming a single loud impulse is harmless because the average or dose passes — one 140 dB(C)-class peak from pyrotechnics or a firearm can cause immediate permanent hearing loss.','Treating 140 dB(C) as a universal cutoff; it is the EU exposure limit value and an OSHA impulse ceiling, but action values (137/135 dB(C)) and other regimes differ.']::text[],ARRAY['A pyrotechnician measures LCpeak at the nearest crew position to confirm a stage effect stays under the peak exposure limit.','A range safety officer records peak levels from gunfire to specify hearing protection against impulse noise.','An occupational assessor logs LCpeak from cartridge-operated tools on a construction site against the peak action values.','An enforcement officer investigates a hearing-injury complaint after a fireworks display by checking recorded peak levels.']::text[],'intermediate','L_Cpeak = 20·log10( p_peak / p0 ),  p0 = 20 µPa,  p_peak = max instantaneous C-weighted pressure','Peak sound pressure level equals twenty times the base-ten logarithm of the maximum instantaneous C-weighted sound pressure divided by the reference pressure of twenty micropascals.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Peak sound pressure level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ac3531a-64af-5664-a67c-0d699395beb8','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ac3531a-64af-5664-a67c-0d699395beb8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ac3531a-64af-5664-a67c-0d699395beb8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '35001e8b-29d3-5067-9f0a-8e33a2ff76df','Lmax','Lmax is the maximum time-weighted sound pressure level recorded during a measurement interval — the highest value the meter''s Fast (125 ms) or Slow (1 s) exponential time weighting reaches over the period. Because it depends on the time weighting and the frequency weighting used, it must be reported with both (for example LAFmax for A-weighted Fast, LASmax for A-weighted Slow). It is distinct from the true peak level, which uses an instantaneous detector and reads higher for transients. Lmax is widely written into environmental and entertainment noise conditions to control the loudest single events — a passing train, an aircraft, a loud song — where an average alone would not protect against short intrusive maxima. The chosen weightings, threshold and limit vary by jurisdiction, licence and method.','Lmax is the highest level a meter reaches in a period. It uses the meter''s Fast or Slow time setting. So you must state that setting, like LAFmax or LASmax. It is not the same as the true peak level. The peak detector reacts faster and reads higher. Lmax is used to limit the loudest single events. Examples are a passing train, a plane, or one loud song. It works alongside average limits, not instead of them. Exact settings and limits differ by rule and licence.','It exists to control the loudest single events that an energy average can hide. A quiet-on-average night can still be ruined by one very loud pass-by, so regulators add an Lmax condition to cap individual maxima. It gives a simple, enforceable ceiling on intrusive events for aircraft, rail, road and entertainment noise, complementing LAeq-based average limits and reflecting how people react to sudden loud sounds.','A compliance officer logs LAFmax or LASmax at a receiver to check whether individual events breach a permit''s maximum-event condition, and a festival team sets a limiter and monitors Lmax to stop any single song or effect exceeding a licensed maximum. Airport and rail assessors use Lmax alongside average metrics to characterise the worst single pass-bys for night-time protection.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Peak sound pressure level','LAeq,T','dB(A)','dB(C)','LAeq,8h','IEC 61672']::text[],ARRAY['Confusing Lmax with peak level; Lmax uses Fast or Slow time weighting and reads lower than the true instantaneous peak for transient sounds.','Reporting Lmax without stating its time and frequency weighting, so LAFmax and LASmax get muddled and are not comparable.','Assuming meeting an LAeq limit automatically satisfies an Lmax condition; a low average can still contain a breaching single event.','UNSAFE: Treating a passing Lmax as evidence hearing is protected against impulses — for pyrotechnics and gunfire the true peak level, not Lmax, is the safety-critical measure.']::text[],ARRAY['A licensing officer checks LASmax at a home near a stadium to see if individual events broke the permit''s maximum-level condition.','An airport night-noise study reports LAFmax for the loudest aircraft movements alongside average contours.','A festival team tunes a limiter so no single song''s Lmax exceeds the venue''s licensed maximum.','An enforcement officer measures Lmax during a noise complaint to identify the specific loud events involved.']::text[],'intermediate','L_max = max_{t∈T} L_{Wτ}(t),  W = A or C weighting, τ = Fast (125 ms) or Slow (1 s)','Lmax equals the greatest value, over the measurement interval, of the frequency-weighted and time-weighted sound level, where the time weighting is Fast at 125 milliseconds or Slow at one second and the frequency weighting is stated.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lmax');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '35001e8b-29d3-5067-9f0a-8e33a2ff76df','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='35001e8b-29d3-5067-9f0a-8e33a2ff76df') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='35001e8b-29d3-5067-9f0a-8e33a2ff76df');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f3eb5a57-6d38-5320-a0aa-b6fc7b95a029','Lmin','The minimum time-weighted sound pressure level recorded during a measurement interval: the lowest instantaneous level a sound level meter reaches over the period, at a stated frequency weighting (usually A) and time weighting (Fast or Slow). It marks the floor of the range of levels observed, in contrast to Lmax (the highest) and Leq (the energy average). Because it is a single lowest reading rather than a statistical quantity, its value depends heavily on the chosen weightings and on any brief dip in the signal, and it is not the same as the background level.','Lmin is the lowest sound level during a measurement. A meter tracks the level as it changes. Lmin is the quietest reading it sees. It depends on the time setting, Fast or Slow. It also depends on the weighting, like A or C. Lmin shows the quiet gaps between louder sounds. It is not the same as the average level. It is also not the true background level.','It marks the bottom of the range of levels in a survey, helping describe lulls, quiet periods and the dynamic range of a noise. Reported with Lmax and Leq, it gives a fuller picture of how much a sound varies over time and can help confirm that a meter responded down to genuinely quiet moments.','A technician reports Lmin alongside Lmax and Leq during a survey to show the spread of levels. A compliance officer may check that Lmin fell to a plausible value, confirming the instrument and its settings were working and that quiet intervals really occurred.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Lmax','LAeq','LA90','Fast/Slow time weighting','Sound level meter (IEC 61672)','Percentile level']::text[],ARRAY['Confusing Lmin with LA90; Lmin is the single lowest time-weighted reading, while LA90 is a statistical level exceeded for 90% of the time.','Assuming Lmin represents the true background; a brief dip can push Lmin below the real ambient level.','Forgetting that Lmin depends on the chosen time and frequency weightings, so values are not comparable unless both are stated.']::text[],ARRAY['An acoustic consultant logging Lmin, Lmax and Leq during an overnight survey to describe how quiet a site becomes.','An enforcement officer checking whether a meter''s Lmin fell to a plausible level, confirming the instrument worked.','A venue technician reviewing Lmin between songs to gauge the quiet points of a set.']::text[],'beginner',NULL,NULL,'16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lmin');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f3eb5a57-6d38-5320-a0aa-b6fc7b95a029','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f3eb5a57-6d38-5320-a0aa-b6fc7b95a029') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f3eb5a57-6d38-5320-a0aa-b6fc7b95a029');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e271e245-ac74-5aa3-9327-99b65acf8eaf','LA10','The A-weighted sound pressure level exceeded for 10% of a stated measurement period, written LA10,T; a statistical (percentile) descriptor of a fluctuating noise. Because it reflects the higher, more intrusive part of the level distribution while ignoring rare extreme peaks, it has long been used in road-traffic and entertainment-noise criteria. In New South Wales, for example, standard licence conditions for licensed and live-entertainment venues are expressed as LA10 levels relative to background at the nearest affected residence. Percentile conventions and the exact criteria vary by standard and jurisdiction.','LA10 is a sound level passed only part of the time. It is the A-weighted level beaten for 10% of the measured time. So the sound is above LA10 one-tenth of the time. This picks out the louder, more annoying part of the noise. Road noise and venue noise often use LA10. In New South Wales, venue limits use LA10 near homes. The exact rules change by place and standard.','It gives regulators a robust handle on the intrusive upper portion of a fluctuating noise without being distorted by a single extreme peak. It is used to set and check limits where the louder, more disturbing part of the noise is what matters, such as traffic flow or entertainment noise reaching homes.','An acoustic consultant measures LA10 at a complainant''s boundary and compares it with a licence condition, such as LA10 not exceeding background by a set margin. A council officer uses LA10 to quantify traffic or venue intrusion in an assessment report.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['LA90','LAeq,15min','Background correction','BS 4142','Percentile level','Rating level']::text[],ARRAY['Reading LA10 as a maximum; it is exceeded 10% of the time, so brief peaks (Lmax) are higher.','Assuming LA10 equals LAeq; for fluctuating noise the two differ and are not interchangeable.','Forgetting to state the time base T; LA10 over 15 minutes and over an hour are different figures.']::text[],ARRAY['A consultant assessing a bar against an NSW LA10 licence condition at the nearest bedroom window.','A highway engineer using LA10 to describe peak traffic intrusion in a planning report.','A council officer comparing measured LA10 with a consent limit after neighbour complaints.']::text[],'intermediate','LA10,T = the A-weighted level exceeded for 10% of time period T','LA10 over a period is the A-weighted sound level that the measured level exceeds for ten percent of that period.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LA10');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e271e245-ac74-5aa3-9327-99b65acf8eaf','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e271e245-ac74-5aa3-9327-99b65acf8eaf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e271e245-ac74-5aa3-9327-99b65acf8eaf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '870c2afa-7a8d-5874-993d-c07ddcb098d2','LA90','The A-weighted sound pressure level exceeded for 90% of a stated measurement period, written LA90,T. Because it reflects the level present for almost all of the time, it is used as the background (residual) sound level in assessment methods such as BS 4142 and ISO 1996-2, and in planning and plant-noise criteria. It is a statistical descriptor, distinct from Lmin (the single lowest reading), and its value varies with time of day, day of week and season.','LA90 is the level present most of the time. It is the A-weighted level beaten for 90% of the time. So the sound stays above LA90 nearly all the time. This makes LA90 a good measure of background sound. Methods like BS 4142 use LA90 as the background level. Planners use it to judge new noise sources. The value depends on the time and place.','It provides a stable, agreed measure of the quiet underlying background against which a new or specific source is judged. It underpins the ''how much louder than background'' logic used in nuisance, planning and industrial-noise assessment.','An acoustic consultant records LA90 with the source off, or during lulls, to establish the background, then compares the source''s rating level to it under BS 4142. Planners set conditions a few decibels above the measured LA90.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['LA10','Background correction','Rating level','BS 4142','ISO 1996-2','Residual sound level']::text[],ARRAY['Treating LA90 as the true minimum; it is a statistical background, not the single lowest reading (Lmin).','Measuring LA90 while the source is running and calling it background, which contaminates the result.','Assuming one LA90 fits all times; background differs by day, night and season.']::text[],ARRAY['A consultant establishing night-time LA90 background before assessing a proposed heat pump under BS 4142.','A planning officer setting a plant-noise condition a few decibels above measured LA90.','An enforcement officer using LA90 to show a venue raised the background level in nearby homes.']::text[],'intermediate','LA90,T = the A-weighted level exceeded for 90% of time period T','LA90 over a period is the A-weighted sound level that the measured level exceeds for ninety percent of that period.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LA90');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '870c2afa-7a8d-5874-993d-c07ddcb098d2','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='870c2afa-7a8d-5874-993d-c07ddcb098d2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='870c2afa-7a8d-5874-993d-c07ddcb098d2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '56adcb8a-7459-5949-ae7d-93358126bf36','Lden','The day-evening-night sound level: a long-term, A-weighted annual average noise indicator defined in Annex I of the EU Environmental Noise Directive (2002/49/EC). It energy-averages the day, evening and night periods (default 12, 4 and 8 hours) after adding a 5 dB penalty to the evening level and a 10 dB penalty to the night level, to reflect greater sensitivity at those times. It is used for strategic noise mapping and action planning; the EU and EEA commonly report population exposure at and above 55 dB Lden. Period boundaries and application can be adjusted by member states within the Directive, and binding limits differ by country.','Lden is a yearly average noise level for a place. It blends day, evening and night into one number. Evening noise gets a 5 dB penalty added. Night noise gets a 10 dB penalty added. These penalties reflect that noise annoys more later on. The EU uses Lden to map road, rail and plane noise. Maps often show people exposed above 55 dB Lden. Exact hours and limits can vary by country.','It gives Europe a single, comparable long-term indicator so noise from different sources and places can be mapped, compared and acted upon. The evening and night penalties build the time-of-day disturbance difference into that one number.','An environmental authority computes Lden from modelling to draw strategic noise maps and trigger action plans. A planner uses Lden contours to site housing or require mitigation near motorways and airports.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Lnight','Day-evening-night penalty','LAeq,1h','Strategic noise map','Environmental Noise Directive (2002/49/EC)','WHO Environmental Noise Guidelines']::text[],ARRAY['Thinking Lden is measured over a single day; it is a long-term (yearly) average.','Reading 55 dB Lden as a legal limit everywhere; it is mainly an EU reporting and mapping threshold, and binding limits vary by country.','Adding the penalties to a whole meter reading; the +5 and +10 apply to the evening and night period levels inside the energy average.']::text[],ARRAY['A city environmental team producing strategic noise maps of road traffic in Lden for EU reporting.','A planner checking Lden contours before approving flats beside a rail line.','An airport authority preparing an action plan for homes above a chosen Lden level.']::text[],'advanced','Lden = 10·log10{ (1/24)[ 12·10^(Lday/10) + 4·10^((Levening+5)/10) + 8·10^((Lnight+10)/10) ] }','Lden is ten times the log of a twenty-four-hour average of three energy terms: twelve day hours, four evening hours each raised by five decibels, and eight night hours each raised by ten decibels.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lden');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '56adcb8a-7459-5949-ae7d-93358126bf36','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='56adcb8a-7459-5949-ae7d-93358126bf36') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='56adcb8a-7459-5949-ae7d-93358126bf36');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f170ff22-5758-5b0e-9494-7fc89ac82c0b','Lnight','The night-time noise indicator: the A-weighted long-term average sound level over the night period (default 23:00-07:00), defined in Annex I of the EU Environmental Noise Directive (2002/49/EC) and used as the health-related, sleep-focused indicator. As an annual average of the night-period equivalent levels, it is distinct from a single night''s reading. The WHO Night Noise Guidelines for Europe recommend an Lnight,outside of 40 dB, with an interim target of 55 dB. Period boundaries, thresholds and binding limits vary by jurisdiction.','Lnight is the average night-time noise level over a year. It covers the night hours, often 11 pm to 7 am. It uses A-weighting, which matches human hearing. Lnight links noise to sleep and health. The WHO suggests staying under 40 dB Lnight outside bedrooms. Their weaker interim target is 55 dB. The EU uses Lnight in its noise maps. Exact hours and limits vary by country.','It isolates the night period, when sleep disturbance and related health effects dominate, so policy can measure, map and limit night-time noise separately from the day. This lets authorities target the times that most affect rest and health.','An authority maps Lnight to find homes at risk of sleep disturbance near roads, rail or airports and to prioritise night mitigation such as barriers or curfews. Researchers link measured or modelled Lnight to reported sleep and health outcomes.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Lden','Day-evening-night penalty','WHO Night Noise Guidelines','Environmental Noise Directive (2002/49/EC)','LAeq,1h','Strategic noise map']::text[],ARRAY['Confusing WHO''s 40 dB Lnight recommendation with a binding legal limit; national night limits differ.','Assuming Lnight is a single night''s measurement; it is a yearly average of night levels.','Treating a low outdoor Lnight as proof of safe sleep for everyone; sensitive people can still be disturbed, and indoor levels depend on the building.']::text[],ARRAY['An environmental agency mapping Lnight near a motorway to find homes facing sleep disturbance.','A public-health researcher linking measured Lnight to reported sleep problems.','A council weighing a night lorry curfew against modelled Lnight in a residential street.']::text[],'advanced','Lnight = 10·log10[ (1/N) · Σ_i 10^(LAeq,night,i /10) ] over all N night periods in the year','Lnight is ten times the log of the yearly energy average of the A-weighted equivalent night-time levels across all nights.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lnight');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f170ff22-5758-5b0e-9494-7fc89ac82c0b','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f170ff22-5758-5b0e-9494-7fc89ac82c0b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f170ff22-5758-5b0e-9494-7fc89ac82c0b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e57fa422-e6a9-5972-84e6-122f9407da44','Day-evening-night penalty','The fixed decibel additions applied to the evening and night periods within the Lden indicator to reflect people''s greater sensitivity to noise at those times. Under Annex I of the EU Environmental Noise Directive (2002/49/EC), +5 dB is added to the evening period level and +10 dB to the night period level before the twenty-four-hour energy average is formed. It is a calculation weighting, not a measured increase in level. Penalties and period boundaries can be adjusted by member states, and the related US day-night level (Ldn) uses only a 10 dB night penalty with no evening period.','This is the extra weight added to evening and night noise. In the EU Lden metric, evening noise gets +5 dB. Night noise gets +10 dB. The penalty does not mean the meter reads louder. It makes late noise count more in the average. This reflects that noise disturbs more when people rest. So a quiet night source still weighs heavily. The exact penalties can vary by country.','It encodes the time-of-day annoyance and sleep-sensitivity difference into a single indicator, so the same physical level is judged more harshly in the evening and at night. This shapes Lden contours and steers where mitigation and curfews are targeted.','A noise modeller applies the +5 and +10 penalties when computing Lden for maps, which pushes evening and night sources over thresholds sooner and can force earlier curfews or stronger source mitigation. The effect shows up directly in the contour lines planners read.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Lden','Lnight','Environmental Noise Directive (2002/49/EC)','LAeq,1h','Strategic noise map','Ldn (day-night level)']::text[],ARRAY['Thinking the penalty means the meter reads higher at night; it is a calculation weighting, not a measured increase.','Confusing Lden''s +5/+10 penalties with the US Ldn, which adds only a 10 dB night penalty and has no evening period.','Applying the penalties to the final Lden number instead of to the evening and night period levels before averaging.']::text[],ARRAY['A modeller building Lden contours who adds +5 dB evening and +10 dB night to the period levels.','A student comparing the EU Lden penalties with the US day-night level Ldn.','A planner explaining why a mostly-night delivery yard breaches an Lden threshold.']::text[],'intermediate','evening term uses (Levening + 5) dB and night term uses (Lnight + 10) dB inside the Lden energy average','Before averaging, five decibels are added to the evening period level and ten decibels to the night period level.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Day-evening-night penalty');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e57fa422-e6a9-5972-84e6-122f9407da44','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e57fa422-e6a9-5972-84e6-122f9407da44') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e57fa422-e6a9-5972-84e6-122f9407da44');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5fe8ab0d-62f8-53d7-9e3d-dac7cc2a669d','Event LAeq','The A-weighted equivalent continuous sound level averaged over the duration of a performance or event, used to characterise audience noise exposure at concerts and festivals. UK HSE guidance for event organisers recommends, for example, that the Event LAeq in any part of the audience area should not exceed 107 dB and that C-weighted peaks stay below 140 dB; where noise is likely to reach 96 dB, organisers should warn the audience in advance of the risk to hearing. There is no single audience-noise law: values, duties and whether worker or audience rules apply vary by country, venue licence and context.','Event LAeq is the average sound level across a whole show. It sums the sound energy over the event and averages it. Louder moments raise it more than quiet ones. It shows how much sound the crowd takes in overall. UK HSE advice says it should stay under 107 dB in the crowd. It also says to keep C-weighted peaks under 140 dB. Organisers should warn people when sound may reach 96 dB. Audience rules differ from worker rules and by country.','It gives event producers and safety officers a single exposure figure for the audience across a show, so they can judge hearing risk and decide on warnings, protection and speaker positioning. This is distinct from worker dose metrics, which measure a person''s daily exposure at work.','A festival''s sound and compliance lead measures Event LAeq at front-of-house and audience positions, keeps it within the venue licence or HSE-advised figure, adds notices and free earplugs when levels approach the warning threshold, and logs the results for licensing.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['LAeq,15min','LCeq,15min','C-weighted peak (LCpeak)','LEX,8h','Control of Noise at Work Regulations 2005','Sound limiter']::text[],ARRAY['Confusing Event LAeq (audience, over the show) with LEX,8h (a worker''s normalised daily dose).','UNSAFE: Assuming a compliant Event LAeq removes hearing risk for the crowd; long, loud shows can still damage hearing, so warnings and earplugs still matter.','Reading HSE''s 107 dB and 96 dB figures as universal law; they are UK guidance, and audience rules vary by country.','Ignoring peaks; a moderate Event LAeq can still hide dangerous C-weighted peak levels.']::text[],ARRAY['A festival compliance officer logging Event LAeq at several audience points against the site licence.','A production manager adding hearing-risk notices when the show''s Event LAeq is expected near 96 dB.','A council licensing officer reviewing an event''s Event LAeq records after complaints.']::text[],'intermediate','LAeq,T = 10·log10[ (1/T) ∫₀ᵀ (p_A(t)² / p₀²) dt ], with T = event duration and p₀ = 20 µPa','Event LAeq is ten times the log of the time-average, over the event, of the squared A-weighted sound pressure divided by the reference pressure squared.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Event LAeq');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5fe8ab0d-62f8-53d7-9e3d-dac7cc2a669d','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5fe8ab0d-62f8-53d7-9e3d-dac7cc2a669d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5fe8ab0d-62f8-53d7-9e3d-dac7cc2a669d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8ed31f54-06c6-5237-a756-7c7aff9e14fb','LCeq,15min','The C-weighted equivalent continuous sound level over a 15-minute interval. C-weighting is nearly flat across most of the audible range, so LCeq captures low-frequency (bass) energy that A-weighting strongly discounts, making it useful for controlling bass-heavy amplified music. France''s regulation for venues diffusing amplified sound (décret 2017-1244 and its arrêté) sets, for example, a general limit of 118 dB LCeq,15min alongside 102 dB LAeq,15min, with lower limits of 104 dB LCeq,15min and 94 dB LAeq,15min for spaces admitting children aged six and under. Limits, weightings and averaging times vary by jurisdiction.','LCeq,15min is a C-weighted average level over 15 minutes. C-weighting counts bass almost as much as mid tones. So it catches the low, thumping energy that A-weighting misses. This helps control loud bass in clubs and gigs. France caps venues at 118 dB LCeq over 15 minutes. Rooms for young children have a lower cap of 104 dB. It sits beside an A-weighted limit for the same time. Limits and rules vary by country.','It adds a low-frequency control that A-weighted limits alone miss, so bass energy from amplified music can be measured and limited at the venue. This matters both for neighbour nuisance and for the hearing risk that heavy bass can carry.','A club''s sound limiter is set to hold both LAeq,15min and LCeq,15min under the French limits. An acoustic consultant checks LCeq to see whether bass, rather than overall level, is driving neighbour complaints or breaching the C-weighted cap.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['LAeq,15min','C-weighting','Sound limiter','dB(C) − dB(A)','LCpeak','Event LAeq']::text[],ARRAY['Assuming C-weighting equals unweighted (linear); C-weighting still rolls off at the frequency extremes.','Comparing an LCeq figure directly with an LAeq figure; the C value is usually higher because it counts bass.','UNSAFE: Passing an A-weighted limit but ignoring LCeq; heavy bass can remain a hearing and nuisance problem even when LAeq looks acceptable.','Treating France''s 118 dB as a universal limit; values, weightings and times differ by country.']::text[],ARRAY['A Paris club setting its limiter to meet both 102 dB LAeq and 118 dB LCeq over 15 minutes.','A consultant using LCeq to show bass is the cause of complaints from a flat above a bar.','An inspector checking a children''s event against the lower 104 dB LCeq limit.']::text[],'intermediate','LCeq,15min = 10·log10[ (1/T) ∫₀ᵀ (p_C(t)² / p₀²) dt ], with T = 15 min and p₀ = 20 µPa','LCeq over fifteen minutes is ten times the log of the time-average, over that period, of the squared C-weighted sound pressure divided by the reference pressure squared.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LCeq,15min');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8ed31f54-06c6-5237-a756-7c7aff9e14fb','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8ed31f54-06c6-5237-a756-7c7aff9e14fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8ed31f54-06c6-5237-a756-7c7aff9e14fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c07e16b-8139-571d-80f4-59c3f9caa9dd','LAeq,15min','The A-weighted equivalent continuous sound level over a 15-minute interval: the steady level that would contain the same A-weighted sound energy as the actual fluctuating sound during those 15 minutes. It is a common averaging window in music-venue and event regulation because it smooths brief peaks yet still responds within a set. France, for example, sets a general amplified-sound limit of 102 dB LAeq,15min, and 94 dB for spaces admitting children aged six and under. Averaging period and limits vary by jurisdiction.','LAeq,15min is an average sound level over 15 minutes. It is A-weighted to match human hearing. It gives the steady level with the same energy as the real sound. Short quiet gaps and loud peaks both feed into it. Venues and events often use this 15-minute window. France caps amplified sound at 102 dB LAeq over 15 minutes. Rooms for young children have a lower 94 dB cap. Limits and times vary by country.','It gives a short, standard averaging window that smooths brief peaks yet still responds within a set. This lets a venue''s level be capped and checked in near real time by a limiter or an inspector during a performance.','A venue limiter enforces LAeq,15min against the licensed figure, reducing or muting output if the rolling 15-minute average approaches the cap. An officer measures LAeq,15min at the desk or in the room to check compliance during a set.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['LCeq,15min','LAeq,1h','Event LAeq','Sound limiter','A-weighting','LA10']::text[],ARRAY['Thinking a single brief peak breaches an LAeq,15min limit; it is averaged over 15 minutes, so short peaks have limited effect on it.','UNSAFE: Assuming a level under the venue LAeq limit is safe for long exposure; hours at high levels still risk hearing damage.','Confusing LAeq,15min with LAeq,1h; the shorter window reacts faster and can read differently.','Reading France''s 102 dB as a universal figure; limits and averaging times differ by country.']::text[],ARRAY['A club engineer holding the rolling LAeq,15min under the licensed cap during a DJ set.','An officer measuring LAeq,15min at the mixing desk to check a French venue''s compliance.','A festival tech comparing LAeq,15min at several stages against permit conditions.']::text[],'intermediate','LAeq,15min = 10·log10[ (1/T) ∫₀ᵀ (p_A(t)² / p₀²) dt ], with T = 15 min and p₀ = 20 µPa','LAeq over fifteen minutes is ten times the log of the time-average, over that period, of the squared A-weighted sound pressure divided by the reference pressure squared.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LAeq,15min');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c07e16b-8139-571d-80f4-59c3f9caa9dd','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c07e16b-8139-571d-80f4-59c3f9caa9dd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c07e16b-8139-571d-80f4-59c3f9caa9dd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '331a3686-fd65-506c-a91c-3706ee2aa69d','LAeq,1h','The A-weighted equivalent continuous sound level averaged over one hour. It is used where an hourly exposure or emission window suits the assessment or the regulatory category. Switzerland''s Sound and Laser Ordinance, for example, uses hourly averages for amplified events: organisers of events above 93 dB(A) LAeq,1h must notify the authorities and inform the audience, with a general maximum average of 100 dB(A) LAeq,1h. Thresholds, duties and averaging conventions vary by jurisdiction.','LAeq,1h is an average sound level over one hour. It is A-weighted to match human hearing. It gives the steady level holding the same energy as the real sound. It reacts more slowly than a 15-minute average. Switzerland uses hourly limits for loud events. Events over 93 dB(A) must be reported to authorities. The general cap there is 100 dB(A) over an hour. Rules and numbers vary by country.','It provides an hour-long exposure window that some regimes use to categorise and permit events and to relate audience exposure to health-based thresholds over a realistic listening period. A longer window ties the metric to sustained exposure rather than momentary peaks.','A Swiss event organiser measures LAeq,1h, files the required notification when it will exceed the trigger, keeps it under the cap, and provides the audience information or hearing protection that the category demands.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['LAeq,60min','LAeq,15min','Momentary value','Swiss Sound and Laser Ordinance','Event LAeq','Lden']::text[],ARRAY['Confusing the notification trigger with the maximum; some regimes require reporting above one level and cap output at a higher one.','UNSAFE: Believing an hour under a venue LAeq,1h cap is harmless; repeated or longer high-level exposure still risks hearing loss.','Treating Switzerland''s 93 and 100 dB(A) figures as universal; thresholds and duties vary by country.','Assuming LAeq,1h and LAeq,15min give the same value; different windows can read differently for changing sound.']::text[],ARRAY['A Swiss club filing an event notification because its LAeq,1h will exceed 93 dB(A).','An event producer holding LAeq,1h under the 100 dB(A) cap across a headline set.','A regulator checking hourly averages logged by a venue''s monitoring system.']::text[],'intermediate','LAeq,1h = 10·log10[ (1/T) ∫₀ᵀ (p_A(t)² / p₀²) dt ], with T = 1 h and p₀ = 20 µPa','LAeq over one hour is ten times the log of the time-average, over that hour, of the squared A-weighted sound pressure divided by the reference pressure squared.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LAeq,1h');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '331a3686-fd65-506c-a91c-3706ee2aa69d','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='331a3686-fd65-506c-a91c-3706ee2aa69d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='331a3686-fd65-506c-a91c-3706ee2aa69d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a0379e3-b211-5794-9d3c-bec478fce5e2','LAeq,60min','The A-weighted equivalent continuous sound level over a 60-minute (one-hour) window — the same physical quantity as LAeq,1h, often written Leq60'' in European venue guidance. It is the metric on which Switzerland''s tiered event categories are built: hourly averages around 93, 96 and 100 dB(A) separate notification-only, higher-level and maximum categories with escalating duties (audience information, free hearing protection, and rest/respite areas for the loudest and longest events). Category boundaries, metrics and duties vary by jurisdiction.','LAeq,60min is an average sound level over one hour. It is the same as LAeq,1h, just named by the minutes. It is A-weighted to match human hearing. Swiss event rules build categories on this hourly average. Thresholds near 93, 96 and 100 dB(A) set the bands. Louder bands add duties like earplugs and rest areas. Above 93 dB(A) the event must be reported. Exact bands and duties vary by country.','It gives a consistent one-hour metric on which tiered regulatory categories and their duties can be built. Louder events then carry proportionally stronger audience-protection obligations, tying the rules to sustained exposure.','A Swiss promoter classifies an event by its planned LAeq,60min, then meets the duties for that band: notification, audience information, free hearing protection, and rest areas for the highest, longest and loudest events.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['LAeq,1h','Momentary value','Swiss Sound and Laser Ordinance','LAeq,15min','Event LAeq','Hearing protection']::text[],ARRAY['Thinking LAeq,60min differs from LAeq,1h; they are the same one-hour average under different names.','UNSAFE: Assuming the top 100 dB(A) category is safe without protection; an hour near that level can harm hearing, which is why protection is required.','Mixing up the category thresholds with a single limit; the bands trigger different duties, not just one cap.','Reading the Swiss 93/96/100 dB(A) bands as universal; other countries use different metrics and numbers.']::text[],ARRAY['A Swiss festival assigning each stage to a sound category by its expected LAeq,60min.','A promoter arranging a chill-out room because a long set exceeds the higher hourly band.','An inspector auditing whether a venue met the duties for its LAeq,60min category.']::text[],'intermediate','LAeq,60min = 10·log10[ (1/T) ∫₀ᵀ (p_A(t)² / p₀²) dt ], with T = 60 min and p₀ = 20 µPa','LAeq over sixty minutes is ten times the log of the time-average, over that hour, of the squared A-weighted sound pressure divided by the reference pressure squared.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LAeq,60min');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a0379e3-b211-5794-9d3c-bec478fce5e2','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a0379e3-b211-5794-9d3c-bec478fce5e2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a0379e3-b211-5794-9d3c-bec478fce5e2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '47f988fc-2f30-5933-896a-ebd9dcc3477d','Momentary value','A short-duration maximum sound level that must not be exceeded at any instant during an event, used alongside averaged (Leq) limits to cap brief but intense peaks. In the Swiss Sound and Laser Ordinance, for example, the momentary value is specified as a maximum A-weighted, Fast-time-weighted level (LAFmax) of 125 dB(A) that must not be exceeded at any time. It differs from a true acoustic peak (LCpeak), which is unweighted in time and usually higher. The exact metric, time weighting and figure vary by jurisdiction.','A momentary value is a peak limit for a single instant. It caps the loudest moment, not the average. Even a very short burst must stay under it. In Switzerland this value is 125 dB(A), Fast weighting. The sound must never cross that level. It works beside the hourly average limits. It stops brief, painful spikes of sound. The exact figure and setting vary by country.','It protects against sudden, very loud peaks that an average level would hide. This guards hearing and comfort against transient bursts even when the hourly average stays within its limit.','A sound engineer sets the system and limiter so instantaneous peaks stay below the momentary cap, such as 125 dB(A) Fast in Switzerland. Throughout the show they watch the maximum reading, not just the average, to stay compliant.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['LAeq,60min','Lmax','LCpeak','Swiss Sound and Laser Ordinance','Sound limiter','Fast/Slow time weighting']::text[],ARRAY['Confusing the momentary value (a Fast-weighted maximum) with a true peak (LCpeak), which is time-unweighted and usually higher.','UNSAFE: Assuming a compliant hourly average means the peaks are safe; a single loud burst above the momentary cap can still harm hearing.','Ignoring the time weighting; a Fast-weighted maximum differs from a Slow-weighted one.','Treating 125 dB(A) as a universal figure; the momentary limit and metric vary by country.']::text[],ARRAY['A Swiss front-of-house engineer watching the LAFmax so it never crosses 125 dB(A).','A limiter technician setting a peak ceiling to guard against sudden effects or feedback.','An inspector checking logged maximum levels against the event''s momentary limit.']::text[],'intermediate',NULL,NULL,'16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Momentary value');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '47f988fc-2f30-5933-896a-ebd9dcc3477d','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='47f988fc-2f30-5933-896a-ebd9dcc3477d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='47f988fc-2f30-5933-896a-ebd9dcc3477d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b3678521-c757-5fe4-9d0d-89a4dd59e0db','Background correction','The adjustment made when residual (background) noise contributes to a measured total (ambient) level, so that the level of the source alone — the specific sound level — can be estimated by logarithmic (energy) subtraction. In BS 4142 and ISO 1996-2 practice, if the total level exceeds the residual by 10 dB or more the background is negligible and no correction is needed; where the difference is roughly 3 to 10 dB, the specific level is found by subtracting the energies; if the difference is under 3 dB the measurement is unreliable and only an upper-bound estimate can be reported. Exact thresholds and procedures vary by standard.','Background correction removes the background from a measurement. A meter hears both the source and the background together. This method subtracts the background energy to find the source alone. If the total is 10 dB or more above background, ignore the background. If it is 3 to 10 dB above, subtract to get the source. If it is under 3 dB above, the result is unreliable. Methods like BS 4142 set these rules. Exact steps vary by standard.','It lets an assessor isolate the noise actually caused by a specific source from the surrounding background. This way limits and ratings apply to the source itself, not to the whole acoustic environment.','A consultant measures the ambient level with the source running and the residual with it off, checks the difference, and either subtracts to get the specific level or flags the result as an upper bound when the background is too close.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['LA90','Residual sound level','Rating level','BS 4142','ISO 1996-2','Specific sound level']::text[],ARRAY['Subtracting decibels arithmetically (for example 60 − 57 = 3 dB); levels must be combined on an energy basis, not by simple subtraction.','Applying a correction when the source is under 3 dB above background; the result is then too uncertain to trust.','Measuring residual under different conditions (weather, season, time) than the ambient, which biases the correction.','Confusing background correction with the character (tonal or impulsive) penalties added later to form the rating level.']::text[],ARRAY['A consultant subtracting background to isolate a chiller''s specific sound level under BS 4142.','An officer discarding a measurement because the source was under 3 dB above background.','An acoustician re-measuring residual at night to match the source''s operating conditions.']::text[],'advanced','L_specific = 10·log10( 10^(L_ambient/10) − 10^(L_residual/10) )','The specific sound level equals ten times the log of ten-to-the-power of the ambient level over ten minus ten-to-the-power of the residual level over ten.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Background correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b3678521-c757-5fe4-9d0d-89a4dd59e0db','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b3678521-c757-5fe4-9d0d-89a4dd59e0db') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b3678521-c757-5fe4-9d0d-89a4dd59e0db');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cfd960ca-4da5-573f-a14f-ce0017a31324','Tonal penalty','A correction added to a measured specific noise level to account for the extra annoyance caused by an audible tone, giving a higher ''rating level'' that is then compared with a background or limit. In schemes such as BS 4142:2014+A1:2019 and ISO 1996-2, a prominent tone (hum, whine, transformer buzz, fan blade-pass) attracts a fixed decibel addition. Under BS 4142 the subjective method adds +2, +4 or +6 dB where a tone is just, clearly or highly perceptible, while an objective one-third-octave or reference method can give a value on a sliding scale up to about 6 dB. Whether a tone is penalised, the trigger criterion, the size of the addition and the measurement method all vary by standard and jurisdiction.','A tonal penalty adds decibels to a noise reading. It is used when the noise has a clear tone. A tone is a hum, whine, or buzz you can pick out. Tones annoy people more than plain noise. So rules add a few decibels to reflect that. For example, UK BS 4142 adds 2, 4, or 6 dB. The size depends on how easy the tone is to hear. The added level is then checked against a limit. Exact rules differ by country and standard.','It exists because energy-based measures like LAeq understate how disturbing a steady tone is: two sources with the same A-weighted level are not equally annoying if one contains a clear tone. The penalty lets an assessor or regulator capture that extra annoyance in a single rating number, so licensing, planning and complaint decisions reflect the perceived character of a sound, not only its loudness.','An acoustic consultant preparing a BS 4142 report listens for and measures tones from plant such as fans, chillers or transformers, selects the correction from the subjective or one-third-octave method, adds it to the specific sound level to form the rating level, and reports whether that rating level exceeds the measured background by a margin indicating an adverse impact.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Pure tone component','Rating level','BS 4142','ISO 1996-2','Impulse penalty','Tone-to-noise ratio','Specific sound level']::text[],ARRAY['Assuming the penalty is the same everywhere; BS 4142, ISO 1996-2 and national codes use different values, triggers and methods.','Thinking a tone must be loud to attract a penalty; audibility against the surrounding residual noise, not absolute level, is what matters.','Believing the correction changes the measured LAeq itself; it is added to form a separate rating level, leaving the measurement intact.','Treating the subjective +2/+4/+6 dB steps as universal law; they are one method, and the reference or one-third-octave method can give a different value.']::text[],ARRAY['A council environmental health officer assesses a supermarket refrigeration plant humming near homes and applies a tonal correction under BS 4142.','A festival compliance officer notes a generator whine and flags whether a tonal adjustment applies at the nearest dwelling.','A consultant modelling a new electricity substation predicts transformer hum and adds a tonal penalty to test the planning noise limit.','An enforcement team investigating a factory complaint measures a clear fan tone and raises the rating level accordingly.']::text[],'intermediate',NULL,NULL,'16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tonal penalty');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cfd960ca-4da5-573f-a14f-ce0017a31324','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cfd960ca-4da5-573f-a14f-ce0017a31324') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cfd960ca-4da5-573f-a14f-ce0017a31324');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aa858312-5e52-554d-a6e7-9565e658a8fb','Impulse penalty','A correction added to a measured specific noise level to reflect the greater annoyance and startle of impulsive sounds — short bursts with rapid onset such as impacts, hammering, gunshots, pile driving or pyrotechnics — forming a higher rating level for comparison with a background or limit. Under BS 4142:2014+A1:2019 the subjective method adds +3, +6 or +9 dB where impulsivity is just, clearly or highly perceptible, and a reference method can give a value from 0 to 9 dB. ISO 1996-2 and various national schemes characterise impulsive sound differently. The trigger, size of addition and measurement method vary by standard and jurisdiction, and this community-annoyance correction is separate from occupational peak-exposure limits.','An impulse penalty adds decibels for sudden, sharp sounds. These are short bursts like bangs, hammering, or shots. Such sounds startle people more than steady noise. So rules add extra decibels to reflect the added annoyance. For example, UK BS 4142 adds 3, 6, or 9 dB. The size depends on how sharp the sound is. This raises the rating level checked against a limit. Rules and values differ by country and standard.','Impulsive sounds carry more perceived disturbance than their A-weighted energy suggests, partly because rapid onset triggers a startle response. The penalty lets assessors and regulators represent that extra impact in the rating level, so decisions on planning, licensing and complaints account for character as well as measured level.','A consultant assessing a metalworking shop or construction site identifies impulsive events such as drop-forging or piling, chooses the impulsivity correction from the subjective or reference method, adds it to the specific sound level, and reports the resulting rating level against the background for a BS 4142 judgement.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Tonal penalty','Rating level','BS 4142','Peak sound pressure level','Impulsive noise','Specific sound level','ISO 1996-2']::text[],ARRAY['Confusing the community impulse penalty with hearing-protection peak limits; the penalty adjusts an averaged rating level, whereas peak limits (for example the 140 dB(C) exposure limit value under EU Directive 2003/10/EC) guard against hearing damage directly.','Assuming a single fixed value applies everywhere; BS 4142 uses +3/+6/+9 dB while other standards score impulsivity differently.','UNSAFE: Thinking an impulse correction makes a site hearing-safe; a compliant community rating level says nothing about on-site peak exposure, where impulsive impact or pyrotechnic noise can still damage hearing without protection.','Believing only very loud bangs qualify; the trigger is impulsive character relative to the residual noise, not absolute loudness.']::text[],ARRAY['A safety officer at a forging plant notes hammer impacts and applies an impulsivity correction in a community noise assessment.','A pyrotechnics operator at an outdoor show considers how impulsive firework reports are treated in the venue''s noise conditions.','A consultant for a piling contractor adds an impulse penalty when predicting rating levels at nearby homes.','An environmental health team investigating a scrapyard complaint measures repeated metal impacts and raises the rating level.']::text[],'intermediate',NULL,NULL,'16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impulse penalty');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aa858312-5e52-554d-a6e7-9565e658a8fb','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aa858312-5e52-554d-a6e7-9565e658a8fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aa858312-5e52-554d-a6e7-9565e658a8fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd8160598-80df-584a-99d4-a81afb356aec','Low-frequency penalty','A special assessment or correction applied where noise is dominated by low frequencies (broadly the one-third-octave bands from about 10 Hz to 160–200 Hz), which A-weighted metrics tend to underrepresent because A-weighting strongly discounts bass. Rather than one universal figure, regimes use dedicated tools: a common screening indicator is the difference between C-weighted and A-weighted levels (LCeq − LAeq), a large value signalling significant low-frequency content; some regimes then compare one-third-octave band levels against a threshold or audibility curve (for example the UK DEFRA/NANR45 procedure with a night-time criterion) or apply a fixed decibel addition. Whether low frequency is penalised, by what method and by how much varies by country, standard and time of day.','A low-frequency penalty deals with deep bass and rumble. Normal A-weighted meters play down low sounds. So bass can annoy people even when meters read low. This rule adds a check or extra decibels for bass. One quick test compares C-weighted and A-weighted levels. A big gap means strong low-frequency content. Some rules then compare bass bands to a set curve. The UK DEFRA method uses a night-time bass curve. Exact rules and limits differ by country and time of day.','A-weighting was designed around moderate broadband sound and can badly understate the intrusion of bass and rumble, which travels far, penetrates buildings and provokes complaint at levels that look compliant on an A-weighted meter. The low-frequency penalty or dedicated procedure exists to catch that mismatch, so assessment reflects real disturbance from sources such as clubs, HVAC, substations and industry.','When a resident complains of a night-time hum or throb, an environmental health officer measures one-third-octave levels indoors, computes the C-minus-A difference as a screen, and compares band levels with a low-frequency criterion curve (such as the DEFRA procedure) to decide whether a low-frequency problem exists and what mitigation to require.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Low-frequency noise (LFN)','Infrasound','C-weighting','A-weighting','Tonal penalty','DEFRA NANR45 procedure','One-third-octave band']::text[],ARRAY['Assuming a low A-weighted level proves there is no problem; A-weighting discounts bass, so low-frequency noise can still annoy at a compliant dB(A).','Treating the C-minus-A screen as a pass/fail limit; it flags low-frequency content but does not by itself set a legal threshold.','Confusing low-frequency noise with infrasound; low-frequency penalties usually target audible bass (roughly 10–160 Hz), not only sound below 20 Hz.','Believing one universal low-frequency criterion exists; the UK DEFRA curve and the Danish, Swedish and German schemes differ in bands, limits and timing.']::text[],ARRAY['A council officer investigates a neighbour''s report of a night-time bass hum from a nightclub and applies a low-frequency criterion.','A consultant assessing a data-centre''s cooling plant checks the C-minus-A difference to screen for low-frequency intrusion at homes.','An enforcement team compares indoor one-third-octave levels against the DEFRA night curve during a rumble complaint.','A wind-farm objector and developer dispute whether low-frequency content warrants a special assessment beyond the A-weighted limit.']::text[],'advanced','C-A indicator = L_Ceq,T - L_Aeq,T  (dB)','The low-frequency content indicator is the C-weighted equivalent continuous sound level minus the A-weighted equivalent continuous sound level measured over the same period; a large positive difference indicates that low frequencies dominate the sound.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Low-frequency penalty');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd8160598-80df-584a-99d4-a81afb356aec','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d8160598-80df-584a-99d4-a81afb356aec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d8160598-80df-584a-99d4-a81afb356aec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee728cc4-0b95-522c-9f52-2b9c5684e055','Intermittency penalty','A correction added where noise switches on and off or fluctuates irregularly, since intermittent sound is often more noticeable and disturbing than steady sound of the same average level. Under BS 4142:2014+A1:2019, intermittency that is readily distinctive against the residual acoustic environment attracts an addition (commonly +3 dB) as an ''other characteristic'', raising the specific sound level to a rating level. Whether intermittency is corrected, and by how much, varies by standard and jurisdiction; some schemes instead address it through the choice of measurement period or descriptor rather than a fixed penalty.','An intermittency penalty deals with on-and-off noise. Sound that keeps starting and stopping draws attention. It can annoy more than steady noise at the same average. So some rules add a few decibels for it. UK BS 4142 can add about 3 dB when it stands out. This raises the rating level checked against a limit. Not every rule uses this penalty. Values and methods differ by country and standard.','Average metrics like LAeq can smooth over the very feature that makes a noise disturbing — its stop-start pattern. The intermittency correction lets an assessor put that character back into the rating level, so a pump that cycles or a bay door that bangs periodically is judged on how it is actually experienced, not only on its energy average.','A consultant assessing plant that cycles — a compressor, lift motor or loading operation — judges whether the on/off pattern is readily distinctive at the receiver, and if so adds an intermittency correction under BS 4142 before comparing the rating level with the measured background.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Tonal penalty','Impulse penalty','Rating level','BS 4142','Specific sound level','Residual sound level','LAeq']::text[],ARRAY['Assuming intermittency always adds a fixed 3 dB; it is applied only when readily distinctive, and other standards treat it differently or not at all.','Confusing intermittency with impulsivity; impulsive sounds are sharp short bursts, while intermittent sound is a broader on/off or fluctuating pattern.','Thinking a long LAeq automatically captures the disturbance; averaging can hide the stop-start character the penalty is meant to represent.','Believing intermittency and the chosen reference time period are unrelated; the measurement window strongly affects how intermittent operation appears in the result.']::text[],ARRAY['A council officer assesses a car-park barrier that beeps and lifts through the night and considers an intermittency correction.','A consultant evaluating a factory''s cyclic extraction fan judges whether its on/off pattern is readily distinctive at homes.','An enforcement team investigating intermittent loading-bay noise decides whether to raise the rating level under BS 4142.','A planner reviewing a delivery yard weighs how intermittent reversing operations should be represented in the noise assessment.']::text[],'intermediate',NULL,NULL,'16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intermittency penalty');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee728cc4-0b95-522c-9f52-2b9c5684e055','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee728cc4-0b95-522c-9f52-2b9c5684e055') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee728cc4-0b95-522c-9f52-2b9c5684e055');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e59e0d03-f855-5a85-9c57-8b13464d8c8f','Pure tone component','A narrowband, essentially single-frequency spectral element embedded within a broader, more random noise — for example the discrete peak from a fan blade-pass, transformer hum, motor whine or ballast buzz. In a spectrum it appears as a sharp line standing above the surrounding broadband noise. Standards judge whether such a tone is prominent — and therefore whether it attracts a tonal correction — using audibility or ratio criteria, such as the tonal-audibility method in ISO 1996-2 or a tone-to-noise ratio measured in one-third-octave or narrowband (FFT) analysis. The thresholds and methods for deciding prominence vary by standard.','A pure tone component is a single-pitch part of a noise. It sits inside a wider, more random sound. Think of a steady hum inside general machine noise. On a spectrum it shows as a sharp spike. Fans, motors, and transformers often make such tones. Standards check if the tone stands out enough to matter. If it does, a tonal penalty may be added. The test and threshold depend on the standard.','Identifying a pure tone component matters because tones are heard and judged differently from broadband noise; the ear locks onto them and they drive complaints. Detecting and quantifying the tone underpins decisions on whether a tonal penalty applies, what mitigation (for example damping or a blade-pass change) is needed, and how a source is diagnosed.','A consultant runs a narrowband or one-third-octave analysis of a noise recording, identifies discrete tonal peaks against the broadband floor, and applies the standard''s audibility or tone-to-noise-ratio criterion to decide whether the tone is prominent enough to warrant a tonal correction and to trace it to a specific machine.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Tonal penalty','Tone-to-noise ratio','ISO 1996-2','One-third-octave band','Narrowband analysis','Prominent discrete tone','Blade-pass frequency']::text[],ARRAY['Assuming any spectral bump is a prominent tone; standards require the tone to exceed neighbouring bands or the masking threshold by a defined margin.','Thinking one-third-octave analysis always reveals tones; closely spaced tones can need narrowband (FFT) analysis to separate them.','Believing a tone must be loud to matter; audibility relative to the surrounding noise, not absolute level, decides prominence.','Confusing a pure tone with broadband hiss or harmonics; only the discrete narrowband line is the tonal component.']::text[],ARRAY['A consultant diagnosing a rooftop chiller identifies a blade-pass tone and traces it to fan speed.','An environmental health officer confirms a transformer hum as a prominent tone before applying a penalty.','An acoustician commissioning a ventilation system checks whether a motor whine is an audible pure tone at desks.','A wind-farm assessor tests turbine recordings for tonal components under the relevant tonality method.']::text[],'intermediate',NULL,NULL,'16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pure tone component');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e59e0d03-f855-5a85-9c57-8b13464d8c8f','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e59e0d03-f855-5a85-9c57-8b13464d8c8f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e59e0d03-f855-5a85-9c57-8b13464d8c8f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '790089b6-1a6e-52d0-a03d-a635f18047f2','Low-frequency noise (LFN)','Noise in which acoustic energy is concentrated in the low part of the audible spectrum — commonly taken as roughly the one-third-octave bands from about 10 Hz (or 20 Hz) up to 160–200 Hz. Because A-weighting heavily attenuates these frequencies, A-weighted limits can understate LFN''s intrusiveness; it also attenuates slowly with distance and passes readily through building structure, so it is a frequent source of night-time complaint from clubs, HVAC, compressors, substations, wind turbines and industry. Assessment often uses one-third-octave analysis against dedicated criteria rather than a single A-weighted limit, and the exact band range and criteria vary by standard and country.','Low-frequency noise is sound made mostly of deep, low tones. It covers roughly 10 to 160 hertz. Normal A-weighted meters play these sounds down. So the noise can feel worse than the meter shows. Bass also travels far and passes through walls. It often causes night-time complaints. Sources include clubs, fans, and heavy industry. Assessors use band analysis and special curves, not just dB(A). The exact band range differs by standard.','Naming and defining LFN gives regulators and assessors a category that ordinary A-weighted limits handle poorly, so complaints about hums, throbs and rumble can be assessed with fit-for-purpose methods. It underpins dedicated procedures and criteria that protect residents from disturbance an A-weighted metric would miss.','An investigator responding to a persistent indoor hum measures one-third-octave band levels at the affected position, checks them against a low-frequency criterion curve, and identifies the offending plant so mitigation such as anti-vibration mounts or silencers can be specified.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Low-frequency penalty','Infrasound','C-weighting','One-third-octave band','DEFRA NANR45 procedure','Structure-borne noise','Tonal penalty']::text[],ARRAY['UNSAFE: Assuming LFN is harmless because it seems quiet; sustained low-frequency exposure is linked to sleep disturbance and stress, so a low dB(A) reading should not be treated as proof of no effect.','Believing dB(A) fully captures LFN; A-weighting discounts low frequencies, so measure in one-third-octave bands or use a low-frequency method.','Equating LFN with infrasound; LFN is mostly audible bass, while infrasound is below about 20 Hz.','Thinking distance and walls solve LFN; low frequencies travel far and pass through structures more easily than high frequencies.']::text[],ARRAY['A resident reports a night hum; an officer measures band levels and compares them with a low-frequency curve.','A consultant assesses a supermarket''s refrigeration plant for low-frequency intrusion into flats above.','A wind-farm planning hearing debates whether low-frequency content beyond the A-weighted limit is significant.','A factory near homes reviews its compressor foundations after repeated low-frequency complaints.']::text[],'intermediate',NULL,NULL,'16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Low-frequency noise (LFN)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '790089b6-1a6e-52d0-a03d-a635f18047f2','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='790089b6-1a6e-52d0-a03d-a635f18047f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='790089b6-1a6e-52d0-a03d-a635f18047f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f6b6dcf9-57fc-5110-9c82-bd72af4ea70e','Infrasound','Sound at frequencies below the nominal lower limit of normal human hearing, conventionally below 20 Hz, though people can perceive it at high sound pressure levels. It is measured with the G-weighting defined in ISO 7196:1995, which covers 1–20 Hz. Infrasound arises from wind turbines, large fans and compressors, transport, ventilation, explosions and natural sources, and features in disputes because it propagates far with little attenuation and is hard to insulate against. Whether specific infrasound levels cause health or annoyance effects is contested; major reviews report that community and wind-turbine infrasound normally sits below audibility/perception thresholds, but measurement approaches and any limits vary widely by country.','Infrasound is sound below about 20 hertz. That is below normal human hearing. People can still sense it if it is very strong. It is measured with a special G-weighting. Sources include wind turbines, big fans, and transport. It travels far and is hard to block. Its health effects are debated. Most bodies say wind-turbine infrasound is usually below what people perceive. Rules and any limits differ a lot by country.','Defining infrasound separately matters because standard A-weighted noise metrics ignore it almost entirely, yet it is a source of complaint and public concern. A clear definition and the G-weighting give assessors a consistent way to measure very low frequencies and to test claims about sources such as wind farms against evidence.','An acoustician investigating wind-turbine or industrial complaints deploys an infrasound-capable microphone with G-weighting or narrowband analysis, compares measured 1–20 Hz levels with hearing/perception thresholds and any national guidance, and reports whether perceptible infrasound is present.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Low-frequency noise (LFN)','G-weighting','ISO 7196','Wind-turbine noise','Hearing threshold','Low-frequency penalty','C-weighting']::text[],ARRAY['UNSAFE: Assuming inaudible automatically means harmless; while most authorities find wind-turbine infrasound below perception, very high infrasound in some industrial settings can have effects, so exposure should still be characterised.','Believing A-weighted or even C-weighted meters capture infrasound; below 20 Hz you need G-weighting or narrowband measurement.','Treating all wind-farm infrasound claims as proven health harm; major reviews report levels typically below audibility and find weak evidence of direct harm at those levels.','Confusing infrasound with low-frequency noise; infrasound is below about 20 Hz, while LFN is audible bass above it.']::text[],ARRAY['A community group and a wind developer dispute whether turbine infrasound near homes exceeds perception thresholds.','An acoustician measures 1–20 Hz levels near a large industrial fan using G-weighting.','A regulator reviews infrasound evidence when setting conditions for a new wind farm.','A researcher studies infrasound from a compressor station reported by nearby residents.']::text[],'advanced',NULL,NULL,'16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Infrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f6b6dcf9-57fc-5110-9c82-bd72af4ea70e','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f6b6dcf9-57fc-5110-9c82-bd72af4ea70e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f6b6dcf9-57fc-5110-9c82-bd72af4ea70e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a000cc6c-2e59-5987-b2db-937add758808','Ground-borne noise','Low-frequency noise radiated inside a building when ground-transmitted vibration makes floors, walls and ceilings vibrate and re-radiate sound — heard as a low rumble rather than reaching the listener through the air. Typical sources are underground and surface rail, construction (piling, tunnelling) and heavy industry, and the audible rumble usually falls in a low-frequency range (about 16–250 Hz). In US practice (FTA/FRA transit guidance) it is quantified in A-weighted decibels derived from the building vibration, with residential impact criteria on the order of 35–43 dB(A) depending on how often events occur, while the vibration itself is expressed in VdB. Descriptors, criteria and thresholds vary by country, source and building.','Ground-borne noise is a rumble you hear inside a building. It starts as vibration traveling through the ground. That vibration shakes floors and walls. The shaking surfaces then radiate sound into the room. You hear it without any sound coming through the air. Common sources are trains, tunnelling, and heavy industry. It is mostly low-frequency rumble. US transit guidance sets home limits near 35 to 43 dB(A). Limits and methods differ by country and source.','Ground-borne noise exists as a distinct category because it bypasses the airborne path that ordinary walls and windows control, so it cannot be fixed with façade insulation. Defining and measuring it lets engineers assess railway, tunnelling and construction projects and design vibration isolation before rumble reaches occupants.','A rail-project acoustician predicts building vibration from train pass-bys, converts it to a ground-borne noise level, compares it with the transit authority''s criteria, and specifies mitigation such as floating slab track or resilient rail fasteners where the rumble would exceed limits.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Structure-borne noise','Ground-borne vibration','Vibration dose value (VDV)','Airborne noise','VdB (vibration velocity level)','FTA transit noise and vibration guidance','Floating slab track']::text[],ARRAY['Assuming façade sound insulation stops ground-borne noise; it enters through the structure, so isolation at the source or foundation is needed instead.','Confusing ground-borne noise with ground-borne vibration; the vibration is the feelable motion, the noise is the audible rumble it radiates.','Thinking A-weighted airborne limits govern it; transit guidance uses separate ground-borne noise criteria derived from building vibration.','Believing it is a high-frequency problem; the rumble is dominated by low frequencies, roughly 16–250 Hz.']::text[],ARRAY['A metro extension''s design team predicts rumble in flats above a new tunnel and specifies floating track.','A concert hall built over a rail line is assessed for ground-borne noise during quiet passages.','A construction firm piling near a hospital checks predicted ground-borne noise against limits.','A resident above an underground line reports rumble and the operator investigates track isolation.']::text[],'advanced',NULL,NULL,'16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ground-borne noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a000cc6c-2e59-5987-b2db-937add758808','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a000cc6c-2e59-5987-b2db-937add758808') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a000cc6c-2e59-5987-b2db-937add758808');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6ad97667-ab6b-546d-9d0d-33365323e4f1','Structure-borne noise','Noise generated when vibration travels through the solid parts of a structure — floors, walls, columns, pipes — and is re-radiated as airborne sound at some other location, as opposed to sound that travels directly through the air. Impact and machinery sources (footsteps, pumps, lifts, HVAC, slammed doors) inject vibration into the building fabric, which then acts as a sound radiator elsewhere; ground-borne noise is a special case where the vibration enters via the ground. Building acoustics distinguishes it from airborne noise because the transmission path — and therefore the control measures (resilient mounts, floating floors, isolation) — are different. Descriptors and limits vary by code and building type.','Structure-borne noise travels through the solid parts of a building. Vibration moves along floors, walls, and pipes. It then turns back into sound somewhere else. This differs from sound that travels through the air. Footsteps, pumps, and lifts are common causes. The building itself acts like a loudspeaker. Ground-borne rumble is one type of it. Fixes use isolation, resilient mounts, or floating floors. Rules and terms differ by building code.','Separating structure-borne from airborne noise matters because the two need different fixes; adding mass or sealing gaps helps airborne sound but does little for vibration running through the frame. The concept guides where to break the path with resilient layers, isolators and floating floors so machinery and impact noise do not reappear as sound in other rooms.','A building-services engineer isolates a rooftop chiller on spring mounts and floats a plant-room floor so its vibration is not re-radiated as noise in offices below, choosing isolation targets from the structure-borne transmission path rather than from façade insulation.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Airborne noise','Ground-borne noise','Impact sound','Vibration isolation','Floating floor','Flanking transmission','Resilient mount']::text[],ARRAY['Assuming mass or sealed gaps will fix it; structure-borne noise needs the vibration path broken with resilient isolation, not just heavier walls.','Confusing structure-borne with airborne noise; they share a receiver but travel by different paths and need different controls.','Overlooking flanking; vibration can bypass a treated element and re-radiate through connected floors, walls or pipes.','Thinking impact sound such as footsteps is airborne; it is a structure-borne path best controlled with resilient or floating floors.']::text[],ARRAY['An engineer isolates gym equipment above offices so impacts do not radiate as noise below.','A studio designer floats a live room to stop plant vibration re-radiating during recording.','A building-control officer assesses impact sound insulation between flats under the building code.','A hotel investigates lift and pump noise reaching guest rooms through the structure.']::text[],'intermediate',NULL,NULL,'16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Structure-borne noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6ad97667-ab6b-546d-9d0d-33365323e4f1','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6ad97667-ab6b-546d-9d0d-33365323e4f1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6ad97667-ab6b-546d-9d0d-33365323e4f1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '448f9f43-46cb-5f69-aee7-8eb1e77c44eb','Airborne noise','Sound that travels from source to receiver through the air as pressure fluctuations, rather than through solid structure or the ground. It is the everyday transmission path for speech, music, traffic and most environmental noise, and is controlled by distance, barriers, absorption and the airborne sound insulation of building elements such as walls, windows and doors. Building acoustics contrasts it with structure-borne and impact sound, which travel through the fabric, because the distinction determines which insulation strategy applies. It is normally quantified with A-weighted levels and descriptors such as LAeq, and element insulation is rated by quantities like the sound reduction index. Exact limits and rating methods vary by jurisdiction and context.','Airborne noise travels to you through the air. It moves as small changes in air pressure. Speech, music, and traffic reach you this way. Most everyday noise is airborne. You control it with walls, windows, distance, and absorption. This differs from sound that travels through the building frame. Meters usually measure it in dB(A). A wall''s performance is rated by its sound insulation. Limits and methods differ by country and setting.','The airborne category defines the most common noise path and the one most limits and insulation ratings are built around. Naming it separately from structure-borne and impact sound tells a designer which controls to reach for — façade insulation, barriers, absorption and layout — and underpins standard descriptors used across environmental and building noise law.','An acoustic designer sizes glazing and wall build-ups to meet an airborne sound-insulation target between a noisy road or bar and a bedroom, using the sound reduction index of each element and the predicted external LAeq to demonstrate compliance.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Structure-borne noise','Ground-borne noise','Sound reduction index','LAeq','A-weighting','Sound insulation','Noise barrier']::text[],ARRAY['Assuming all noise problems are airborne; footstep and plant noise are often structure-borne and need different controls.','Thinking small gaps can be ignored; airborne insulation is very sensitive to leaks and air paths around a partition.','Believing more mass always wins; resonance, stiffness and flanking also govern airborne insulation, not mass alone.','Treating a wall''s lab-rated insulation as the on-site value; flanking and workmanship usually make field performance lower.']::text[],ARRAY['A designer specifies acoustic glazing so road-traffic noise meets a bedroom''s internal limit.','A venue adds a lobby and seals doors to cut airborne music breakout to the street.','A building-control check measures airborne sound insulation between new flats.','An office fit-out uses absorption and partitions to control airborne speech between rooms.']::text[],'beginner',NULL,NULL,'16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Airborne noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '448f9f43-46cb-5f69-aee7-8eb1e77c44eb','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='448f9f43-46cb-5f69-aee7-8eb1e77c44eb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='448f9f43-46cb-5f69-aee7-8eb1e77c44eb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '584752ea-3af5-53d2-a9b7-f809d132480f','Vibration dose value (VDV)','A cumulative measure of human exposure to vibration (including shock) that emphasises peaks by using the fourth power of the frequency-weighted acceleration integrated over the exposure time. Defined in BS 6472-1:2008 and related to ISO 2631, the VDV is the fourth root of the time integral of the fourth power of the weighted acceleration, with units of metres per second to the power 1.75 (m/s^1.75). Because of the fourth-power law it responds much more strongly to vibration magnitude than to duration, which suits intermittent and impulsive vibration such as from trains or construction. BS 6472-1 gives indicative residential ranges for probability of adverse comment (for example, roughly 0.2–0.4 m/s^1.75 for low probability by day, with lower values at night). Criteria, weightings and axes vary by standard and building use.','The vibration dose value sums up vibration exposure over time. It uses the fourth power of the shaking, so peaks count heavily. Then it takes the fourth root of that total. Its units are metres per second to the power 1.75. Because peaks dominate, it suits bursty vibration well. Trains and construction are common cases. UK BS 6472 links VDV ranges to complaint risk. For example, low daytime risk sits near 0.2 to 0.4 units. Criteria differ by standard, direction, and building use.','Ordinary average measures understate the impact of occasional strong jolts, which drive vibration complaints in buildings. The VDV''s fourth-power weighting captures those transients in a single cumulative figure, giving assessors a metric that correlates better with annoyance and lets them compare intermittent sources such as passing trains against acceptability ranges.','A vibration consultant measures frequency-weighted floor acceleration from train pass-bys or piling over a representative day and night, computes the VDV, and compares it with the BS 6472-1 residential ranges to judge the probability of adverse comment and to size isolation if it is exceeded.','Sound Law — Measurement Descriptors & Compliance Metrics',ARRAY['Ground-borne noise','Ground-borne vibration','BS 6472','ISO 2631','VdB (vibration velocity level)','Root-mean-quad','Frequency weighting (Wb/Wd)']::text[],ARRAY['Reading VDV like an average; its fourth-power basis means a few strong events dominate the total far more than steady vibration.','Ignoring units; VDV is in m/s^1.75, not the m/s^2 of acceleration, so its values are not directly comparable to RMS acceleration.','Assuming one universal threshold applies; BS 6472-1 gives ranges by day/night and building use, and other standards differ.','Forgetting the frequency weighting and axis; the acceleration must be weighted (for example Wb or Wd) and taken in the relevant direction before computing VDV.']::text[],ARRAY['A consultant assesses a new rail line''s vibration in nearby homes using day and night VDV.','A contractor monitors piling vibration and reports VDV against acceptability ranges.','A developer of flats over a railway checks predicted VDV to decide if a floating floor is needed.','An enforcement case over construction vibration compares measured VDV with BS 6472-1 guidance.']::text[],'advanced','VDV = ( ∫₀ᵀ [a_w(t)]⁴ dt )^(1/4)   [units: m/s^1.75]','The vibration dose value equals the fourth root of the time integral, over the exposure period T, of the fourth power of the frequency-weighted acceleration a_w(t); the result is expressed in metres per second to the power 1.75.','16a88917-e3bb-4bc7-ae40-8f8075c7f04c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vibration dose value (VDV)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '584752ea-3af5-53d2-a9b7-f809d132480f','16a88917-e3bb-4bc7-ae40-8f8075c7f04c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='584752ea-3af5-53d2-a9b7-f809d132480f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='584752ea-3af5-53d2-a9b7-f809d132480f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e0aaa783-450c-501e-90fa-67911cd65636','Audience exposure limit','An audience exposure limit is the maximum sound exposure a venue or event may deliver to patrons, expressed with acoustic descriptors and tied to a defined measurement position and averaging time. It is usually stated as an A-weighted equivalent continuous level (LAeq) over a window, sometimes paired with a C-weighted peak or maximum cap. The controlling figure, descriptor, window, and receiver location vary by country, city, venue licence, and measurement method, so no single number is universal. For example, France''s Article R1336-1 of the Code de la santé publique caps venues diffusing amplified music at 102 dB(A) LAeq over 15 minutes and 118 dB(C) over 15 minutes (lower for spaces open to young children), Germany''s DIN 15905-5 uses a 99 dB(A) reference over 30 minutes at the loudest audience area with a 135 dB LpCpeak cap, the Swiss Sound and Laser Ordinance sets a 100 dB(A) hourly maximum, and UK HSE event guidance advises not exceeding an Event LAeq of 107 dB with a 140 dB(C) peak. Some limits are legal ceilings; others are advisory good practice.','An audience exposure limit caps how loud a show can be for the crowd. It protects the ears of people who come to watch. The cap is often an average level over some minutes. Some rules add a cap on short, sharp peaks. The exact number changes by country and venue. For example, France caps venues at 102 dB(A) over 15 minutes. Germany''s DIN 15905-5 uses 99 dB(A) over 30 minutes. Very loud shows can harm hearing.','It exists to protect patrons'' hearing, since audiences are not workers and cannot be assumed to wear protection or control their own exposure. By fixing a descriptor, an averaging window, and a reference position, it converts a health goal into a measurable, enforceable, or auditable ceiling that a venue or promoter can design a show around.','A system tech or compliance officer identifies the controlling limit for the jurisdiction and licence, sets front-of-house levels so the loudest audience area stays under it, and logs LAeq and peak throughout the show to prove the ceiling was respected in a licence review or complaint.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Loudest audience position','Front-of-house reference position','Audience warning notice','Hearing protection availability','Level logging','Sound limiter','Chill-out zone']::text[],ARRAY['Assuming one universal dB number applies everywhere, when the limit, descriptor, averaging window, and measurement position all vary by jurisdiction, licence, and method.','Confusing an advisory good-practice figure (such as UK HSE''s Event LAeq guidance) with a hard legal ceiling like France''s R1336-1 or the Swiss ordinance.','Treating an audience limit as if it were an occupational limit; workplace rules like OSHA 1910.95 or EU 2003/10/EC protect staff, not patrons, and use different thresholds.','UNSAFE: Believing that staying under an average LAeq limit makes brief peaks harmless; a single impulsive peak near 135–140 dB(C) can injure hearing even when the average is compliant.']::text[],ARRAY['A promoter planning an indoor concert in France sets the rig so patron exposure stays under the 102 dB(A) / 118 dB(C) 15-minute limits of Article R1336-1.','A German festival''s acoustician positions a monitoring mic at the loudest audience area to hold the DIN 15905-5 99 dB(A)/30-min reference and 135 dB peak.','A local licensing officer reviews a venue''s stored level logs after a hearing-damage complaint to check whether the audience ceiling was exceeded.','A touring engineer compares the audience limits of three countries on a run and pre-sets scene levels differently for each date.']::text[],'advanced',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audience exposure limit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e0aaa783-450c-501e-90fa-67911cd65636','f31111e1-7660-420a-a3b8-4f55780f8148',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e0aaa783-450c-501e-90fa-67911cd65636') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e0aaa783-450c-501e-90fa-67911cd65636');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8ceb82f3-8ef8-5bb8-bdb7-e1c0771d8947','Amplified-sound event','An amplified-sound event is an event whose sound is produced or reinforced through electroacoustic equipment (loudspeakers driven by microphones, mixers, and amplifiers) rather than by unassisted acoustic sources alone. The term matters legally because many entertainment and public-health rules attach only once amplification is used or once amplified levels cross a stated threshold, drawing a regulatory line between amplified and purely acoustic activity. Which thresholds, permits, and obligations apply varies by jurisdiction, venue licence, and event type. For example, the Swiss Sound and Laser Ordinance imposes duties on events whose amplified level exceeds 93 dB(A) LAeq over an hour, and France''s amplified-music venue regime (R1336-1) applies to premises diffusing amplified sounds; both illustrate how the amplified/non-amplified distinction defines scope.','An amplified-sound event uses speakers and gear to make sound louder. Think of a mixer, amps, and a PA system. Many laws only start to apply once sound is amplified. Some apply only above a set loudness. For example, Swiss rules kick in above 93 dB(A) over an hour. So the gear used, not just the volume, can decide which rules apply.','The concept exists to scope regulation: lawmakers use amplification as a trigger because electroacoustic systems can reach hazardous or disturbing levels far more easily than acoustic sources. Defining the amplified-sound event lets a rule apply to the situations that actually create risk while leaving small acoustic activity outside its reach.','An event producer checks whether a planned show counts as an amplified-sound event under local rules to know which permits, notifications, level limits, and documentation attach; a compliance officer uses the same test to decide whether a licence condition or notification duty is engaged.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Electroacoustically amplified sound','Audience exposure limit','Sound limiter','Level logging','Front-of-house reference position','Hearing protection availability']::text[],ARRAY['Assuming any loud event qualifies; the trigger is usually electroacoustic amplification or a stated amplified level, not loudness from acoustic sources alone.','Thinking the label alone fixes the duties; the specific obligations still depend on the jurisdiction, venue licence, threshold, and event type.','Believing amplified-event rules are only about neighbour nuisance, when many also protect the audience''s own hearing.']::text[],ARRAY['A community hall booking a DJ with a PA checks whether the night counts as an amplified-sound event and needs a licence condition.','A Swiss club running sets above 93 dB(A) LAeq over an hour treats the night as within the Sound and Laser Ordinance''s scope.','An outdoor market with only acoustic buskers concludes its stalls fall outside amplified-event permit thresholds.']::text[],'beginner',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Amplified-sound event');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8ceb82f3-8ef8-5bb8-bdb7-e1c0771d8947','f31111e1-7660-420a-a3b8-4f55780f8148',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8ceb82f3-8ef8-5bb8-bdb7-e1c0771d8947') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8ceb82f3-8ef8-5bb8-bdb7-e1c0771d8947');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6b07983f-d1fa-5b71-95b0-d388c33b9cb6','Electroacoustically amplified sound','Electroacoustically amplified sound is sound generated or reinforced by converting acoustic or electrical signals through electronic amplification and loudspeakers — the microphone-to-amplifier-to-loudspeaker chain characteristic of public-address and sound-reinforcement systems. Continental European regulation, notably the Swiss Sound and Laser Ordinance, uses this precise phrasing to define its subject matter and separate reinforced sound from unamplified acoustic performance. Obligations attach by level and duration and vary by jurisdiction and venue licence. For example, under the Swiss ordinance, organisers of events with electroacoustically amplified sound above 93 dB(A) LAeq over an hour must notify the authority in advance, post hearing-risk information, and provide free earplugs, with further duties (measurement, level recording, respite areas) at higher levels or longer durations, and a 100 dB(A) hourly maximum.','Electroacoustically amplified sound is sound made louder by electronics and speakers. It runs from a mic, through an amp, out of a loudspeaker. Swiss and other European laws use this exact phrase. It sets what the rules cover. For example, Swiss rules apply above 93 dB(A) over an hour. Above that, organisers must warn the crowd and hand out free earplugs. The hourly level must stay under 100 dB(A).','Using a precise technical phrase gives a law a clear, testable boundary: it captures reinforced sound systems that can reach hazardous levels while excluding unassisted acoustic activity. This lets health authorities attach graduated duties to exactly the technology that creates the exposure risk.','A venue operator or touring engineer checks whether their PA output falls under the electroacoustically-amplified-sound definition and its level bands to determine notification, hearing-protection, measurement, and logging duties before doors open.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Amplified-sound event','Audience exposure limit','Hearing protection availability','Level logging','Chill-out zone','Loudest audience position']::text[],ARRAY['Reading the phrase as any loud sound; it specifically means sound reinforced through electronic amplification and loudspeakers, not acoustic-only sources.','Assuming the Swiss thresholds are global; the 93 dB(A) notification trigger and 100 dB(A) hourly cap are specific to the Swiss Sound and Laser Ordinance.','UNSAFE: Assuming that because a night stays under the 100 dB(A) hourly maximum, individual patrons face no hearing risk; sustained levels near that ceiling can still cause temporary or permanent damage without protection.']::text[],ARRAY['A Zurich club notifies the cantonal authority because its planned sets exceed 93 dB(A) LAeq over an hour under the Sound and Laser Ordinance.','A Swiss festival crossing the higher level and duration bands arranges level recording and a quieter respite area for patrons.','A touring engineer maps how one country''s electroacoustic-sound definition differs from a neighbour''s to plan compliance for a multi-date run.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electroacoustically amplified sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6b07983f-d1fa-5b71-95b0-d388c33b9cb6','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6b07983f-d1fa-5b71-95b0-d388c33b9cb6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6b07983f-d1fa-5b71-95b0-d388c33b9cb6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d844f96-cad2-5705-91b8-946e1d574832','Sound-level measurement, management and documentation (SLMMD)','Sound-level measurement, management and documentation (SLMMD) is the integrated venue practice of continuously measuring event sound with calibrated instrumentation, actively managing levels to stay within an applicable target or limit, and documenting the results as a retained record. It is the operational backbone of the WHO Global Standard for Safe Listening Venues and Events, whose recommendations pair a maximum average level (100 dB LAeq over 15 minutes at a defined reference position) with real-time monitoring by a designated person and tamper-resistant logs. What exactly must be measured, to what limit, and how long records are kept varies by jurisdiction, licence, and standard adopted.','SLMMD means measuring, controlling, and recording a show''s sound. Staff watch the level in real time with a calibrated meter. They keep it under the target and save the data. The WHO safe-listening standard is built on this idea. It pairs a level cap with live monitoring and logs. For example, WHO advises staying under 100 dB averaged over 15 minutes. The saved record proves the venue stayed in range.','It exists to turn a sound limit from a paper rule into a running, provable process: measurement makes the level visible, management keeps it within target, and documentation creates the evidence a regulator, insurer, or venue can later audit. Together they close the loop between a health goal and daily operation.','A venue assigns a trained person to watch a calibrated meter against the reference level all night, adjust or instruct engineers when it drifts high, and retain the logged data so the venue can demonstrate compliance in a licence review or complaint.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Calibrated logging meter','Level logging','Audience exposure limit','Loudest audience position','Front-of-house reference position','Hearing protection availability']::text[],ARRAY['Thinking a one-off spot reading is enough; SLMMD requires continuous measurement, active management, and a retained record across the whole event.','Treating documentation as optional paperwork, when the stored log is often the only evidence that levels stayed within the target.','Assuming the WHO 100 dB LAeq,15min figure is a legal limit everywhere; it is a global voluntary standard, and binding limits vary by jurisdiction.']::text[],ARRAY['A live-music venue adopting the WHO safe-listening standard sets up continuous metering, a named sound steward, and nightly saved logs.','A touring production carries its own SLMMD workflow so it can document compliance consistently across different countries'' limits.','An insurer or local authority asks a venue for its retained sound documentation after a patron reports hearing harm.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-level measurement, management and documentation (SLMMD)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d844f96-cad2-5705-91b8-946e1d574832','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d844f96-cad2-5705-91b8-946e1d574832') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d844f96-cad2-5705-91b8-946e1d574832');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a8808a22-78d8-5736-9bb0-4c4025bd2db6','Front-of-house reference position','The front-of-house (FOH) reference position is the sound-control/mixing location in the audience area used as a practical vantage point for monitoring and setting overall levels during an event. Guidance such as UK HSE event advice treats it as a control reference while cautioning that it is often not the point of greatest audience exposure: patrons at a front-of-stage barrier or nearer loudspeakers can be significantly louder. Because many laws require compliance at the loudest audience location or at a property boundary, the FOH reference position generally must be related, by measured offset, to those legally decisive points rather than substituted for them. Its status varies by jurisdiction, standard, and licence.','The front-of-house reference position is the mixing spot in the crowd. Engineers use it to watch and set the overall level. But it is often not the loudest place for the crowd. People at the barrier or near speakers hear more. Many laws judge compliance at the loudest audience spot, not here. So engineers measure the gap between the two. Then they set the desk to keep the loud spot legal.','It gives engineers a stable, accessible place to monitor and control a mix, but its regulatory value depends on being tied to the legally decisive point. Establishing the offset between FOH and the loudest audience area lets a team control from FOH while still protecting patrons where exposure is highest.','During soundcheck a tech measures the level difference between FOH and the front-of-stage barrier or loudest audience area, then sets a working FOH target that keeps the loudest point under the controlling limit throughout the show.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Loudest audience position','Audience exposure limit','Calibrated logging meter','Level logging','Sound-level measurement, management and documentation (SLMMD)','Sound limiter']::text[],ARRAY['Assuming the FOH reading equals audience exposure; the loudest audience area, often near the stage or speakers, is typically louder than FOH.','Using FOH as the compliance point when the controlling rule requires measurement at the loudest audience location or the property boundary.','UNSAFE: Trusting a comfortable FOH level as proof the crowd is safe, when patrons at the barrier may be exposed well above a hazardous threshold.']::text[],ARRAY['A touring engineer measures the FOH-to-barrier offset at soundcheck so the front row stays under the venue''s audience limit.','A licensing officer questions a venue that documented only FOH readings when the licence sets a limit at the loudest audience area.','A festival stage crew relates FOH levels to a barrier monitoring mic to hold DIN 15905-5 compliance at the loudest audience zone.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Front-of-house reference position');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a8808a22-78d8-5736-9bb0-4c4025bd2db6','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a8808a22-78d8-5736-9bb0-4c4025bd2db6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a8808a22-78d8-5736-9bb0-4c4025bd2db6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '726ff15a-0924-5110-bab0-ad4624d3a044','Loudest audience position','The loudest audience position is the location within the accessible audience area that receives the highest sound level, and which several audience-protection frameworks make the decisive point for compliance. Germany''s DIN 15905-5, for instance, evaluates audience hearing protection at the loudest area patrons can occupy (or an equivalent substitute immission point), applying a reference of 99 dB(A) LAeq over 30 minutes with a 135 dB LpCpeak ceiling; UK HSE event guidance similarly notes that exposure at a front-of-stage barrier can be significantly higher than at front-of-house. Because this point drives worst-case exposure, it — not the mixing desk — is where limits are checked. The exact descriptor, value, and averaging window vary by standard and jurisdiction.','The loudest audience position is the spot in the crowd that hears the most sound. It is often at the barrier or close to the speakers. Some rules check the limit right there, not at the desk. That spot faces the worst-case exposure. For example, Germany''s DIN 15905-5 uses 99 dB(A) over 30 minutes there. It also caps sharp peaks at 135 dB. Protecting this spot protects the most-exposed fans.','It exists so that audience protection is judged where risk is greatest, not where it is convenient to measure. Anchoring the limit to the worst-case location prevents a venue from passing on a mild average at the desk while patrons near the stage are overexposed.','A festival acoustician places or references a monitoring mic at the loudest audience area, sets FOH so that point stays under the DIN or licence limit, and logs it as the compliance record; enforcement staff check readings against this location.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Front-of-house reference position','Audience exposure limit','Level logging','Calibrated logging meter','Audience warning notice','Hearing protection availability']::text[],ARRAY['Assuming the loudest point is always dead-centre; it is often at the front barrier or beside a loudspeaker stack, not the geometric middle.','Checking compliance at front-of-house instead of the loudest audience area required by the controlling standard.','UNSAFE: Believing a safe average at the desk means the whole crowd is safe, when patrons at the loudest position can exceed a hazardous exposure and suffer hearing damage.']::text[],ARRAY['A German arena show is assessed under DIN 15905-5 at the loudest audience area against the 99 dB(A)/30-min reference and 135 dB peak.','A UK festival crew accepts that the front-of-stage barrier, not FOH, is the exposure-critical point for audience protection.','An enforcement officer takes readings at the loudest reachable patron location during a spot inspection.']::text[],'advanced',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Loudest audience position');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '726ff15a-0924-5110-bab0-ad4624d3a044','f31111e1-7660-420a-a3b8-4f55780f8148',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='726ff15a-0924-5110-bab0-ad4624d3a044') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='726ff15a-0924-5110-bab0-ad4624d3a044');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '047ea36c-5633-5719-837a-6913d70335be','Audience warning notice','An audience warning notice is a communication that informs patrons in advance that an event may expose them to sound levels capable of harming hearing, so they can choose protection or a quieter area. It is required or recommended once expected exposure crosses a stated threshold and may appear on tickets, advertising, signage at entry, or venue displays. For example, UK HSE event guidance advises informing the audience of the risk to their hearing where the Event LAeq is likely to exceed 96 dB; Swiss and French frameworks similarly require posted information about hearing risk at amplified-sound venues. The trigger level, wording, placement, and whether it is mandatory or advisory vary by jurisdiction, licence, and standard.','An audience warning notice tells fans a show may be loud enough to harm hearing. It lets them get earplugs or step back. It can go on tickets, ads, signs, or screens. Rules require it once expected sound passes a set level. For example, UK HSE advises a warning where the event may top 96 dB. Swiss and French venues must also post hearing-risk information. The exact trigger and wording differ by place.','It exists to give patrons informed choice: because audiences are not required to wear protection, a clear advance warning lets them take precautions or avoid the loudest zones. It also supports a venue''s duty of care and creates a record that risk was communicated.','A promoter adds a hearing-risk line to tickets and posts signage at entry when a show''s expected Event LAeq crosses the advisory threshold, and a compliance officer keeps proof the notice was displayed as part of the event''s documentation.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Hearing protection availability','Audience exposure limit','Chill-out zone','Loudest audience position','Sound-level measurement, management and documentation (SLMMD)']::text[],ARRAY['Assuming a warning is only needed for extreme events; the UK HSE advisory trigger of an Event LAeq likely above 96 dB is reached at many ordinary concerts.','Treating the notice as a substitute for level control or hearing protection, when it complements — not replaces — them.','UNSAFE: Reading the warning as meaning the show is proven safe if you simply stay; sustained loud exposure without protection can still cause permanent hearing damage.']::text[],ARRAY['A UK arena prints a hearing-risk line on tickets because the show''s Event LAeq is expected to exceed 96 dB.','A Swiss club posts required hearing-damage information at the entrance for a night above the ordinance''s amplified-sound threshold.','A French venue displays audience risk information alongside free earplugs as part of its R1336-1 obligations.']::text[],'beginner',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audience warning notice');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '047ea36c-5633-5719-837a-6913d70335be','f31111e1-7660-420a-a3b8-4f55780f8148',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='047ea36c-5633-5719-837a-6913d70335be') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='047ea36c-5633-5719-837a-6913d70335be');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '37a2ff7f-1cfb-52a6-bdc0-f06ed3738c23','Hearing protection availability','Hearing protection availability is the requirement or recommendation that suitable ear protection — typically earplugs — be accessible to patrons at an event, often free of charge, once exposure reaches or is likely to reach a stated level. It appears across audience-protection frameworks: the WHO Global Standard recommends personal hearing protection meeting a minimum performance (high-fidelity earplugs giving at least 12 dB attenuation for most users) be available at no or low cost with usage guidance; France''s R1336-1 requires free individual protectors suited to the audience; and the Swiss Sound and Laser Ordinance requires free earplugs above its notification threshold. Whether provision is mandatory or advisory, and any threshold, cost, and performance conditions, vary by jurisdiction, licence, and standard.','Hearing protection availability means earplugs are on hand for the crowd. They are often free once a show gets loud enough. The WHO safe-listening standard advises this, with usage tips. France requires free plugs suited to the audience. Swiss rules require free plugs above their trigger level. Good plugs cut some sound but still let you enjoy music. Availability lets fans protect their ears by choice.','It exists to give patrons a practical way to lower their own exposure, recognising that venues cannot force protection on an audience. Making suitable protection easy and often free removes a barrier, complementing level limits and warnings within a layered hearing-health approach.','A venue stocks and offers earplugs at entry or bars when a show crosses the local threshold, posts how to use them, and records that they were provided; a compliance officer verifies availability as part of licence conditions.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Audience warning notice','Audience exposure limit','Chill-out zone','Sound-level measurement, management and documentation (SLMMD)','Loudest audience position']::text[],ARRAY['Thinking any foam plug is equivalent; frameworks like the WHO standard point to protectors meeting a minimum attenuation and, for music, high-fidelity types that keep sound clear.','Assuming availability alone discharges the duty, when limits, warnings, and quiet areas are also expected in most frameworks.','UNSAFE: Believing earplugs make any level safe for unlimited time; heavy over-limit exposure can still risk damage, and poorly fitted plugs give far less real-world protection than their rated value.']::text[],ARRAY['A French concert hall offers free, audience-appropriate earplugs at the door to meet its R1336-1 obligations.','A Swiss festival above the ordinance threshold hands out free earplugs alongside posted hearing-risk information.','A venue pursuing WHO safe-listening recognition stocks high-fidelity earplugs and posts guidance on fitting them.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hearing protection availability');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '37a2ff7f-1cfb-52a6-bdc0-f06ed3738c23','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='37a2ff7f-1cfb-52a6-bdc0-f06ed3738c23') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='37a2ff7f-1cfb-52a6-bdc0-f06ed3738c23');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd96eb9cb-646e-56d0-b0e9-9bc97eb9c3a8','Chill-out zone','A chill-out zone is a designated lower-level area within or near a venue where patrons can rest their ears away from the main sound, reducing cumulative exposure over an event. Audience-protection frameworks recommend or require such spaces: the WHO Global Standard calls for quiet zones accommodating at least 10% of venue capacity, clearly marked and free of other hazards; the Swiss Sound and Laser Ordinance requires respite areas for longer, louder events kept at LAeq ≤ 85 dB(A) and covering at least 10% of the audience space; France''s R1336-1 requires acoustic rest areas or periods. Exact level targets, size, and whether provision is mandatory vary by jurisdiction, licence, and standard.','A chill-out zone is a quieter space where fans can rest their ears. It sits away from the loudest sound. Time spent there lowers a person''s total exposure. Safe-listening rules ask venues to provide one. For example, WHO advises a quiet area for at least 10% of the crowd. Swiss rules set respite areas at 85 dB(A) or less. France requires rest areas or rest breaks too.','It exists because total hearing risk depends on both level and time; giving patrons a place to recover breaks up cumulative dose. It also addresses safety and welfare more broadly, offering respite from crowding and heat alongside the reduced sound.','An event producer designates and signs a lower-level area sized to a share of capacity, keeps it below the target level, and documents it to satisfy a licence condition or safe-listening standard; staff direct patrons there during peak sets.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Hearing protection availability','Audience exposure limit','Audience warning notice','Sound-level measurement, management and documentation (SLMMD)','Loudest audience position']::text[],ARRAY['Treating any bar or corridor as a chill-out zone; frameworks specify a target level, minimum size (often about 10% of capacity), and clear signage.','Assuming a quiet area replaces level limits or earplugs, when it is one layer among several audience-protection measures.','Thinking the space only serves comfort, when its regulatory purpose is to cut cumulative sound exposure and give the ears recovery time.']::text[],ARRAY['A festival organiser sets up a signed quiet tent sized for at least 10% of attendees to meet WHO safe-listening guidance.','A Swiss venue running a long, loud event provides a respite area kept at 85 dB(A) or below covering 10% of the audience space.','A French club designates an acoustic rest area as part of its R1336-1 compliance.']::text[],'beginner',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Chill-out zone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd96eb9cb-646e-56d0-b0e9-9bc97eb9c3a8','f31111e1-7660-420a-a3b8-4f55780f8148',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d96eb9cb-646e-56d0-b0e9-9bc97eb9c3a8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d96eb9cb-646e-56d0-b0e9-9bc97eb9c3a8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cc6bd526-0930-5139-bf92-5994166ab1a6','Sound limiter','A sound limiter (noise limiter) is a device fitted in a venue''s audio signal or power path that automatically attenuates, warns, or cuts output when the measured level exceeds a preset threshold, so a room cannot exceed a level tied to a licence or environmental condition. Devices range from indicator units to microphone-referenced limiters that reduce gain, and are commonly installed as a condition on premises licences to control noise breakout to neighbours or protect audiences. Whether one is required, the threshold, and the type accepted vary by jurisdiction, venue licence, and local authority; some regimes have moved toward performance-based conditions rather than mandating a specific device.','A sound limiter is a box that stops a venue getting too loud. It watches the level against a set point. If sound goes over, it warns, turns it down, or cuts power. Local licences often require one to protect neighbours or the crowd. The set point and the type of device depend on the licence. Some areas now judge results instead of demanding a fixed device.','It exists to give a venue an automatic backstop so licence or environmental limits hold even without constant human attention. By enforcing a ceiling in real time, it protects neighbours from breakout noise and, in some settings, supports audience-level control.','A venue''s licence may require a limiter set and certified to a level agreed with the local authority; an engineer calibrates the show to work under it, while a compliance officer keeps the setting certificate and treats the seal as evidence the threshold is unchanged.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Limiter tamper seal','Audience exposure limit','Level logging','Calibrated logging meter','Amplified-sound event']::text[],ARRAY['Assuming a limiter measures audience exposure; many are set to control noise breakout to neighbours, referenced to a licence condition, not patron hearing.','Thinking a limiter is legally required for every venue, when whether one is mandated, and its threshold, depend on the specific licence and local authority.','Believing the on-stage or FOH level equals what the limiter reads; the device responds to level at its own reference sensor, which may differ.']::text[],ARRAY['A UK premises licence conditions live music on a certified sound limiter set to an agreed threshold to prevent neighbour nuisance.','A wedding band checks a hired hall''s limiter threshold in advance to plan their stage levels around it.','An environmental health officer reviews a venue''s limiter certificate and seal during a noise-complaint investigation.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound limiter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cc6bd526-0930-5139-bf92-5994166ab1a6','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cc6bd526-0930-5139-bf92-5994166ab1a6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cc6bd526-0930-5139-bf92-5994166ab1a6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '47d4891e-62d8-5802-9f46-c2c1b3c5dd37','Limiter tamper seal','A limiter tamper seal is the physical seal, lock, or software access control applied to a sound limiter''s threshold and configuration to prevent unauthorised changes after it has been set and certified. It provides tamper evidence: a broken or missing seal, or an audit-log entry, signals that the calibrated limit may have been altered from the value agreed under a licence condition. Sealing may be a mechanical cover over controls, a locked enclosure, a password-protected setting, or a logged access record. Whether a seal is required and its form vary by jurisdiction, licence, and device, and are typically tied to a certification that records the sealed threshold.','A limiter tamper seal locks a sound limiter''s settings after they are set. It can be a physical seal, a lock, or a password. Its job is to show if someone changed the level. A broken seal means the setting may not be trusted. Licences often require the seal to stay intact. It ties the device to the level agreed with the authority.','It exists to preserve the integrity of an agreed limit: without a seal, a threshold set for compliance could be quietly raised. The seal makes tampering visible, giving licensing and environmental-health officers confidence that the certified level is the one still in force.','After a limiter is set and certified, the installer seals the threshold and records the seal on the certificate; venue staff keep the seal intact, and an officer inspecting the venue checks the seal and certificate to confirm the limit has not been changed.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Sound limiter','Calibrated logging meter','Level logging','Audience exposure limit','Amplified-sound event']::text[],ARRAY['Thinking the seal changes the sound; it only protects the setting and provides evidence, without altering how the limiter behaves.','Assuming any staff member may reset a sealed limiter, when re-setting normally requires an authorised, re-certified, re-sealed procedure under the licence.','Believing an intact seal proves the level is currently correct; it evidences no change since setting, but the original calibration and certificate still matter.']::text[],ARRAY['An installer seals and certifies a venue''s limiter threshold so a licensing officer can later confirm it is unchanged.','A venue manager reports a broken seal to arrange re-certification before hosting further live events.','An environmental-health inspector finds a missing tamper seal and treats the limiter reading as unverified during a complaint case.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Limiter tamper seal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '47d4891e-62d8-5802-9f46-c2c1b3c5dd37','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='47d4891e-62d8-5802-9f46-c2c1b3c5dd37') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='47d4891e-62d8-5802-9f46-c2c1b3c5dd37');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ce4418f-5bc3-528f-852c-988187fd15fb','Calibrated logging meter','A calibrated logging meter is a sound level meter that both meets a recognised instrument specification and records a time history of measured levels for enforcement or self-documentation. The instrument class and accuracy are defined by IEC 61672-1 (Class 1 for higher precision, Class 2 for general use), field calibration uses an acoustic calibrator conforming to IEC 60942, and the logging function stores descriptors such as LAeq, LCpeak, or Lmax over time. Calibration before and after measurement establishes traceability so the stored data can be trusted. Which class, descriptors, logging interval, and retention period are required vary by jurisdiction, standard, and licence.','A calibrated logging meter is a proper sound meter that saves its readings. It meets a known accuracy grade under IEC 61672. It is checked with a calibrator under IEC 60942 before and after use. The log stores the level over time. This makes the data trustworthy for a licence check or complaint. Class 1 meters are more precise; Class 2 are for general use.','It exists so that event sound data is both accurate and defensible: calibration to a standard gives the readings traceable trust, and logging turns momentary levels into an evidential record. Together they let a venue prove compliance and let an enforcer rely on the numbers.','A compliance tech field-calibrates the meter with an IEC 60942 calibrator, logs LAeq and peak at the reference or loudest audience position through the show, and archives the record; officers use the same class of instrument to take enforceable measurements.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Level logging','Sound-level measurement, management and documentation (SLMMD)','Loudest audience position','Front-of-house reference position','Audience exposure limit']::text[],ARRAY['Confusing a consumer or phone app with a compliant meter; enforceable measurement uses an IEC 61672 Class 1 or Class 2 instrument, calibrated to IEC 60942.','Skipping the pre- and post-measurement calibration check, which is what makes the logged data traceable and defensible.','Assuming any logging is acceptable, when the required class, descriptors, interval, and retention are set by the applicable standard or licence.']::text[],ARRAY['A council officer arrives with a Class 1 meter and IEC 60942 calibrator to take enforceable readings at a festival.','A venue logs LAeq and LCpeak with a calibrated meter all night to document compliance with its licence.','A touring compliance tech calibrates before and after a show so the archived data withstands later scrutiny.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Calibrated logging meter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ce4418f-5bc3-528f-852c-988187fd15fb','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ce4418f-5bc3-528f-852c-988187fd15fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ce4418f-5bc3-528f-852c-988187fd15fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '435bc6e1-596b-5589-8765-36ffa8c9c02b','Level logging','Level logging is the continuous recording and storage of measured sound levels throughout an event, producing a time-stamped record of descriptors such as LAeq, LCeq, LCpeak, or Lmax at a defined measurement position. It is the documentation element of audience-protection and licensing regimes: France''s R1336-1 requires venues to record public-exposure levels in dB(A) and dB(C) and retain them (for example, six months); the Swiss ordinance requires recording and retention (for example, 30 days) for longer, louder events; and the WHO standard recommends tamper-resistant logs. The descriptors, sampling, retention period, and whether logging is mandatory vary by jurisdiction, licence, and standard.','Level logging means saving a show''s sound levels over the whole event. It keeps a time-stamped record of how loud things were. This record proves the venue stayed within its limit. Many rules require it. For example, France makes venues record levels and keep them for months. Swiss rules require recording for longer, louder events. The WHO standard advises logs that cannot be edited.','It exists to create durable evidence: a live reading vanishes, but a stored log lets a venue demonstrate compliance and lets a regulator or complainant reconstruct what happened. Tamper-resistance and retention rules ensure the record stays credible over time.','A venue configures its meter or limiter to log the required descriptors at the reference position, secures the data against editing, and retains it for the mandated period so it can produce the record in a licence review or complaint.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Calibrated logging meter','Sound-level measurement, management and documentation (SLMMD)','Audience exposure limit','Loudest audience position','Limiter tamper seal']::text[],ARRAY['Thinking a few manual spot readings count as logging, when the requirement is continuous, time-stamped recording across the event.','Ignoring retention rules; regimes set how long records must be kept (for example, months in France or set periods in Switzerland), and discarding them early breaches the duty.','Assuming the raw log alone proves compliance, when the data is only trustworthy if the meter was calibrated and the record kept tamper-resistant.']::text[],ARRAY['A French amplified-music venue records public exposure in dB(A) and dB(C) and retains the logs for the required period under R1336-1.','A Swiss festival exceeding the ordinance''s duration and level bands records and stores measurements for the mandated retention window.','A venue produces its stored level log for a licensing officer after a neighbour''s noise complaint.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Level logging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '435bc6e1-596b-5589-8765-36ffa8c9c02b','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='435bc6e1-596b-5589-8765-36ffa8c9c02b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='435bc6e1-596b-5589-8765-36ffa8c9c02b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11f1dfdf-e95f-5104-aa7d-7e8c5156d0f2','Sound check limit','A sound check limit is a permit, licence, or noise-management-plan condition that governs sound produced during rehearsal and system tuning before an event opens, treated as distinct from the performance itself. It may impose a lower emitted or received level, a shorter permitted window, earlier finish or later start times, or a rule that full-level testing occur only within a narrow band before the show. Because sound checks often fall in daytime, when background noise and neighbour tolerance differ from show hours, regulators frequently address them separately from the main event. Exact provisions vary by jurisdiction, venue licence, event permit, time of day, receiver location, and measurement method; for example, a UK festival noise management plan may cap the off-site music noise level during the sound check below the evening performance limit.','A sound check is a rehearsal to test the sound system before a show. Rules can limit it. The rules may set a lower loudness cap than the show. They may allow only a short time window. They may set an earlier start or stop time. Sound checks often happen in the day. Neighbours may be less tolerant then. So permits often treat the sound check apart from the show. Exact rules change by place, venue, and time of day.','It stops pre-show testing from causing nuisance or breaching limits when full-level runs happen outside performance hours. It gives producers a defined, lawful allowance for necessary tuning while protecting neighbours during quieter parts of the day.','A production manager schedules line checks and full-level tests inside the permitted soundcheck window, keeps off-site levels within the stated cap, and logs times and readings. A compliance officer reads the noise management plan to confirm soundcheck conditions before signing off.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Curfew breach','Off-site noise monitoring','Music noise level (MNL)','Special event permit','Exceedance event']::text[],ARRAY['Assuming soundcheck is unregulated because no audience is present — permits and licences often restrict it explicitly.','Treating the show-time limit as also covering soundcheck — the soundcheck allowance may be lower or time-boxed.','UNSAFE: Running the system at full concert level for long soundchecks without hearing protection — cumulative exposure to crew can be hazardous even in an empty room.']::text[],ARRAY['A touring engineer arranging a full-level soundcheck must fit it inside the daytime window a city permit allows.','A council officer reviewing a festival noise plan checks that soundcheck off-site limits sit below the evening show limit.','A venue manager schedules a support act''s line check earlier so amplified testing ends before a licensed quiet period.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound check limit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11f1dfdf-e95f-5104-aa7d-7e8c5156d0f2','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11f1dfdf-e95f-5104-aa7d-7e8c5156d0f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11f1dfdf-e95f-5104-aa7d-7e8c5156d0f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a5e03569-897b-5ce9-a47b-0d5d6c319185','Bass containment','Bass containment is the practice and objective of limiting the propagation of low-frequency sound energy (roughly below about 250 Hz) beyond a venue or event site so it does not disturb off-site receivers. It matters because low frequencies attenuate slowly with distance, transmit through building fabric readily, and are strongly discounted by A-weighting, so a site can satisfy an A-weighted limit while still generating bass complaints. Techniques include directional subwoofer arrays, stage siting and orientation, level and spectral management, and setting low-frequency-specific criteria (for example separate 63 Hz and 125 Hz octave-band limits, or a dB(C) minus dB(A) indicator). Whether and how it is regulated varies by jurisdiction, licence, permit, receiver location, and measurement method; for example, some UK festival premises licences add octave-band low-frequency limits alongside a broadband LAeq.','Bass is low-frequency sound, like the thump of a kick drum. It travels far. It passes through walls easily. A-weighted meters give it little weight. So a show can pass a loudness test but still shake neighbours. Bass containment means keeping this low sound on site. Methods include aiming subwoofers and setting bass-only limits. Some UK festival licences add limits for low bands like 63 hertz. Exact rules change by place and permit.','It targets the specific annoyance and complaint driver that broadband A-weighted limits can miss. Controlling low-frequency spill protects distant residents from throb and rattle and helps events keep their licences and community goodwill.','A system designer chooses directional sub arrays and orients the stage to push bass away from housing, then verifies with octave-band readings at receivers. A compliance officer sets and checks separate low-frequency limits written into the noise management plan.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Subwoofer directivity control','Off-site noise monitoring','Music noise level (MNL)','Outdoor stage orientation','Exceedance event']::text[],ARRAY['Assuming a dB(A) limit controls bass — A-weighting heavily discounts low frequencies, so bass can spill while the dB(A) reading stays compliant.','Thinking more subwoofers always mean worse off-site bass — directional arrays can raise on-site bass while lowering it behind and off-site.','Believing distance or walls alone stop bass — long wavelengths diffract and transmit through structures far better than treble.']::text[],ARRAY['A festival receiving 63 Hz complaints from a village adds directional subs and re-aims the main stage.','An acoustic consultant sets separate low-frequency octave-band limits in a premises-licence noise plan.','A club near flats measures dB(C) and dB(A) to show bass, not just overall level, drives the complaints.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bass containment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a5e03569-897b-5ce9-a47b-0d5d6c319185','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a5e03569-897b-5ce9-a47b-0d5d6c319185') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a5e03569-897b-5ce9-a47b-0d5d6c319185');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c563f616-b97e-594d-9723-854c17498fac','Subwoofer directivity control','Subwoofer directivity control is the deployment of multiple low-frequency loudspeakers in configured arrays — cardioid, end-fire, or gradient — using controlled delay, polarity, and spacing so the combined radiation becomes directional rather than the near-omnidirectional pattern of a single subwoofer. In a compliance context the goal is to concentrate bass toward the audience while reducing radiation behind and beside the stage, cutting low-frequency spill to off-site receivers. The achievable rejection is frequency- and geometry-dependent and finite, so it supplements rather than replaces siting, level management, and limits. It is an engineering means to a regulatory end, not itself a legal limit; applicable off-site criteria vary by jurisdiction, permit, receiver, and measurement method.','A single subwoofer sends bass in all directions. That wastes energy toward neighbours. Directivity control uses several subs in a set pattern. Delay, spacing, and polarity shape where the bass goes. Common patterns are cardioid and end-fire arrays. They aim bass at the crowd. They cut bass behind and beside the stage. This lowers spill to homes off site. It works only within limits and by frequency. It supports, but does not replace, siting and level limits.','It gives sound designers a physical tool to meet off-site low-frequency limits without simply turning the system down for the audience. By steering bass, it reduces complaints and exceedances while preserving the on-site experience.','A system tech models and deploys a cardioid or end-fire sub array aimed away from the nearest housing, then measures rear and off-site attenuation to confirm the design. The chosen array is documented in the event''s noise management plan.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Bass containment','Outdoor stage orientation','Off-site noise monitoring','Music noise level (MNL)','Exceedance event']::text[],ARRAY['Assuming a cardioid array removes all rear bass — it provides finite rejection that varies with frequency and array geometry.','Confusing directivity control with just lowering the level — it changes where bass goes, not only how loud it is overall.','Thinking one array design fits every site — spacing and delay must be tuned to the layout and the target frequencies.']::text[],ARRAY['A festival designer builds an end-fire sub array to push bass toward the field and away from an estate.','An engineer measures behind the stacks to verify rear cancellation before an environmental officer''s inspection.','A promoter documents directional sub use to show reasonable steps were taken to limit off-site bass.']::text[],'advanced',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Subwoofer directivity control');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c563f616-b97e-594d-9723-854c17498fac','f31111e1-7660-420a-a3b8-4f55780f8148',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c563f616-b97e-594d-9723-854c17498fac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c563f616-b97e-594d-9723-854c17498fac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb85b2e4-e8c2-577b-945d-c20cf27e548f','Off-site noise monitoring','Off-site noise monitoring is the measurement of event or venue sound at locations away from the source — typically the facade of the nearest noise-sensitive premises, an agreed monitoring position, or a site or property boundary — to assess compliance with received-level conditions. Measurements use an integrating sound level meter (for example IEC 61672 class 1) reporting descriptors such as LAeq over a defined period (commonly 15 minutes for music), sometimes with octave-band or LCeq values, following procedures aligned with ISO 1996-2. Positions, descriptors, averaging times, and limits vary by jurisdiction, licence, permit, and method; for example, the UK Noise Council concert code assesses the music noise level as LAeq over 15 minutes at 1 m from a dwelling facade.','Off-site monitoring means measuring event sound away from the stage. Readings are taken near homes or at the site boundary. A meter records levels over set periods. For music this is often 15 minutes. The reading is compared with the permit limit. The UK concert code measures 1 metre from a home. Positions and limits change by place and permit. This shows whether neighbours are being protected.','It provides objective evidence of what neighbours actually receive, which is the basis for enforcing received-level limits and responding to complaints. It lets producers manage levels in real time and lets regulators verify compliance.','A noise officer or contractor takes timed LAeq readings at agreed receiver positions during a show and calls the stage to reduce level as a limit is approached. Logged results form the compliance record and evidence in any complaint or licence review.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Music noise level (MNL)','Real-time noise display','Exceedance event','Bass containment','Special event permit','Curfew breach']::text[],ARRAY['Confusing off-site received levels with audience exposure at front of house — they are different positions with different limits.','Assuming a single instantaneous reading proves compliance — most limits use a time-averaged LAeq over a set period.','Forgetting to account for background and weather — wind and traffic can raise measured levels not caused by the event.']::text[],ARRAY['A festival stations monitoring teams at three villages to log LAeq over 15 minutes at dwelling facades each hour.','A council officer measures at a complainant''s boundary to check a licence''s received-level condition.','A production sets a monitoring point near flats and reduces subs when the reading nears the permit limit.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Off-site noise monitoring');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb85b2e4-e8c2-577b-945d-c20cf27e548f','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb85b2e4-e8c2-577b-945d-c20cf27e548f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb85b2e4-e8c2-577b-945d-c20cf27e548f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3bd2d74a-90b3-54a5-a105-e86bdb577705','Real-time noise display','A real-time noise display is a screen or indicator presenting live sound-level metrics — such as running LAeq, LCeq, instantaneous and peak levels, accumulated dose or remaining time, and limit exceedances — to a front-of-house engineer, production team, or regulator during an event. It is usually driven by a class 1 sound level meter or logging system and may use numeric readouts, time-history plots, or traffic-light indicators referenced to a permitted value. It supports both audience-exposure management (for example under Germany''s DIN 15905-5 or WHO safe-listening guidance) and off-site compliance. The displayed descriptor, averaging window, and reference limit depend on the applicable standard, licence, or permit.','A real-time noise display is a live screen of sound levels. It shows values like average and peak loudness. It updates during the show. Engineers and officers can watch it. Some use a traffic-light view against the limit. It helps keep the show within audience-safety and off-site limits. Germany''s DIN 15905-5 supports this kind of monitoring. The exact value shown depends on the standard or permit. It turns limits into something staff can see and act on.','It converts abstract limits into an immediate visual signal so staff can act before a breach, rather than discovering an exceedance afterward. It underpins documented, defensible level management for both hearing safety and neighbour compliance.','An engineer keeps the running LAeq below the set-point shown on the meter display, easing level as the indicator nears the limit. A compliance officer records the display as time-stamped evidence of the levels achieved.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Off-site noise monitoring','Music noise level (MNL)','Exceedance event','Exceedance allowance','Curfew breach']::text[],ARRAY['Assuming the big instantaneous number is the compliance figure — most limits are a time-averaged LAeq, which the display tracks separately.','UNSAFE: Trusting an audience-exposure reading to protect the crew''s own hearing — engineers near monitors and subs still need hearing protection.','Believing a green light guarantees legality everywhere — the reference value depends on the specific standard or permit loaded.']::text[],ARRAY['A front-of-house engineer watches a running LAeq readout to stay under a venue''s house limit.','A regulator reviews logged screen data to confirm an arena stayed within DIN 15905-5 guidance.','A festival links receiver meters to a production screen so managers see off-site levels live.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Real-time noise display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3bd2d74a-90b3-54a5-a105-e86bdb577705','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3bd2d74a-90b3-54a5-a105-e86bdb577705') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3bd2d74a-90b3-54a5-a105-e86bdb577705');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f07dfbca-8937-5ee5-a85b-a7b9b0566a73','Exceedance event','An exceedance event is a logged instance in which a measured sound descriptor rises above an applicable limit — for example a 15-minute LAeq at a receiver above a licence''s received-level condition, an audience LAeq above a venue set-point, or a peak above a stated cap. It is defined by the descriptor, threshold, averaging period, and measurement position specified in the controlling permit, licence, or standard, and is typically time-stamped in a monitoring record. Whether an exceedance constitutes a breach, and its consequences, depend on the jurisdiction and on whether the permit includes tolerances; some conditions treat any exceedance as a violation while others allow limited short-term excursions.','An exceedance event is a moment when a reading goes over a limit. The limit comes from a permit, licence, or standard. It is set by the value, the averaging time, and the spot measured. The meter log records when it happened. Some permits count any exceedance as a breach. Others allow short, small overruns. So an exceedance is not always a legal breach. The rules depend on the place and the permit. Logs of these events drive enforcement.','It gives a precise, recordable unit for tracking and enforcing sound limits and for triggering corrective action. Defining exceedances lets producers respond quickly and lets regulators demonstrate a breach with evidence.','A monitoring system flags and time-stamps each exceedance so the engineer can pull level down and the record shows how it was handled. A regulator counts exceedances against licence conditions when deciding on warnings, fines, or a review.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Exceedance allowance','Off-site noise monitoring','Real-time noise display','Music noise level (MNL)','Curfew breach']::text[],ARRAY['Assuming every exceedance is automatically an offence — some permits build in tolerances or short-term allowances; others do not.','Logging only the peak — the relevant exceedance is usually of the specified averaged descriptor at the specified position.','Thinking an unrecorded exceedance did not happen — regulators may rely on their own measurements and complaint evidence.']::text[],ARRAY['A festival meter logs a 15-minute LAeq above the village limit, prompting an immediate level cut.','A council uses recorded exceedances at a receiver as evidence in a licence review.','A venue''s system flags an audience-level exceedance so the engineer eases the mix.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Exceedance event');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f07dfbca-8937-5ee5-a85b-a7b9b0566a73','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f07dfbca-8937-5ee5-a85b-a7b9b0566a73') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f07dfbca-8937-5ee5-a85b-a7b9b0566a73');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '06db0ca7-8dee-514b-984f-2c764558fd6e','Exceedance allowance','An exceedance allowance is a provision in a permit, licence, or standard that tolerates limited departures from a stated sound limit — such as a permitted number of short-term excursions, a margin above the criterion for a defined fraction of the event, a small number of louder event-days per year, or an explicit measurement-uncertainty allowance — rather than treating every excursion as a breach. It reflects the practical variability of live performance and of measurement. Its existence, size, and form vary widely by jurisdiction, licence, and method; many conditions include no allowance at all, so any excess is a breach, while others, for example, permit a set number of higher-level concert days per year.','An exceedance allowance is built-in room above a limit. It lets small or short overruns happen without a breach. It may allow a few louder days a year. It may allow brief excursions or a measurement margin. It exists because live sound and meters vary. Many permits give no allowance at all. Then any excess is a breach. The size and form change by place and permit. Techs must read the exact wording.','It balances firm limits against the real variability of performances and instruments, avoiding penalising trivial or momentary excursions. It gives producers a defined, lawful margin and gives regulators a clear line for what counts as a breach.','A compliance officer reads the permit to learn whether, and by how much, brief exceedances are tolerated, and manages levels to stay inside any allowance. A promoter plans a small number of headline-loud days within an annual allowance where the licence provides one.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Exceedance event','Special event permit','Music noise level (MNL)','Off-site noise monitoring','Curfew breach']::text[],ARRAY['Assuming an allowance always exists — many licence conditions treat any exceedance as a breach with no tolerance.','Treating measurement uncertainty as free headroom to aim into — allowances are specific to the wording, not a general licence to run hot.','Confusing an annual allowance of louder days with a nightly buffer — they are different provisions.']::text[],ARRAY['A promoter uses a licence''s allowance of a few higher-level event-days a year for a headline weekend.','A consultant checks whether a permit tolerates brief LAeq excursions before setting the show''s target level.','An officer confirms a condition has zero tolerance, so a single logged exceedance is actionable.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Exceedance allowance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '06db0ca7-8dee-514b-984f-2c764558fd6e','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='06db0ca7-8dee-514b-984f-2c764558fd6e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='06db0ca7-8dee-514b-984f-2c764558fd6e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fd22d8c9-421a-5e74-be4e-4a890670e164','Music noise level (MNL)','The music noise level (MNL) is the term, used in UK and Commonwealth entertainment-noise practice, for the equivalent continuous A-weighted sound pressure level (LAeq) of music at a stated receiver, typically assessed over a 15-minute period. In the UK Noise Council Code of Practice on Environmental Noise Control at Concerts (1995) it is measured at 1 m from the facade of noise-sensitive premises, and guideline values are tiered by how often a venue holds concerts — for example, for venues staging only a few concerts a year the guidance is that the MNL should not exceed 65 dB(A) over 15 minutes, while for more frequent venues the guidance references the background level plus a margin. It isolates the music contribution from other noise sources. Exact criteria, positions, and periods vary by jurisdiction and licence.','The music noise level, or MNL, measures how loud the music is at a location. It is an average A-weighted level. It is usually taken over 15 minutes. The UK concert code measures it 1 metre from a home. It tries to capture only the music, not other noise. Guideline values depend on how often the venue holds concerts. For a venue with few concerts, the guide is 65 A-weighted decibels over 15 minutes. Exact rules change by country and licence.','It gives regulators and producers a single agreed descriptor for the music''s impact at a receiver, separable from background and patron noise. That keeps limits, monitoring, and complaint assessment consistent and enforceable.','A monitoring team measures the MNL at agreed positions and compares it with the permit''s guideline to decide whether to instruct a level reduction. A consultant predicts the MNL at receivers when preparing a festival''s noise management plan.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Off-site noise monitoring','Entertainment noise','Exceedance event','Bass containment','Real-time noise display','Curfew breach']::text[],ARRAY['Assuming the MNL is measured at the mixing desk — the concert code assesses it at the receiver, typically 1 m from a dwelling facade.','Reading the 65 dB(A) figure as a universal limit — it is a UK guideline tier that varies with venue concert frequency and jurisdiction.','UNSAFE: Confusing the MNL with audience exposure — the MNL is an off-site received descriptor, not a measure of hearing-damage risk at the front of stage.']::text[],ARRAY['A consultant predicts the MNL at the nearest houses when drafting a festival noise plan.','A monitoring officer logs the MNL at 1 m from a facade and calls for a cut as it nears the guideline.','A council compares the measured MNL with the concert code tiers during a licence review.']::text[],'advanced','MNL = L_Aeq,15min = 10 * log10( (1/T) * integral_0^T [ p_A(t)^2 / p0^2 ] dt ),  T = 15 min,  p0 = 20 uPa','The music noise level equals the A-weighted equivalent continuous level: ten times the base-ten logarithm of the time-average, over a fifteen-minute period, of the squared A-weighted sound pressure divided by the square of the reference pressure of twenty micropascals.','f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Music noise level (MNL)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fd22d8c9-421a-5e74-be4e-4a890670e164','f31111e1-7660-420a-a3b8-4f55780f8148',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fd22d8c9-421a-5e74-be4e-4a890670e164') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fd22d8c9-421a-5e74-be4e-4a890670e164');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fe7fbf54-beaa-5196-bad4-491ace544ff2','Entertainment noise','Entertainment noise is the regulatory category covering sound generated by entertainment activities — concerts, festivals, nightclubs, pubs, bars, and similar amplified or live-performance venues — as distinct from industrial, transport, or general neighbourhood noise. It is typically controlled through licensing conditions, planning or permit conditions, and environmental or nuisance law, using received-level limits at neighbours, hours restrictions, and sometimes audience-exposure rules. Both the definition and the controls differ by jurisdiction; for example, some Australian frameworks regulate amplified-music or entertainment noise from licensed premises via liquor-licence conditions (such as an LA10 criterion referenced to background), while the WHO addresses the audience-hearing side through its safe-listening guidance.','Entertainment noise is sound from shows and venues. It covers concerts, clubs, pubs, and festivals. Law treats it apart from traffic or factory noise. It is controlled mainly through licences and permits. Controls include limits at neighbours and hours rules. Some places also limit how loud it is for the audience. Australian licensed venues may use an LA10 rule tied to background. The exact rules change by country and city. It is both a neighbour issue and a hearing issue.','It groups performance-related sound so authorities can apply tailored controls — licence conditions, hours, and level limits — that fit its social value and its distinct annoyance and hearing risks. It defines the scope of who and what is regulated.','A venue operator maps which entertainment-noise conditions attach to its liquor or premises licence and builds compliance around them. A regulator classifies a complaint as entertainment noise to apply the right licensing and nuisance powers.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Patron noise','Music noise level (MNL)','Special event permit','Off-site noise monitoring','Curfew breach','Exceedance event']::text[],ARRAY['Assuming entertainment noise is judged only by loudness — character, hours, tonality, and background context often matter to a nuisance assessment.','UNSAFE: Treating audience-hearing limits and neighbour limits as the same rule — they are separate regimes with different values and positions, and mixing them can leave the audience over-exposed.','Believing one national limit applies — entertainment-noise controls vary by country, city, licence, and time of day.']::text[],ARRAY['A city licensing team attaches entertainment-noise conditions to a new bar''s premises licence.','An environmental officer classifies late-night club complaints as entertainment noise to use licensing powers.','A festival organiser addresses entertainment-noise limits at neighbours in the event permit application.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Entertainment noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fe7fbf54-beaa-5196-bad4-491ace544ff2','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fe7fbf54-beaa-5196-bad4-491ace544ff2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fe7fbf54-beaa-5196-bad4-491ace544ff2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '201e09b5-c052-590b-a1c8-b36c4f1201f0','Patron noise','Patron noise is sound made by a venue''s customers — talking, shouting, singing, queueing, smoking-area gatherings, and dispersal at closing — as opposed to amplified music or other equipment noise. It is commonly regulated separately from music because it is harder to control technically and raises distinct legal questions about a venue''s responsibility for people on or near its premises. Some jurisdictions bring patron noise within licensing or nuisance controls (imposing management-plan, capacity, dispersal, or door-supervision duties), while others limit a venue''s liability off the premises. Definitions, responsibility, and thresholds vary by jurisdiction, licence, and location; for example, NSW licensing distinguishes amplified-music noise from patron noise in how complaints are handled.','Patron noise is noise from a venue''s customers. It includes talking, shouting, and queueing outside. It also covers smoking areas and people leaving. It is different from the amplified music. It is often regulated on its own. It is harder to control than a sound system. Rules may require a management plan or door staff. Some places limit how far a venue is responsible. The rules change by country, city, and licence.','It captures a real annoyance source that music limits and limiters cannot fix, and assigns venues duties to manage crowd behaviour and dispersal. It lets regulators address late-night disturbance that comes from people, not speakers.','A venue writes a dispersal and smoking-area plan and posts door staff to reduce patron noise near homes. A licensing officer assesses whether patron-noise complaints warrant conditions such as earlier closing or capacity limits.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Entertainment noise','Special event permit','Curfew breach','Off-site noise monitoring','Music noise level (MNL)']::text[],ARRAY['Assuming a sound limiter or lower music level fixes patron noise — crowd noise is separate and often unaffected by the sound system.','Thinking a venue is never liable for customers outside — many licensing regimes impose dispersal and management duties.','Confusing patron noise with the music noise level in a complaint — they are assessed differently and need different remedies.']::text[],ARRAY['A late bar near flats adds a dispersal policy after patron-noise complaints about the smoking area.','A licensing panel imposes an earlier terrace curfew to curb patron noise, not music.','An officer separates crowd noise from amplified music when investigating a nightclub complaint.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Patron noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '201e09b5-c052-590b-a1c8-b36c4f1201f0','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='201e09b5-c052-590b-a1c8-b36c4f1201f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='201e09b5-c052-590b-a1c8-b36c4f1201f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd61f332d-02ee-5114-83f1-289adaa3bc6e','Outdoor stage orientation','Outdoor stage orientation is the compliance-relevant siting and aiming of a stage and its loudspeaker system at an open-air event so that sound is projected toward the audience and away from the nearest noise-sensitive receivers. Because a stage and its arrays radiate most energy forward, the direction the stage faces strongly affects received levels off-site, particularly for mid and high frequencies, and interacts with terrain, screening, meteorology, and subwoofer directivity. It is a design variable set during event planning and captured in the noise management plan, alongside level limits and monitoring. It is a mitigation measure, not itself a legal limit; applicable off-site criteria and required assessment vary by jurisdiction, permit, receiver, and method.','Outdoor stage orientation is which way a stage faces. A stage sends most sound forward. So its direction changes how much sound reaches homes. Facing the stage away from housing lowers off-site levels. This works best for mid and high sounds. Terrain, weather, and sub design also matter. Planners set orientation early in the event design. It goes into the noise management plan. It reduces impact but does not replace limits. Exact rules change by place and permit.','It uses basic loudspeaker directivity and site geometry to reduce neighbour impact before any level limiting, protecting both the audience experience and off-site residents. It is one of the first, cheapest mitigations a planner can apply.','A festival planner rotates a stage and array to fire toward open land and away from a village, then models and measures the off-site benefit for the permit application. The chosen orientation is recorded in the noise management plan.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Bass containment','Subwoofer directivity control','Off-site noise monitoring','Music noise level (MNL)','Special event permit']::text[],ARRAY['Assuming orientation fixes bass — low frequencies are far less directional, so stage aiming mainly helps mid and high sound.','Ignoring weather — wind and temperature gradients can carry sound to receivers regardless of which way the stage faces.','Treating orientation as a substitute for limits and monitoring — it is one mitigation among several, not a compliance guarantee.']::text[],ARRAY['A festival faces its main stage toward open fields to keep music off a nearby housing estate.','A consultant models several stage angles to find the lowest predicted level at the nearest homes.','A permit condition records the agreed stage orientation as part of the noise management plan.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Outdoor stage orientation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd61f332d-02ee-5114-83f1-289adaa3bc6e','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d61f332d-02ee-5114-83f1-289adaa3bc6e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d61f332d-02ee-5114-83f1-289adaa3bc6e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a6fee71c-7e03-56f2-9839-42d7bd2cbc87','Curfew breach','A curfew breach is a failure to comply with a required time at which amplified music or event sound must stop or drop to a lower level, as fixed by a licence, permit, planning condition, or local ordinance. Curfews commonly set the latest time for amplified music (and sometimes staged reductions before it), and can differ between weekdays, weekends, and event types. A breach — continuing beyond the stop time, or above the required reduced level — is typically logged and may trigger warnings, fines, licence review, or refusal of future permits. Exact curfew times and consequences vary by jurisdiction, venue licence, permit, and day; for example, a festival premises licence may set music to end at a stated hour with earlier finishes on some nights.','A curfew is a required stop time for amplified sound. A curfew breach means running past that time. It can also mean staying above a required lower level. The stop time comes from a licence, permit, or local law. Times often differ by day and event type. A breach is usually logged. It can bring fines or a licence review. It can also block future permits. Exact times and penalties change by place and permit.','It protects neighbours'' night-time rest by guaranteeing a firm end to amplified sound, and gives regulators a condition that is simple to check and hard to dispute. The stop time is an unambiguous line.','A stage manager runs the show clock so the headline set reaches a hard stop before the licensed curfew and cuts amplified sound on time. A licensing officer records any overrun as a breach for enforcement or a licence review.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Special event permit','Exceedance event','Off-site noise monitoring','Patron noise','Entertainment noise']::text[],ARRAY['Thinking a curfew is only about loudness — it is a time limit, so even a quiet overrun can be a breach.','Assuming the same curfew applies every night — times often differ by day of week and event type.','Believing a few minutes over is harmless — regulators may log any overrun and act on repeat breaches.']::text[],ARRAY['A festival headliner overruns the licensed stop time and the overrun is logged as a curfew breach.','A promoter schedules encores to end before a weekday curfew that is earlier than the weekend one.','A council cites repeated curfew breaches when reviewing a venue''s premises licence.']::text[],'beginner',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Curfew breach');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a6fee71c-7e03-56f2-9839-42d7bd2cbc87','f31111e1-7660-420a-a3b8-4f55780f8148',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a6fee71c-7e03-56f2-9839-42d7bd2cbc87') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a6fee71c-7e03-56f2-9839-42d7bd2cbc87');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11e34fe4-52b9-5a72-bd62-aeb93315db40','Special event permit','A special event permit is a temporary authorisation issued by a local authority for a specific event that would otherwise not be covered by a venue''s standing licence, commonly carrying conditions on sound — received-level limits at neighbours, permitted hours and a curfew, monitoring and reporting duties, and a required noise management plan. Names and mechanisms vary: for example, England and Wales use Temporary Event Notices and premises licences under the Licensing Act 2003, while US cities such as Seattle and San Francisco issue special-event or outdoor amplified-sound permits with their own decibel and hours conditions. Exact requirements, limits, and processes vary by jurisdiction, venue, receiver, and event type.','A special event permit is temporary approval for one event. A council or city issues it. It covers events not under a normal venue licence. It usually carries sound conditions. These include level limits, hours, and a curfew. It may require a noise plan and monitoring. Names differ by country and city. England uses Temporary Event Notices and premises licences. US cities issue their own amplified-sound permits. Exact rules change by place and event.','It lets authorities approve one-off or short-term events while attaching enforceable, event-specific sound controls to protect neighbours. It gives organisers a lawful route and gives regulators a conditioned, time-limited permission.','An event producer applies for the permit, submits a noise management plan, and runs the show inside its level, hours, and monitoring conditions. A licensing officer sets and later checks those conditions and can refuse renewals after breaches.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Curfew breach','Off-site noise monitoring','Music noise level (MNL)','Entertainment noise','Exceedance allowance']::text[],ARRAY['Assuming a permit removes noise limits — it typically adds event-specific conditions rather than granting a free pass.','Thinking one permit type fits everywhere — mechanisms and limits differ by country, city, and event size.','Overlooking the noise management plan requirement — many permits will not issue without one.']::text[],ARRAY['A promoter files a Temporary Event Notice for a one-night outdoor concert under the UK Licensing Act.','A Seattle organiser obtains an outdoor amplified-sound permit with set decibel and time conditions.','A city refuses a repeat permit after the previous event breached its hours and level conditions.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Special event permit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11e34fe4-52b9-5a72-bd62-aeb93315db40','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11e34fe4-52b9-5a72-bd62-aeb93315db40') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11e34fe4-52b9-5a72-bd62-aeb93315db40');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'afb103a3-eb16-5ac6-bce4-01ae455f75dc','Mass-gathering noise condition','A noise-control condition attached to the permit, licence or authorisation that allows a large public event or ''mass gathering'' — such as a festival, concert, parade, sporting fixture or public celebration — to proceed. It is imposed by the licensing or environmental authority to manage the event''s acoustic impact on the surrounding community and, in some regimes, on the audience. Such a condition typically specifies one or more controls: a maximum permitted music noise level, set as an LAeq over a stated period at a defined receiver point (for example the nearest noise-sensitive facade or the front-of-house mixing position); curfew or restricted operating hours; a limited number of events per year; continuous sound-level monitoring and logging; a nominated noise-liaison or complaint line; and low-frequency or peak controls. The precise metric, limit value, measurement location, averaging time and enforcement mechanism vary widely by country, city, venue licence, event category, time of day and the guidance the authority follows (for example a national code of practice for concert noise).','A mass gathering is a big public event. Think of a festival, concert, parade, or match. A permit or licence often sets noise rules for it. These are the mass-gathering noise conditions. They may cap how loud the music can be. They may limit the hours for loud sound. They may fix where and how sound is measured. They may set a limit on events per year. Limits differ by country, city, and venue. Officials set them to protect nearby homes and people.','The condition exists to balance the cultural, social and economic value of large public events against the amenity and health of nearby residents and, increasingly, the hearing of attendees. Rather than banning events outright, the licensing regime uses tailored, enforceable terms to keep noise within tolerable limits at sensitive receivers and to define when sound must stop. It also creates an audit trail — monitoring logs and complaint records — that lets the authority verify compliance and act on breaches. In effect it converts general nuisance and public-health duties into specific, measurable obligations that an organiser can plan and be held to.','An event producer or their acoustic consultant reads the noise conditions early in planning and designs the show around them: choosing loudspeaker types and aiming, setting a house sound limit, positioning the monitoring microphone at the specified point, rostering a noise-management officer to log LAeq readings, and scheduling sound checks and the finale within curfew. On the day, front-of-house engineers work to the agreed limit while the noise officer records levels and liaises with the local authority; the logs become the evidence of compliance if complaints or enforcement arise.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Event permit / entertainment licence','Music noise level (MNL)','LAeq','Curfew / restricted hours','Noise-sensitive receiver','Code of practice on environmental noise at concerts','Front-of-house mixing position']::text[],ARRAY['Assuming the permitted level is a single universal number — the limit, its metric, averaging time and measurement point are set case by case by the authority and code being applied.','Thinking the condition only protects residents; some regimes also cap audience exposure (for example a recommended event LAeq at the audience) as a separate matter.','Believing the limit applies at the mixing desk when it is often specified at the nearest residential facade, so the two readings can differ greatly.','Treating monitoring and logging as optional paperwork rather than an enforceable licence obligation whose records are used to prove or disprove compliance.']::text[],ARRAY['A festival promoter applies for an outdoor event licence and is granted conditions capping the music noise level at the nearest houses and imposing an 11 pm curfew.','A city environmental-health officer reviews a stadium concert''s noise-monitoring logs after residents complain about late-night bass.','A touring production''s noise-management officer sets up a calibrated logging microphone at the permit-specified receiver point before doors open.','A council licensing panel decides how many large outdoor concerts a park may host each year and writes the cap into the site''s conditions.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mass-gathering noise condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'afb103a3-eb16-5ac6-bce4-01ae455f75dc','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='afb103a3-eb16-5ac6-bce4-01ae455f75dc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='afb103a3-eb16-5ac6-bce4-01ae455f75dc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f6ef828a-b3f6-5bf9-888d-d9f52230176f','Pyrotechnic peak noise','The very high, very short-duration impulsive sound pressure produced by fireworks and stage pyrotechnics at an event, characterised by its peak (instantaneous maximum) sound pressure level rather than by an energy-averaged level such as LAeq. Because a single detonation deposits its acoustic energy in milliseconds and can generate peaks well above the levels of amplified music, regulators and standards commonly treat impulsive/peak noise under a separate C-weighted or unweighted (Z/''true'') peak metric (LCpeak or Lpeak) with its own ceiling, distinct from the A-weighted continuous limit that governs music. Reported peaks close to pyrotechnic devices can reach and exceed roughly 140 dB and, for larger effects at short range, considerably higher. Applicable ceilings vary by jurisdiction and standard: for example US OSHA (29 CFR 1910.95) advises that impulsive or impact noise should not exceed 140 dB peak sound pressure level; EU Directive 2003/10/EC sets a peak exposure limit value of 140 dB(C) (200 Pa) for workers; and DIN 15905-5 in Germany applies an LCpeak limit of 135 dB at accessible audience positions. Exact limits, weighting, measurement position and whether the figure protects workers or audience differ by regime.','Fireworks and stage pyrotechnics make very short, very loud bangs. This is called peak noise. The peak is the highest pressure in that split second. It can pass 140 decibels close to the blast. Such a spike can harm hearing right away. It differs from steady music loudness. So rules often measure and limit it on its own. For example, US OSHA says impulse noise should not top 140 decibels peak. Distance from the blast and barriers help protect people. Limits and methods differ by country and standard.','Peak metrics and separate pyrotechnic limits exist because energy-averaged measures like LAeq can hide a brief, dangerous impulse: a single blast may be over before it meaningfully moves a 15- or 30-minute average, yet its instantaneous pressure can injure the ear immediately. Regulating the peak protects both crew (as an occupational exposure) and audience against acute, impulse-driven hearing damage, and forces organisers to control device selection, charge size, firing position and stand-off distance from people rather than relying on average-level compliance alone.','A pyrotechnician and the event''s safety/acoustic officer use peak limits when planning effects: they choose device types and calculate exclusion zones so that the peak level at the nearest audience or crew position stays within the applicable ceiling, position mortars and flame units away from people, and where required log peak readings alongside the music LAeq. During a show a compliance officer monitors LCpeak so a finale''s pyrotechnics do not breach the permit''s impulse condition, and documents the readings as evidence.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Peak sound pressure level (LCpeak / Lpeak)','Impulse noise','C-weighting','DIN 15905-5','EU Directive 2003/10/EC','OSHA 29 CFR 1910.95','Exclusion / stand-off distance']::text[],ARRAY['Assuming a low music LAeq means the show is safe — a brief pyrotechnic peak can far exceed the average yet cause immediate harm, so it is controlled separately.','UNSAFE: Believing a single loud bang cannot damage hearing because it is over quickly — impulse peaks around or above 140 dB can cause instant, permanent injury.','Confusing A-weighted continuous limits with peak limits; peaks are usually assessed C-weighted or unweighted (LCpeak/Lpeak), not on the A-weighted music scale.','UNSAFE: Thinking ordinary foam earplugs fully neutralise close-range pyrotechnic impulses, so people can stand anywhere — protector attenuation is limited and distance and exclusion zones remain essential.','Treating one national 140 dB figure as the global rule when ceilings, weighting and measurement points differ by standard and jurisdiction.']::text[],ARRAY['A pyrotechnician sizes the audience exclusion zone for a stadium finale so the peak level at the front barrier stays within the permit''s impulse limit.','An occupational-safety officer measures crew exposure to C-weighted peaks near flame and concussion effects against the workplace peak limit value.','A festival compliance officer logs LCpeak during a fireworks display to show the local authority the impulse condition was met.','An enforcement inspector investigates a complaint of an unexpectedly loud pyrotechnic bang and reviews the event''s peak-noise records and stand-off distances.']::text[],'advanced','L_peak = 20 · log10(p_peak / p0),  p0 = 20 µPa','The peak sound pressure level in decibels equals twenty times the base-ten logarithm of the greatest instantaneous sound pressure divided by the reference pressure of twenty micropascals.','f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pyrotechnic peak noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f6ef828a-b3f6-5bf9-888d-d9f52230176f','f31111e1-7660-420a-a3b8-4f55780f8148',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f6ef828a-b3f6-5bf9-888d-d9f52230176f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f6ef828a-b3f6-5bf9-888d-d9f52230176f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7d3779a1-58f6-5dfa-b78b-fbd69423bf40','Recreational noise exposure','Exposure to potentially hazardous sound arising from leisure and entertainment activities rather than from paid work — including live concerts, nightclubs and bars, festivals, personal listening devices and headphones, cinemas, motorsport and sporting events, fitness classes and personal firearms/pyrotechnics use. It is the non-occupational counterpart to occupational noise exposure and is a growing focus of public-health and consumer-safety policy because it falls largely outside workplace noise law yet can accumulate to injurious weekly doses. The WHO estimates that over a billion young people (aged roughly 12–35) are at risk of hearing loss from recreational sound. Risk is assessed on the same equal-energy basis as occupational exposure — combining level and duration — so guidance is often framed as a weekly ''sound allowance'': for example, the WHO–ITU safe-listening standard (ITU-T H.870) uses a reference of 80 dB(A) over 40 hours per week for adults and 75 dB(A) over 40 hours per week for children. Because most recreational settings are unregulated by occupational limits, controls tend to be voluntary standards, venue codes, product-design requirements and public-information campaigns; the exact reference levels and their status vary by standard and country.','Recreational noise is loud sound from your free time. It comes from concerts, clubs, headphones, sports, and bars. It is not noise from your job. Loud leisure sound can still damage hearing over time. Health bodies treat it as a real risk. The WHO says over one billion young people are at risk. Safe-listening advice uses a weekly sound budget. For example, WHO and ITU suggest 80 decibels for 40 hours a week. Louder sound uses up that budget much faster. Exact figures and rules differ by standard and country.','The concept exists to name and manage hearing risk that workplace noise law does not reach. By framing leisure sound as a measurable, dose-based exposure, it lets public-health bodies, standards writers and device makers set safe-listening references, design volume-limiting and dose-tracking features into audio products, justify venue sound limits and earplug provision, and run awareness campaigns. It also matters in hearing-loss claims, where distinguishing occupational from recreational contribution can affect liability. In short, it extends hearing-conservation thinking beyond the factory floor to everyday entertainment.','A venue operator or event compliance officer uses the idea to justify audience sound limits, free earplugs, quiet zones and signage under safe-listening schemes. An audiologist or occupational-health assessor asks about concerts, headphones and shooting when separating recreational from work-related hearing loss in a claim. A product engineer implements the WHO–ITU sound-allowance and volume-limiting functions in a personal audio device so users can track how much of their weekly allowance they have used.','Sound Law — Live Events & Entertainment Compliance',ARRAY['Make Listening Safe','WHO–ITU safe listening standard (ITU-T H.870)','Occupational noise exposure','Noise-induced hearing loss (NIHL)','Sound allowance','Equal-energy principle','Personal audio device / safe listening']::text[],ARRAY['UNSAFE: Believing that because it is ''just leisure'' and not work, recreational sound cannot cause permanent hearing loss — the ear is damaged by dose (level and time), regardless of the setting.','Assuming occupational limits such as an 85 dB(A) eight-hour action value legally govern concerts and clubs; most recreational settings sit outside workplace noise law and rely on voluntary standards.','UNSAFE: Thinking headphone listening is automatically safe at any volume — high levels over long weekly hours can exceed the WHO–ITU 80 dB(A)/40-hour reference and injure hearing.','Treating one figure as the universal safe level; safe-listening references (level and duration) vary by standard and are lower for children than adults.']::text[],ARRAY['A nightclub joins a safe-listening scheme and provides earplugs, quiet chill-out zones and a capped sound level to reduce patrons'' recreational exposure.','An audiologist assessing a musician''s hearing loss weighs recreational headphone and gig exposure alongside any occupational history.','A smartphone maker builds a dose-tracking ''sound allowance'' feature based on the WHO–ITU standard so users see their weekly listening budget.','A public-health authority runs a campaign warning young festival-goers that repeated loud events add up to a hazardous weekly dose.']::text[],'intermediate',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Recreational noise exposure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7d3779a1-58f6-5dfa-b78b-fbd69423bf40','f31111e1-7660-420a-a3b8-4f55780f8148',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7d3779a1-58f6-5dfa-b78b-fbd69423bf40') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7d3779a1-58f6-5dfa-b78b-fbd69423bf40');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '81fe5214-56f8-587d-a1d1-a0a53483ce6f','Make Listening Safe','A World Health Organization initiative, launched within its work on deafness and hearing loss, that aims to prevent hearing loss from recreational sound exposure by promoting safe-listening practices. It targets three areas: venues and events, personal audio devices and systems, and public awareness — motivated by WHO''s estimate that over a billion young people worldwide are at risk from unsafe listening. Its two main technical outputs are the WHO ''Global standard for safe listening venues and events'' (2022) and, jointly with the ITU, the safe-listening standard for personal audio devices (ITU-T H.870). The venue standard sets six recommended features: a maximum average sound level (WHO recommends 100 dB); live, calibrated sound-level monitoring by trained staff; optimised venue acoustics and sound systems; available hearing protection with usage guidance; quiet zones for ear rest; and staff training and information. The initiative is public-health guidance, not binding law; its recommendations become enforceable only where a country, city or venue adopts them into regulation, licence conditions or codes.','Make Listening Safe is a WHO project. It aims to stop hearing loss from loud sound. It focuses on music, venues, and personal audio. The WHO wrote a standard for safe venues and events. It suggests a maximum average level near 100 decibels. It also asks for sound monitoring and free earplugs. It asks for quiet rest zones and trained staff. With the ITU, the WHO set a standard for audio devices. The goal is to let people enjoy music more safely. It is guidance, not a binding law by itself.','The initiative exists to coordinate a global, evidence-based response to a preventable but rising cause of hearing loss that mostly occurs outside workplace noise law. By publishing agreed features for safe venues, standards for audio devices, and public messaging, it gives governments, event operators and manufacturers a common reference to design safer products, run safer events and legislate consistently, and it equips the public to protect their own hearing. It turns diffuse concern about loud music into concrete, adoptable measures.','An event organiser or venue uses the six features as a checklist to build a safe-listening programme — setting a house sound limit, rostering a monitor to log calibrated levels, stocking earplugs, laying out quiet zones and briefing staff. A regulator or licensing authority cites the WHO features when writing event noise conditions or a national safe-listening policy. A device manufacturer implements the WHO–ITU standard''s volume-limiting and sound-allowance functions to comply with or anticipate consumer-safety requirements.','Sound Law — Live Events & Entertainment Compliance',ARRAY['WHO Global standard for safe listening venues and events (2022)','WHO–ITU safe listening standard (ITU-T H.870)','Recreational noise exposure','Noise-induced hearing loss (NIHL)','Personal hearing protection','Sound-level monitoring','Quiet zone']::text[],ARRAY['Assuming Make Listening Safe is a binding law — it is WHO public-health guidance that only becomes enforceable where a country, city or venue adopts it into regulation or licence terms.','Thinking the initiative only covers concerts and clubs; it also addresses personal audio devices, headphones and public-information alongside the WHO–ITU device standard.','UNSAFE: Reading the venue standard''s 100 dB average recommendation as a level everyone can safely enjoy for unlimited time — it is a ceiling paired with monitoring, earplugs and quiet zones, not a guarantee of safety.','Confusing the WHO venue standard with occupational noise limits; they serve different populations and use different metrics and legal status.']::text[],ARRAY['A festival adopts the WHO safe-listening features, capping the average level, logging sound with calibrated meters, and handing out earplugs at entry.','A national health ministry references the WHO Global standard when drafting a safe-listening policy for entertainment venues.','A headphone manufacturer builds the WHO–ITU volume-limiting and sound-allowance functions into its product to support safe listening.','A city licensing officer points an arena operator to the six WHO features while negotiating audience hearing-protection conditions for its licence.']::text[],'beginner',NULL,NULL,'f31111e1-7660-420a-a3b8-4f55780f8148' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Make Listening Safe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '81fe5214-56f8-587d-a1d1-a0a53483ce6f','f31111e1-7660-420a-a3b8-4f55780f8148',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='81fe5214-56f8-587d-a1d1-a0a53483ce6f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='81fe5214-56f8-587d-a1d1-a0a53483ce6f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '31e40ddb-1333-5555-95fc-d6f088baf4ff','Strategic noise mapping','The large-scale, model-based assessment of long-term environmental-noise exposure across a defined area, presented as maps of a harmonised indicator (typically Lden for overall annoyance and Lnight for sleep disturbance) plus tables of the number of people and dwellings exposed in stated level bands. Under the EU Environmental Noise Directive (2002/49/EC), competent authorities must produce strategic noise maps on a repeating cycle for agglomerations and for major roads, railways and airports above stated traffic thresholds, using a common calculation method (CNOSSOS-EU under Directive (EU) 2015/996) rather than measurement alone. The maps drive the number of people counted as exposed and feed later action planning. The sources, thresholds, indicators, level bands, height and calculation method that apply vary by legal round, Member State transposition and the guidance the authority follows; national or non-EU schemes (for example US airport or highway noise contours) use their own metrics and rules.','A strategic noise map shows long-term noise across a whole area. It is built by computer models, not just by meters. It uses agreed measures like the day-evening-night level and the night level. It also counts how many homes and people face each noise band. In the EU, authorities must make these maps on a set cycle. They cover big towns and busy roads, railways and airports. The maps then guide plans to cut noise. Exact rules, sources and cut-off points differ by country and law.','It exists to give regulators a consistent, comparable picture of who is exposed to environmental noise and by how much, so that noise can be managed as a public-health issue across borders. By standardising indicators, sources and calculation methods, strategic mapping lets Member States and the European Commission quantify exposure, track trends between rounds, target the worst-affected populations, and provide the evidence base that noise action plans and quiet-area protection are legally built on.','An acoustic consultant or local-authority noise officer assembles source data (traffic flows, speeds, fleet mix, rail and flight movements), a terrain and buildings model, and population data, runs the CNOSSOS-EU method in mapping software, and produces Lden/Lnight rasters, facade-point results and exposure tables. These outputs are published, reported to the Commission, and used to identify hotspots, prioritise mitigation, and demonstrate the statutory duty to map has been met.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Noise action plan','Agglomeration noise','Receiver grid','Noise contour','Environmental Noise Directive 2002/49/EC','CNOSSOS-EU','Lden']::text[],ARRAY['Thinking strategic maps are made from measurements at every point; they are computed with a standard calculation method, with monitoring used mainly for input and validation.','Assuming the exposure numbers are exact real levels at a home; they are modelled long-term averages at defined heights and facade points, with known uncertainty.','Believing one fixed set of thresholds applies; the source thresholds (for example roads above three or six million vehicles a year) and duty differ by legal round and country.','Confusing the map (assessment) with the action plan (the response); mapping identifies exposure, the action plan sets out what will be done about it.']::text[],ARRAY['A city environmental-health team compiles its five-yearly strategic noise maps for road and rail to report exposed-population counts to the national authority and the European Commission.','A regional transport agency maps a motorway above the vehicle-passage threshold to show how many dwellings fall in the highest Lden bands before planning barriers.','An airport operator produces Lden and Lnight contours around the runway to feed the surrounding agglomeration''s mapping and support night-flight discussions.','A consultant validates a modelled map against short-term facade measurements at a few reference dwellings before publication.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Strategic noise mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '31e40ddb-1333-5555-95fc-d6f088baf4ff','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='31e40ddb-1333-5555-95fc-d6f088baf4ff') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='31e40ddb-1333-5555-95fc-d6f088baf4ff');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee89cd51-a722-5bd2-9475-c5c2b9e41831','Noise action plan','A statutory plan drawn up by a competent authority to manage environmental-noise problems and their effects, and to reduce noise where necessary, based on the results of strategic noise mapping. Under the EU Environmental Noise Directive (2002/49/EC, Article 8 and Annex V), action plans are required for agglomerations and for major roads, railways and airports above stated thresholds, must be reviewed and revised on the mapping cycle (and at least every five years), and typically include the mapping results, exposure estimates, identified priority areas and quiet areas, the measures already in force and planned, a long-term strategy, a record of public consultation, and an estimate of the reduction in exposed people. The measures themselves (source limits, low-noise surfaces, barriers, speed or traffic management, insulation grants, quiet-area protection, operating restrictions) and any numeric triggers are chosen nationally and locally, so content and ''limit values'' vary by Member State, authority and receiver.','A noise action plan is a legal plan to manage and cut noise. It is built on the results of noise maps. In the EU, big towns and busy transport routes must have one. It sets out where noise is worst and who is affected. It lists the steps already taken and steps planned. These may include quieter road surfaces, barriers or speed limits. It also protects quiet areas and records public views. Plans are reviewed on a set cycle. The exact triggers and measures differ by country and place.','It exists to turn the picture from noise mapping into action, so that mapping is not an end in itself. The plan gives authorities a transparent, consultable framework to prioritise the most-affected people, coordinate measures across transport and planning bodies, protect areas that are still quiet, and be held accountable for progress between rounds. It converts broad public-health duties on noise into specific, reviewable commitments.','A local-authority or transport-body noise team uses the strategic maps to rank hotspots, then drafts an action plan proposing measures such as low-noise asphalt, barriers, or night-time speed limits, models their effect on exposed-population counts, runs a public consultation, and adopts the plan. It is then reported to the national authority and Commission and used to justify budgets and scheme prioritisation.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Strategic noise mapping','Quiet area','Agglomeration noise','Environmental Noise Directive 2002/49/EC','Lden','Noise contour']::text[],ARRAY['Assuming a noise action plan sets legally binding numeric noise limits; the Directive requires plans and lets Member States decide whether and what limit values or triggers to use.','Thinking the plan must eliminate noise; its duty is to manage effects and reduce noise where appropriate and feasible, prioritising the worst-affected.','Confusing the action plan with the noise map; the map assesses exposure, the plan is the response and must be consulted on with the public.','Believing every measure applies everywhere; measures and their triggers are selected per authority, source and receiver, and vary widely.']::text[],ARRAY['A metropolitan authority adopts a noise action plan proposing quieter road surfaces and barriers on the streets its maps show in the highest Lden bands.','A national roads agency reviews its major-road action plan on the five-year cycle and reports the estimated drop in people exposed above the reporting bands.','An airport''s action plan sets out night-movement management and insulation grants for dwellings inside its Lnight contours.','A citizen group responds during the statutory consultation asking that a nearby park be designated and protected as a quiet area.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise action plan');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee89cd51-a722-5bd2-9475-c5c2b9e41831','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee89cd51-a722-5bd2-9475-c5c2b9e41831') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee89cd51-a722-5bd2-9475-c5c2b9e41831');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '31f5fd58-873f-5a67-abcf-a95733809ce0','Agglomeration noise','Environmental noise assessed and managed at the scale of an ''agglomeration'' — a defined-term unit under the EU Environmental Noise Directive (2002/49/EC, Article 3(k)) meaning part of a territory with a population above 100,000 persons and a population density such that the Member State considers it an urbanised area. For agglomerations above the threshold, the competent authority must strategically map all relevant sources within the urban area (road, rail, air and industry, including IPPC sites) together, not just one source, and then produce a noise action plan. In the first legal round the mapping duty applied to larger agglomerations (above 250,000 inhabitants); from the second round it extended to all agglomerations above 100,000. Exact boundaries, which sources are included, indicators and reporting bands are set through national transposition and Commission reporting guidance, so the precise scope differs between Member States and mapping rounds.','An agglomeration is a large built-up urban area. In the EU it means a place with more than 100,000 people. It must also be dense enough to count as urban. Agglomeration noise is the noise mapped and managed across that whole area. Here all sources are assessed together, not just one road or line. This covers road, rail, air and industry inside the area. Big agglomerations must be mapped and given a noise action plan. The exact boundary and rules are set by each country.','The concept exists so that dense urban populations, where many noise sources overlap, are assessed as a whole rather than source by source. Treating the built-up area as one reporting unit captures combined exposure, lets authorities compare cities on a common basis, and ensures the places with the most people affected trigger both mapping and action-planning duties.','A city noise team uses the agglomeration boundary to scope its statutory work: it gathers road, rail, air and industrial source data inside that boundary, produces combined Lden/Lnight maps and exposure tables for the urban population, and builds the agglomeration''s action plan. The boundary and population also determine whether the duty and its deadline apply at all.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Strategic noise mapping','Noise action plan','Quiet area','Environmental Noise Directive 2002/49/EC','Most-exposed facade','Lden']::text[],ARRAY['Treating ''agglomeration'' loosely as any city; in the Directive it is a defined term tied to population above 100,000 and an urbanised density set by the Member State.','Assuming only one source is mapped; within an agglomeration all relevant sources (road, rail, air, industry) are assessed together.','Assuming the 100,000 threshold always applied; the first mapping round used a higher agglomeration threshold before it dropped in later rounds.','Confusing the administrative city boundary with the agglomeration boundary, which the Member State defines for noise purposes and may differ.']::text[],ARRAY['A national authority delineates which urban areas exceed 100,000 people and the urban-density test, fixing which cities owe agglomeration mapping in the coming round.','A city combines road, tram, rail and industrial source data to produce a single agglomeration Lden map and exposed-population table.','A metropolitan planner cross-checks two adjoining towns to decide whether they form one agglomeration for reporting.','An enforcement review compares agglomeration exposure figures between rounds to judge whether the city''s action plan is working.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Agglomeration noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '31f5fd58-873f-5a67-abcf-a95733809ce0','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='31f5fd58-873f-5a67-abcf-a95733809ce0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='31f5fd58-873f-5a67-abcf-a95733809ce0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '61335f7f-2010-587e-9fb3-1e73d35e1fad','Quiet area','A protected category of area whose existing good acoustic quality should be preserved from increases in environmental noise. The EU Environmental Noise Directive (2002/49/EC, Article 3(l) and (m)) distinguishes a ''quiet area in an agglomeration'' — delimited by the competent authority and not exposed to a value of Lden, or another appropriate indicator, greater than a value set by the Member State — from a ''quiet area in open country'', undisturbed by noise from traffic, industry or recreational activity. Designation, the numeric or descriptive criteria used, and the protective weight given (through action plans and planning decisions) are left to Member States and authorities, so both the threshold and the legal effect vary by country, method and, in soundscape-based approaches (ISO 12913), perceived quality rather than level alone.','A quiet area is a place kept free from rising noise. The aim is to protect its good sound quality. In the EU there are two types. One is a quiet area inside a big town or city. It must stay below a noise level the country sets. The other is a quiet area in open countryside. It should be undisturbed by traffic, industry or leisure noise. Authorities choose the areas and the test used. The exact level and how strongly it is protected differ by country.','It exists to shift noise policy from only reducing bad noise to also safeguarding places that are still restful, recognising the health and amenity value of calm. Designating quiet areas gives authorities a hook to resist new noise in those places through action plans and planning control, and gives the public identifiable spaces for relief from urban noise.','A local authority identifies candidate quiet areas (parks, green spaces, tranquil open country) using its noise maps and, where used, soundscape surveys, sets criteria against Lden or another indicator, designates them in the noise action plan, and then weighs that status when considering developments or transport schemes that would raise levels there.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Noise action plan','Strategic noise mapping','Agglomeration noise','Environmental Noise Directive 2002/49/EC','Lden','Soundscape (ISO 12913)']::text[],ARRAY['Thinking a quiet area means silence; it means relatively undisturbed or below a set indicator value, not zero sound.','Assuming there is one EU-wide numeric threshold; the qualifying level and criteria are set by each Member State and can differ widely.','Believing designation legally freezes noise; protection works mainly through action plans and planning weight, not an automatic ban on all new sources.','Treating quiet-in-agglomeration and quiet-in-open-country as the same; the Directive defines them differently, one by an indicator value, the other by being undisturbed.']::text[],ARRAY['A city designates a central park as a quiet area in its noise action plan and cites that status to oppose a nearby road-widening scheme.','A national park authority maps tranquil open country and argues for quiet-area protection against a proposed distribution depot.','A planning officer weighs a designated quiet area when assessing a night-time entertainment venue application on its edge.','A soundscape team surveys visitor perceptions to help set the qualifying criteria for candidate urban quiet areas.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quiet area');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '61335f7f-2010-587e-9fb3-1e73d35e1fad','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='61335f7f-2010-587e-9fb3-1e73d35e1fad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='61335f7f-2010-587e-9fb3-1e73d35e1fad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f9f47836-1229-5e04-bc25-a2ff9aad601e','Facade correction','An adjustment that accounts for the sound reflected by a building facade near the microphone, so that a level measured at or close to a facade can be related to the incident (free-field) sound used in environmental-noise assessment. A hard facade roughly doubles the sound pressure of the reflected component: for a microphone placed about 0.5–2 m in front of a reflecting facade, ISO 1996-2 associates a reflection contribution of about +3 dB, so a facade correction of roughly −3 dB converts that reading toward the incident level; a microphone flush with or very close to the facade sees pressure doubling of about +6 dB (approximately +5.7 dB), corrected accordingly. The EU Environmental Noise Directive assesses the incident sound at 4 m at the most exposed facade, excluding the reflection from the facade being assessed. Exact correction values, tolerances and whether they apply depend on the standard edition, microphone position, frequency content and geometry, and are not universal constants.','A facade correction adjusts for sound bouncing off a wall near the mic. A hard wall reflects sound back and raises the reading. About 0.5 to 2 metres from a reflecting facade, this adds roughly 3 decibels. So you subtract about 3 decibels to get the free-field level. A mic right on the wall can read about 6 decibels high. You subtract about that much to correct it. EU maps use the incident sound at the facade, not its own reflection. The exact figure depends on the standard, the mic spot and geometry.','It exists so that levels measured or modelled at different microphone positions can be compared on a common basis, and so that a dwelling''s exposure is not overstated by counting the reflection from its own wall. Standardising the correction lets facade-based measurements, free-field measurements and model outputs be reconciled, which matters when checking compliance or validating a noise map.','A technician choosing a facade or near-facade microphone position applies the correction from ISO 1996-2 for that geometry (about −3 dB at 0.5–2 m from a reflecting facade, more if flush-mounted) so the reported figure matches the incident-level basis the assessment or map requires, and records the position and correction in the measurement report.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Reflection correction','Most-exposed facade','Microphone height criterion','ISO 1996-2','Strategic noise mapping','Environmental Noise Directive 2002/49/EC']::text[],ARRAY['Assuming the facade always adds exactly 3 dB; +3 dB applies roughly to a position a short distance in front of a reflecting facade, while a flush-mounted mic sees closer to +6 dB.','Applying a facade correction to a genuine free-field measurement, which double-corrects and understates the level.','Confusing the incident (free-field) level with the total level at the facade; the Directive uses the incident field, excluding the assessed facade''s own reflection.','Treating the correction as a fixed constant across all frequencies and geometries when it depends on position, standard edition and conditions.']::text[],ARRAY['An acoustic consultant mounts a microphone 2 m in front of a bedroom facade for a night-noise complaint and applies the ISO 1996-2 reflection correction before reporting.','A mapping engineer sets model facade points to output the incident level so results are comparable with the Directive''s 4 m assessment basis.','A regulator reviews a compliance report and checks whether the facade correction matched the microphone position used.','A student compares free-field and facade measurements at the same house to see the reflection contribution.']::text[],'advanced','L_incident ≈ L_measured − C_facade,  C_facade ≈ 3 dB (0.5–2 m in front of a reflecting facade), ≈ 6 dB (flush-mounted)','The incident (free-field) level is approximately the measured level minus a facade correction; that correction is about three decibels for a microphone a short distance in front of a reflecting facade, and about six decibels for a microphone mounted flush against it.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Facade correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f9f47836-1229-5e04-bc25-a2ff9aad601e','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f9f47836-1229-5e04-bc25-a2ff9aad601e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f9f47836-1229-5e04-bc25-a2ff9aad601e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '621a32f6-d9ab-59b2-815d-7a7ad92439b2','Reflection correction','A general adjustment that removes, or accounts for, the contribution of reflected sound so that a measured or modelled level represents the intended quantity (usually the incident or free-field sound). It is the broader family of which facade correction is the most common case: reflections can come from the building under assessment, other nearby hard surfaces, the ground, or reflecting screens. In ISO 1996-2 practice, a microphone near a single reflecting surface receives roughly +3 dB from that reflection at a short distance and up to about +6 dB flush against it, and the corresponding reflection correction (about −3 dB or −6 dB) is applied. In propagation models such as ISO 9613-2 and CNOSSOS-EU, reflections are handled explicitly as extra ray paths with a reflection loss, and the assessment result is defined to include or exclude the reflection from the receiver''s own facade as the method specifies. Exact values depend on surface absorption, geometry, angle, frequency and the standard applied, so no single correction is universal.','Sound often reaches a mic both directly and after bouncing off surfaces. A reflection correction adjusts for that bounced sound. It is used so a reading matches the level you actually want. Near one hard surface, a short distance away, reflection adds about 3 decibels. Right against the surface it can add about 6 decibels. You subtract that to get the direct, free-field level. In noise models, reflections are traced as extra sound paths instead. The exact figure depends on the surface, angle and standard used.','It exists to keep noise levels honest by separating the sound of interest from artefacts of nearby geometry, so results at different positions and from different methods can be compared and combined. Without a defined reflection correction, a level would depend heavily on incidental hard surfaces near the microphone, undermining compliance checks, map validation and cross-site comparison.','A technician identifies reflecting surfaces near a measurement point and either moves the microphone to a free-field position or applies the standard''s reflection correction for the geometry used; a modeller sets reflection order and surface absorption in the software and confirms whether the receiver''s own-facade reflection is included, so outputs match the required assessment basis.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Facade correction','Most-exposed facade','ISO 1996-2','ISO 9613-2','Receiver grid','Strategic noise mapping']::text[],ARRAY['Assuming reflection correction only ever means −3 dB; the value depends on distance, surface, angle and frequency, and can approach −6 dB flush against a surface.','Forgetting reflections from surfaces other than the assessed facade, such as opposite buildings or the ground, when siting a microphone.','Double-counting by both correcting a measurement for reflection and modelling the same reflection as a separate path.','Assuming every method excludes the receiver-facade reflection; whether it is included depends on the standard and the defined assessment quantity.']::text[],ARRAY['A consultant measuring in a street canyon accounts for reflections from the facade opposite as well as the building behind the microphone.','A modeller sets the reflection order and facade absorption in a CNOSSOS-EU calculation to match the Directive''s assessment definition.','An enforcement officer rejects a reading taken 30 cm from a hard wall without any reflection correction noted.','A rail-noise study corrects near-barrier measurements for reflections off the barrier before comparing them to free-field predictions.']::text[],'advanced','L_free-field ≈ L_measured − C_refl,  C_refl ≈ 3 dB (short distance from one reflecting surface) to ≈ 6 dB (flush)','The free-field level is approximately the measured level minus a reflection correction, where that correction is about three decibels near a single reflecting surface and about six decibels for a microphone flush against it, with the exact value set by geometry, surface and standard.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reflection correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '621a32f6-d9ab-59b2-815d-7a7ad92439b2','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='621a32f6-d9ab-59b2-815d-7a7ad92439b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='621a32f6-d9ab-59b2-815d-7a7ad92439b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '70222291-2502-5a71-918f-913c35e01f04','Microphone height criterion','The rule specifying the height above ground at which the assessment or measurement point is placed, because sound level varies with height due to ground effect, screening and source geometry. For strategic mapping under the EU Environmental Noise Directive (Annex I), the assessment height is 4.0 m ± 0.2 m (i.e. 3.8–4.2 m) above ground at the most exposed facade, reflecting a representative upper-floor exposure and allowing a common basis across Member States; lower positions may be used with correction to the equivalent 4 m value. Local or compliance measurements under ISO 1996-2 or national codes commonly specify other heights (for example around 1.2–1.5 m for a standing or seated receiver, or a stated height at a specific floor). The correct height therefore depends on purpose (strategic mapping versus specific-complaint measurement), the governing standard, the receiver being represented, and national method, and is not a single universal figure.','Noise level changes with height above the ground. So a rule fixes the height of the measuring point. For EU strategic maps, that height is 4 metres, plus or minus 0.2 metres. This stands for a typical upper-floor window. Lower points can be used if adjusted to the 4 metre value. Local and complaint checks often use a lower height instead. Around 1.2 to 1.5 metres is common for a person''s ear height. The right height depends on the job, the standard and the country.','It exists to make levels reproducible and comparable, since the same source can give different readings at different heights. Fixing the height ties the assessment to a defined receiver (an upper-floor facade for mapping, or a person''s ear height for some local checks) and prevents disputes or map inconsistencies caused by arbitrary microphone placement.','A mapping engineer sets facade assessment points at 4 m in the model to satisfy the Directive; a field technician handling a noise complaint instead follows the applicable code''s height (often about 1.5 m, or at the affected room''s window) and records it, so the measurement matches the standard being applied and can be defended in enforcement.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Most-exposed facade','Facade correction','Strategic noise mapping','Receiver grid','ISO 1996-2','Environmental Noise Directive 2002/49/EC']::text[],ARRAY['Assuming one height fits all tasks; strategic mapping uses 4 m at the facade, while many local and compliance measurements use lower heights.','Treating the 4 m mapping height as a measurement instruction; it is primarily a modelled assessment height, with lower measured positions corrected to it.','Ignoring that height interacts with ground effect and screening, so a barrier judged effective at ear height may protect less at 4 m.','Recording a level without noting the height and position, making the result impossible to reproduce or compare.']::text[],ARRAY['A consultant configures 4 m facade points in mapping software so the strategic map meets the Directive''s assessment basis.','An environmental-health officer measures a nightclub complaint at about 1.5 m at the complainant''s window per the local code and logs the height.','A reviewer rejects a submitted map that placed assessment points at ground level instead of 4 m.','A researcher compares 1.5 m and 4 m results at the same facade to show how barrier benefit falls with height.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microphone height criterion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '70222291-2502-5a71-918f-913c35e01f04','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='70222291-2502-5a71-918f-913c35e01f04') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='70222291-2502-5a71-918f-913c35e01f04');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '23b35cfc-9c14-5f28-ae90-27d9f4db6ce6','Most-exposed facade','The face of a building that receives the highest environmental-noise level, used as the reference location for assessing a dwelling''s exposure. Under the EU Environmental Noise Directive (Annex I), the assessment point is placed at 4 m above ground at the most exposed facade, and the incident sound is assessed there, excluding the reflection from that facade itself. Because a building''s sides differ in exposure depending on their orientation to the source and any screening, using the most-exposed facade gives a consistent, protective (worst-case-per-dwelling) basis for counting people in Lden/Lnight exposure bands. Some assessments also report the quietest facade or a habitable-room facade for particular purposes. Which facade qualifies, how it is chosen in a model, and whether additional facades are reported depend on the method, national guidance and the assessment''s aim, so the concept is defined by role rather than a fixed physical rule.','A building''s sides do not all get the same noise. The most-exposed facade is the side facing the loudest sound. It is used as the reference point for that home''s exposure. EU maps assess the level there, 4 metres up. They use the incident sound and leave out that wall''s own reflection. Picking the loudest side gives a fair, cautious basis per home. Some studies also report the quietest side for other reasons. How the loudest facade is chosen depends on the method and country.','It exists to give a defined, comparable and reasonably protective point for exposure counting, so that the number of people in each noise band does not depend on which wall an assessor happens to pick. Anchoring the count to the loudest facade captures the exposure that matters most for annoyance and sleep disturbance and keeps results consistent across dwellings and cities.','A mapping engineer''s software identifies each building''s most-exposed facade, places a 4 m assessment point there, computes the incident Lden/Lnight, and assigns the dwelling''s residents to the resulting exposure band; where a scheme also cares about respite, the model may additionally output the quietest-facade level to inform, for example, dual-aspect dwelling design.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Microphone height criterion','Facade correction','Strategic noise mapping','Receiver grid','Environmental Noise Directive 2002/49/EC','Lden']::text[],ARRAY['Assuming the most-exposed facade always faces the nearest road; screening, orientation and reflections can move the loudest face elsewhere.','Confusing the most-exposed facade level with the level inside the dwelling; the assessment is the outdoor incident level at the facade, not indoors.','Believing the assessment includes the reflection off that facade; the Directive uses the incident field, excluding the assessed facade''s own reflection.','Thinking a quiet rear facade lowers the counted exposure; exposure is usually assigned from the most-exposed facade for the protective count.']::text[],ARRAY['A mapping team assigns each block of flats to a noise band using the 4 m level at its most-exposed facade.','A planner requires a new residential building to place bedrooms away from the most-exposed facade to meet indoor noise targets.','An enforcement review checks that a developer''s noise assessment used the most-exposed facade rather than a sheltered side.','A consultant reports both most-exposed and quietest facade levels to support a dual-aspect layout with a quiet side.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Most-exposed facade');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '23b35cfc-9c14-5f28-ae90-27d9f4db6ce6','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='23b35cfc-9c14-5f28-ae90-27d9f4db6ce6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='23b35cfc-9c14-5f28-ae90-27d9f4db6ce6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6e5a26b8-e773-5a80-b29b-a22fac660144','Receiver grid','A regular array of calculation points (receivers) laid over the study area in a noise model, at which sound levels are computed so the results can be interpolated into continuous maps and contours. In strategic noise mapping, a horizontal grid (commonly a fixed spacing such as 10 m, refined near sources or buildings) is combined with facade receiver points on buildings for exposure counting; the calculation height matches the assessment height (for example 4 m under the EU Environmental Noise Directive). Each grid point receives contributions from all modelled source paths (direct, ground-reflected, screened, and reflected), and finer grids give smoother contours at higher computational cost. Grid spacing, height, refinement rules and whether facade points or a free-field grid are used depend on the calculation method (CNOSSOS-EU, ISO 9613-2), the software, the purpose (display map versus exposure statistics) and national guidance, so there is no single mandatory resolution.','A receiver grid is a mesh of calculation points over the area. The model works out the noise level at each point. These points are then joined into a smooth map and contours. A common grid spacing is 10 metres, made finer near sources or buildings. The height matches the assessment height, often 4 metres in the EU. Each point adds up all the sound paths reaching it. A finer grid gives smoother maps but takes more computing. Spacing, height and rules depend on the method and software.','It exists to turn point-by-point model calculations into the continuous exposure surfaces regulators need, balancing accuracy against computation. The grid defines where levels are known; facade points feed the legally required exposed-population counts, while the area grid produces the display contours used to communicate and prioritise.','A modeller sets the grid spacing and height in the software (for example 10 m at 4 m height, refined near roads and buildings), adds facade receiver points for the exposure statistics, runs the calculation, and interpolates the grid into the published Lden/Lnight contour map, choosing finer spacing where the map must resolve steep gradients such as behind barriers.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Noise contour','Iso-decibel contour','Strategic noise mapping','Most-exposed facade','CNOSSOS-EU','ISO 9613-2']::text[],ARRAY['Thinking the grid points are measurements; they are computed values from a propagation model at chosen points.','Assuming a single mandatory grid resolution; spacing and refinement are set by method, purpose and software, not one universal number.','Using the area grid for exposure counts instead of building facade points, which can miscount people.','Believing a coarser grid is always fine; too coarse a grid smooths over sharp gradients like the shadow behind a barrier.']::text[],ARRAY['A consultant sets a 10 m grid at 4 m height, refined near a motorway, to generate a city''s strategic Lden contours.','A modeller adds facade receivers on every building to produce the exposed-population table the regulator requires.','An analyst increases grid density behind a proposed barrier to resolve the acoustic shadow accurately.','A reviewer questions a submitted map whose coarse grid hid a hotspot between calculation points.']::text[],'advanced',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Receiver grid');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6e5a26b8-e773-5a80-b29b-a22fac660144','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6e5a26b8-e773-5a80-b29b-a22fac660144') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6e5a26b8-e773-5a80-b29b-a22fac660144');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1120d963-ef8f-5c57-b1ad-d0053a878140','Noise contour','A line on a map joining points of equal sound level, drawn from modelled or measured data to show how a chosen noise indicator (for example Lden or Lnight) is distributed across an area. Contours are usually plotted in fixed bands (commonly 5 dB steps) and shaded to reveal the spatial pattern of exposure around roads, railways, airports, industry or event sites. They are derived by interpolating between receiver-grid calculation points. A noise contour describes the sound field, not automatically a legal limit; whether crossing a given contour triggers any obligation depends on the applicable regime. The indicator, band width, height, calculation method and any regulatory meaning attached to a contour vary by jurisdiction and purpose (EU strategic mapping under 2002/49/EC, US airport DNL or highway contours, industrial or festival modelling), so the same-looking contour can mean different things.','A noise contour is a line joining points of equal sound level. It works like a height line on a map, but for noise. Contours show how noise spreads across an area. They are often drawn in steps, such as every 5 decibels. Colours between the lines show louder and quieter zones. They are built by joining calculated grid points. A contour shows the sound, not always a legal limit. What a given contour means depends on the country and rules.','It exists to make invisible sound patterns visible and comparable, so planners, regulators and the public can see where noise is high, where it falls off, and where sensitive receivers lie. Contours communicate exposure at a glance, support hotspot prioritisation, and let alternative mitigation options be compared on a map.','A consultant produces Lden/Lnight contour maps from a validated model to accompany a strategic map, a planning application or an event plan, uses the contours to show which dwellings fall in which bands, and tests whether a barrier or layout change pulls a target contour back from sensitive receivers.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Iso-decibel contour','Receiver grid','Strategic noise mapping','Noise catchment','Lden','Environmental Noise Directive 2002/49/EC']::text[],ARRAY['Reading a contour as a legal limit line; it shows equal level, and any obligation depends on the regime, not the contour itself.','Assuming contours are measured; they are usually interpolated from model calculations at grid points.','Treating a contour as exact at the metre; it carries the model''s uncertainty and grid resolution.','Comparing contours between studies without checking they use the same indicator, height, band width and method.']::text[],ARRAY['An airport publishes DNL/Lden contours to show which neighbourhoods lie in each exposure band for its noise programme.','A city overlays Lnight contours on a residential map to target night-noise action in the highest bands.','A festival''s acoustic consultant models spill contours to keep the highest band off nearby homes when siting the stage.','A planner uses road-noise contours to decide the setback and glazing spec for a new housing block.']::text[],'beginner',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise contour');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1120d963-ef8f-5c57-b1ad-d0053a878140','fe939357-1f13-4421-b331-61ce91d66150',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1120d963-ef8f-5c57-b1ad-d0053a878140') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1120d963-ef8f-5c57-b1ad-d0053a878140');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ef5cd24e-ab73-59b5-b4af-3474d8c40230','Iso-decibel contour','A noise contour named for what it depicts: a line of equal (''iso-'') decibel level on a map, connecting points that share the same value of a chosen indicator. It is functionally the same object as a noise contour and the term is used interchangeably, most often in airport, industrial and large-event modelling where ''iso-dB'' or ''iso-contour'' emphasises the equal-level nature of each line. Iso-decibel contours are generated by interpolating a receiver grid and are typically drawn in fixed steps (for example 5 dB) of an indicator such as Lden, Lnight, DNL or LAeq. Like any contour, an iso-decibel line describes the modelled or measured sound field and only carries regulatory weight where a specific regime attaches meaning to a given level; the indicator, step, height and method, and thus the interpretation, vary by jurisdiction and application.','An iso-decibel contour is just a noise contour by another name. ''Iso'' means equal, so it joins points of equal decibel level. Airport, industry and big-event studies often use this name. Each line marks one sound level across the map. They are usually drawn in steps, such as every 5 decibels. They come from joining calculated grid points. The line shows the sound, not always a legal limit. Its meaning depends on the measure, method and country used.','It exists for the same reason as any noise contour: to show equal-level lines so spatial exposure can be seen, compared and communicated. The ''iso-decibel'' label simply stresses that each line is one constant level, which is helpful when several indicators or sources are shown together.','An airport or industrial acoustician plots iso-decibel contours of DNL or Lden to define which properties fall inside each exposure band for land-use, insulation or permitting decisions, and compares scenarios by watching how an iso-dB line moves when operations or mitigation change.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Noise contour','Receiver grid','Noise catchment','Strategic noise mapping','Lden','Environmental Noise Directive 2002/49/EC']::text[],ARRAY['Thinking an iso-decibel contour differs technically from a noise contour; it is the same thing under a name stressing equal level.','Assuming the line is a hard boundary of harm; it is one modelled level, with obligations depending on the regime.','Comparing iso-dB contours across studies without matching indicator, step and method.','Reading the contour as measured rather than interpolated from grid calculations.']::text[],ARRAY['An airport land-use plan uses DNL iso-decibel contours to define compatible and incompatible zones around the runway.','An industrial site models iso-dB LAeq contours to show a permitting authority the level at the nearest dwellings.','An event acoustician compares iso-decibel lines for two stage orientations to protect a residential edge.','A regulator overlays iso-dB contours from successive rounds to see whether exposure zones have shrunk.']::text[],'beginner',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Iso-decibel contour');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ef5cd24e-ab73-59b5-b4af-3474d8c40230','fe939357-1f13-4421-b331-61ce91d66150',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ef5cd24e-ab73-59b5-b4af-3474d8c40230') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ef5cd24e-ab73-59b5-b4af-3474d8c40230');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6ab1e79a-1fc5-52b3-ba02-2eeee628212a','Noise catchment','The geographic area over which a given source''s noise is significant, i.e. the footprint of the population and receivers meaningfully affected by that source. By analogy with a water catchment, it delimits where the source''s contribution matters for assessment, complaints or management, typically bounded by a chosen threshold contour (for example the area inside a stated Lden or LAeq value) beyond which the source''s contribution is negligible relative to background. Noise catchment is used to scope which dwellings and sensitive receivers to include in an assessment, to estimate the exposed population attributable to a source, and to define consultation or liaison zones. It is a working/analytical concept rather than a single legally fixed boundary; its extent depends on source power and directivity, terrain and screening, meteorology, the threshold chosen, and the applicable method, so different thresholds or conditions give different catchments for the same source.','A noise catchment is the area a source noticeably affects. It is like a water catchment, but for sound. It is often bounded by a chosen level line, such as an Lden value. Inside it, the source adds meaningfully to the noise. Outside it, the source barely matters against background. It sets which homes and receivers an assessment should include. It also helps estimate how many people a source affects. Its size depends on the source, terrain, weather and the level chosen.','It exists to bound the analysis and responsibility for a source sensibly, so an assessment or complaint response focuses on receivers the source actually reaches rather than the whole map. Defining a catchment supports estimating source-attributable exposure, scoping consultation and monitoring, and allocating mitigation duties to the right area.','A consultant or operator sets a threshold (for example an Lden or LAeq contour) to draw a source''s noise catchment, includes the dwellings inside it in the exposure assessment or complaint-handling zone, and uses that boundary to decide who to notify, where to place monitors, and how far mitigation must reach.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Noise contour','Iso-decibel contour','Strategic noise mapping','Most-exposed facade','Receiver grid','Noise action plan']::text[],ARRAY['Treating the catchment as a fixed legal boundary; it is analytical and shifts with the threshold, source and conditions chosen.','Ignoring meteorology and terrain, which can extend a catchment downwind or across open ground well beyond a naive circle.','Assuming one radius fits all sources; catchment depends on source power, directivity and screening, not distance alone.','Confusing the catchment with the audible limit; faint audibility can extend past the level where the source meaningfully adds to exposure.']::text[],ARRAY['A wind-farm or industrial applicant defines the noise catchment to a chosen Lday/Lnight contour to scope which dwellings its assessment must cover.','An event producer sets a spill catchment to decide which streets to leaflet and where to station community-liaison monitors.','A council maps a road''s noise catchment to attribute exposed population to that road within the wider agglomeration.','An enforcement officer uses the catchment to judge which complaints are plausibly linked to a specific plant under downwind conditions.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise catchment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6ab1e79a-1fc5-52b3-ba02-2eeee628212a','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6ab1e79a-1fc5-52b3-ba02-2eeee628212a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6ab1e79a-1fc5-52b3-ba02-2eeee628212a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '416867ee-ab63-537a-b7e1-d498d30ce0a9','Acoustic zoning','The land-use planning technique of dividing a territory into zones classified by their noise sensitivity or permitted acoustic environment, with each class assigned limit values (for emission at the source and/or immission at the receiver) by time of day. It links what may happen acoustically to how land is used: quiet, sensitive uses (hospitals, schools, protected residential and rural areas) get the strictest limits, and industrial areas the most permissive. A well-known example is Italy''s acoustic classification under Law 447/1995 and DPCM 14/11/1997, which sorts municipal territory into six classes (from Class I ''particularly protected'' to Class VI ''exclusively industrial'') each with day (06:00–22:00) and night (22:00–06:00) absolute limits in dB(A); ISO 1996-1 similarly recognises area categories for setting limits. The number of classes, the metric, the limit values, the day/night split and the legal effect all vary by country and municipality, so acoustic zoning is a framework, not a single universal scale.','Acoustic zoning splits land into zones by noise sensitivity. Each zone gets its own noise limits, set by law. Quiet, sensitive places get the strictest limits. Think of hospitals, schools and protected homes. Industrial areas get the most relaxed limits. Limits usually differ for day and night. Italy, for example, uses six acoustic classes with day and night limits. The measure, the number of classes and the values differ by country and town.','It exists to prevent incompatible land uses from clashing acoustically and to give planners and enforcers clear, place-based limits. By tying limit values to zones, acoustic zoning lets authorities protect sensitive receivers, guide where noisy activities may locate, judge new developments against a known target, and resolve disputes with an objective, mapped basis.','A municipality adopts an acoustic classification map assigning each area a class and its day/night limits; planners then check new developments and activities against the limit for that zone, and enforcement officers measure against the immission limit for the receiver''s class when handling complaints, requiring mitigation where the class limit is exceeded.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Quiet area','Noise action plan','Strategic noise mapping','ISO 1996-1','Most-exposed facade','Noise catchment']::text[],ARRAY['Assuming acoustic zones and their limits are the same everywhere; the number of classes, metric and values are set nationally or locally and differ widely.','Confusing emission limits (at the source) with immission limits (at the receiver); zoning schemes often set both, and they are not the same figure.','Treating a zone limit as an instantaneous cap; many schemes apply it as an average over day or night periods, with separate rules for peaks.','Believing zoning applies limits only to new sources; it typically also sets targets that existing areas and remediation plans must work toward.']::text[],ARRAY['An Italian comune adopts its acoustic classification, assigning a residential district Class II with 55 dB(A) day and 45 dB(A) night immission limits.','A planning authority refuses a workshop in a zone whose class limit its predicted emissions would exceed at neighbouring homes.','An enforcement officer measures a complaint against the immission limit for the receiver''s acoustic class, day and night.','A city aligns its acoustic zoning map with its noise action plan so quiet, sensitive zones are protected from new development.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic zoning');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '416867ee-ab63-537a-b7e1-d498d30ce0a9','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='416867ee-ab63-537a-b7e1-d498d30ce0a9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='416867ee-ab63-537a-b7e1-d498d30ce0a9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '82fdfcd5-5d67-547b-83e9-59c7258e3f10','Zoning noise criterion','A noise limit or target that a regulator sets according to the land-use zone in which the receiver sits — for example residential, commercial, industrial, mixed-use, or a special-use zone such as a hospital or quiet-recreation area. The premise is that acceptable noise depends on the character and expected quiet of the surroundings, so a quiet residential neighbourhood is assigned a lower permitted level than a commercial or industrial district. Zoning criteria are usually expressed as an outdoor level (for example an LAeq over a stated period, or a day/night indicator such as Ldn or Lden) measured at or near the affected property, and they are commonly paired with time-of-day differentiation so night limits are stricter than day limits. ISO 1996-1 provides the framework of area categories and long-term rating levels that many national and municipal schemes build on. The actual numeric values, the metric used, the measurement position, the averaging time and the zone boundaries vary widely by country, state, city ordinance, venue licence and the standard the authority follows.','A zoning noise criterion sets a noise limit by land-use type. Quiet homes get a lower limit than shops or factories. The idea is simple. People expect more quiet in a housing area. So the rule allows less noise there. Busier zones are allowed more noise. Limits are usually measured near the affected property. Night limits are often stricter than day limits. The exact numbers change by country, city, and method. Local officials set the zone lines and the values.','The criterion exists to make noise limits fair and predictable by tying them to what each area is used for and the quiet people reasonably expect there. Instead of one blanket number, it lets planners protect sensitive receivers like homes, schools and hospitals while allowing appropriate activity in commercial and industrial zones. It gives developers, operators and enforcement officers a clear, location-specific yardstick for planning consent, permit conditions and complaint investigation, and it underpins land-use planning decisions such as buffer zones and setback distances.','A planning consultant checks the zoning category of the nearest sensitive receiver, reads the applicable day and night limits for that zone, and predicts or measures the development''s level there to show compliance in a planning or licensing submission. An environmental-health officer investigating a complaint identifies the receiver''s zone, applies the matching criterion at the correct measurement position, and compares the measured rating level against it to decide whether a breach has occurred and what mitigation to require.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['ISO 1996-1','Land-use planning','Time-of-day correction','Noise-sensitive receiver','Ldn / Lden','Buffer zone / setback','LAeq']::text[],ARRAY['Assuming a single national number applies everywhere — zoning limits, their metric, averaging time and measurement point are set by the local authority and zone category.','Confusing the zone of the noise source with the zone of the receiver; the criterion is generally applied at the affected receiver''s location, not the source''s.','Thinking the daytime limit also governs night; most schemes set a separate, stricter night criterion for the same zone.','Treating a rezoning or new development as automatically exempt; a new noise source usually must still meet the receiving zone''s criterion.']::text[],ARRAY['A developer planning a distribution depot beside a housing estate checks the residential-zone night limit before siting loading bays.','A city environmental-health officer applies the mixed-use zone criterion at a flat above a bar while investigating a complaint.','A planner drafting an ordinance assigns lower limits to a hospital quiet zone than to the adjacent commercial strip.','A wind-farm consultant compares predicted levels at scattered rural dwellings against the applicable rural-zone criterion.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Zoning noise criterion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '82fdfcd5-5d67-547b-83e9-59c7258e3f10','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='82fdfcd5-5d67-547b-83e9-59c7258e3f10') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='82fdfcd5-5d67-547b-83e9-59c7258e3f10');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e48fad1c-2760-5eb0-895e-b84987d92e00','Time-of-day correction','The general practice, in environmental-noise assessment, of adjusting either the permitted limit or the assessed level according to the period of the day, so that the same physical sound is judged more severely at times when people expect quiet and are more easily disturbed — typically evening and night. It takes two common forms: (a) tiered limits, where a zone''s night criterion is set lower than its day criterion; and (b) rating-level penalties, where a fixed number of decibels is added to the measured level in sensitive periods before comparison with a single limit. The composite day-evening-night indicator Lden used across the EU embodies the second form, adding a weighting to evening and night contributions. The exact period boundaries, the size of any penalty and the metric all vary by jurisdiction and standard; under Directive 2002/49/EC the default periods are day 07:00–19:00, evening 19:00–23:00 and night 23:00–07:00, but Member States may shift the evening boundary by one to two hours.','A time-of-day correction makes noise rules stricter at certain hours. People want more quiet in the evening and at night. So the rule treats the same sound as worse then. This is done in two ways. One way sets a lower limit at night. The other way adds extra decibels to the reading first. The EU Lden indicator uses the second way. Default periods are day, evening, and night hours. Exact hours and penalty sizes change by country and method.','The correction exists because human sensitivity to noise is not constant through the day: the same level that is tolerable at noon can disturb rest and sleep at night. By weighting or restricting sensitive periods, regulators protect health-critical rest without banning activity outright, and they create a single defensible basis for setting curfews, planning conditions and enforcement thresholds. It lets one indicator or limit reflect both how loud a source is and when it operates.','An acoustic consultant applies the correct period boundaries and any penalty when computing a rating level for a planning report, so an operation that runs into the evening is assessed against the appropriate stricter benchmark. A compliance officer scheduling a survey times measurements to the regulated period and applies the specified evening or night adjustment before comparing the result with the limit, ensuring the assessment reflects when the noise actually occurs.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Lden','Evening penalty','Night penalty','Lnight','Curfew / restricted hours','Zoning noise criterion','Directive 2002/49/EC']::text[],ARRAY['Assuming the period boundaries are universal; the day/evening/night hours and any penalty are defined by the applicable directive, standard or local ordinance and can differ.','Applying a daytime limit to an evening or night operation because the raw level looks compliant, ignoring the required correction.','Believing Lden''s evening and night weightings are extra measured noise rather than fixed decibel additions applied in the calculation.','Forgetting that some regimes use lower night limits instead of penalties, so the two approaches must not be double-counted.']::text[],ARRAY['A consultant assessing a late-opening venue applies the evening and night weightings when computing Lden for a noise-mapping report.','An enforcement officer times a survey to the regulated night period before comparing levels with the night criterion.','A licensing authority sets a curfew as a time-of-day control after evening penalties push a venue''s rating over the limit.','A logistics operator reschedules HGV movements to daytime after realising night corrections make evening deliveries non-compliant.']::text[],'intermediate','L_den = 10·log10( (1/24)·[12·10^(L_day/10) + 4·10^((L_evening+5)/10) + 8·10^((L_night+10)/10)] )','The day-evening-night level equals ten times the base-ten logarithm of the twenty-four-hour energy average, where the evening level is raised by five decibels and the night level by ten decibels before averaging over their respective hours.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-of-day correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e48fad1c-2760-5eb0-895e-b84987d92e00','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e48fad1c-2760-5eb0-895e-b84987d92e00') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e48fad1c-2760-5eb0-895e-b84987d92e00');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4bb8af98-201d-5a93-8220-a91af450c542','Evening penalty','A fixed decibel addition applied to the evening period''s noise contribution in composite day-evening-night indicators of the Lden family, reflecting that people are more sensitive to noise in the early-night leisure and wind-down hours than during the working day. Under Directive 2002/49/EC (the Environmental Noise Directive), the evening period is by default 19:00–23:00 and its A-weighted equivalent level is increased by 5 dB before being combined with the day and night contributions to form Lden. The penalty is a calculation weighting, not additional measured sound: 5 dB is added to the evening Leq term inside the energy average. Member States may shorten or lengthen the evening period by one to two hours, adjusting the day and night periods accordingly, provided the choice is used consistently for all sources. The penalty''s size and the exact period boundaries are defined by the standard or jurisdiction in use and can differ elsewhere.','The evening penalty adds extra decibels to evening noise in a calculation. It reflects that people want more quiet in the evening. In the EU Lden system the evening is 7 pm to 11 pm by default. Five decibels are added to the evening level. This is a math weighting, not real extra sound. It makes evening noise count as worse. The result feeds into the overall Lden figure. Countries may shift the evening hours a little. The penalty size and hours are set by the rule in use.','The evening penalty exists to make a single long-term indicator reflect the greater disturbance caused by the same level in the evening, when many people relax at home, eat and prepare for sleep. By loading evening noise in the calculation, Lden discourages shifting loud activity into that period and gives planners and regulators a health-weighted basis for mapping, limits and mitigation. It captures timing, not just loudness, in one comparable number.','A noise-mapping analyst applies the 5 dB evening weighting to the evening Leq when computing Lden across a road, rail or industrial map, so the resulting contours reflect evening sensitivity. A consultant assessing a venue that trades into the evening includes the penalty in the predicted Lden used in a planning submission, which can be the difference between a pass and a required mitigation such as reduced hours or added attenuation.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Lden','Night penalty','Time-of-day correction','Directive 2002/49/EC','Strategic noise mapping','LAeq','Lnight']::text[],ARRAY['Thinking the 5 dB is extra noise that was measured, rather than a fixed weighting added to the evening term in the Lden formula.','Assuming the evening period is always 19:00–23:00; Member States may adjust it by one to two hours, so the boundaries must be confirmed.','Confusing the evening penalty with the larger night penalty; they are separate additions of 5 dB and 10 dB to different periods.','Applying the penalty to indicators that do not use it — a plain daytime LAeq assessment does not carry the Lden evening weighting.']::text[],ARRAY['A city noise-mapping team applies the 5 dB evening weighting when generating Lden contours for a strategic noise map.','A consultant modelling a new bar''s Lden includes the evening penalty for its 19:00–23:00 trading, tipping the result toward requiring acoustic treatment.','A regulator reviewing an airport''s Lden map checks that the evening flights carry the correct weighting.','A student technician learning EU indicators calculates Lden by hand and applies the +5 dB evening term correctly.']::text[],'intermediate','evening term = 10^((L_evening + 5)/10),  with L_evening = LAeq over 19:00–23:00','In the Lden energy average the evening contribution is the evening A-weighted equivalent level increased by five decibels before conversion to energy and weighting by the four evening hours.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Evening penalty');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4bb8af98-201d-5a93-8220-a91af450c542','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4bb8af98-201d-5a93-8220-a91af450c542') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4bb8af98-201d-5a93-8220-a91af450c542');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9bba3ee5-eccd-58be-b180-75681154680d','Night penalty','A fixed decibel addition applied to the night-period noise contribution in composite indicators of the Lden family, reflecting the strong evidence that night-time noise disturbs sleep and carries health consequences beyond mere annoyance. Under Directive 2002/49/EC (the Environmental Noise Directive), the night period is by default 23:00–07:00 and its A-weighted equivalent level is increased by 10 dB before being combined with day and evening contributions to form Lden. As with the evening penalty, this is a calculation weighting applied to the night Leq term, not additional measured sound. The directive also defines a separate night indicator, Lnight, which is the night LAeq without the 10 dB weighting and is used specifically for sleep-related assessment. The penalty size, the night boundaries and the choice of indicator are set by the standard or jurisdiction; the WHO Night Noise Guidelines and Environmental Noise Guidelines frame the underlying health basis.','The night penalty adds ten decibels to night noise in a calculation. Night noise is added into the Lden figure this way. It reflects that noise at night harms sleep and health. In the EU the night is 11 pm to 7 am by default. The ten decibels are a math weighting, not real extra sound. Night noise therefore counts far more than daytime noise. A separate figure, Lnight, uses the plain night level. Lnight is used to study sleep effects. The penalty size and hours depend on the rule in use.','The night penalty exists because sleep protection is a core aim of noise policy: disturbed sleep is linked to cardiovascular and other health effects, so the same level at night warrants far stronger weighting than during the day. Loading night noise heavily in Lden steers planning, mapping and mitigation toward controlling late-night sources, and the paired Lnight indicator gives regulators a direct, unweighted measure to compare against sleep-based guideline values.','A noise-mapping analyst applies the 10 dB night weighting to the night Leq when producing Lden maps and, separately, reports Lnight for sleep-impact assessment and action-planning. A consultant assessing a 24-hour operation or a late venue includes the night penalty in predicted Lden and checks Lnight at bedrooms against the relevant guideline, which often drives curfews, restricted deliveries or additional façade insulation.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Lnight','Lden','Evening penalty','Time-of-day correction','Sleep disturbance criterion','WHO Night Noise Guidelines','Directive 2002/49/EC']::text[],ARRAY['Treating the 10 dB as measured night noise instead of a fixed weighting added to the night term in the Lden calculation.','UNSAFE: Dismissing night limits as mere annoyance controls — night noise disturbs sleep and is linked to cardiovascular and other health effects, which is why it is weighted most heavily.','Confusing Lden''s weighted night term with the separate unweighted Lnight indicator used for sleep assessment.','Assuming the night period is universally 23:00–07:00 or the penalty universally 10 dB; both are defined by the applicable directive, standard or ordinance.']::text[],ARRAY['A strategic noise-mapping team applies the 10 dB night weighting for Lden and reports Lnight separately for the action plan.','A consultant assessing a night-time logistics hub checks predicted Lnight at nearby bedrooms against the sleep-based guideline.','An airport authority reviewing complaints examines the heavily weighted night contribution to its Lden contours.','A licensing officer imposes a curfew after a venue''s night penalty and Lnight indicate a likely sleep-disturbance impact.']::text[],'intermediate','night term = 10^((L_night + 10)/10),  with L_night = LAeq over 23:00–07:00','In the Lden energy average the night contribution is the night A-weighted equivalent level increased by ten decibels before conversion to energy and weighting by the eight night hours; the unweighted Lnight indicator omits this addition.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Night penalty');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9bba3ee5-eccd-58be-b180-75681154680d','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9bba3ee5-eccd-58be-b180-75681154680d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9bba3ee5-eccd-58be-b180-75681154680d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '74a636c9-1194-510c-9c1e-3ea6de3b021b','Emergence','In the French and several other European neighbourhood-noise regimes, emergence (émergence) is the difference between the ambient noise level measured with the source of interest operating and the residual noise level measured with that source stopped, at the same receiver position. It isolates the contribution of a disputed source against the pre-existing background, so a source is judged by how much it raises the local soundscape rather than by its absolute level alone. Under the French Code de la santé publique, neighbourhood-noise emergence limits are commonly 5 dB(A) for the daytime period (07:00–22:00) and 3 dB(A) for the night period (22:00–07:00), with a term-of-duration correction that relaxes the limit for short cumulative durations of the source. For places diffusing amplified sound there is additionally a spectral emergence requirement in octave bands. Exact values, periods, the duration correction and the measurement protocol are fixed by the applicable national regulation and differ between countries and methods.','Emergence is how much a source lifts the noise above the background. You measure with the source on. Then you measure with it off. The difference is the emergence. It judges a source by how much it stands out. In France, common limits are 5 dB(A) by day. The night limit is lower, at 3 dB(A). Day is 7 am to 10 pm; night is 10 pm to 7 am. A duration rule can relax short bursts. The exact values and method are set by national law.','Emergence exists to assess nuisance fairly in places where the background already varies: a fixed absolute limit can be too harsh in quiet rural settings and too lax in noisy urban ones, whereas emergence measures the audible intrusion the source actually adds. It gives environmental-health officers an objective, background-relative test for neighbourhood-noise complaints against venues, plant, ventilation and similar sources, and it links directly to how noticeable and annoying a new source is.','An environmental-health officer investigating a complaint measures the ambient level with the venue or plant running, then the residual level with it switched off, and compares the difference against the day or night emergence limit to decide whether a breach exists. A consultant designing mitigation targets the residual level plus the permitted emergence as the maximum the source may reach at the façade, sizing attenuation or setting a limiter accordingly.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Specific noise emergence','Residual noise','Ambient noise','Spectral emergence','France Code de la santé publique','BS 4142','Background sound level']::text[],ARRAY['Confusing ambient and residual: ambient is measured with the source on, residual with it off, and emergence is their difference.','Treating emergence as the source''s absolute level; it is always relative to the local background at the receiver.','Assuming one country''s values apply everywhere — the limits, periods and duration correction are set by national regulation and vary.','Ignoring the duration correction, which can lawfully relax the limit for sources that operate only briefly.']::text[],ARRAY['A French environmental-health officer measures ambient then residual level at a flat to check a bar''s night emergence.','An acoustic consultant sets a venue limiter so its façade level stays within the permitted daytime emergence over background.','A plant operator facing a ventilation-noise complaint commissions an emergence assessment before and after fitting an attenuator.','A regulator applies the duration correction when a source runs only a few minutes per hour.']::text[],'advanced','E = L_ambient − L_residual','Emergence equals the A-weighted ambient level measured with the source operating minus the residual level measured at the same point with the source stopped.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Emergence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '74a636c9-1194-510c-9c1e-3ea6de3b021b','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='74a636c9-1194-510c-9c1e-3ea6de3b021b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='74a636c9-1194-510c-9c1e-3ea6de3b021b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4c8d33b5-496b-5fd1-a214-36456eb26517','Specific noise emergence','The amount by which a single identified source — the ''specific'' source under investigation, such as a nightclub, plant item or ventilation unit — raises the sound level at a receiver above the residual (background) noise that would exist without it. It is a refinement of the general emergence concept: rather than the difference between total ambient and residual, it targets the specific source''s own contribution, which may be found by measuring with the source on and off, by acoustic separation, or by comparing the specific sound level with the residual. In the British Standard BS 4142 tradition the key quantities are the specific sound level (the source alone at the receiver) and, after adding any character corrections to form the rating level, its excess over the background sound level (LA90,T), which drives the impact assessment. French spectral emergence for amplified-sound venues applies the same logic band by band. The exact metric, correction and threshold depend on the standard and jurisdiction being applied.','Specific noise emergence is how much one named source lifts the level above background. It focuses on a single source, like one club or fan. You find the source''s own level at the home. Then you compare it with the background without it. The gap is the specific emergence. This tells you how much that source stands out. British and French methods both use this idea. Some methods check it band by band. The metric and limit depend on the standard used.','Specific noise emergence exists to attribute intrusion to the actual culprit source in a mixed soundscape, so enforcement and mitigation are aimed correctly. When several sources contribute, judging the total against a limit can wrongly blame or excuse an operator; isolating the specific source''s rise over background shows precisely how much that source intrudes and by how much it must be reduced. It supports fair complaint resolution and targeted attenuation design.','A consultant determines the specific sound level from the source alone at the receiver, measures or derives the residual level, and reports the emergence (with any character correction) against the applicable threshold to conclude whether the source causes an adverse impact. This drives mitigation design: the required reduction is the amount by which the specific emergence exceeds the permitted value, which the engineer meets through attenuators, screening, source changes or a limiter setting.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Emergence','Specific sound level','Residual noise','BS 4142','Spectral emergence','Rating level','Background sound level']::text[],ARRAY['Using the total ambient rise when the assessment requires isolating one specific source''s contribution above residual.','Forgetting to apply character corrections (for tonality or impulsivity) before comparing the specific source with the limit where the method requires them.','Assuming the residual level is negligible; a high background can genuinely reduce a source''s assessed emergence and must be measured properly.','Treating a single method''s threshold as universal — the metric, corrections and pass/fail value differ between BS 4142, French spectral emergence and other regimes.']::text[],ARRAY['A consultant separates a single chiller''s specific sound level from other plant to assess its emergence at a home under BS 4142.','A French inspector checks a venue''s spectral emergence octave band by octave band against the residual background.','An acoustician sizes an attenuator to cut a fan''s specific emergence to within the permitted value.','A tribunal weighs whether a club, not passing traffic, is the specific source responsible for the assessed emergence.']::text[],'advanced','E_specific = L_specific − L_residual','Specific noise emergence equals the specific source''s sound level at the receiver minus the residual (background) sound level at the same point, after any required character corrections.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Specific noise emergence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4c8d33b5-496b-5fd1-a214-36456eb26517','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4c8d33b5-496b-5fd1-a214-36456eb26517') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4c8d33b5-496b-5fd1-a214-36456eb26517');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0668bd40-789e-5013-97f6-307b5fa1d532','Tonality assessment','The determination of whether a noise contains audible tonal components — discrete, pitched frequencies such as a whine, hum or drone standing out from broadband noise — and, where present, the application of a decibel penalty (character correction) to the assessed level because tonal sounds are more annoying than broadband sound of the same energy. Assessment may be subjective (a trained assessor judging perceptibility) or objective/analytical (spectral measurement quantifying how far a tone rises above the masking noise in its critical band). In ISO 1996-2 the analytical route yields a tonal audibility, and the tonal adjustment rises on a sliding scale from 0 dB up to a maximum of about 6 dB as audibility increases (no adjustment below roughly 4 dB audibility, reaching the cap around 10 dB). BS 4142 uses graded subjective corrections of 2, 4 or 6 dB for just, clearly or highly perceptible tonality. The method, thresholds and penalty sizes are set by the standard and jurisdiction in use.','Tonality assessment checks a noise for a clear pitched tone. A tone is a whine, hum, or drone that stands out. Such tones annoy people more than plain noise. If a tone is found, a decibel penalty is added. You can judge tones by ear or by measurement. Measurement shows how far a tone rises above the noise. ISO adds up to about 6 extra decibels for strong tones. BS 4142 adds 2, 4, or 6 decibels by ear. The exact method and penalty depend on the standard.','Tonality assessment exists because equal-energy metrics like LAeq do not capture annoyance from character: a tonal hum can be far more disturbing than louder broadband sound. Adding a tonal penalty makes the assessed rating level reflect real annoyance and disturbance potential, so limits, planning conditions and enforcement respond to how a noise is perceived, not just its energy. It also directs mitigation toward the offending tone, such as a specific fan blade-pass or transformer frequency.','A consultant assessing plant or a venue identifies any prominent tone by ear and by spectrum, selects the applicable penalty (for example a graded BS 4142 correction or an ISO 1996-2 audibility-based adjustment), and adds it to the specific sound level to form the rating level compared with the limit. Recognising the tone''s frequency also guides the fix — retuning, damping or attenuating the specific tonal source rather than treating the whole spectrum.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Narrowband analysis for tonality','Audibility correction','ISO 1996-2','BS 4142','Rating level','Character correction','Critical band']::text[],ARRAY['Assuming a low LAeq means no problem; a clearly audible tone can be highly annoying and still attract a penalty even at modest levels.','Treating tonal penalties as fixed everywhere; ISO 1996-2 uses a sliding 0–6 dB adjustment while BS 4142 uses graded 2/4/6 dB corrections.','Confusing a tone with general loudness — tonality is about a discrete pitched component standing out, not overall level.','Skipping objective spectral checks and relying only on a listener when the standard requires an analytical determination.']::text[],ARRAY['A consultant hears a transformer hum at a home and applies the tonal correction when computing the rating level.','An enforcement officer disputes a plant operator''s assessment because a clear fan tone was not penalised.','An acoustician measures a substation spectrum to quantify tonal audibility under ISO 1996-2 for a planning appeal.','A wind-farm assessor checks turbine noise for a prominent tone that would trigger a penalty at nearby dwellings.']::text[],'advanced','K_tonal = 0 (ΔL_ta < 4); K_tonal = ΔL_ta − 4 (4 ≤ ΔL_ta ≤ 10); K_tonal = 6 (ΔL_ta > 10)','The tonal adjustment in decibels is zero below four decibels of tonal audibility, equals the audibility minus four between four and ten decibels, and is capped at six decibels above ten decibels of audibility.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tonality assessment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0668bd40-789e-5013-97f6-307b5fa1d532','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0668bd40-789e-5013-97f6-307b5fa1d532') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0668bd40-789e-5013-97f6-307b5fa1d532');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fa879816-ab0b-54f8-80c8-bd5d84e118b1','Narrowband analysis for tonality','The use of high-resolution frequency analysis — a fine-band FFT (fast Fourier transform) spectrum, or in the simpler survey route one-third-octave band levels — to detect and quantify tonal components in a noise for the purpose of applying a tonality penalty. The narrowband (engineering) method of ISO 1996-2 identifies a candidate tone, defines the masking noise in the critical band surrounding it, and computes the tone''s audibility (roughly, how far the tone''s level exceeds the masking noise, with a critical-band correction), from which the tonal adjustment is derived. Fine resolution matters because closely spaced tones and narrow peaks are smeared and hidden in coarse octave or third-octave bands. Related engineering-acoustics measures such as the tone-to-noise ratio and prominence ratio (ANSI/ECMA methods) express the same idea for product and machinery noise. The exact bandwidth, critical-band model, prominence criteria and resulting penalty are defined by the standard applied.','Narrowband analysis uses a fine frequency view to find tones. It splits the sound into many thin frequency slices. A tone shows up as a sharp spike in the spectrum. The method measures how far the spike rises above nearby noise. That rise gives the tone''s audibility. From audibility you get the decibel penalty. Fine slices matter because wide bands hide narrow tones. ISO 1996-2 uses an FFT engineering method for this. A simpler survey route uses one-third-octave bands. The exact rules depend on the standard.','Narrowband analysis exists to make tonality judgments objective and repeatable. Ear-based decisions vary between assessors and can be disputed in enforcement or planning; a defined FFT procedure with a critical-band model gives a defensible, measurable audibility figure that maps to a penalty. It also pinpoints the exact frequency of the offending tone, which is essential both for defending the assessment and for engineering the correct mitigation.','An acoustician records the noise, computes a fine-resolution FFT spectrum, identifies the prominent tone and its critical-band masking, and calculates tonal audibility to set the ISO 1996-2 penalty applied in the rating level. The same spectrum tells the engineer which source to treat — matching the tone to a fan blade-pass, motor or transformer harmonic — so mitigation such as damping, retuning or a targeted silencer addresses the actual tonal frequency.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Tonality assessment','ISO 1996-2','FFT / spectral analysis','Tone-to-noise ratio','Prominence ratio','Critical band','One-third-octave band']::text[],ARRAY['Using coarse octave or third-octave bands alone for the engineering assessment, which can smear and hide closely spaced or narrow tones.','Confusing tone-to-noise ratio and prominence ratio (product-noise methods) with the ISO 1996-2 audibility method; they are related but defined differently.','Assuming any spectral peak is a penalisable tone; the standard requires it to exceed defined prominence criteria relative to its critical-band masking.','Neglecting adequate frequency resolution and averaging time, which can create or erase apparent tones and bias the audibility figure.']::text[],ARRAY['An acoustician runs an FFT on substation noise to quantify a 100 Hz hum''s audibility for an ISO 1996-2 penalty.','A planning-appeal expert defends a tonal correction by presenting the narrowband spectrum and critical-band calculation.','A machinery engineer uses tone-to-noise ratio to certify a product''s tonal emission before sale.','A wind-farm assessor analyses turbine noise spectra for prominent tones at the nearest dwellings.']::text[],'advanced','ΔL_ta ≈ L_tone − L_masking_noise (with critical-band correction, per ISO 1996-2)','The tonal audibility is approximately the level of the tone minus the level of the masking noise in the surrounding critical band, adjusted by the standard''s critical-band correction, and it determines the tonal penalty.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Narrowband analysis for tonality');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fa879816-ab0b-54f8-80c8-bd5d84e118b1','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fa879816-ab0b-54f8-80c8-bd5d84e118b1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fa879816-ab0b-54f8-80c8-bd5d84e118b1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e483e66d-c68a-5712-8ed0-57a7d78748a0','Audibility correction','A decibel adjustment (penalty) added to an assessed noise level when a particular feature — most often a tone, but sometimes an impulsive or otherwise distinctive character — is clearly audible at the receiver, on the principle that a feature which can be plainly heard adds annoyance beyond what its energy alone implies. It is the mechanism by which subjective or measured audibility is turned into a numeric character correction that feeds the rating level. In ISO 1996-2 the tonal audibility governs a sliding adjustment up to about 6 dB; in BS 4142 audibility of tonal, impulsive, intermittent or other features attracts graded corrections (for example tonal 2/4/6 dB, impulsive 3/6/9 dB, and 3 dB for readily distinctive intermittency or other character). Some neighbourhood regimes phrase the test directly as whether the source is ''clearly audible'' at or inside the affected property. The size of the correction, the features covered and the audibility test are set by the applicable standard or jurisdiction.','An audibility correction adds decibels when a feature is clearly heard. The feature is often a tone but can be a thump or beat. If people can plainly hear it, it annoys them more. So the method adds a penalty to the level. ISO 1996-2 adds up to about 6 decibels for tones. BS 4142 adds set amounts for tones, thumps, and beats. Some local rules simply ask if the source is clearly audible. Being clearly heard, not just loud, drives the penalty. The amounts and tests depend on the standard used.','The audibility correction exists to bridge measurement and perception: two sources with the same LAeq can differ greatly in how noticeable and annoying they are, and audibility of a distinctive feature is what separates them. By converting ''you can clearly hear it'' into decibels on the rating level, the correction lets limits and enforcement respond to real disturbance, and it justifies mitigation aimed at removing the audible feature rather than only cutting overall level.','A consultant judges (by ear and, where required, by measurement) whether a tone or impulse is perceptible at the receiver, selects the graded correction from the applicable standard, and adds it to the specific sound level to form the rating level compared with the limit. In neighbourhood cases an officer may apply an ''audible at the façade or indoors'' test directly. Recognising which feature is audible steers the fix toward that feature — for example damping a tonal hum or softening an impulsive impact.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Tonality assessment','Character correction','Rating level','BS 4142','ISO 1996-2','Indoor audibility criterion','Impulsivity correction']::text[],ARRAY['Believing a feature must be loud to be penalised; the test is audibility of the feature at the receiver, which can trigger a correction at modest levels.','Applying a fixed correction regardless of perceptibility, when standards grade the penalty by how clearly the feature is heard.','Confusing the audibility correction with the overall level; it is an addition for character, not a re-measurement of loudness.','Assuming one standard''s corrections apply universally — the features covered, the audibility test and the decibel values differ by standard and jurisdiction.']::text[],ARRAY['A consultant adds a tonal audibility correction after clearly hearing a compressor whine at a bedroom window.','An officer applies a ''clearly audible indoors'' test to a nightclub''s bass in a complainant''s living room.','A wind-farm assessor grades the audibility of an intermittent swish before setting the character correction.','A tribunal weighs whether an impulsive hammering was audible enough at the receiver to justify the applied penalty.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audibility correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e483e66d-c68a-5712-8ed0-57a7d78748a0','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e483e66d-c68a-5712-8ed0-57a7d78748a0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e483e66d-c68a-5712-8ed0-57a7d78748a0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '363c9e34-e32f-5456-876b-bd0571bc68f7','Low-frequency C-A difference','The difference between the C-weighted and A-weighted equivalent levels of the same noise (LCeq − LAeq), used as a quick indicator of how much low-frequency energy a sound contains. A-weighting rolls off strongly at low frequencies to approximate the ear''s reduced sensitivity there, whereas C-weighting is nearly flat across the low-frequency range; therefore a noise rich in bass and rumble produces a much higher C-weighted than A-weighted level, giving a large positive difference, while a spectrally balanced or high-frequency-dominated sound gives a small one. A commonly cited screening rule is that a difference of roughly 15–20 dB or more suggests a significant low-frequency component that may warrant detailed low-frequency (octave or third-octave) analysis and specific assessment, because A-weighted limits alone can understate the disturbance from bass and rumble. It is an indicator, not a limit; the exact trigger value and follow-up method vary by guidance document and jurisdiction.','This is the C-weighted level minus the A-weighted level of a sound. A-weighting cuts low bass to match the ear. C-weighting keeps most of the low bass in. So a bass-heavy noise gives a big difference. A balanced or trebly noise gives a small one. A common screening rule flags a difference near 15 to 20 decibels. That large gap points to a strong low-frequency component. Then a detailed bass check is done. It is a warning sign, not a limit itself. The trigger value depends on the guidance used.','The C-A difference exists as a fast, single-number screen for low-frequency content, which A-weighted metrics can hide. Bass and rumble from clubs, plant, ventilation and traffic penetrate buildings well and disturb people even when the A-weighted level looks acceptable, so a simple LCeq − LAeq check tells an assessor when to stop relying on A-weighting and carry out proper low-frequency analysis. It is an efficient triage tool that prevents low-frequency problems being overlooked.','A field technician logs LCeq and LAeq simultaneously and computes the difference on site; a large value flags the complaint as a low-frequency case, prompting octave or third-octave measurement and comparison against a low-frequency criterion or curve. Consultants use it to decide whether standard A-weighted assessment suffices or whether specialist low-frequency methods and bass-targeted mitigation (isolation, absorption, source control) are needed.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['dB(C) minus dB(A)','A-weighting','C-weighting','Low-frequency noise','One-third-octave band','Indoor audibility criterion','LAeq']::text[],ARRAY['Treating the C-A difference as a limit or a measure of loudness; it is only a screening indicator of low-frequency content.','Assuming a small difference guarantees no problem; some low-frequency issues still need octave-band analysis to confirm.','Using a single trigger value as universal — the roughly 15–20 dB screening figure varies by guidance and is not a legal threshold.','Forgetting that C-weighting is not flat everywhere; it too rolls off at the extremes, so the difference approximates rather than exactly quantifies bass energy.']::text[],ARRAY['A technician on a bass-complaint callout computes LCeq minus LAeq to decide whether to run a third-octave survey.','A consultant screens nightclub noise and finds a large C-A difference indicating a dominant bass problem.','An environmental-health officer uses the difference to justify moving from A-weighted checks to low-frequency assessment.','A building-services engineer checks plant noise for a high C-A difference before specifying low-frequency isolation.']::text[],'intermediate','ΔLC−A = LCeq − LAeq','The low-frequency indicator is the C-weighted equivalent level minus the A-weighted equivalent level of the same noise over the same period; a large positive value indicates strong low-frequency content.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Low-frequency C-A difference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '363c9e34-e32f-5456-876b-bd0571bc68f7','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='363c9e34-e32f-5456-876b-bd0571bc68f7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='363c9e34-e32f-5456-876b-bd0571bc68f7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd0dc6e9e-d6f7-5bde-a1ce-711e82c7b7bd','dB(C) minus dB(A)','The practical field-check form of the low-frequency indicator: the C-weighted level of a noise minus its A-weighted level, read from a sound-level meter that reports both weightings simultaneously, used on site to gauge whether a sound is bass-dominant. Because A-weighting attenuates low frequencies heavily while C-weighting passes them, a large dB(C) − dB(A) gap signals substantial low-frequency energy (rumble, bass beat), whereas a small gap indicates a mid/high-frequency-balanced sound. Technicians use it as an at-a-glance triage during live events and neighbourhood callouts: a high value warns that A-weighted readings and A-weighted limits may understate the real disturbance and that low-frequency-specific measurement or controls are needed. The figure is diagnostic, not a compliance limit in itself, and any threshold used to flag ''high'' bass content depends on the guidance, meter setting and jurisdiction.','This is a quick on-site check for bass in a sound. You read the C level and the A level from the meter. Then you subtract A from C. A big gap means the sound is bass-heavy. A small gap means the bass is not dominant. Techs use it fast during shows and callouts. A high value warns that A-weighted readings hide the bass. Then you do a proper low-frequency check. It is a diagnostic, not a limit by itself. Any ''high'' cutoff depends on the guidance used.','This check exists to give working technicians and officers an immediate read on bass content without a full spectral analysis. Live music and plant noise often cause complaints driven by bass that A-weighted meters downplay; a single subtraction on the meter tells the operator whether the problem is low-frequency and whether the A-weighted limit they are working to might be misleading. It turns a routine dual-weighting reading into fast, actionable triage.','A front-of-house or noise-management technician sets the meter to display LCeq and LAeq together, notes the difference during the show, and — if it is large — investigates the bass, adjusts the subwoofer level or crossover, or repositions arrays before residents complain. An enforcement officer uses the same quick difference at a complainant''s home to decide whether to escalate to a low-frequency assessment against a specific criterion.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Low-frequency C-A difference','C-weighting','A-weighting','Subwoofer / low-frequency management','LCeq','Indoor audibility criterion','Sound-level meter']::text[],ARRAY['Reading the difference as a compliance limit; it is a diagnostic indicator, and the actual limit is set separately by the applicable regulation.','Assuming a low difference means no bass complaint is possible; some low-frequency disturbance still needs detailed measurement to detect.','Comparing dB(C) and dB(A) taken at different times or settings; the check is only valid when both weightings cover the same sound over the same period.','Treating one ''high bass'' cutoff as universal — the flag value depends on guidance, meter time-weighting and jurisdiction.']::text[],ARRAY['A festival noise officer watches a growing dB(C) − dB(A) gap and asks the engineer to trim subwoofer output.','An environmental-health officer takes a quick C-minus-A reading at a flat to confirm a bass complaint before a full survey.','A touring engineer uses the difference during soundcheck to balance low-frequency energy against the venue''s limit.','A student technician learns to read both weightings on the meter and interpret their difference on the job.']::text[],'intermediate','dB(C) − dB(A) = LCeq − LAeq (same source, same period)','Subtract the A-weighted level from the C-weighted level of the same sound over the same measurement period; a large positive result flags a bass-dominant noise for further low-frequency assessment.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='dB(C) minus dB(A)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd0dc6e9e-d6f7-5bde-a1ce-711e82c7b7bd','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d0dc6e9e-d6f7-5bde-a1ce-711e82c7b7bd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d0dc6e9e-d6f7-5bde-a1ce-711e82c7b7bd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '841a98fc-84af-5e7c-85b1-66ba103109d7','Indoor audibility criterion','An assessment rule that judges nuisance by whether the source — typically music, and especially its bass beat — is audible or intelligible inside a habitable room of an affected dwelling, rather than solely by an outdoor decibel level at the façade. It recognises that low-frequency music can be plainly heard and felt indoors even when outdoor A-weighted levels appear modest, so some licensing regimes and codes of practice frame the standard directly in perceptual terms: for example that amplified music should be ''inaudible'' within noise-sensitive rooms, or should not be distinctly audible above the background, sometimes qualified by time of day (stricter at night with windows closed). Where quantified, it may be paired with indoor low-frequency limits in octave or third-octave bands to make ''audibility'' measurable. The precise wording, whether it demands inaudibility or merely ''not clearly audible'', the room and window conditions and any numeric backing all depend on the licence, code and jurisdiction.','This rule judges noise by what is heard inside a home. It asks if the music or bass is audible in a room. It does not rely only on an outdoor decibel level. Bass can be clearly heard indoors even when outdoor levels seem low. Some licences say music must be inaudible inside homes. Others say it must not be clearly audible above background. Night rules are often stricter, with windows shut. Sometimes indoor bass limits make ''audible'' measurable. The exact wording depends on the licence and area.','The criterion exists because outdoor façade limits can fail to protect people from intrusive indoor bass: what matters to a resident is whether they can hear the beat in their bedroom, not the number on a façade meter. An indoor-audibility test targets that lived experience directly, closing the gap where A-weighted outdoor limits are met yet occupants are still disturbed. It gives licensing authorities a receiver-focused, perceptually meaningful condition for venues and events.','A licensing officer writes a condition that amplified music must be inaudible (or not clearly audible) in nearby habitable rooms and, on complaint, an environmental-health officer listens inside the affected room — often with any qualifying window conditions — and may take indoor low-frequency measurements to judge compliance. A venue''s acoustic consultant then designs isolation, limiter settings and sub management to satisfy the indoor test, not merely the outdoor level.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Audibility correction','Low-frequency C-A difference','dB(C) minus dB(A)','Music noise level (MNL)','Sleep disturbance criterion','Entertainment licence conditions','Low-frequency noise']::text[],ARRAY['Assuming meeting an outdoor façade limit guarantees compliance; an indoor-audibility condition can still be breached by intrusive bass indoors.','Reading ''inaudible'' and ''not clearly audible'' as the same test; regimes differ in strictness and in the window and room conditions assumed.','Treating the criterion as purely subjective; many regimes back it with indoor low-frequency band limits to make audibility measurable.','Ignoring time-of-day qualification — indoor-audibility tests are often stricter at night when background is low and windows are closed.']::text[],ARRAY['A licensing panel imposes an ''inaudible in nearby homes'' music condition on a late-night bar.','An environmental-health officer stands in a complainant''s bedroom at night to judge whether the club''s bass is clearly audible.','A venue consultant designs sub isolation and a limiter to meet an indoor-audibility condition, not just the façade limit.','A festival organiser negotiates an indoor-audibility standard for the nearest terrace of houses as a permit condition.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Indoor audibility criterion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '841a98fc-84af-5e7c-85b1-66ba103109d7','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='841a98fc-84af-5e7c-85b1-66ba103109d7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='841a98fc-84af-5e7c-85b1-66ba103109d7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9aba3926-43c9-5f48-9320-cbbf2db06267','Sleep disturbance criterion','A night-noise assessment threshold set specifically to protect sleep, expressed as a night-time indicator (commonly Lnight,outside — the annual average A-weighted level over the night period at the façade — and sometimes supplemented by maximum-level or event-count criteria such as LAFmax for individual noise events that trigger awakenings). It rests on epidemiological evidence linking night noise to awakenings, arousals, altered sleep structure and longer-term health effects. The WHO Night Noise Guidelines for Europe (2009) set a night noise guideline of Lnight,outside 40 dB as the level protecting the public, including vulnerable groups, with an interim (feasibility-based) target of 55 dB where 40 dB cannot yet be met; the WHO Environmental Noise Guidelines (2018) give source-specific night recommendations. Distinct from guideline values, binding sleep-disturbance limits appear in national and local law and in event/venue codes. The chosen indicator, the numeric value, the averaging basis and legal status vary by jurisdiction, source and standard.','This is a night-noise limit made to protect sleep. It usually uses a night-time average level at the home. It may add a limit on loud single events too. Night noise causes awakenings and can harm health over time. The WHO set a night guideline of 40 decibels Lnight. That level aims to protect people, including vulnerable groups. Where 40 is not yet reachable, WHO gives an interim target of 55. National and local laws set their own binding limits. The indicator, value, and legal force differ by place and source.','The criterion exists because sleep is a health-critical function that noise readily disrupts, and daytime or annual-average metrics do not capture night risk. By fixing a night indicator and, where used, event-based maxima, it lets authorities protect rest, justify curfews, restricted night operations and façade insulation, and set action-plan priorities. It converts sleep-health evidence into a measurable planning and enforcement benchmark aimed at the most sensitive period.','A consultant assessing a road scheme, airport or late venue predicts or measures Lnight (and often LAFmax for individual events) at nearby bedrooms and compares it with the applicable sleep-based criterion, driving mitigation such as barriers, curfews, night-flight limits or acoustic glazing. Regulators use night indicators to prioritise noise action plans and to set night conditions on permits, and environmental-health officers apply them when night-noise complaints are investigated.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Lnight','Night penalty','WHO Night Noise Guidelines','LAFmax','Time-of-day correction','Curfew / restricted hours','Directive 2002/49/EC']::text[],ARRAY['UNSAFE: Treating night noise as mere annoyance; it disturbs sleep and is linked to cardiovascular and other health effects, which is why a dedicated criterion exists.','Assuming an average night level alone is sufficient; individual loud events (LAFmax) can cause awakenings even when the average complies.','Quoting the WHO 40 dB Lnight guideline as a binding legal limit; it is a health-based guideline, while enforceable limits are set in national or local law.','Confusing the WHO interim target of 55 dB with the health-based 40 dB guideline; the interim value is feasibility-based, not fully protective.']::text[],ARRAY['An airport consultant models Lnight and night LAFmax at nearby homes to assess sleep-disturbance impact for a runway proposal.','A city noise action plan prioritises streets exceeding the night criterion for barriers and glazing.','A licensing officer sets a night curfew after a venue''s Lnight at bedrooms exceeds the sleep-based limit.','An environmental-health officer investigating a night-noise complaint measures Lnight and event maxima against the applicable criterion.']::text[],'advanced',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sleep disturbance criterion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9aba3926-43c9-5f48-9320-cbbf2db06267','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9aba3926-43c9-5f48-9320-cbbf2db06267') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9aba3926-43c9-5f48-9320-cbbf2db06267');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee81b88b-676b-545b-9b51-d15511bc6938','Annoyance dose-response','The quantified statistical relationship between long-term environmental-noise exposure (the ''dose'', usually the day-evening-night level Lden in dB) and the community response of annoyance (the ''response'', usually the percentage of a population that is highly annoyed, %HA). It is typically expressed as a fitted curve, most often a quadratic function of Lden, derived by pooling socio-acoustic survey data across many studies. Separate curves are given per source type because the same energy-level produces different annoyance for aircraft, road and railway noise (aircraft generally being most annoying at equal Lden). The relationships underpin environmental-noise impact assessment, strategic noise mapping and burden-of-disease estimates. The specific curve, its coefficients and the level metric are set by the governing framework — for example the WHO 2018 Environmental Noise Guidelines and the associated Guski/Schreckenberg/Schuemer 2017 review, ISO 1996-1 Annex F, or the EU Environmental Noise Directive assessment methods — and exact predicted percentages therefore vary by which relationship, source and jurisdiction apply.','This links how loud an area is to how much people mind it. The ''dose'' is the long-term noise level. The ''response'' is the share of people who feel highly annoyed. Researchers survey thousands of residents. They fit a curve to the results. Louder places have more annoyed people. Planes, roads and trains each get their own curve. Planes annoy people most at the same level. The WHO and ISO publish these curves. The exact numbers differ by source, method and country.','It converts a physical noise level into an expected human-impact figure, so that noise can be assessed as a public-health and amenity problem rather than only a number of decibels. This lets authorities compare scenarios, estimate how many people a road, airport or plan will highly annoy, set exposure targets, justify limit values, and feed annoyance into wider disability-adjusted-life-year and cost-benefit calculations. It gives regulation an evidence base linking exposure to a recognised health effect.','A noise consultant or planning authority takes modelled Lden values at dwellings from a noise map and applies the relevant dose-response curve to estimate the number of highly annoyed residents for a proposed motorway, runway or development. Those estimates populate an environmental impact assessment, support a strategic noise action plan under the EU Directive, or compare mitigation options (barriers, quieter surfaces, re-routing) by how much they reduce predicted %HA.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Highly annoyed percentage (%HA)','Lden','WHO Environmental Noise Guidelines','ISO 1996-1','Strategic noise mapping','Environmental Noise Directive (2002/49/EC)','Highly sleep disturbed (%HSD)']::text[],ARRAY['Assuming one universal curve fits all noise — separate dose-response relationships apply to aircraft, road and railway, and different frameworks (WHO 2018, ISO 1996-1, national) give different coefficients.','Reading the curve as an individual prediction; it estimates the percentage of a population highly annoyed, not whether a specific person will be annoyed.','Believing Lden alone fully explains annoyance — non-acoustic factors (attitude, fear, trust, source visibility) shift the response and are why scatter around the curve is large.','Confusing ''annoyed'' with ''highly annoyed''; the standard endpoint is the high-annoyance cut-point on the survey scale, which yields lower percentages.']::text[],ARRAY['A consultant estimates how many residents a new bypass would make highly annoyed, using the road-traffic curve on modelled Lden.','A national authority preparing a noise action plan compares airport scenarios by predicted %HA under the WHO relationships.','A researcher validates a local socio-acoustic survey against the WHO 2018 curves to check whether the community is more sensitive than average.','An environmental court weighs an expert''s dose-response estimate of community annoyance when reviewing a contested planning permission.']::text[],'advanced','%HA = a + b·Lden + c·Lden²  (e.g. road, WHO 2018: 78.9270 − 3.1162·Lden + 0.0342·Lden²)','The percentage of people highly annoyed equals a constant plus a linear term times the day-evening-night level plus a coefficient times that level squared, with source-specific coefficients; for road traffic under the WHO 2018 guidelines the constant is 78.9270, the linear coefficient is minus 3.1162, and the squared-term coefficient is 0.0342.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Annoyance dose-response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee81b88b-676b-545b-9b51-d15511bc6938','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee81b88b-676b-545b-9b51-d15511bc6938') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee81b88b-676b-545b-9b51-d15511bc6938');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '49492cb0-648a-5105-8b8f-b189ff5b9672','Highly annoyed percentage (%HA)','An environmental-noise impact metric giving the proportion of an exposed population that reports being ''highly annoyed'' by a noise source, conventionally defined as those scoring in the upper portion (typically the top 27–28%, or the top two categories) of a standardised socio-acoustic annoyance scale as specified in ISO/TS 15666. It is the standard response variable in dose-response relationships and is predicted from a long-term exposure level (usually Lden) via a source-specific curve. %HA is used in strategic noise mapping, impact assessment and burden-of-disease work as the accepted quantitative measure of the annoyance health effect. The exact cut-point definition, the exposure metric and the predictive curve depend on the governing standard or guideline (ISO/TS 15666 for the scale; WHO 2018 or ISO 1996-1 for the relationships), so reported %HA values are only comparable when the same definitions and source type are used.','This is the share of people who are highly annoyed by noise. It comes from asking residents on a set survey scale. People near the top of the scale count as highly annoyed. The survey wording follows a standard so results can be compared. Officials predict %HA from the area''s noise level. Each noise source has its own curve. A higher level means a higher %HA. It measures a real health effect, not just loudness. The cut-off and method are fixed by standards.','It provides a single, standardised, comparable number for how much a noise source harms community wellbeing through annoyance, which is itself a recognised adverse health effect. By fixing how the question is asked (ISO/TS 15666) and what counts as ''highly annoyed'', it lets surveys, maps and impact studies from different places and sources be compared and aggregated, supports target-setting and action planning, and feeds annoyance into cost-benefit and disability-adjusted-life-year calculations.','An acoustician reports %HA at sensitive receivers as the headline impact figure in an environmental statement or noise action plan, computed by applying the WHO or ISO dose-response curve to mapped Lden. Surveyors use the ISO/TS 15666 question and scale to gather primary %HA data for a community, and authorities use predicted %HA to rank hotspots, prioritise mitigation and demonstrate whether a scheme increases or decreases the number of highly annoyed people.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Annoyance dose-response','ISO/TS 15666','Lden','Highly sleep disturbed (%HSD)','Strategic noise mapping','WHO Environmental Noise Guidelines','Environmental Noise Directive (2002/49/EC)']::text[],ARRAY['Treating %HA as the share of people ''annoyed'' generally — it counts only the ''highly annoyed'' upper cut-point of the ISO/TS 15666 scale, a stricter and smaller group.','Comparing %HA figures from different sources or methods directly; values only match when the same scale cut-point, exposure metric and source-specific curve are used.','Assuming %HA describes an individual''s likely reaction; it is a population statistic with wide individual variation around it.','Thinking a low measured level guarantees a low %HA — non-acoustic factors such as attitude to the source can raise reported annoyance at the same decibel level.']::text[],ARRAY['A city noise map reports the number of residents highly annoyed by road traffic in each district as %HA to prioritise action.','A consultant compares two runway layouts by their predicted aircraft %HA at nearby villages.','A community group commissions an ISO/TS 15666 survey to show the local %HA is higher than the standard curve predicts.','An enforcement authority uses %HA estimates to support conditions requiring noise mitigation on a new industrial site.']::text[],'intermediate','%HA = 100 · (highly annoyed respondents / total respondents); predicted %HA = a + b·Lden + c·Lden²','As a survey statistic, the highly annoyed percentage equals one hundred times the number of respondents scoring above the high-annoyance cut-point divided by the total respondents; as a prediction it equals a source-specific constant plus a linear coefficient times the day-evening-night level plus a coefficient times that level squared.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Highly annoyed percentage (%HA)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '49492cb0-648a-5105-8b8f-b189ff5b9672','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='49492cb0-648a-5105-8b8f-b189ff5b9672') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='49492cb0-648a-5105-8b8f-b189ff5b9672');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '12d958ca-b561-5c09-a846-6cd09259b5ea','Highly sleep disturbed (%HSD)','A night-noise health-impact metric giving the percentage of an exposed population that reports being ''highly sleep disturbed'' by a noise source, based on self-reported disturbance in socio-acoustic surveys. It is predicted from the night-time exposure level Lnight (the A-weighted long-term average over the night period, e.g. 23:00–07:00) using a source-specific quadratic exposure-response curve, and is the sleep-effect counterpart to %HA. %HSD is a core outcome in the WHO Environmental Noise Guidelines and in night-noise policy because self-reported sleep disturbance is a recognised adverse health effect distinct from measured physiological arousals. The controlling curve and coefficients are set by the framework applied — for example the WHO 2018 sleep review (Basner & McGuire) provides road, railway and aircraft functions of Lnight — so predicted values depend on source type and the guideline in force, and exact limits or trigger levels vary by jurisdiction.','This is the share of people whose sleep is badly disturbed by noise. It is worked out from the average night noise level. That level is called Lnight. People report their sleep problems in surveys. A curve links the night level to the share disturbed. Louder nights disturb more people. Planes, roads and trains each have their own curve. Poor sleep is a real health effect, not just a bother. The WHO publishes these curves. Exact trigger levels differ by country.','It quantifies the sleep-disturbance burden of night-time noise so that night exposure can be regulated and mapped separately from daytime annoyance. Because disturbed sleep is linked to wider health harm, %HSD gives authorities a measurable basis for night-noise limits, curfews, action-plan targets and burden-of-disease estimates, and lets them compare how different sources and mitigations affect the sleeping population rather than only average levels.','A consultant applies the relevant %HSD curve to modelled Lnight at bedroom facades to estimate the number of highly sleep-disturbed residents from an airport, freight line or 24-hour operation, and reports it in an impact assessment or night-noise action plan. Authorities use the figure to justify night curfews, movement caps or insulation grants, and to check whether a scheme keeps the sleep-disturbed population below a policy target.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Lnight','Highly annoyed percentage (%HA)','WHO Night Noise Guidelines','Annoyance dose-response','Strategic noise mapping','Environmental Noise Directive (2002/49/EC)','Night-time noise limit / curfew']::text[],ARRAY['Confusing self-reported %HSD with instrumented awakenings; %HSD is a survey-based population statistic, not a count of measured physiological arousals during the night.','Using a daytime metric such as Lden to predict sleep disturbance — %HSD is driven by the night-only level Lnight, and the curves differ by source.','Assuming a single %HSD curve applies to all sources; railway, road and aircraft have distinct WHO 2018 functions with different coefficients.','Reading %HSD as an individual risk rather than a proportion of the exposed population, with large individual variation around it.']::text[],ARRAY['An airport authority estimates the number of highly sleep-disturbed residents under a proposed night-flight schedule using the aircraft Lnight curve.','A city maps Lnight along a freight corridor and reports %HSD to justify a night-time speed or movement restriction.','A public-health team compares insulation and re-routing options by their reduction in predicted %HSD.','An inspectorate reviews a 24-hour plant''s night-noise assessment, checking the %HSD estimate against the local night limit.']::text[],'intermediate','%HSD = a + b·Lnight + c·Lnight²  (e.g. road, WHO 2018: 19.4312 − 0.9336·Lnight + 0.0126·Lnight²)','The percentage of people highly sleep disturbed equals a source-specific constant plus a linear coefficient times the night-time average level plus a coefficient times that level squared; for road traffic under the WHO 2018 sleep review the constant is 19.4312, the linear coefficient is minus 0.9336, and the squared-term coefficient is 0.0126.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Highly sleep disturbed (%HSD)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '12d958ca-b561-5c09-a846-6cd09259b5ea','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='12d958ca-b561-5c09-a846-6cd09259b5ea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='12d958ca-b561-5c09-a846-6cd09259b5ea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '16f609ba-e6e3-5753-8e43-9c04c712526e','Soundscape assessment','A human-centred method of evaluating the acoustic environment as perceived, experienced or understood by people in context, rather than judging it solely by measured noise levels. Formalised in the ISO 12913 series, soundscape assessment treats the meaning and quality of sound — pleasant, calming, chaotic, eventful — as the object of study, combining acoustic measurement with perceptual data gathered through validated questionnaires, soundwalks, in-situ or laboratory listening, and analysis along dimensions such as pleasantness and eventfulness. It recognises that some sounds (birdsong, water, wanted music) can be positive and that context, expectation and activity shape response. It is applied in urban planning, park and public-space design, and increasingly in noise policy as a complement to level-based limits. The exact protocol, questionnaire and analysis method are set by ISO 12913-2 and -3 and by the study design, and results are qualitative-plus-quantitative rather than a single pass/fail number, so they inform rather than replace statutory noise limits.','This judges a place by how its sound feels to people. It does not rely only on decibel readings. Some sounds are pleasant, like birds or water. Others feel chaotic or stressful. Soundscape work studies both the sound and the human response. People answer set questions and take guided listening walks. Results describe qualities such as calm or lively. It is used in parks, streets and city planning. A method standard, ISO 12913, guides the work. It supports, but does not replace, legal noise limits.','It exists because level-only assessment misses how people actually experience sound: two places at the same decibel level can feel very different, and quiet is not always ''good'' nor loud always ''bad''. Soundscape assessment gives planners and authorities a structured way to capture wanted and unwanted sound, design spaces that people find restorative or lively as intended, and set goals for acoustic quality that go beyond keeping numbers under a limit.','A landscape architect or urban acoustician runs a soundscape assessment when designing a park, plaza or regeneration scheme: measuring levels, conducting soundwalks and ISO 12913 questionnaires, and mapping perceived pleasantness to decide where to add water features, vegetation or screening and where to preserve valued sounds. Results feed masterplans, public-space briefs and, increasingly, local acoustic-quality objectives alongside conventional noise mapping.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Acoustic environment quality','ISO 12913','Masking sound','Strategic noise mapping','Quiet area / tranquil space','Environmental Noise Directive (2002/49/EC)','Annoyance dose-response']::text[],ARRAY['Equating a low noise level with a good soundscape; a quiet space can be experienced as eerie or monotonous, and a lively one as positive, so level alone does not decide quality.','Assuming soundscape assessment replaces statutory noise limits — it complements level-based regulation, it does not override hearing-protection or nuisance limits.','Treating it as purely subjective opinion; ISO 12913 provides standardised questionnaires and protocols to make perceptual data structured and comparable.','Believing all noise is bad and should be removed — soundscape work explicitly values wanted sounds and may recommend adding, not only reducing, sound.']::text[],ARRAY['An urban designer assesses a proposed pocket park with soundwalks and ISO 12913 questionnaires to plan where water features will mask traffic.','A city regeneration team compares before-and-after soundscape quality to justify a public-realm scheme to councillors.','A researcher evaluates whether a designated quiet area is experienced as restorative, not merely low in decibels.','A transport authority supplements a noise map with soundscape data to prioritise which streets most need intervention.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Soundscape assessment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '16f609ba-e6e3-5753-8e43-9c04c712526e','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='16f609ba-e6e3-5753-8e43-9c04c712526e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='16f609ba-e6e3-5753-8e43-9c04c712526e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24171917-3fb8-5c13-a405-d6ad67585b0f','Acoustic environment quality','A broad planning concept describing the overall character and desirability of the sound at a place, encompassing both wanted and unwanted sound, as distinct from a narrow focus on excess noise. In the ISO 12913 framework the ''acoustic environment'' is the sound at a receiver from all sources as modified by the environment, and its quality is judged by how well it supports the intended use and human wellbeing — for example whether a park is restorative, a plaza is lively, or a residential street is calm. It combines objective measures (levels, spectra, temporal patterns) with perceptual outcomes and contextual fit. The concept underlies quiet-area and tranquillity policy and soundscape design, sitting alongside — not replacing — statutory level limits. There is no single universal quality index; how quality is defined and measured depends on the framework, the intended use of the space, and the jurisdiction''s planning and noise policy.','This is the overall quality of the sound at a place. It covers good sounds and bad sounds together. It is more than just ''how much noise is there''. A good acoustic environment fits what the place is for. A park may aim to feel calm and restful. A square may aim to feel lively. Planners judge it using levels and how people feel. It guides quiet-area and public-space policy. There is no single quality score. What counts as good depends on the place and local rules.','It gives planning and noise policy a positive goal — a good sound environment — rather than only the negative goal of keeping noise under a limit. This lets authorities protect and create valued acoustic conditions (tranquil areas, well-functioning public spaces), justify designating quiet areas, and evaluate schemes by whether they improve the experience of a place, capturing benefits that a decibel limit alone cannot express.','Planners and acousticians use the concept to set acoustic-quality objectives for a masterplan or open space, to designate and protect quiet areas under environmental-noise policy, and to appraise developments on whether they enhance or degrade the sound of a place. It shapes briefs for public realm, informs where to apply mitigation versus where to preserve wanted sound, and frames soundscape studies that support planning decisions.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Soundscape assessment','ISO 12913','Quiet area / tranquil space','Masking sound','Residual acoustic environment','Strategic noise mapping','Environmental Noise Directive (2002/49/EC)']::text[],ARRAY['Reducing acoustic environment quality to a single decibel number; it is a multi-dimensional judgement of wanted and unwanted sound and fitness for the place''s use.','Assuming lower levels always mean higher quality — a very quiet space can be experienced as bleak or unsafe, and some wanted sound improves quality.','Confusing it with statutory noise limits; it is a planning and design concept that complements, but does not override, legal limits.','Treating quality as fixed and universal rather than dependent on context, intended use and local policy.']::text[],ARRAY['A planning authority sets acoustic-quality objectives for a new neighbourhood, aiming for calm courtyards and a lively high street.','A council designates and protects a park as a quiet area based on its acoustic environment quality, not just its level.','A developer''s appraisal argues a scheme improves local sound quality by adding vegetation and water while screening a road.','An inspector weighs acoustic environment quality when deciding whether a mixed-use development preserves a valued tranquil space.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic environment quality');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24171917-3fb8-5c13-a405-d6ad67585b0f','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24171917-3fb8-5c13-a405-d6ad67585b0f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24171917-3fb8-5c13-a405-d6ad67585b0f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd606e1fd-b397-5dab-a917-a5c18e40b062','Masking sound','Sound that reduces or removes the audibility of another sound by raising the auditory threshold at which that other sound can be detected, through the perceptual mechanism of auditory masking. In assessment, mapping and mitigation practice, masking sound is relevant in two ways: as a natural or introduced element of a soundscape (for example water features or foliage rustle masking traffic in a park), and as engineered ''sound masking'' in offices and healthcare settings, where a low-level, broadband, speech-shaped sound is added to reduce the intelligibility and distraction of intruding speech and to protect speech privacy. Its effectiveness depends on the spectrum and level of the masker relative to the target sound and on the listener''s task. Masking is also central to disputes and standards on speech privacy and audibility of a specific noise. The masker''s spectrum, level and legitimacy are constrained by context, comfort limits and, in workplaces, by not itself becoming an excessive or hazardous noise source; acceptable practice and any limits vary by standard, building code and jurisdiction.','A masking sound hides or covers another sound. It raises the level needed to hear the other sound. In a park, water can cover traffic noise. In an office, a soft background sound covers nearby speech. This protects privacy and cuts distraction. The masker must match the sound it is covering. It works best when its pitch range overlaps the target. The masking sound should stay quiet and comfortable. It must not itself become loud or harmful. Rules and good practice differ by building type and country.','Masking exists to manage audibility rather than absolute level: sometimes the goal is to make an unwanted sound less noticeable (traffic in a park, HVAC hum) or to stop speech carrying (open-plan offices, consulting rooms, banks). It offers a mitigation route where reducing the source is impractical, improving perceived acoustic quality and speech privacy. Understanding masking also matters when assessing whether a specific complained-of sound is genuinely audible above the existing background.','An acoustic consultant specifies a sound-masking system in an open-plan office or clinic — setting the spectrum and level so intruding speech becomes unintelligible while the masker stays unobtrusive — to meet speech-privacy goals. In outdoor design, a planner introduces water or planting to mask road noise as part of a soundscape scheme. In nuisance assessment, an investigator judges whether an alleged noise is audible against, or masked by, the residual background.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Soundscape assessment','Speech privacy','Residual acoustic environment','Acoustic environment quality','Background/ambient sound level','Signal-to-noise ratio','Audibility']::text[],ARRAY['Thinking masking removes the unwanted sound; it only makes it harder to detect by raising the audibility threshold, and the target energy is still present.','Assuming louder masking is always better — excessive masking becomes annoying, harms comfort, and can itself constitute a noise problem.','Confusing masking with soundproofing; masking adds sound to hide another, while insulation blocks sound transmission — they solve different problems.','Believing masking works regardless of spectrum; a masker is effective only where its frequency content overlaps the sound to be masked.']::text[],ARRAY['An office designer installs a speech-shaped sound-masking system to protect confidential conversations in an open-plan floor.','A park designer adds a fountain so moving water masks distant motorway noise for visitors.','A noise investigator decides whether a neighbour''s alleged hum is audible or masked by the existing background before assessing nuisance.','A hospital acoustician uses masking in a waiting area to keep reception conversations from being overheard.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Masking sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd606e1fd-b397-5dab-a917-a5c18e40b062','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d606e1fd-b397-5dab-a917-a5c18e40b062') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d606e1fd-b397-5dab-a917-a5c18e40b062');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'af8397c2-e592-50ff-b826-49a241e01bce','Residual acoustic environment','The sound that remains at a location when the specific source or sources under assessment are removed or stopped — the baseline sound environment against which a proposed or complained-of source is judged. It corresponds to ISO 1996-1''s concept of ''residual sound'': the total remaining sound when the specific sound(s) of interest are suppressed. It differs from the general background or ambient level in that it is defined by the exclusion of the assessed source, not merely by a statistical floor. Characterising the residual environment (its level, spectrum, and how it varies by time of day) is essential to determining the change a source causes and whether that change is significant. In many rating methods a source is assessed by comparing the specific sound level to the residual/background, since the same source is more intrusive in a quiet residual environment than in a busy one. The exact definitions, descriptors and how the residual is measured are set by the applicable standard (e.g. ISO 1996-2, BS 4142) and vary by jurisdiction and method.','This is the sound left when you take away the source being studied. It is the baseline before the new or disputed sound is added. Turn off the factory, and what remains is the residual environment. It is not just a general background number. It is defined by leaving out the one source of interest. Assessors measure its level and how it changes over the day. A source stands out more in a quiet baseline. So the residual is the yardstick for judging impact. The exact method is set by standards and differs by country.','It provides the reference condition needed to isolate and judge the effect of a particular source. Impact and nuisance are about change and intrusion, so a source cannot be fairly assessed in absolute terms alone — the residual environment tells you how much the source adds and whether it will be noticeable or intrusive. Defining it precisely (by excluding the assessed source) keeps assessments consistent and defensible in planning and enforcement.','A consultant measuring for a BS 4142-style industrial assessment characterises the residual sound level (with the plant off or during comparable periods) to compare against the specific plant level and rate the likely impact. In planning, the residual environment sets the baseline in an environmental noise chapter; in a nuisance case, an investigator establishes the residual before the complained-of source starts to show how much it changes conditions.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Background/ambient sound level','Specific sound source','ISO 1996-1','BS 4142','Representative measurement period','Masking sound','Rating level']::text[],ARRAY['Equating residual sound with the general ambient or background number; the residual is specifically what remains after removing the assessed source, not just a statistical floor.','Measuring the residual with the assessed source still contributing, which contaminates the baseline and understates the source''s impact.','Assuming the residual environment is constant; it varies strongly by time of day, weather and other activity, so it must be characterised across representative periods.','Judging a source only by its absolute level and ignoring the residual, missing that the same level is far more intrusive in a quiet baseline.']::text[],ARRAY['An acoustician measures the residual sound with a factory shut down to establish the baseline for a BS 4142 assessment.','A planning consultant sets the residual acoustic environment as the pre-development baseline in an environmental statement.','A nuisance officer records the residual before a bar''s plant switches on to quantify how much it raises night-time levels.','A wind-farm assessor characterises the quiet rural residual environment against which turbine noise will be judged.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Residual acoustic environment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'af8397c2-e592-50ff-b826-49a241e01bce','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='af8397c2-e592-50ff-b826-49a241e01bce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='af8397c2-e592-50ff-b826-49a241e01bce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac034352-1efc-5bf1-b8b2-2bea72f395aa','Representative measurement period','A time interval chosen for measurement (or prediction) so that the result typifies the noise condition being assessed, rather than an unusually high or low moment. Under ISO 1996-2 and similar methods, the assessor must select periods that represent the relevant operating and propagation conditions — the source running as it normally does, and meteorological conditions favourable to (or typical of) propagation to the receiver — and of sufficient duration to capture the variability of the source and environment. Representativeness may require measuring across several periods, times of day, days of the week, or seasons, and excluding or noting atypical events. The reference time interval over which a descriptor such as LAeq is evaluated (day, evening, night) is also part of specifying a representative result. What counts as representative — the duration, number of samples and conditions — is set by the governing standard, regulation or assessment brief and varies by source type and jurisdiction.','This is a measuring time chosen to be typical of the noise. It should not catch only the loudest or quietest moment. The source should be running as it usually does. The weather should be normal for how sound travels there. The period must be long enough to catch the ups and downs. Sometimes you must measure on several days or times. Odd one-off events are noted or left out. This makes the result fair and repeatable. Standards and local rules set what counts as typical.','It ensures a measurement reflects the true, ongoing situation rather than a cherry-picked or accidental extreme, so assessments are fair, reproducible and defensible. Noise varies with source operation, traffic, time and weather; without choosing representative periods, the same site could be shown to pass or fail at will. Defining representativeness keeps compliance checks and impact assessments consistent and resistant to challenge.','An acoustician planning a survey selects representative periods — for example typical weekday operations under near-neutral or downwind conditions — and measures long enough, on enough occasions, to capture normal variability, documenting any atypical events. This underpins a defensible LAeq or rating level for a planning assessment, a compliance check, or a nuisance investigation, and is scrutinised if the result is contested.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['ISO 1996-2','Reference time interval','LAeq','Worst-case operating condition','Meteorological correction','Residual acoustic environment','BS 4142']::text[],ARRAY['Measuring for a single short interval and treating it as representative; adequate representativeness usually needs enough duration and repetition to capture variability.','Choosing periods to flatter the result — either the quietest or loudest moment — instead of typical conditions, which invalidates the assessment.','Ignoring meteorological conditions; a period is only representative if propagation conditions are typical or specified, not accidental.','Confusing the representative period with the worst-case condition; they answer different questions and may require separate measurements.']::text[],ARRAY['A consultant schedules noise surveys across several typical weekdays to obtain a representative LAeq for a factory assessment.','An enforcement officer rejects a single-reading complaint measurement because it did not represent normal operating conditions.','A wind-farm assessor measures over many periods and wind conditions to capture representative turbine noise.','A planner specifies representative day, evening and night periods for baseline monitoring in an environmental statement.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Representative measurement period');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac034352-1efc-5bf1-b8b2-2bea72f395aa','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac034352-1efc-5bf1-b8b2-2bea72f395aa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac034352-1efc-5bf1-b8b2-2bea72f395aa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8efcb8ee-369a-515a-8901-8abe7c175931','Worst-case operating condition','A measurement or prediction scenario in which the source is assumed to produce its maximum realistic output and/or propagation is most favourable to the receiver, used to test compliance against the highest impact that can reasonably occur. Rather than typical operation, it combines the source running at full or peak load (all plant on, maximum production, busiest schedule) with conditions that maximise received level — for example downwind or temperature-inversion propagation. Assessing the worst case is common where a standard or permit requires that limits not be exceeded even under adverse but foreseeable conditions, particularly for planning approvals and permit conditions that must protect receivers at all times. It is distinct from, and often used alongside, a representative (typical) assessment. What constitutes the reasonable worst case, and whether it or a representative condition governs, is defined by the applicable standard, regulator or permit and varies by jurisdiction and source type.','This is the scenario where a source is at its loudest realistic output. All the plant runs at once, at full load. The weather also helps the sound reach the receiver. Assessors use it to test the hardest case. It checks that limits still hold under bad but possible conditions. It is not the typical day; it is the reasonable worst day. Permits often must protect people even then. It is used beside, not instead of, typical assessment. The applicable standard or permit defines what counts as worst case.','It protects receivers against the highest foreseeable impact, not just the average one. Because a source that complies on a typical day may breach limits when running flat out under favourable propagation, regulators and permit-writers require the reasonable worst case to be assessed so conditions hold up under adverse circumstances. It gives a safety margin and prevents approvals that would fail whenever demand or weather turns unfavourable.','An acoustician modelling a proposed plant assesses the reasonable worst case — all equipment at rated output, downwind propagation to the nearest dwellings — to demonstrate the design meets limits even then, sizing barriers, silencers or setbacks accordingly. Regulators write permit conditions referencing worst-case operation, and enforcement may test a site during peak activity and favourable propagation to check compliance.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Representative measurement period','Downwind propagation condition','Meteorological correction','Temperature inversion','Rating level','ISO 9613-2','Permit noise condition']::text[],ARRAY['Assuming worst case means physically impossible extremes; it is the reasonable, foreseeable maximum, not an implausible combination of every adverse factor.','Using only typical operation to prove compliance where the permit or standard requires the worst case to be within limits.','Forgetting propagation; the worst case combines maximum source output with conditions (e.g. downwind, inversion) that maximise the received level.','Treating worst-case and representative assessments as interchangeable, when they answer different regulatory questions and may both be required.']::text[],ARRAY['A consultant models a factory with all machinery at full load and downwind wind to prove it meets limits even at worst case.','A permitting authority requires an incinerator''s noise assessment to demonstrate compliance under maximum throughput.','An enforcement officer times a site visit to peak operations and favourable propagation to test a disputed limit.','A wind-farm developer assesses turbines at rated power in the wind direction that maximises noise at the nearest home.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Worst-case operating condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8efcb8ee-369a-515a-8901-8abe7c175931','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8efcb8ee-369a-515a-8901-8abe7c175931') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8efcb8ee-369a-515a-8901-8abe7c175931');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7832b1d1-f79f-5fa3-bb27-5c475a2e58be','Meteorological correction','An adjustment applied in outdoor sound-propagation assessment to account for the effect of weather — wind speed and direction, temperature gradient (lapse or inversion), and to a lesser extent humidity — on how efficiently sound travels from source to receiver. Because sound bends (refracts) upward in upwind or lapse conditions and downward toward the receiver in downwind or inversion conditions, the received long-term level differs from that under a single reference propagation condition. In ISO 9613-2, prediction is made for favourable (downwind) propagation and a meteorological correction Cmet is subtracted to obtain a long-term average level that reflects the proportion of time such favourable conditions actually occur; Cmet depends on source and receiver heights, the source-receiver distance, and a site factor C0 representing local meteorological statistics. Humidity and temperature also govern atmospheric absorption, corrected separately. The exact correction, the value of C0 and how meteorology is handled depend on the standard and local climate data, so values vary by method and site.','This adjusts noise predictions for the effect of weather. Wind and temperature change how far sound carries. Sound bends down toward listeners when wind blows from source to receiver. It also bends down under a temperature inversion. This makes distant noise louder at those times. Prediction methods first assume this helpful, downwind case. Then a correction lowers the result to a long-term average. The correction reflects how often such weather really happens. It depends on distances, source and receiver height, and local climate. The exact method and figures vary by standard and site.','It reconciles a single modelled propagation scenario with reality, where weather constantly changes how much sound reaches a receiver. Predicting only the favourable (worst-for-the-receiver) case would overstate the long-term average, while ignoring weather would understate peaks; the correction lets assessors report a defensible long-term level tied to local meteorological statistics. This matters for comparing predictions to long-term limits and for fair impact assessment at distance.','An acoustician using ISO 9613-2 to model a plant or road computes the favourable-condition level, then applies Cmet with a site-specific C0 from local wind and stability data to derive the long-term average level at each receiver, reported in the noise assessment. Where a worst-case check is needed, the favourable-condition (uncorrected) level is used instead. Enforcement and planning reviewers scrutinise the C0 value and its climatic basis.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['ISO 9613-2','Downwind propagation condition','Temperature inversion','Ground attenuation','Atmospheric absorption','Worst-case operating condition','Representative measurement period']::text[],ARRAY['Assuming weather has no effect at typical assessment distances; downwind or inversion conditions can raise received levels noticeably, especially far from the source.','Applying the long-term meteorological correction when a worst-case (favourable-propagation) level is what the assessment requires, thereby understating peak impact.','Confusing the geometric/downwind correction Cmet with atmospheric absorption; the latter depends on frequency, temperature and humidity and is handled separately.','Using a generic C0 value without local climate data, since the correction depends on how often favourable propagation actually occurs at the site.']::text[],ARRAY['A consultant derives long-term average levels at distant dwellings by applying Cmet to ISO 9613-2 favourable-condition predictions.','A wind-farm assessor accounts for frequent night-time downwind and inversion conditions when predicting turbine noise.','An enforcement reviewer challenges a report''s C0 value as unsupported by local meteorological statistics.','A planner requires both a worst-case downwind level and a meteorologically corrected long-term level for a proposed quarry.']::text[],'advanced','Cmet = 0 for dp ≤ 10(hs+hr);  Cmet = C0·[1 − 10(hs+hr)/dp] for dp > 10(hs+hr)','The meteorological correction is zero when the source-to-receiver horizontal distance is at most ten times the sum of the source and receiver heights; beyond that distance it equals the site meteorological factor C0 multiplied by one minus ten times the sum of source and receiver heights divided by the horizontal distance.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Meteorological correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7832b1d1-f79f-5fa3-bb27-5c475a2e58be','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7832b1d1-f79f-5fa3-bb27-5c475a2e58be') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7832b1d1-f79f-5fa3-bb27-5c475a2e58be');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'daec242a-50a6-5aae-8b1b-b1ce502c058f','Downwind propagation condition','A propagation scenario in which the wind blows from the source toward the receiver (or, equivalently, a positive vertical sound-speed gradient exists), causing sound rays to refract downward and reach the receiver more efficiently, with reduced shielding by the ground and barriers. It is the standard ''favourable'' condition adopted in outdoor prediction methods such as ISO 9613-2, which predict the level under downwind propagation and then apply a meteorological correction to obtain a long-term average. Downwind (and the analogous temperature-inversion) conditions represent the higher-impact case for a receiver, so they are used for worst-case assessment and are the basis from which long-term levels are corrected. The magnitude of the enhancement grows with distance and depends on source and receiver heights, terrain and the strength of the gradient. Whether the downwind condition is used directly (worst case) or corrected to a long-term average, and the numerical treatment, are set by the applicable standard and vary by method and jurisdiction.','This is when the wind blows from the source to the listener. The wind bends the sound downward toward the ground. So the sound reaches the listener more easily. Barriers and the ground shield less in this case. It makes distant noise louder than on a calm day. Prediction methods treat this as the favourable case. They use it as the higher-impact, worst-case setting. A correction can then turn it into a long-term average. The effect grows with distance. The exact treatment is set by the standard used.','It defines a consistent reference for the condition under which a receiver hears the most from a source, so assessments can test the higher-impact case and derive long-term averages from it. Standardising on downwind propagation removes ambiguity from predictions and enforcement: everyone models the same favourable condition, then adjusts for how often it occurs. It is essential to fair worst-case assessment at distance, where wind and temperature effects dominate the received level.','An acoustician predicting noise at distant dwellings assumes downwind propagation from source to each receiver (per ISO 9613-2), giving the worst-case level; measurements to verify a prediction or check compliance are likewise made under downwind conditions so results are comparable. Where a long-term figure is needed, the downwind result is meteorologically corrected. Planners and regulators expect downwind assumptions to be stated and justified.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Meteorological correction','Temperature inversion','ISO 9613-2','Worst-case operating condition','Ground attenuation','Representative measurement period','ISO 1996-2']::text[],ARRAY['Believing wind direction barely matters; downwind propagation can raise received levels substantially at distance compared with upwind or calm conditions.','Measuring or predicting upwind and treating the low result as typical, which understates the impact the receiver actually experiences.','Assuming the downwind (favourable) level already equals the long-term average; it is the higher-impact case and usually needs meteorological correction for a long-term figure.','Ignoring that a temperature inversion produces the same downward refraction as downwind, so calm nights can still give strong long-distance propagation.']::text[],ARRAY['A consultant models downwind propagation to each nearby home to establish worst-case levels from a proposed industrial site.','A field technician schedules verification measurements for downwind conditions so they match the ISO 9613-2 prediction.','A wind-farm assessor treats the wind direction toward dwellings as the governing downwind case for noise limits.','An enforcement officer measures under downwind conditions to fairly test a distant receiver''s complaint.']::text[],'advanced',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Downwind propagation condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'daec242a-50a6-5aae-8b1b-b1ce502c058f','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='daec242a-50a6-5aae-8b1b-b1ce502c058f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='daec242a-50a6-5aae-8b1b-b1ce502c058f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ac5a14b9-ad37-5219-80f8-2f3d4380b96f','Temperature inversion','An atmospheric condition in which air temperature increases with height instead of decreasing, creating a positive vertical sound-speed gradient that refracts sound rays downward toward the ground and greatly enhances long-distance propagation. Inversions commonly form on clear, calm nights and in early morning as the ground cools, and they are the still-air analogue of downwind propagation: both bend sound back toward receivers, reducing ground and barrier shielding and raising received levels far from the source. Because inversions coincide with quiet night-time periods when background levels are low and people are trying to sleep, they are significant for night-noise complaints and for the assessment of sources such as industry, wind farms, motorways and railways at distance. Prediction and measurement standards treat this downward-refracting case within their favourable-propagation and meteorological-correction framework. The strength of the effect depends on the gradient, distance and terrain, and how it is accounted for varies by standard and jurisdiction.','Normally air gets colder as you go up. In a temperature inversion, air gets warmer with height. This bends sound downward toward the ground. So sound carries much farther than usual. Inversions often form on clear, calm nights. That is when background noise is low and people sleep. So distant noise can suddenly seem loud at night. It has the same effect as a downwind breeze. Barriers and ground shield less during an inversion. Standards handle this within their weather corrections.','The concept explains why distant sources can be clearly and disturbingly audible on still nights when they are inaudible by day, and it justifies assessing the downward-refracting case in propagation modelling. Recognising inversions helps authorities and assessors understand night-noise complaints, choose appropriate worst-case assumptions, and evaluate sources whose impact is dominated by night-time long-distance propagation, such as wind farms and heavy industry.','An acoustician investigating night-time complaints about a distant plant or wind farm considers whether inversions explain the intermittent audibility, and reflects the downward-refracting condition in prediction and in the timing of measurements. Because inversions align with the favourable-propagation case, they inform worst-case assessment and the choice of when to measure to capture the highest realistic received levels at sensitive receivers.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Downwind propagation condition','Meteorological correction','ISO 9613-2','Worst-case operating condition','Ground attenuation','Lnight','Representative measurement period']::text[],ARRAY['Assuming calm, windless nights mean sound does not travel far; a temperature inversion refracts sound downward and can enhance long-distance propagation without any wind.','Explaining louder night-time noise only by lower background levels, overlooking that inversions also physically increase the received level.','Confusing an inversion (warmer air aloft) with normal daytime conditions (cooler air aloft), which refract sound upward and reduce distant levels.','Ignoring inversions in worst-case assessment of distant sources, thereby underestimating night-time impact at sensitive receivers.']::text[],ARRAY['An investigator attributes intermittent night-time audibility of a distant factory to temperature inversions and schedules measurements accordingly.','A wind-farm assessor evaluates stable night-time inversion conditions as a governing case for received noise.','A resident''s complaint that a motorway is only loud at night is examined against inversion-driven propagation.','A regulator asks that an assessment of a quarry include downward-refracting inversion conditions, not just daytime measurements.']::text[],'advanced',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temperature inversion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ac5a14b9-ad37-5219-80f8-2f3d4380b96f','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ac5a14b9-ad37-5219-80f8-2f3d4380b96f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ac5a14b9-ad37-5219-80f8-2f3d4380b96f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f13f2e71-f621-5ae2-b58d-d042bc0db55f','Ground attenuation','The change in outdoor sound level caused by interaction of the propagating sound with the ground surface between source and receiver, arising from interference between the direct ray and the ray reflected from the ground. Whether the ground adds or removes energy depends on frequency, source and receiver heights, the source-receiver distance, and the acoustic hardness or porosity of the ground: acoustically soft (porous) ground such as grass, soil and vegetation generally produces net attenuation over distance, while acoustically hard ground such as water, concrete or paving reflects strongly and gives little attenuation or even reinforcement. In ISO 9613-2, ground attenuation Agr is quantified either by a source, middle and receiver region method using ground factor G (0 for hard, 1 for porous), or by a simplified formula for the middle region; the term can be several decibels and is frequency-dependent. Because it depends on the ground type assumed and the method used, ground attenuation values vary between standards, sites and jurisdictions and must be justified in an assessment.','This is how the ground changes sound as it travels across it. Sound reaches a listener directly and by bouncing off the ground. These two paths mix and can cancel or add. Soft ground like grass and soil absorbs and cuts the level. Hard ground like water or concrete reflects and keeps it loud. The effect depends on the ground type and the frequencies. It also depends on how high the source and listener are. The loss can be several decibels over distance. Methods like ISO 9613-2 give a way to work it out. The ground assumed must be justified in a report.','It captures a real and often large propagation effect so predictions at distance are accurate: the same source over grass versus over water or hard paving can differ by several decibels at a receiver. Modelling ground attenuation lets assessors predict levels reliably, credit soft ground where it genuinely reduces noise, and avoid over- or under-estimating impact. It also identifies where hard reflective surfaces (water bodies, hard yards) will worsen received levels.','An acoustician modelling road, rail or industrial noise assigns a ground factor to the terrain between source and receiver (soft farmland versus hard water or paving) and computes Agr per ISO 9613-2 for each octave band, feeding it into the predicted level at each dwelling. Getting the ground type right is often decisive in whether a scheme is shown to meet limits, so the assumption is documented and scrutinised in planning and enforcement review.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['ISO 9613-2','Downwind propagation condition','Meteorological correction','Atmospheric absorption','Barrier attenuation / insertion loss','Worst-case operating condition','Octave-band analysis']::text[],ARRAY['Assuming ground attenuation is always a loss; over hard or reflective ground (water, concrete) the ground gives little attenuation and can reinforce the level.','Applying a single broadband figure; ground attenuation is strongly frequency-dependent and is normally computed per octave band.','Crediting soft-ground attenuation without justification when the real path is over water, paving or a hard yard, overstating the mitigation.','Ignoring the effect of source and receiver height; ground attenuation diminishes when either is raised well above the surface.']::text[],ARRAY['A consultant models grassland between a bypass and homes to credit ground attenuation in the predicted levels.','An assessor over a lake or hardstanding uses a hard-ground factor, recognising little attenuation, when predicting industrial noise.','A reviewer challenges a report''s soft-ground assumption because the propagation path crosses a paved yard.','A rail-noise study computes octave-band ground attenuation to design the height and placement of a lineside barrier.']::text[],'advanced','Agr(middle region) = 4.8 − (2·hm/d)·[17 + 300/d],  with Agr ≥ 0 (hm = mean propagation height, d = distance)','In the simplified middle-region form of ISO 9613-2, the ground attenuation in decibels equals 4.8 minus twice the mean propagation height divided by the source-receiver distance, that quantity multiplied by seventeen plus three hundred divided by the distance, with the result not allowed to fall below zero.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ground attenuation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f13f2e71-f621-5ae2-b58d-d042bc0db55f','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f13f2e71-f621-5ae2-b58d-d042bc0db55f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f13f2e71-f621-5ae2-b58d-d042bc0db55f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '09ec4ca3-02af-5283-9173-fb6163e0b823','Barrier insertion loss','The reduction in sound level at a receiver caused by placing a solid acoustic barrier (a wall, berm, screen or fence) between a noise source and that receiver, defined as the difference between the level measured or predicted with the barrier absent and the level with the barrier present, all other conditions unchanged. It is the working performance figure for a screen in transportation, industrial and construction noise mitigation, and is distinct from a barrier''s laboratory transmission loss because insertion loss also accounts for sound diffracting over and around the obstacle and reflecting off the ground. In prediction, insertion loss depends mainly on the extra path length that sound must travel over the barrier top relative to the direct source–receiver line, expressed through the Fresnel number, and it grows with frequency and with barrier height. Empirical single-diffraction models such as Maekawa''s chart, and the screening term within engineering methods like ISO 9613-2, are commonly used to estimate it. Achievable values are limited in practice — often to the order of about 5 to 10 dB in the field and rarely beyond roughly 20 to 25 dB — because flanking paths, gaps, reflections and meteorological effects erode the theoretical shielding, and the exact predicted figure depends on geometry, frequency content, ground and the method and jurisdiction applied.','A noise barrier is a solid wall or bank between a source and a listener. Insertion loss is how much quieter it makes things. You compare the level with the wall to the level without it. The gap between the two numbers is the insertion loss. Sound still bends over the top of the barrier. So a barrier cannot block noise fully. Taller barriers and higher pitched sounds are blocked better. Real screens usually cut only about 5 to 10 decibels. Gaps, ground and weather all reduce the effect. The exact figure depends on the layout and the method used.','Insertion loss is the metric that tells a planner or acoustic engineer whether a proposed barrier will deliver the noise reduction a scheme needs at a given receiver. It converts a mitigation idea into a testable number, letting designers compare barrier heights, positions and materials against a target level or a regulatory limit before construction, and letting authorities judge whether a road, rail or industrial scheme meets its noise obligations. Because it captures real-world diffraction and flanking rather than idealised blocking, it guards against over-promising the protection a wall can give.','A transport or environmental acoustics consultant computes predicted insertion loss when designing a highway or railway noise wall: they model source, barrier and dwelling geometry, calculate the path-length difference and Fresnel number, and iterate the barrier height until the level at the nearest facade meets the scheme''s target. On existing schemes an assessor may verify performance by measuring levels before and after a barrier, or at shielded and exposed positions, to confirm the built wall achieves the design insertion loss and to support decisions on residents'' noise complaints or entitlement to mitigation.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Source-path-receiver model','Engineering noise control','ISO 9613-2','Fresnel number','Diffraction','Noise barrier / acoustic screen','Transmission loss']::text[],ARRAY['Confusing insertion loss with a barrier''s sound transmission loss; insertion loss includes diffraction over the top and flanking, so it is usually far smaller than the material''s rated blocking.','Assuming a taller wall keeps adding large gains; benefit grows with height but with diminishing returns, and flanking and reflections cap real-world performance.','Believing a barrier helps everywhere; a receiver with line-of-sight to the source, or one high up in a building, may gain little or nothing.','Treating one predicted decibel figure as guaranteed; the value depends on geometry, frequency, ground, weather and the calculation method and standard used.']::text[],ARRAY['A highway authority''s acoustic consultant sizes the height of a roadside noise wall so the predicted insertion loss brings facade levels within the scheme''s target.','An environmental health officer reviews before-and-after measurements to check whether an installed industrial screen delivers the insertion loss its designer claimed.','A rail project team models Fresnel numbers for line-of-sight and shielded dwellings to map which homes a proposed barrier will actually protect.','A construction-site planner positions temporary hoarding close to a breaker to maximise diffraction shielding at nearby flats during permitted working hours.']::text[],'advanced','IL = L_without − L_with ;  N = 2δ/λ  (δ = A + B − d)','Insertion loss in decibels equals the sound level with no barrier minus the level with the barrier in place; the governing Fresnel number equals twice the path-length difference divided by the wavelength, where the path-length difference is the source-to-top plus top-to-receiver distance minus the straight source-to-receiver distance.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Barrier insertion loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '09ec4ca3-02af-5283-9173-fb6163e0b823','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='09ec4ca3-02af-5283-9173-fb6163e0b823') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='09ec4ca3-02af-5283-9173-fb6163e0b823');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8ada0982-d122-52b3-ac66-daa1b6d103d1','Source-path-receiver model','The foundational conceptual framework of noise control, which analyses any noise problem as a chain of three linked elements: the source that generates the sound, the path along which it travels (through air, ground or structure), and the receiver who is exposed to it. Control can be applied at any one or more of these three points — reducing emission at the source, interrupting or lengthening the path, or protecting the receiver — and the framework guides engineers, assessors and regulators to identify where intervention is most effective, feasible and durable. It underpins both the technical mitigation hierarchy and the structure of most environmental and occupational noise assessments, which characterise the source''s sound power or emission, model propagation losses along the path (distance, air absorption, ground, screening, meteorology), and evaluate the resulting immission at the receiver against an applicable limit. The relative priority given to each element, and the limits applied at the receiver, vary by jurisdiction, setting (occupational versus environmental) and the standard or code in force.','Every noise problem has three parts. First is the source that makes the sound. Second is the path the sound travels along. Third is the receiver, the person who hears it. You can act on any of these three parts. You can make the source quieter at the start. You can block or lengthen the path in the middle. You can protect the person at the end. This simple chain guides most noise control work. It also shapes how assessors measure and model noise. Which part you fix first depends on cost and the setting.','The model exists to give a clear, systematic way to diagnose noise problems and choose where to intervene, rather than reaching straight for one favoured fix. By separating generation, transmission and exposure, it forces analysts to ask which link is easiest and most cost-effective to break, and it exposes options — such as quieting a machine or moving a receiver — that a narrow focus on barriers or earplugs would miss. It also organises assessment: measuring source emission, modelling path losses and checking receiver immission map directly onto its three stages, making it the backbone of noise mapping, prediction and compliance work.','A noise consultant or safety officer uses the framework to structure an assessment and mitigation plan: they quantify the source, trace how sound reaches each affected person, and then propose controls at whichever stage yields the best result — for example specifying a quieter machine, adding an enclosure or barrier in the path, and reserving hearing protection for residual exposure at the receiver. Regulators and event compliance staff apply the same logic when they set source emission conditions, require screening or setbacks, and specify receiver-based limits at facades or work positions.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Noise mitigation hierarchy','Engineering noise control','Administrative noise control','Personal hearing protection','Barrier insertion loss','Noise-sensitive receiver','Sound propagation / ISO 9613']::text[],ARRAY['Jumping straight to hearing protection or a barrier without first asking whether the source itself can be quietened, which is usually the most effective and durable control.','Thinking only one point can be treated; effective schemes often combine controls at source, path and receiver together.','Confusing the source''s emission (sound power) with the receiver''s immission (the level actually experienced); the path between them changes the number substantially.','Assuming the path is only through the air; structure-borne and ground-transmitted paths often dominate and need different controls.']::text[],ARRAY['An occupational-health engineer maps a noisy workshop as source, path and receiver to decide whether to enclose a machine or relocate workstations.','An environmental consultant structures a planning noise assessment around source emission, propagation path and facade immission at nearby homes.','A festival compliance officer applies the framework to cut stage output, aim speakers away from housing, and offer audience earplugs.','A council enforcement team uses the model to explain to a factory why source and path controls are expected before relying on staff hearing protection.']::text[],'beginner',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source-path-receiver model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8ada0982-d122-52b3-ac66-daa1b6d103d1','fe939357-1f13-4421-b331-61ce91d66150',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8ada0982-d122-52b3-ac66-daa1b6d103d1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8ada0982-d122-52b3-ac66-daa1b6d103d1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '396de908-01f1-5564-b17c-6605d31811e1','Best practicable environmental option (BPEO)','An environmental decision-making concept — originating in UK environmental policy and popularised by the Royal Commission on Environmental Pollution — under which, for a given objective, the option is chosen that provides the most benefit or least damage to the environment as a whole, across air, water and land, at acceptable cost, in the long term as well as the short term. Applied to noise, BPEO is used when comparing mitigation or development alternatives: it weighs a scheme''s noise impact against its other environmental effects and its practicability and cost, rather than optimising for noise alone. The word ''practicable'' signals that the option must be technically achievable and not disproportionately expensive, echoing related statutory tests such as ''best practicable means''. BPEO is an appraisal principle rather than a fixed numeric limit; how it is weighed, and whether it is formally required, depends on the jurisdiction, the consenting regime and the guidance in force, and in some regimes it has been superseded or absorbed into wider integrated environmental assessment and best-available-techniques frameworks.','BPEO stands for best practicable environmental option. It is a way to compare choices for a project or fix. You pick the option that harms the whole environment least. You look at air, water and land, not just noise. You also weigh cost and what is realistic to build. So the quietest option is not always the winner. A costly noise wall might cause other harm or waste. BPEO balances all these effects together over time. It is a judgement principle, not a fixed decibel limit. Its role depends on local law and guidance.','BPEO exists to stop decision-makers from solving one environmental problem while creating others, and from demanding perfection regardless of cost. By requiring a balanced appraisal of alternatives across all environmental media and over time, it justifies a proportionate choice of mitigation and creates a defensible, documented rationale for why one option was preferred. In noise work it provides the reasoning that supports selecting, for example, a source or layout change over an intrusive barrier, and helps authorities and developers show a consenting body that impacts were genuinely weighed rather than ignored.','A planning or environmental consultant invokes BPEO in an environmental statement or noise mitigation appraisal to explain why the chosen option was selected: they list feasible alternatives, score each on noise and other environmental effects, cost and buildability, and record the balanced conclusion for the decision-maker. Regulators and inspectors use it to test whether an applicant has genuinely considered less harmful or more practicable options before granting consent, and it can feature in the reasoning behind conditions attached to a permit or in the defence of an abatement decision.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Best practicable means (BPM)','Best available techniques (BAT)','Noise mitigation hierarchy','Environmental impact assessment','Noise action plan','Proportionality / acceptable cost']::text[],ARRAY['Reading BPEO as ''the quietest option wins''; it balances noise against all other environmental effects, cost and practicability, so a lower-noise option can still be rejected.','Confusing BPEO with best available techniques (BAT); they are related appraisal ideas but arise from different regimes and are not identical.','Treating BPEO as a numeric standard; it is a reasoned appraisal principle, not a fixed limit value to measure against.','Assuming it is universally mandatory; whether and how BPEO applies depends on the jurisdiction, the consent regime and current guidance, and it has been superseded in some frameworks.']::text[],ARRAY['A developer''s environmental statement uses a BPEO appraisal to justify choosing a site layout change over a tall perimeter noise barrier.','A regulator reviewing a waste or industrial permit checks whether the applicant weighed noise against other impacts under a best-practicable-option test.','An acoustic consultant scores mitigation alternatives on noise, visual impact, carbon and cost to record the balanced option for a planning inspector.','A local authority defends the mitigation it required at appeal by showing the chosen measures were the best practicable environmental option.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Best practicable environmental option (BPEO)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '396de908-01f1-5564-b17c-6605d31811e1','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='396de908-01f1-5564-b17c-6605d31811e1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='396de908-01f1-5564-b17c-6605d31811e1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '58bffef8-3059-5e9a-83e1-6b6a7bc37259','Noise mitigation hierarchy','The ordered set of preferred noise-control strategies, applied top-down, in which controls higher in the order are favoured because they are more reliable and protect more people than those below. In occupational practice it mirrors the general hierarchy of controls: first eliminate the noise source or the need for it; then substitute quieter processes or equipment; then apply engineering controls (enclosures, barriers, silencers, damping, isolation) that reduce noise at source or in the path; then administrative controls (limiting exposure time, scheduling, rotation, restricted hours); and finally, as the last line of defence, personal hearing protection worn by the exposed person. Environmental and planning regimes use a parallel logic — avoid or design out impact, reduce at source, mitigate along the path, and only then compensate or protect receivers. The hierarchy expresses that source and engineering controls are preferred over reliance on hearing protectors, which fail when misused or poorly fitted; the precise ordering, terminology and legal weight vary by jurisdiction and by whether the context is occupational or environmental.','The noise mitigation hierarchy ranks ways to control noise. You try the most reliable methods first. Best of all is removing the noisy source completely. Next you swap in quieter machines or processes. Then you use engineering fixes like enclosures and barriers. Then you limit how long people are exposed. Last of all comes wearing earplugs or earmuffs. Hearing protection is the weakest option, not the first. It fails when it is worn wrongly or not at all. So good schemes fix the source before handing out earplugs. The exact order and rules vary by country and setting.','The hierarchy exists to steer duty-holders away from cheap, fragile fixes toward controls that work even when people are careless. Because personal hearing protection depends on correct, continuous use and can give far less real protection than its rating, laws and codes require higher-order controls to be considered and applied first, reserving protectors for residual risk. Ranking the options also gives inspectors a clear test — was the source tackled before earplugs were issued? — and gives employers and event operators a defensible, prioritised plan for reducing exposure and demonstrating that risk was reduced as far as reasonably practicable.','A workplace noise assessor or event safety officer uses the hierarchy to build a compliant control plan: they document attempts to eliminate or substitute noisy equipment, specify engineering controls such as enclosures or barriers, add administrative measures like job rotation or curfews, and only then provide and enforce hearing protection for the exposure that remains. Enforcement officers check that this order was followed, and will challenge a scheme that leans on earplugs while ignoring feasible source or engineering controls; the documented hierarchy also underpins risk assessments and audits.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Hierarchy of controls','Engineering noise control','Administrative noise control','Personal hearing protection','Source-path-receiver model','Control of Noise at Work Regulations','As low as reasonably practicable (ALARP)']::text[],ARRAY['UNSAFE: Treating hearing protection as the first or main control; it is the last line of defence and, if relied on alone, often leaves workers under-protected because real-world attenuation is much lower than the rating.','Assuming any single measure satisfies the law; regulators generally require higher-order controls to be considered and applied before protectors.','Confusing engineering with administrative controls; enclosures and barriers are engineering, while rotation and restricted hours are administrative and less reliable.','Believing the hierarchy is optional guidance; in many occupational regimes following it, or justifying departures, is a legal duty.']::text[],ARRAY['A factory safety manager documents source and engineering controls before issuing earplugs, to show an inspector the hierarchy was followed.','A construction planner substitutes hydraulic breakers for pneumatic ones and adds screening before relying on crew hearing protection.','An HSE-style inspector rejects a noise assessment that jumps straight to hearing protection without considering quieter machinery.','A touring production reduces stage volume and improves speaker aiming before handing out audience earplugs at an urban festival.']::text[],'beginner',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise mitigation hierarchy');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '58bffef8-3059-5e9a-83e1-6b6a7bc37259','fe939357-1f13-4421-b331-61ce91d66150',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='58bffef8-3059-5e9a-83e1-6b6a7bc37259') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='58bffef8-3059-5e9a-83e1-6b6a7bc37259');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '99d34f21-7bcc-53fa-85c1-c71fe51db553','Administrative noise control','The class of noise-control measures that reduce exposure or impact by changing how, when and for how long noisy activity occurs, rather than by physically altering the source or the path. In occupational settings this includes limiting the time individuals spend in noisy areas, job rotation to share exposure, scheduling loud tasks when fewer people are present, providing quiet rest breaks away from noise, and posting warnings and information. In environmental and event settings the parallel measures include restricted operating hours and curfews, limits on the number of noisy events, time-of-day restrictions, delivery and plant-use scheduling, and complaint-handling procedures. Administrative controls sit below engineering controls in the mitigation hierarchy because they depend on people following procedures and do not lower the sound level itself; they are typically used to supplement engineering controls and to manage residual exposure, and the specific measures and any mandated limits (such as permitted hours or maximum events per year) vary by jurisdiction, licence and code.','Administrative noise control changes when and how long noise happens. It does not make the source itself quieter. At work it can mean limiting time in loud areas. It can mean rotating workers so no one gets too much. It can mean quiet rest breaks and clear warning signs. For events it can mean curfews and set quiet hours. It can also cap how many loud events are allowed. These rules rely on people actually following them. So they are weaker than fixing the machine itself. They usually back up engineering controls, not replace them. Exact limits vary by permit, country and code.','Administrative controls exist to manage the exposure that engineering measures cannot fully remove, and to give regulators and managers levers that need no new hardware — hours, rotas, timing and procedures. Because dose depends on both level and duration, cutting the time a person spends in noise lowers their exposure even when the level is unchanged, and restricting when noisy activity happens protects sensitive receivers during vulnerable periods such as night. They also formalise responsibilities — who monitors, who logs, who handles complaints — creating the procedural backbone that lets an organisation demonstrate ongoing compliance.','A safety officer schedules the loudest machining for a night shift with minimal staffing, rotates operators through a noisy line to keep each person''s daily dose down, and enforces mandatory breaks in a quiet room. An event or environmental compliance officer builds administrative controls into a permit and its management plan — curfew times, a cap on event days, delivery windows and a manned complaint line — and records adherence in logs that become the evidence of compliance if the authority investigates a breach or a resident complains.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Engineering noise control','Noise mitigation hierarchy','Curfew / restricted hours','Personal noise dosimeter','Dosimetry exchange criterion','Noise management plan']::text[],ARRAY['UNSAFE: Believing that limiting exposure time alone makes a very loud area safe; at high levels the permitted time falls steeply, and brief exposure to extreme or impulse noise can still injure hearing.','Ranking administrative controls above engineering controls; they sit lower in the hierarchy because they do not reduce the sound level and depend on compliance.','Assuming curfews and hour limits are the same everywhere; permitted hours and event caps are set locally by licence, code and time of day.','Treating rotas and signage as a substitute for source control rather than a supplement to it.']::text[],ARRAY['A plant manager rotates workers through a noisy packing line and schedules the loudest runs off-peak to keep individual daily doses down.','A city licensing condition caps an outdoor venue to a set number of amplified events per year with an 11 pm curfew.','A construction site restricts breaking and piling to defined daytime hours under a local authority consent to protect nearby residents.','An occupational-health officer adds mandatory quiet breaks and exposure-time limits to a noise plan while engineering enclosures are being installed.']::text[],'beginner',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Administrative noise control');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '99d34f21-7bcc-53fa-85c1-c71fe51db553','fe939357-1f13-4421-b331-61ce91d66150',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='99d34f21-7bcc-53fa-85c1-c71fe51db553') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='99d34f21-7bcc-53fa-85c1-c71fe51db553');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5559c14e-bf92-56e8-9b73-320ac0b81e2f','Engineering noise control','The class of noise-control measures that physically reduce sound by acting on the source or on the transmission path, rather than by changing work procedures or protecting the exposed person. Typical engineering measures include: at the source, quieter equipment, reduced drive speeds, better-balanced or damped components, and vibration isolation; and along the path, acoustic enclosures and hoods, close-fitting shields, partial barriers and screens, in-duct and exhaust silencers/mufflers, absorptive linings, resilient mounts and floating floors to break structure-borne paths, and directional loudspeaker arrays that steer sound away from receivers. Because they lower the actual emitted or transmitted sound level and do not rely on individual behaviour, engineering controls sit above administrative controls and personal protection in the mitigation hierarchy and are the preferred technical solution in both occupational and environmental regimes. The choice, effectiveness and any mandated ''reduce at source so far as reasonably practicable'' duty depend on the process, the frequency content, the setting and the standard or law in force.','Engineering noise control uses physical changes to cut sound. It works on the source or on the path it travels. At the source you can fit quieter machines or slow them down. You can add damping or rubber mounts to stop vibration. Along the path you can box a machine inside an enclosure. You can add silencers, barriers or sound-absorbing linings. You can also aim speakers away from homes. These fixes lower the real sound level for everyone nearby. They do not depend on people wearing earplugs. So they rank above earplugs and rotas in the hierarchy. The best choice depends on the machine and the law.','Engineering controls exist to remove or cut noise at its physical origin, giving protection that persists regardless of whether individuals follow procedures or wear protectors correctly. This reliability is why occupational and environmental laws generally require reduction at source and along the path to be pursued first and ''so far as is reasonably practicable'' before leaning on administrative measures or hearing protection. By lowering emission and immission, they protect everyone in range at once — workers, neighbours and audiences — and can bring a site within a regulatory limit permanently rather than depending on ongoing behaviour.','A noise-control engineer specifies engineering measures after a survey identifies dominant sources: enclosing a compressor, fitting an exhaust silencer, adding a close shield or absorptive lining, isolating a vibrating machine, or reconfiguring a PA into steerable arrays that keep energy off nearby housing. In environmental schemes the same discipline delivers roadside barriers, plant enclosures and silenced ventilation to meet planning noise conditions. Compliance officers and inspectors expect to see these measures considered and applied before a duty-holder relies on exposure-time limits or hearing protectors.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Administrative noise control','Noise mitigation hierarchy','Barrier insertion loss','Source-path-receiver model','Acoustic enclosure','Vibration isolation','Silencer / muffler']::text[],ARRAY['Assuming an acoustic enclosure or barrier blocks all noise; gaps, openings, flanking and structure-borne paths limit the real reduction achieved.','Confusing engineering with administrative controls; enclosures, silencers and isolation are engineering, whereas rotas and restricted hours are administrative.','Overlooking structure-borne and vibration paths, so airborne fixes alone fail to solve a low-frequency or impact-noise problem.','Treating engineering control as optional once earplugs are issued; regulators generally require source and path controls to be applied first so far as reasonably practicable.']::text[],ARRAY['A noise-control engineer designs an acoustic enclosure and exhaust silencer for a factory compressor to bring workplace levels below the action value.','A road scheme installs absorptive roadside barriers and low-noise surfacing to meet planning noise limits at nearby dwellings.','A live-sound designer configures a cardioid subwoofer array to steer low-frequency energy away from residential facades at a city festival.','An inspector reviewing a noisy workshop asks the employer to show which engineering controls were tried before hearing protection was issued.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Engineering noise control');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5559c14e-bf92-56e8-9b73-320ac0b81e2f','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5559c14e-bf92-56e8-9b73-320ac0b81e2f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5559c14e-bf92-56e8-9b73-320ac0b81e2f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9eacc3cd-9067-5599-ae39-8519bb23b0b1','Personal hearing protection','Devices worn on or in the ear — chiefly earplugs (foam, pre-moulded or custom) and earmuffs, plus level-dependent, communication and ''flat'' (uniform-attenuation) variants — that attenuate the sound reaching the eardrum, used to reduce a person''s noise exposure. In the mitigation hierarchy it is the last line of defence, applied to the residual exposure that remains after source and engineering controls, because its real-world protection depends on correct selection, fit, condition and continuous use and is typically much lower than the laboratory-derived rating. Products are rated by standardised single-figure or multi-band methods — for example the SNR and HML values under EN ISO 4869-2 in Europe or the NRR under US EPA/ANSI rules — which must be derated for realistic performance and matched to the noise spectrum so that the wearer is protected but not over-protected (over-attenuation can impair communication and warning-signal audibility). Selection duties, marking requirements and derating conventions vary by jurisdiction and standard.','Personal hearing protection means earplugs or earmuffs you wear. They lower the sound that reaches your eardrum. They are the last line of defence, not the first. You use them for the noise left after other controls. Their real protection depends on a good, constant fit. Worn loosely or briefly, they protect far less than their rating. Products carry ratings like SNR or NRR to compare them. These ratings must be reduced to reflect real-world use. You should match the protector to the noise, not over-block it. Too much blocking can hide speech and warning alarms.','Personal hearing protection exists to guard the individual against the exposure that source, path and administrative controls cannot fully remove, and to bridge situations where engineering fixes are impractical or still being installed. It gives portable, immediate risk reduction, but because its effectiveness hinges on human behaviour it is deliberately ranked last. Its rating systems and derating rules exist so that a duty-holder can choose a protector that brings exposure below the relevant action or limit value at the ear, while avoiding over-protection that would isolate the wearer from speech and safety signals.','A safety officer selects protectors by comparing the measured noise level and spectrum against candidate devices'' derated SNR, HML or NRR, aiming for an at-ear level safely under the action or limit value without over-attenuating; they then train wearers on fitting, run fit checks, and enforce use inside designated zones. In live sound, crew use musician-grade flat-response or level-dependent protectors to preserve mix accuracy, and audiences are offered plugs as supplementary protection. Records of selection, issue and training support the noise risk assessment and any enforcement inquiry.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Attenuation derating','Single Number Rating (SNR)','HML method','Noise Reduction Rating (NRR)','Hearing protection zone','Noise mitigation hierarchy','Noise-induced hearing loss (NIHL)']::text[],ARRAY['UNSAFE: Assuming a protector delivers its labelled SNR or NRR in practice; poor fit, wrong size, broken seal and intermittent use mean real attenuation is often far lower, so ratings must be derated.','UNSAFE: Believing more attenuation is always safer; over-protection can mask speech and warning signals and lead workers to remove protectors, increasing risk.','Thinking hearing protection can replace source and engineering controls; it is the last resort for residual exposure, not the primary control.','Treating one rating system as universal; SNR/HML (Europe) and NRR (US) use different methods and derating conventions and are not directly interchangeable.']::text[],ARRAY['An occupational-health officer selects earmuffs whose derated SNR brings the at-ear level just under the exposure limit without over-protecting.','A festival hands out earplugs to audience members as supplementary protection alongside a capped stage level.','A touring monitor engineer wears flat-response musician earplugs to protect hearing while keeping the mix tonally accurate.','An inspector reviews a factory''s protector selection, fit-testing and training records during a noise-compliance audit.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Personal hearing protection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9eacc3cd-9067-5599-ae39-8519bb23b0b1','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9eacc3cd-9067-5599-ae39-8519bb23b0b1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9eacc3cd-9067-5599-ae39-8519bb23b0b1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ff7d726-1b6b-58aa-a1fc-89531e19a608','Hearing protection zone','A designated area of a workplace in which noise exposure is high enough that wearing hearing protection is mandatory, marked with prescribed warning signage and, so far as reasonably practicable, restricted so that only those wearing protectors enter. In the UK Control of Noise at Work Regulations 2005, employers must delineate and mark such zones where any exposure is likely to reach the upper exposure action values — an LEX daily/weekly exposure of 85 dB(A) or a peak sound pressure of 137 dB(C) — and must ensure protection is worn there; comparable ''hearing protection required'' area concepts exist under other regimes, for example EU Directive 2003/10/EC and US OSHA/NIOSH practice, though the exact trigger level, signage and legal wording differ. The zone converts a measured exposure threshold into a physical, visible control: a boundary that tells everyone where protectors must be worn, supports enforcement, and helps limit the number of people exposed. The triggering level and marking requirements vary by jurisdiction and standard.','A hearing protection zone is a marked area at work. Inside it, wearing ear protection is compulsory. Warning signs show where the zone begins. Access is limited so far as is practical to protected people. The zone is set where noise crosses a legal action level. For example, UK rules use a daily exposure of 85 decibels A-weighted. They also use a peak of 137 decibels C-weighted. Other countries use similar ''protection required'' areas with their own triggers. The zone turns a noise measurement into a clear boundary. It makes the rule easy to see and to enforce.','The zone exists to translate an abstract exposure threshold into an unmistakable, enforceable boundary on the floor: it tells workers and visitors exactly where protectors must be worn, removes ambiguity about when the duty applies, and helps restrict entry so fewer people are exposed. Signage and demarcation support supervision and enforcement, provide evidence that the employer identified and controlled the risk, and reinforce the wider hearing-conservation programme by pairing measurement with a visible, always-on instruction at the point of hazard.','After a noise survey, a safety officer maps which areas reach the upper action values and demarcates them as hearing protection zones with the standard ''ear protection must be worn'' signs, provides protectors at the boundary, restricts access, and audits compliance. Inspectors check that zones are correctly identified, signed and enforced, and that the survey data justify their extent. On event sites and in plant rooms the same approach marks stage wings, near-array positions or generator enclosures where protectors are required.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Personal hearing protection','Upper exposure action value','LEX,8h (daily noise exposure)','Peak sound pressure level (LCpeak)','Noise risk assessment','Noise mitigation hierarchy']::text[],ARRAY['UNSAFE: Assuming that simply entering a hearing protection zone with any earplug is enough; the protector must be correctly fitted and adequate for the level, or exposure inside the zone can still be hazardous.','Believing the trigger level is the same worldwide; UK zones are set at the upper action values (85 dB(A) LEX or 137 dB(C) peak), while other regimes use different thresholds and wording.','Thinking a zone removes the duty to reduce noise; it marks residual high-exposure areas but does not replace source and engineering controls.','Treating the signed boundary as covering only the marked line rather than the whole area whose exposure exceeds the trigger.']::text[],ARRAY['A factory safety officer marks a stamping-press area as a hearing protection zone after a survey shows daily exposure above the upper action value.','An inspector checks that a plant room''s generator enclosure is signed and enforced as a mandatory ear-protection area.','A stage manager designates the near-line-array wings as a hearing protection zone for crew during a loud touring show.','A shipyard restricts entry to a blasting bay to protected personnel and posts hearing-protection signage at its boundary.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hearing protection zone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ff7d726-1b6b-58aa-a1fc-89531e19a608','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ff7d726-1b6b-58aa-a1fc-89531e19a608') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ff7d726-1b6b-58aa-a1fc-89531e19a608');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eed2d18e-1581-5cfc-bcc3-fd40052e902a','Attenuation derating','The deliberate downward adjustment of a hearing protector''s laboratory-derived attenuation rating (such as NRR, SNR or HML values) to produce a more realistic estimate of the protection actually achieved by workers in the field, where fit, seal, training, motivation, comfort and compatibility with other equipment degrade performance well below optimised laboratory results. Different regimes prescribe different derating conventions. US NIOSH recommends reducing the labelled NRR by 25% for earmuffs, 50% for formable (foam) earplugs and 70% for all other earplugs; US OSHA, when using the NRR with A-weighted measurements, first subtracts 7 dB and commonly halves the remainder to give an estimated real-world attenuation. In the UK, HSE advises accounting for real-world performance by assuming the level at the ear is about 4 dB higher than the standard SNR/HML calculation predicts (equivalently derating the protection by 4 dB), except when assessing peak noise. Derating exists precisely because relying on the full labelled figure over-estimates protection and can leave a wearer exposed above the action or limit value. The exact factor and method depend on the standard and jurisdiction applied.','Lab ratings for earplugs and earmuffs are measured in ideal tests. Real workers rarely get that much protection. Poor fit, movement and glasses all reduce the seal. Derating lowers the rated figure to a realistic value. Different rules use different derating amounts. US NIOSH cuts earmuff ratings by 25 percent. It cuts foam earplug ratings by 50 percent. It cuts other earplug ratings by 70 percent. US OSHA subtracts 7 from the NRR, then often halves it. UK HSE assumes the ear level is about 4 decibels higher. Using the full rating overstates protection and can leave people exposed.','Derating exists to close the well-documented gap between laboratory attenuation and the protection real people obtain, so that protector selection does not leave workers unknowingly exposed above the action or limit value. By building in a margin for imperfect fit and use, it makes the selection duty conservative and defensible: a protector chosen on its full rating might look adequate yet fail in practice, whereas one chosen on a derated figure carries headroom. It also disciplines against over-protection, since applying realistic attenuation avoids the illusion that a very high-rated device is needed.','A safety officer never designs to the raw label figure: they apply the derating convention their jurisdiction specifies — HSE''s 4 dB uplift on the SNR/HML result in the UK, or the NIOSH percentage or OSHA (NRR−7)/2 approach in the US — compute the estimated at-ear level, and confirm it sits safely below the relevant action or limit value before issuing the protector. Fit-testing individual workers gives a measured personal attenuation rating that can replace generic derating. Inspectors expect selection calculations to include derating rather than the optimistic laboratory number.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Personal hearing protection','Noise Reduction Rating (NRR)','Single Number Rating (SNR)','HML method','Personal attenuation rating / fit testing','Upper exposure action value']::text[],ARRAY['UNSAFE: Selecting protection using the full labelled NRR/SNR without derating; real-world attenuation is typically much lower, so the wearer may still be exposed above the limit value.','Assuming one derating factor applies everywhere; NIOSH percentages, the OSHA (NRR−7)/2 approach and the UK HSE 4 dB adjustment differ by regime and method.','Applying the HSE 4 dB real-world derating to peak-noise assessment, where HSE guidance says it should not be used.','Thinking derating can be skipped if a fitted device ''feels sealed''; only individual fit-testing gives a measured personal attenuation rating in place of generic derating.']::text[],ARRAY['A UK safety officer adds 4 dB to the SNR-predicted ear level before confirming a protector keeps a worker under the action value.','A US industrial hygienist derates a foam earplug''s NRR by 50% under NIOSH guidance when selecting protection for a stamping shop.','A compliance auditor rejects a noise assessment that used raw NRR values without any real-world derating.','An occupational-health team introduces individual fit-testing so measured personal attenuation replaces generic derating for high-exposure staff.']::text[],'advanced','OSHA (A-weighted): PA'' = L_A − (NRR − 7)/2 ;  NIOSH: NRR_eff = NRR × (1 − k), k = 0.25/0.50/0.70 ;  HSE: L''_A = L_predicted + 4 dB','Under OSHA''s A-weighted method the estimated protected level equals the A-weighted noise level minus one half of the quantity noise reduction rating minus seven; under NIOSH the effective rating equals the labelled rating multiplied by one minus the derating fraction (0.25 for earmuffs, 0.50 for foam earplugs, 0.70 for other earplugs); under UK HSE the assumed at-ear level equals the standard-method predicted level plus four decibels.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Attenuation derating');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eed2d18e-1581-5cfc-bcc3-fd40052e902a','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eed2d18e-1581-5cfc-bcc3-fd40052e902a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eed2d18e-1581-5cfc-bcc3-fd40052e902a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3d3f3e87-de5f-5f33-83de-131df9bc8d7e','Single Number Rating (SNR)','A single-figure descriptor of a hearing protector''s sound attenuation used in Europe and many other regions, derived under EN ISO 4869-2 from the protector''s measured attenuation across frequency bands and a statistical protection level (typically the mean attenuation minus one standard deviation, giving protection expected for about 84% of users). The SNR is applied by subtracting it directly from the measured C-weighted sound pressure level of the noise to estimate the A-weighted level effectively reaching the ear beneath the protector: estimated at-ear level ≈ LC − SNR. Because it uses the C-weighted input, the SNR provides a quick, spectrum-independent estimate that is convenient when only a C-weighted level is available, but it is less precise than the multi-band HML or octave-band methods for noises with unusual spectra. The SNR is the European counterpart to the US NRR (computed under different rules) and, like all laboratory ratings, must be derated for real-world use. Its calculation basis and the required marking are set by EN ISO 4869-2 and the EN 352 product standards.','SNR means Single Number Rating for hearing protectors. It is one figure that sums up how much a protector cuts noise. It comes from lab tests under the EN ISO 4869-2 method. You use it by subtracting it from a C-weighted noise level. That gives a rough level reaching the ear under the protector. So a higher SNR means more attenuation. The SNR is quick because it ignores the exact noise spectrum. That also makes it less precise than band-by-band methods. It is the European equivalent of the US NRR figure. Like all lab ratings, it must be derated for real use.','The SNR exists to give employers, suppliers and buyers a single, comparable number for choosing hearing protection without needing detailed octave-band calculations. By pairing with an easily measured C-weighted level, it lets a safety officer estimate at-ear exposure in one subtraction and screen candidate protectors quickly. It standardises how European products are rated and marked so devices can be compared on a like-for-like basis, while its built-in statistical protection level and the requirement to derate acknowledge that real users vary and rarely achieve laboratory attenuation.','A safety officer measures the C-weighted noise level at a workstation, subtracts a candidate protector''s SNR (after applying the jurisdiction''s real-world derating), and checks the resulting at-ear A-weighted level against the action or limit value — choosing a device that protects adequately without over-attenuating. Purchasers use SNR to compare products on datasheets and packaging, and it feeds noise risk assessments and protector-selection records. Where the noise spectrum is unusual, the officer switches to the HML or octave-band method for a more accurate estimate.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['HML method','Attenuation derating','Personal hearing protection','Noise Reduction Rating (NRR)','C-weighting','EN ISO 4869-2','EN 352']::text[],ARRAY['Subtracting the SNR from an A-weighted level; the SNR is designed to be subtracted from the C-weighted level to estimate the A-weighted level at the ear.','UNSAFE: Treating the SNR as the protection every wearer gets; it reflects laboratory results for about 84% of users and must be derated for real-world fit and use.','Assuming SNR and NRR are interchangeable numbers; they come from different standards and calculation rules and are not directly equal.','Choosing the highest SNR available regardless of noise level; over-attenuation can impair hearing speech and warnings and is discouraged.']::text[],ARRAY['A safety officer subtracts an earmuff''s SNR from a measured C-weighted level to confirm the at-ear exposure sits below the action value.','A procurement team compares the SNR values printed on competing earplug packs when standardising site protection.','A European distributor marks earmuffs with their SNR and HML values per EN ISO 4869-2 and EN 352.','An assessor switches from SNR to the octave-band method for a low-frequency machine whose spectrum the single number handles poorly.']::text[],'intermediate','L''_A ≈ L_C − SNR','The estimated A-weighted sound pressure level reaching the ear under the protector is approximately the measured C-weighted sound pressure level of the noise minus the protector''s Single Number Rating.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Single Number Rating (SNR)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3d3f3e87-de5f-5f33-83de-131df9bc8d7e','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3d3f3e87-de5f-5f33-83de-131df9bc8d7e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3d3f3e87-de5f-5f33-83de-131df9bc8d7e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e3d7529d-cb42-5860-9e40-83f690490586','HML method','A hearing-protector rating and selection method under EN ISO 4869-2 that describes a protector with three attenuation numbers — H (high-frequency), M (medium-frequency) and L (low-frequency) — so that its performance can be estimated with more spectral sensitivity than a single number allows. The user computes a predicted noise reduction (PNR) from the two of these values and from the difference between the noise''s C-weighted and A-weighted levels (LC − LA), which indicates whether the noise is dominated by low or by high/medium frequencies; the estimated at-ear A-weighted level is then LA minus the PNR (with any jurisdictional real-world derating added). When LC − LA is 2 dB or less (high/mid-frequency-dominated noise) the M and H values govern the estimate; when LC − LA exceeds 2 dB (low-frequency-dominated noise) the M and L values govern it. The HML method therefore gives a better protector choice than the SNR for noises with pronounced low- or high-frequency content, while still needing only broadband C- and A-weighted measurements rather than full octave-band data. Its calculation and marking are defined by EN ISO 4869-2 and the EN 352 product standards.','HML gives a hearing protector three attenuation numbers, not one. H is for high sounds, M for medium, and L for low. You pick which numbers to use from the noise itself. You compare the C-weighted and A-weighted levels of the noise. A small gap means the noise is mostly higher pitched. Then the H and M numbers drive the estimate. A larger gap means the noise is mostly low pitched. Then the M and L numbers drive the estimate. This gives a better match than one single number. It still needs only two simple broadband readings.','The HML method exists to improve protector selection where a single number is too crude — noises heavy in low or high frequencies. By splitting attenuation into three bands and steering the calculation with the LC − LA difference, it captures how a protector performs against the actual character of the noise, reducing the risk of choosing a device that looks adequate on one number yet under- or over-protects in that spectrum. Because it still uses only broadband C- and A-weighted levels, it offers most of the accuracy of octave-band work without the measurement burden, making better selection practical on the job.','A safety officer takes both the C- and A-weighted levels at a workstation, finds LC − LA to judge the noise''s frequency balance, selects the H/M or M/L pair accordingly, computes the predicted noise reduction, subtracts it from LA and applies the local real-world derating to estimate the at-ear level against the action or limit value. The HML values printed on protector packaging let buyers compare devices for low- versus high-frequency environments, and the method feeds protector-selection records for a noise risk assessment where the SNR would be too approximate.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Single Number Rating (SNR)','Attenuation derating','Personal hearing protection','C-weighting','A-weighting','EN ISO 4869-2','Octave-band method']::text[],ARRAY['Using the H and L values directly without the correct case logic; the method always pairs M with H or M with L depending on whether LC − LA is at or below, or above, 2 dB.','Assuming H, M and L are single frequencies; they are broadband high-, medium- and low-frequency attenuation figures derived across bands.','UNSAFE: Applying the resulting figure as guaranteed protection; like all laboratory ratings the HML estimate must be derated for real-world fit and use.','Believing HML needs octave-band data; it deliberately uses only broadband C- and A-weighted levels, which is what makes it practical.']::text[],ARRAY['A safety officer measures a large LC − LA at a low-frequency engine room and uses the M and L values to select suitable earmuffs.','An assessor compares two protectors'' H, M and L figures to choose the better match for a high-frequency grinding process.','A procurement team reads HML values off datasheets when specifying protection for mixed low- and high-frequency plant.','An occupational-health officer documents an HML-based selection calculation, with derating, in a workplace noise risk assessment.']::text[],'advanced','If (L_C − L_A) ≤ 2: PNR = M − (H − M)/4 · (L_C − L_A − 2);  if (L_C − L_A) > 2: PNR = M − (M − L)/8 · (L_C − L_A − 2);  L''_A = L_A − PNR','When the C-weighted level minus the A-weighted level is two decibels or less, the predicted noise reduction equals M minus one quarter of the quantity H minus M multiplied by the quantity C-weighted-minus-A-weighted-minus-two; when that difference exceeds two decibels, the predicted noise reduction equals M minus one eighth of the quantity M minus L multiplied by the same difference-minus-two; the estimated A-weighted level at the ear equals the A-weighted noise level minus the predicted noise reduction.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='HML method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e3d7529d-cb42-5860-9e40-83f690490586','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e3d7529d-cb42-5860-9e40-83f690490586') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e3d7529d-cb42-5860-9e40-83f690490586');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '19e33fc6-d8db-5643-90fc-5f9253e26928','Personal noise dosimeter','A small, body-worn sound-measuring instrument that integrates a worker''s noise exposure over a working period and expresses it as a noise dose (percentage of an allowed daily exposure) and related quantities such as the equivalent continuous level (LAeq), the projected or normalised eight-hour exposure (LEX,8h / TWA) and, on many models, peak level and exposure history. The microphone is worn near the ear (typically on the shoulder), and the device applies a set criterion level, exchange rate and threshold that must be configured to match the regulation in force — for example a 90 dB(A) criterion with a 5 dB exchange rate under US OSHA, or an 85 dB(A) criterion with a 3 dB exchange rate under NIOSH and most European/ISO practice — so the same acoustic environment can read as different doses under different rules. Personal noise dosimeters are specified by IEC 61252 (and ANSI/ASA S1.25 in the US), and must be field-calibrated with an acoustic calibrator before and after use; the exact metrics, permitted settings and calibration requirements depend on the standard and jurisdiction applied.','A personal noise dosimeter is a small meter a worker wears. Its microphone sits near the ear, often on the shoulder. It adds up noise exposure across the whole shift. It reports a dose as a percentage of the daily allowance. It also gives an average level and a projected 8-hour figure. The device must be set to match the local rules. US OSHA uses a 90 decibel base and a 5 decibel exchange rate. NIOSH and most of Europe use 85 decibels and 3 decibels. So the same noise can read as different doses. Dosimeters follow the IEC 61252 standard. You must calibrate them before and after each use.','The dosimeter exists to capture a mobile worker''s true cumulative exposure across a varied, changing shift, which a fixed-position sound level meter cannot do. By following the person and integrating level over time, it turns a fluctuating soundscape into a single dose and eight-hour figure that can be compared directly against action and limit values, providing the evidence base for a hearing-conservation programme, for deciding who needs protection or audiometry, and for demonstrating compliance to an inspector. Its configurable criterion and exchange rate let one instrument serve different legal regimes.','An occupational hygienist fits calibrated dosimeters to a representative sample of workers for a full shift, sets the criterion level, exchange rate and threshold to the governing standard, and reads off each person''s dose and projected LEX,8h to place them relative to the action and limit values. The results drive decisions on engineering controls, hearing-protection selection, zone marking and audiometric surveillance, and the calibrated records support the risk assessment and any enforcement or claim. Pre- and post-use calibrator checks confirm the data are valid.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Dosimetry exchange criterion','LAeq','LEX,8h (daily noise exposure)','Sound level meter (IEC 61672)','Acoustic calibrator (IEC 60942)','Criterion level','Noise dose (%)']::text[],ARRAY['Assuming a dose figure is comparable regardless of settings; the criterion level, exchange rate and threshold must match the regulation, and OSHA and NIOSH settings give different doses for the same noise.','Confusing a personal dosimeter with a fixed sound level meter reading; the dosimeter follows the worker and integrates a full shift, giving personal exposure.','UNSAFE: Reading 100% dose as the safe maximum for everyone; it marks the regulatory limit, above which risk of hearing damage rises, and personal susceptibility varies.','Skipping the pre- and post-shift calibrator check, so drift or a knocked microphone invalidates the exposure data.']::text[],ARRAY['An occupational hygienist clips calibrated dosimeters to sampled workers to measure full-shift doses against the action values.','A festival production safety officer logs a stagehand''s daily exposure with a body-worn dosimeter set to the local exchange rate.','An enforcement inspector reviews dosimetry records, including calibration checks, when assessing a factory''s noise compliance.','A mine safety team compares OSHA- and NIOSH-configured dose readings to understand exposure under stricter criteria.']::text[],'advanced','Dose(%) = 100 · Σ (C_i / T_i) ;  TWA = L_c + q·log2(Dose/100)','Noise dose as a percentage equals one hundred times the sum, over each exposure segment, of the actual time spent at a level divided by the permitted time at that level; the equivalent eight-hour time-weighted average equals the criterion level plus the exchange-rate parameter multiplied by the base-two logarithm of the dose divided by one hundred.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Personal noise dosimeter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '19e33fc6-d8db-5643-90fc-5f9253e26928','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='19e33fc6-d8db-5643-90fc-5f9253e26928') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='19e33fc6-d8db-5643-90fc-5f9253e26928');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a61db1a-9d4e-5e6f-a369-12460ca2c3e4','Dosimetry exchange criterion','The rule — also called the exchange rate, trading ratio or doubling rate — that defines how much a change in sound level trades against allowed exposure time when computing noise dose: it is the increase in level (in decibels) that halves the permitted exposure duration (or, equivalently, that doubles the accumulated dose). The choice of exchange rate reflects an assumption about how the ear accumulates damage. A 3 dB exchange rate embodies the equal-energy principle — equal sound energy gives equal risk — and is used by ISO 1999, EU Directive 2003/10/EC, NIOSH and most of the world; under it, every 3 dB rise halves the safe time. A 5 dB exchange rate, used by US OSHA for its permissible exposure limit, allows longer times at higher levels on the assumption that intermittency and quiet periods give the ear some recovery. Because the exchange rate is built into every dosimeter and exposure calculation, the same noise can yield different doses and time limits under different criteria; the applicable rate depends strictly on the standard and jurisdiction in force.','The exchange criterion links noise level to allowed time. It is the rise in decibels that halves your safe exposure time. It is also called the exchange rate or trading ratio. A 3 decibel rate follows the equal-energy idea. Every 3 decibel rise then cuts the safe time in half. Most of the world and Europe use the 3 decibel rate. US OSHA uses a 5 decibel rate for its legal limit. The 5 decibel rate assumes quiet gaps let the ear recover. The rate is built into every dosimeter calculation. So the same noise gives different limits under different rules.','The exchange criterion exists to convert varying, real-world noise into a single comparable exposure by fixing how level and time trade off. Without an agreed rate there is no consistent way to add up a fluctuating day into a dose or an eight-hour figure, or to set the permitted time at any given level. The rate encodes a policy-and-science judgement about damage accumulation; choosing 3 dB (equal energy) versus 5 dB changes how conservative the assessment is, which is why standards specify it and why dosimeters must be set to the governing value before any dose is trusted.','An occupational hygienist selects the exchange rate mandated by the applicable regulation before measuring — 3 dB under EU/ISO/NIOSH practice, 5 dB for an OSHA permissible-exposure calculation — and configures every dosimeter and calculation to it, because a mis-set rate makes doses non-comparable and can understate risk. The criterion also underlies the exposure-time tables workers rely on (for example, how long is permitted at a given level), the design of administrative time limits, and the interpretation of dose data in compliance decisions and hearing-loss claims.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Personal noise dosimeter','Equal-energy principle','LEX,8h (daily noise exposure)','LAeq','Criterion level','OSHA 29 CFR 1910.95','ISO 1999']::text[],ARRAY['UNSAFE: Assuming the 5 dB OSHA exchange rate is protective everywhere; it permits longer times at high levels than the 3 dB equal-energy rate, so an exposure judged acceptable under 5 dB may exceed safer 3 dB-based limits.','Confusing the exchange rate with the criterion level; the exchange rate is the level change that halves permitted time, while the criterion level is the reference level that defines 100% dose.','Comparing doses measured with different exchange rates as if equal; a 3 dB and a 5 dB dose for the same noise are not directly comparable.','Believing the equal-energy (3 dB) rule is a universal law; the applicable rate is set by the standard and jurisdiction, and OSHA uses 5 dB for its legal limit.']::text[],ARRAY['An occupational hygienist sets dosimeters to a 3 dB exchange rate to assess exposure against the EU upper action value.','A US compliance officer computes an OSHA permissible-exposure dose using the 5 dB exchange rate for a variable-level plant.','An expert in a hearing-loss claim explains why the same shift yields different doses under 3 dB and 5 dB criteria.','A multinational safety team reconciles exposure results from sites using different exchange-rate rules before setting a corporate standard.']::text[],'advanced','T = T_0 / 2^((L − L_0)/q) ;  q = 3 dB (equal energy) or 5 dB (OSHA)','The permitted exposure time equals a reference time divided by two raised to the power of the sound level minus the criterion level, all divided by the exchange rate; the exchange rate q is three decibels under the equal-energy rule used by ISO, the EU and NIOSH, or five decibels under the US OSHA permissible exposure limit.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dosimetry exchange criterion');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a61db1a-9d4e-5e6f-a369-12460ca2c3e4','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a61db1a-9d4e-5e6f-a369-12460ca2c3e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a61db1a-9d4e-5e6f-a369-12460ca2c3e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2f1d68f7-b51e-5f5a-adcc-48b04bb24520','Criterion duration','The reference time interval, denoted Tc and most commonly set at 8 hours, over which continuous exposure to the criterion level produces exactly a 100% noise dose in occupational noise dosimetry. It is one of the three parameters that define a dose scheme, alongside the criterion level (the sound level that yields 100% dose over the criterion duration) and the exchange rate (the decibel change that halves or doubles the permitted time). Under the US OSHA scheme (29 CFR 1910.95), the criterion duration is 8 hours, paired with a 90 dB(A) criterion level and a 5 dB exchange rate; the NIOSH recommended scheme (Publication 98-126) also uses an 8-hour criterion duration but with an 85 dB(A) criterion level and a 3 dB exchange rate. The criterion duration anchors the reference-duration curve from which the permitted time at any given level is computed, and it is the normalising period for the 8-hour time-weighted average (TWA) and the daily noise exposure level (LEX,8h). The exact values that accompany it vary by jurisdiction and standard.','The criterion duration is a fixed reference time. It is almost always eight hours. Someone at the criterion level for that whole time reaches 100% of the daily dose. It is one of three numbers that set a dose rule. The other two are the criterion level and the exchange rate. For example, US OSHA pairs eight hours with 90 decibels. US NIOSH pairs eight hours with 85 decibels. The exact numbers change by country and standard.','It gives a dose-based exposure rule a fixed time anchor, so that exposures at different levels and durations can be combined onto a single 0-100% scale and compared against one daily limit. Without an agreed criterion duration, ''100% dose'', the 8-hour TWA and the daily exposure level would have no common reference period, and partial exposures at fluctuating levels could not be summed. It converts the idea of a safe daily sound budget into a defined, auditable quantity that dosimeters and hearing-conservation programmes can compute and act on.','An occupational-hygiene technician setting up a noise dosimeter selects the measurement standard, which fixes the criterion duration (8 hours), criterion level and exchange rate to match the regulator that will read the result. Those settings determine the reported dose, TWA and projected dose, so choosing OSHA versus NIOSH parameters changes whether a given shift reads as compliant. The technician documents which criterion duration and scheme were used so the numbers are defensible in a compliance report or a hearing-loss claim.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Criterion level','Exchange rate','Noise dose','Projected dose','Time-weighted average (TWA)','Daily noise exposure level (LEX,8h)','Threshold level']::text[],ARRAY['Confusing criterion duration with the exchange rate; the criterion duration is the reference time for 100% dose, while the exchange rate is the decibel step that halves or doubles allowed time.','Assuming the criterion duration is always paired with the same level and exchange rate; OSHA uses 8 h with 90 dB(A) and a 5 dB rate, whereas NIOSH uses 8 h with 85 dB(A) and a 3 dB rate.','UNSAFE: Believing that staying under 100% dose for the criterion duration guarantees no hearing damage; the OSHA scheme in particular still carries measurable risk, which is why NIOSH recommends a lower criterion level.','Thinking the criterion duration means work must last exactly 8 hours; it is a normalising reference, and shorter or longer shifts are converted onto the same 8-hour basis.']::text[],ARRAY['An industrial hygienist configures a dosimeter to OSHA parameters (8-hour criterion duration, 90 dB(A), 5 dB) before a full-shift survey of a factory floor.','A safety officer explains to a manager why the same noisy shift reads as a higher dose under NIOSH''s 8-hour criterion and 3 dB exchange rate.','An enforcement inspector checks that a consultant''s noise report states the criterion duration and scheme used before accepting its TWA figures.']::text[],'advanced','T = Tc · 2^((Lc − L)/q);  100% dose when L = Lc for the whole time Tc','The allowed exposure time at a level equals the criterion duration multiplied by two raised to the criterion level minus the measured level, divided by the exchange rate; a full criterion duration at the criterion level gives one hundred percent dose.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Criterion duration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2f1d68f7-b51e-5f5a-adcc-48b04bb24520','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2f1d68f7-b51e-5f5a-adcc-48b04bb24520') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2f1d68f7-b51e-5f5a-adcc-48b04bb24520');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '52e3ce47-9b36-5132-97ff-01aa7a2b4863','Projected dose','An estimate of the noise dose a worker would accumulate over the full criterion duration (or full work shift), extrapolated from a measurement covering only part of that period. When a dosimeter samples for less than a full shift, the instrument or analyst projects the partial result to the whole reference period, most simply by assuming the exposure measured so far continues unchanged for the remainder. The projected dose therefore forecasts the end-of-shift dose or 8-hour TWA before the shift is complete. Its accuracy depends entirely on how representative the sampled period is: a projection from a quiet break under-estimates, and a projection from an unusually loud task over-estimates. Occupational-hygiene practice and dosimeter standards require the sample to cover a representative portion of the shift, and the reported basis (measured versus projected) to be stated. The reference period, exchange rate and criterion level all follow the chosen scheme (for example OSHA or NIOSH).','A projected dose is a forecast of a full-shift noise dose. It is worked out from a shorter sample. The meter assumes the measured noise keeps going at the same rate. So it predicts the end-of-day dose early. The guess is only as good as the sample. A sample taken during a quiet spell reads too low. A sample during a loud task reads too high. Good practice samples a fair slice of the whole shift. The report must say if a dose is measured or projected.','It lets a hygienist judge likely compliance and act before a full shift has elapsed; for example stopping a task, rotating a worker or issuing hearing protection when the projection shows the daily limit will be exceeded. It also allows valid dose estimates when a full-shift measurement is impractical, provided the sampled period is representative. In effect it turns a partial sample into a forward-looking compliance indicator rather than a purely retrospective one.','A noise dosimeter running mid-shift displays a projected TWA and dose; the technician compares it against the action level and permissible limit to decide whether to intervene now. When writing a survey, the analyst notes that a figure is projected, and from what fraction of the shift, because a projection from a short or unrepresentative sample is weaker evidence than a full-shift measurement. Producers and safety officers use projections to plan job rotation and protector use.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Noise dose','Criterion duration','Time-weighted average (TWA)','Action level','Noise dosimeter','Threshold level','Exchange rate']::text[],ARRAY['UNSAFE: Treating a low projected dose from a short, quiet sample as proof the shift is safe; projecting an unrepresentative period can badly under-estimate real exposure and hearing risk.','Assuming a projected dose is a measured fact; it is an extrapolation whose reliability depends on how typical the sampled period was.','Forgetting that the projection assumes the sampled noise continues unchanged, so a quiet remainder or a loud finale can make the real end-of-shift dose very different.','Confusing projected dose with the accumulated dose already measured at the moment of reading.']::text[],ARRAY['A hygienist watches a dosimeter''s projected TWA climb past the action level two hours into a shift and rotates the worker to a quieter task.','A consultant footnotes a report to show a figure was projected from a 4-hour sample rather than a full 8-hour measurement.','A plant safety officer uses mid-shift projected doses to decide who needs mandatory hearing protectors before overtime is authorised.']::text[],'advanced','D_proj = D_meas × (T_shift / t_sample)   (assuming the sampled exposure rate continues)','The projected dose equals the dose measured so far multiplied by the ratio of the full shift or criterion duration to the length of the sample, assuming the average exposure continues unchanged for the rest of the period.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Projected dose');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '52e3ce47-9b36-5132-97ff-01aa7a2b4863','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='52e3ce47-9b36-5132-97ff-01aa7a2b4863') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='52e3ce47-9b36-5132-97ff-01aa7a2b4863');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c6d32367-bb39-57db-9131-3ffc9a836095','Sound exposure meter','An instrument that measures and accumulates a person''s or a location''s sound exposure, the time integral of frequency-weighted (usually A-weighted) squared sound pressure, over a measurement period, rather than reporting an instantaneous level. Body-worn versions are the personal sound exposure meters (noise dosimeters) specified by IEC 61252, which defines their electroacoustic performance for measuring sound exposure, exposure level and/or noise dose. The primary quantity is sound exposure E, expressed in pascal-squared hours (Pa²·h) or pascal-squared seconds (Pa²·s), from which the instrument derives the equivalent continuous level (LAeq), the 8-hour TWA or LEX,8h, and the percentage dose against a chosen criterion. Because it integrates level over time, it captures the combined effect of loudness and duration that governs hearing risk, including intermittent and moving exposures a fixed meter would miss. The dose scheme it reports against (criterion level, criterion duration, exchange rate, threshold) is user-selected to match the applicable standard.','A sound exposure meter adds up sound energy over time. It does not just show the level right now. It combines how loud the sound is with how long it lasts. Body-worn versions are called noise dosimeters. The standard IEC 61252 sets how they must perform. The meter reports total exposure, an average level, and a dose. Dose is exposure compared with a chosen limit. This matters because both loudness and time harm hearing. The user picks settings to match the local rule.','It exists to quantify hearing-hazardous exposure as a dose, capturing that damage depends on both level and time, for workers who move between noisy areas or whose exposure varies through a shift. A single fixed reading cannot represent such exposure; a worn exposure meter follows the person and sums everything they receive. This underpins hearing-conservation programmes, action-level decisions and legal duties to assess and control noise exposure.','An occupational hygienist clips an IEC 61252 dosimeter near a worker''s ear for a representative shift, then reads the accumulated exposure, LAeq/TWA and dose to compare against the action and limit values in the applicable regulation. The stored profile also shows when the loudest exposures occurred, guiding controls such as enclosures, rotation and protectors. Results feed the noise-exposure record that regulators may inspect.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Noise dosimeter','IEC 61252','Sound exposure (E)','LAeq','Noise dose','Criterion duration','Daily noise exposure level (LEX,8h)']::text[],ARRAY['Confusing a sound exposure meter, which integrates exposure over time, with a sound level meter, which reports levels; dosimeters answer ''how much total dose'', meters answer ''how loud now''.','UNSAFE: Assuming a moderate instantaneous reading means low risk; it is the accumulated exposure (level times time) that determines hearing damage, which is exactly what the exposure meter captures.','Forgetting that the reported dose depends on the selected scheme (criterion level, exchange rate, threshold), so the same exposure can read differently under OSHA versus NIOSH settings.','Believing microphone placement and calibration do not matter for a worn meter; poor placement or a missed field check invalidates the exposure result.']::text[],ARRAY['A hygienist fits IEC 61252 dosimeters to a sample of forklift drivers to capture their varying daily noise exposure.','A festival stagehand wears a personal sound exposure meter across a build-and-show day to log cumulative crew exposure.','An enforcement officer reviews dosimeter exposure records to check an employer assessed noise as legally required.']::text[],'intermediate','E = ∫₀ᵀ p_A²(t) dt   (units Pa²·s or Pa²·h)','Sound exposure equals the integral over the measurement time of the A-weighted sound pressure squared, giving units of pascal-squared seconds or pascal-squared hours.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound exposure meter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c6d32367-bb39-57db-9131-3ffc9a836095','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c6d32367-bb39-57db-9131-3ffc9a836095') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c6d32367-bb39-57db-9131-3ffc9a836095');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'daf020c8-4956-5f50-96ab-93300956de41','Class 1 sound level meter','A sound level meter, with its associated microphone, that meets the tightest performance class of IEC 61672-1, the international standard for sound level meters. Class 1 (formerly ''Type 1'' / ''precision'' under the earlier IEC 60651/60804 and ANSI S1.4) specifies the narrowest tolerance limits and the widest guaranteed frequency range of the two classes, so its readings are more accurate, especially at low and high frequencies. For example, at the 1 kHz reference frequency the tolerance is about ±1.1 dB, and the further requirements tighten across the band relative to Class 2. Because of this accuracy, many national and international regimes require Class 1 instruments for enforcement measurements, consultant environmental reports and standardised methods; for instance ISO 20906 for unattended aircraft-noise monitoring requires Class 1 performance. IEC 61672 also defines the periodic and pattern-evaluation tests that verify continued conformance. Whether Class 1 is mandatory, and for which task, is set by the applicable regulation, standard or method, not by the meter alone.','A Class 1 sound level meter is a top-accuracy meter. It meets the strictest grade in the standard IEC 61672-1. It has tighter error limits than a Class 2 meter. It stays accurate across a wider range of pitches. At 1000 hertz its allowed error is about one decibel. Because it is precise, rules often require it for legal work. Enforcement and consultant reports commonly ask for Class 1. Whether it is required depends on the local rule or method. The meter class alone does not set the law.','It provides the accuracy and traceable performance that legal and standardised acoustic work demands, so a level reported at a property boundary or in a compliance test can withstand technical and legal challenge. By fixing tolerances and test methods, IEC 61672-1 makes Class 1 results comparable between operators, instruments and countries, which matters when a number decides consent conditions, penalties or planning outcomes.','An acoustic consultant chooses a Class 1 meter, with a valid calibration certificate and a field calibration check, for an environmental noise survey whose results will support a planning objection or an enforcement notice, because the authority or method specifies Class 1. The tighter frequency response also matters where low-frequency content such as entertainment bass must be measured accurately.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['IEC 61672-1','Class 2 sound level meter','Field calibration check','Traceable calibration','Acoustic calibrator (IEC 60942)','Frequency weighting (A/C/Z)','ISO 1996-2']::text[],ARRAY['Assuming a Class 1 meter is automatically accurate regardless of upkeep; it must hold a valid traceable calibration and pass field checks, or its class means little.','Thinking Class 1 versus Class 2 differ only by price; the real difference is tolerance limits and guaranteed frequency range under IEC 61672-1.','Believing Class 1 is legally required everywhere; the requirement depends on the specific regulation, standard or method, and some tasks accept Class 2.','Confusing the old ''Type 1'' (IEC 60651) label with current ''Class 1'' (IEC 61672-1) as if they were identical performance grades.']::text[],ARRAY['A consultant deploys a Class 1 meter at the nearest dwelling to a proposed venue because the planning authority''s method requires it.','An enforcement officer measures a nightclub''s boundary noise with a Class 1 instrument so the reading holds up if the case goes to appeal.','An aircraft-noise monitoring terminal uses Class 1 performance to meet ISO 20906 for unattended long-term measurement.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Class 1 sound level meter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'daf020c8-4956-5f50-96ab-93300956de41','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='daf020c8-4956-5f50-96ab-93300956de41') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='daf020c8-4956-5f50-96ab-93300956de41');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b972bb2d-794c-535c-9568-68e30f6b3368','Class 2 sound level meter','A sound level meter meeting the second, more relaxed performance class of IEC 61672-1, with wider tolerance limits and a narrower guaranteed frequency range than Class 1 (formerly ''Type 2'' / ''general purpose''). For example, at 1 kHz the tolerance is about ±1.4 dB, with progressively larger permitted deviations toward the frequency extremes than Class 1 allows. Class 2 instruments are accurate enough for many occupational and screening tasks and are explicitly accepted by some regimes: for instance UK guidance under the Control of Noise at Work Regulations 2005 indicates that instruments should meet at least Class 2 of BS EN 61672-1. They are typically less suitable where high accuracy at low or high frequencies, or defensible enforcement precision, is needed, in which case Class 1 is specified. As always, whether Class 2 suffices for a given measurement is determined by the controlling standard, regulation or method.','A Class 2 sound level meter is a general-purpose meter. It meets the second grade in IEC 61672-1. Its error limits are wider than a Class 1 meter. It covers a slightly narrower range of pitches. At 1000 hertz its allowed error is about 1.4 decibels. It is fine for many workplace and screening checks. For example, UK noise-at-work guidance accepts at least Class 2. It is often not enough for strict legal cases. The local rule or method decides what grade is needed.','It offers a lower-cost, adequately accurate option for tasks that do not need Class 1 precision, such as routine occupational noise checks, initial screening to decide whether a fuller survey is needed, and internal monitoring. Defining a formal second class lets standards and regulators set a clear minimum instrument grade without over-specifying, matching measurement accuracy to the stakes of the decision.','A workplace safety officer uses a Class 2 meter to screen production areas and identify where noise may exceed action values, then commissions a Class 1 survey or dosimetry where a formal or contested figure is required. Buyers check that even a screening meter genuinely meets Class 2 of the current IEC 61672-1, not just an old Type 2 label, and keep it calibrated.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['IEC 61672-1','Class 1 sound level meter','Field calibration check','Traceable calibration','Action level','Control of Noise at Work Regulations 2005','Screening survey']::text[],ARRAY['Assuming Class 2 is never acceptable for compliance; several regimes, such as UK noise-at-work guidance, accept at least Class 2 for workplace assessment.','Believing Class 2 is simply a ''worse'' meter; it is a defined grade with stated tolerances, suitable for many tasks but not the tightest enforcement work.','Using a Class 2 meter for low-frequency-critical or legally contested measurements where the method requires Class 1 accuracy.','Treating an uncalibrated Class 2 meter as reliable; without a traceable calibration and field check its class specification is not assured.']::text[],ARRAY['A safety officer screens a workshop with a Class 2 meter to flag areas that then get a full Class 1 dosimetry survey.','A small venue buys a Class 2 meter for routine self-checks against its licence''s indicative level.','An inspector accepts Class 2 data for an initial workplace noise assessment but requires Class 1 for a disputed boundary reading.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Class 2 sound level meter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b972bb2d-794c-535c-9568-68e30f6b3368','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b972bb2d-794c-535c-9568-68e30f6b3368') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b972bb2d-794c-535c-9568-68e30f6b3368');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e5a573ef-202d-53a4-abd5-dfe43264ecf5','Field calibration check','A quick on-site verification that a sound level meter or dosimeter is reading correctly, performed immediately before and after a measurement by applying a known reference sound level to the microphone with an acoustic calibrator (a device conforming to IEC 60942). The calibrator produces a stable tone, commonly 94 dB (1 Pa) or 114 dB at 1 kHz, and the operator confirms or adjusts the instrument to read that value. The purpose is to detect drift, damage or set-up error on the day, not to replace formal laboratory calibration. Standard practice is to check both before and after: if the post-measurement check has drifted beyond a small tolerance (occupational guidance commonly treats about 0.5 dB as the point at which results may be unreliable and resampling is advised), the data may be invalid. A field calibration check is a functional verification against a portable reference; it does not by itself establish metrological traceability, which comes from periodic laboratory calibration of both the meter and the calibrator.','A field calibration check tests a meter on site. You do it just before and just after measuring. You put a small device called a calibrator on the microphone. It makes a steady, known tone, often 94 or 114 decibels. You check the meter shows that value. This catches drift, damage, or setup mistakes on the day. If the after-check has drifted too far, the data may be void. Occupational guidance often flags about half a decibel as too much. It does not replace full lab calibration.','It guards the integrity of a measurement by confirming, at the time and place of use, that the instrument chain is reading true, catching a flat battery, a knocked microphone, moisture or a wrong setting before they corrupt a result. The before-and-after bracket also shows the meter stayed within tolerance for the whole measurement, which is what makes the data defensible in occupational and environmental reporting.','Before a noise survey the technician fits the calibrator, checks and if needed adjusts the meter to the reference level, records the reading, takes the measurements, then repeats the check at the end. Both readings and the calibrator''s serial number and certificate are logged in the report; a post-check drift beyond tolerance triggers resampling. Enforcement and consultancy methods routinely require this bracketing for the data to be accepted.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Acoustic calibrator (IEC 60942)','Traceable calibration','Class 1 sound level meter','Class 2 sound level meter','IEC 61672-1','Measurement uncertainty','Sound level meter drift']::text[],ARRAY['Thinking a field check replaces laboratory calibration; it only verifies the instrument on the day and does not establish traceability to national standards.','Checking only before the measurement; without an after-check you cannot show the meter held tolerance throughout.','Ignoring a small post-check drift; occupational guidance treats around 0.5 dB drift as grounds to resample, because it can shift a pass/fail decision.','Assuming the calibrator itself never needs calibration; the IEC 60942 calibrator must also hold its own traceable calibration.']::text[],ARRAY['A consultant brackets an environmental survey with a 94 dB calibrator check at the start and finish before submitting the data.','A hygienist finds a 0.7 dB drift on the post-shift dosimeter check and repeats the measurement the next day.','An enforcement officer''s report is challenged because no post-measurement calibration check was recorded.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Field calibration check');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e5a573ef-202d-53a4-abd5-dfe43264ecf5','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e5a573ef-202d-53a4-abd5-dfe43264ecf5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e5a573ef-202d-53a4-abd5-dfe43264ecf5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '21a9399c-6581-5a60-a086-e940cf0820d4','Traceable calibration','Calibration whose result is linked, through an unbroken and documented chain of comparisons each with stated measurement uncertainty, to recognised national or international measurement standards, ultimately the SI units realised by national metrology institutes (for example NIST, NPL, PTB). This property, termed metrological traceability in the International Vocabulary of Metrology (VIM, JCGM 200), is what lets a reading from one instrument be trusted and compared against readings from others worldwide. For acoustic instruments it means a sound level meter, its calibrator and reference microphone are periodically calibrated by an accredited laboratory (typically to ISO/IEC 17025), whose own references trace back to national standards, with certificates recording the values, uncertainties and the traceability chain. Traceability underpins the legal defensibility of a measurement: an enforcement or consultant result is only as sound as the traceable calibration of the equipment that produced it. It is distinct from an on-site field calibration check, which verifies function but does not itself create the traceable chain.','Traceable calibration ties a reading to official standards. The tie is an unbroken chain of checks. Each step has a known error range. The chain ends at national standards for the units. Big national labs keep those standards. This lets readings be trusted and compared. For sound gear, an approved lab checks the meter. Its own references trace back the same way. A field check on site is not the same. This is what makes a legal reading hold up.','It provides the trust and comparability that measurement-based regulation depends on. Because a compliance decision may impose penalties or planning conditions, the number must be shown to derive from instruments anchored to recognised standards, not just a manufacturer''s claim. Traceability, with its documented uncertainties, is the mechanism that makes acoustic measurements consistent between laboratories, operators and jurisdictions and able to survive legal scrutiny.','A consultant or enforcement body maintains a schedule sending meters, calibrators and microphones to an ISO/IEC 17025-accredited laboratory at set intervals, and keeps the certificates on file to accompany survey reports. When a result is challenged, the traceable calibration certificates, plus the day''s field check, evidence that the equipment was fit and standards-anchored. Procurement and quality systems specify traceable calibration as a requirement.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Metrological traceability','ISO/IEC 17025','Field calibration check','Acoustic calibrator (IEC 60942)','Class 1 sound level meter','Measurement uncertainty','National metrology institute']::text[],ARRAY['Equating a field calibration check with traceable calibration; the field check verifies the meter on the day but does not create the traceable chain to national standards.','Assuming any calibration certificate proves traceability; it must document an unbroken chain with stated uncertainties, typically from an accredited (ISO/IEC 17025) laboratory.','Believing a meter stays traceably calibrated indefinitely; traceability requires periodic recalibration within the stated interval.','Thinking traceability is bureaucratic overhead rather than the basis on which a contested measurement stands or falls.']::text[],ARRAY['A consultancy files ISO/IEC 17025 calibration certificates for its meter, microphone and calibrator alongside a noise report submitted to a council.','An enforcement case turns on whether the measuring equipment held a current traceable calibration at the time of the reading.','A laboratory manager schedules annual traceable recalibration of the fleet so no instrument drifts out of certification.']::text[],'advanced',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Traceable calibration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '21a9399c-6581-5a60-a086-e940cf0820d4','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='21a9399c-6581-5a60-a086-e940cf0820d4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='21a9399c-6581-5a60-a086-e940cf0820d4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e8da735f-4cbd-5e81-88c3-c205ac40f285','Compliance margin','The difference between a measured or predicted noise level (or dose) and the applicable limit, expressed in the same units, typically decibels or percentage points of dose, indicating how far an exposure or emission sits below or above the threshold. A positive margin (level below limit) shows headroom; a negative margin (level above limit) is an exceedance. Because acoustic limits are set by a specific standard, permit, licence condition or jurisdiction, and vary with time of day, receiver location, metric and averaging method, the margin is only meaningful relative to a named limit and measurement method. In rigorous assessment the margin is read together with the measurement uncertainty: a nominal 2 dB margin may not demonstrate compliance if the expanded uncertainty is comparable in size. Compliance margins are used both retrospectively (was the limit met?) and predictively (how much control is needed to meet it?).','The compliance margin is the gap to the limit. It is the measured or predicted level minus the limit. A level below the limit gives a safe margin. A level above the limit is an exceedance. The margin only means something against a named limit. Limits change with time of day, place, and method. A small margin may not prove compliance on its own. You must also weigh the measurement uncertainty. Engineers use the margin to size noise controls. They also use it to check if a limit was met.','It turns a raw level into a decision: whether an exposure or emission passes, and by how much. As a design quantity it tells engineers how much attenuation a barrier, enclosure or limiter setting must add to reach the target with confidence. As an assessment quantity it summarises the result of a compliance test against a specific limit, and, paired with uncertainty, governs whether a pass can be claimed.','An acoustic consultant designing to a planning noise limit sizes mitigation to leave a positive margin that covers uncertainty and future variation, rather than aiming exactly at the limit. On enforcement, an officer reports the measured level, the applicable limit and the margin, noting whether uncertainty is large enough to affect the conclusion. A venue''s sound engineer keeps house levels a margin below the licensed limit to avoid breaching it on peaks.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Uncertainty allowance','Measurement uncertainty','Noise limit','Exceedance percentile','LAeq','Noise dose','Sliding-window limit']::text[],ARRAY['Reading a small positive margin as certain compliance while ignoring a measurement uncertainty of similar size.','Assuming the margin is universal; it is only defined against a specific limit, receiver, time period and measurement method.','Confusing a margin in dose (percentage points) with a margin in level (decibels); the two scales are not interchangeable.','Designing to hit the limit exactly, leaving no headroom for uncertainty, weather or level variation, so real operation breaches it.']::text[],ARRAY['A consultant designs a barrier to leave a comfortable margin below the night-time limit at the nearest bedroom window.','An enforcement officer records a 1 dB exceedance but notes the measurement uncertainty before deciding on action.','A venue engineer runs the show a few decibels under the licensed LAeq limit to keep a safety margin on loud numbers.']::text[],'intermediate','M = L_limit − L_measured   (positive = headroom below the limit; negative = exceedance)','The compliance margin equals the applicable limit minus the measured or predicted level in the same units; a positive value is headroom below the limit and a negative value is an exceedance.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compliance margin');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e8da735f-4cbd-5e81-88c3-c205ac40f285','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e8da735f-4cbd-5e81-88c3-c205ac40f285') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e8da735f-4cbd-5e81-88c3-c205ac40f285');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1707608a-2096-5f5f-b301-99999b348324','Uncertainty allowance','The explicit handling of measurement uncertainty when deciding whether a noise level or dose complies with a limit; that is, how the expanded uncertainty of a result is factored into the pass/fail decision rather than comparing a bare number to the limit. Every acoustic measurement or prediction has an uncertainty, conventionally reported as an expanded uncertainty U = k·u_c with a coverage factor k (commonly k = 2, for roughly 95% confidence) following the GUM/JCGM 100 approach; standards such as ISO 1996-2 require this uncertainty to be estimated and stated. How it is applied to compliance is a policy choice defined by the regime: some compare the measured value directly, some require the measured value less its uncertainty to still exceed the limit before an exceedance is proven ''beyond reasonable doubt'', and some give the operator the benefit of the doubt. The size of the allowance, and who carries the doubt, therefore depend on the controlling standard, regulator or method; it is not a single fixed figure.','Every noise reading has some doubt in it. This is called measurement uncertainty. The uncertainty allowance is how you handle it. You handle it when you judge compliance. Results come as a value plus or minus a range. That range is the expanded uncertainty. It usually covers about 95% of cases. Standards like ISO 1996-2 ask you to state it. Some rules add the range before calling a breach. Some subtract it and favour the operator.','It makes compliance decisions honest and defensible by acknowledging that no measurement is exact. Deciding in advance how uncertainty is treated prevents disputes where one party quotes the bare figure and another the error bars, and it protects against both false accusations of breach and false claims of compliance. In enforcement it often embodies a ''beyond reasonable doubt'' logic; in design it drives building in headroom.','A consultant states the expanded uncertainty, with its coverage factor, alongside each result and applies the regulator''s decision rule; for example only asserting an exceedance where the measured level minus its uncertainty still exceeds the limit. Enforcement bodies write the uncertainty-handling rule into their methods so results are treated consistently. Designers add an uncertainty allowance to targets so the finished project still complies once real-world spread is included.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Measurement uncertainty','Compliance margin','ISO 1996-2','Expanded uncertainty (k=2)','GUM / JCGM 100','Noise limit','Class 1 sound level meter']::text[],ARRAY['Comparing a bare measured value to the limit and ignoring uncertainty, then over-claiming either compliance or breach.','Assuming the uncertainty allowance is a single universal number; the coverage factor and decision rule depend on the standard and regulator.','Confusing expanded uncertainty (U = k·u_c) with the instrument''s tolerance alone; uncertainty also includes source, weather, position and repeatability effects.','Treating a result within the uncertainty band of the limit as a definite pass or a definite fail, when it is genuinely inconclusive.']::text[],ARRAY['A consultant declines to call a 0.5 dB overshoot an exceedance because it sits inside the stated measurement uncertainty.','A regulator''s method requires the measured level minus uncertainty to exceed the limit before enforcement, protecting operators from marginal calls.','A designer adds a 3 dB uncertainty allowance to the target so the built scheme still meets the limit in practice.']::text[],'advanced','U = k · u_c  (commonly k = 2 ≈ 95%);  exceedance proven when L_meas − U > L_limit','The expanded uncertainty equals the coverage factor times the combined standard uncertainty, with the factor commonly two for about ninety-five percent confidence; a strict rule proves an exceedance only when the measured level minus that uncertainty still exceeds the limit.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Uncertainty allowance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1707608a-2096-5f5f-b301-99999b348324','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1707608a-2096-5f5f-b301-99999b348324') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1707608a-2096-5f5f-b301-99999b348324');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'db64928d-4328-5bba-9ad4-f3a834269538','Exceedance percentile','A statistical descriptor of a fluctuating noise level giving the level exceeded for a stated percentage of the measurement period, written LN (or LAN,T for an A-weighted level over period T). By convention LN is the level exceeded for N% of the time, so a high-N percentile describes the quieter background and a low-N percentile describes the louder, less frequent events: L90 (exceeded 90% of the time) is widely taken as the background or residual level, L10 (exceeded 10% of the time) captures intrusive peaks, and L50 is the median. These percentiles are central to environmental noise assessment; for example BS 4142 uses the background level (typically an LA90) as the baseline against which an industrial or commercial sound''s rating level is compared, and traffic-noise indices have historically used L10. The exact percentile, weighting, time base and application are set by the relevant standard or method; ''exceedance percentile'' can also refer more loosely to the proportion of intervals in which a limit was exceeded.','Real noise goes up and down all the time. An exceedance percentile sums this up in one number. It is the level passed for a set share of the time. It is written as ''L'' with a number, like L90. L90 is exceeded 90% of the time. That high percentage marks the quiet background, so L90 is a low sound level. L10 is exceeded only 10% of the time. That small percentage captures the loud peaks. Standards like BS 4142 use the background L90 as a baseline.','It compresses a varying noise history into a few meaningful numbers, so that background, typical and intrusive conditions can each be quantified and compared. Regulators need the background level to judge how much a new source stands out, and the peak percentiles to characterise disturbance; a single average like LAeq alone hides this structure. Percentiles thus let assessments separate the steady ambience from the events that actually annoy or breach a condition.','An acoustic consultant running a BS 4142 assessment measures the LA90 background over representative periods, then compares the source''s rating level against it to judge likely adverse impact. In enforcement or complaint work, percentiles distinguish a genuinely raised background from occasional peaks. Long-term monitoring dashboards report LN values so managers can see both baseline and peak behaviour at a receiver.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['LA90 / background level','L10','LAeq','BS 4142','Statistical noise level (LN)','Rating level','Compliance margin']::text[],ARRAY['Reading LN as the level reached for N% of the time; it is the level exceeded for N% of the time, so L90 is a low (background) level, not a high one.','Assuming LAeq and a percentile describe the same thing; LAeq is an energy average, while percentiles describe the distribution of levels.','Using the wrong percentile for the task, for example quoting L10 where a method calls for the L90 background.','Ignoring the time base and weighting; an LN value is only comparable when the period, weighting and method match.']::text[],ARRAY['A consultant measures the LA90 background before assessing a new plant''s rating level under BS 4142.','An environmental-health officer uses L10 and L90 to separate steady traffic hum from intermittent industrial peaks in a complaint.','A monitoring station reports nightly LN percentiles so a port operator can watch both background and peak trends.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Exceedance percentile');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'db64928d-4328-5bba-9ad4-f3a834269538','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='db64928d-4328-5bba-9ad4-f3a834269538') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='db64928d-4328-5bba-9ad4-f3a834269538');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4fbc4300-53c8-5ab4-a2ec-2781fee2fedd','Rolling LAeq','An A-weighted equivalent continuous sound level (LAeq) computed over a moving time window that advances continuously, so at each instant the reported value is the LAeq of the most recent window (for example the last 15 minutes or the last hour) rather than of a fixed clock period. As time steps forward the oldest data drop out and the newest data enter, giving a continuously updated running average. It is used in live-event and continuous environmental monitoring because it shows, at any moment, whether the running average is approaching or breaching a windowed limit, letting operators react before a fixed period closes. The window length, frequency weighting and limit come from the applicable code, licence or method (for example event codes that cap a 15-minute LAeq at the audience or a facade). Because LAeq is energy-based, a brief loud passage raises the rolling value for as long as it stays inside the window and then falls away as it exits.','LAeq is the steady level with the same energy as changing sound. A rolling LAeq works it out over a moving time window. The window might be the last 15 minutes or the last hour. It updates all the time as new sound comes in. Old data drop off the back of the window. So you always see the current running average. This helps engineers act before a limit is reached. A loud passage lifts the value while it stays in the window. Then the value falls as that passage ages out.','It gives real-time control of a time-averaged limit. A fixed 15-minute average is only known when the 15 minutes end, too late to prevent a breach; a rolling LAeq exposes the trend continuously, so a sound engineer or noise officer can pull the level down before the window average crosses the line. It converts a retrospective compliance metric into a live operational one.','At a concert, a monitoring system displays the rolling 15-minute LAeq against the licensed limit so front-of-house can trim level as the running average climbs. Noise-management plans specify the window and limit, and the logged rolling trace becomes evidence of how the show was controlled. In environmental monitoring, a rolling LAeq flags when a site is trending toward an hourly limit.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['LAeq','Sliding-window limit','Fixed-interval limit','Music noise level (MNL)','DIN 15905-5','Noise-management plan','Front-of-house mixing position']::text[],ARRAY['Thinking a rolling LAeq resets like a fixed period; it never resets, it continuously drops old data and adds new, so it lags loud events by the window length.','Assuming the instantaneous SPL and the rolling LAeq should match; the rolling value is an average over the window, so it changes more slowly.','UNSAFE: Treating a comfortable rolling average as proof of safe exposure while ignoring short peaks; energy averaging can mask brief impulses that still risk hearing damage.','Believing the window length is universal; it is set by the code or licence (for example 15 minutes in some event codes) and changes the reading.']::text[],ARRAY['A front-of-house engineer watches the rolling 15-minute LAeq creep toward the licence limit and eases the master level.','A festival noise officer logs the rolling LAeq trace at the nearest houses as the record of control.','An environmental analyst uses a rolling hourly LAeq to warn a plant before it trends into an exceedance.']::text[],'advanced','L_Aeq,T(t) = 10·log10[ (1/T) ∫_{t−T}^{t} (p_A²(τ)/p0²) dτ ],  p0 = 20 µPa','The rolling A-weighted equivalent level at a given moment equals ten times the base-ten logarithm of the time average, over the most recent window of length T, of the squared A-weighted sound pressure divided by the squared reference pressure of twenty micropascals.','fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rolling LAeq');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4fbc4300-53c8-5ab4-a2ec-2781fee2fedd','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4fbc4300-53c8-5ab4-a2ec-2781fee2fedd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4fbc4300-53c8-5ab4-a2ec-2781fee2fedd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8e14fa8b-e958-5c23-a2b5-a982e3089840','Sliding-window limit','A noise limit assessed over every possible rolling time window of a given length, rather than only over fixed, pre-set clock intervals, so the limit must be met continuously no matter where within the timeline the window falls. If the limit is, say, an LAeq over any 15-minute window, then the running (rolling) average of any 15 consecutive minutes must stay within the value; there is no ''reset'' at the top of each quarter-hour. This is stricter than a fixed-interval assessment because it removes the possibility of concentrating loud content across the boundary between two fixed periods to keep each period''s average down. Sliding-window (rolling) assessment is favoured where continuous protection matters, such as event and community noise control, and is typically paired with rolling-LAeq monitoring. The window length, metric and value are defined by the applicable licence, code or standard.','A sliding-window limit applies to every rolling time window. The window might be any 15 minutes long. The running average of any such window must stay legal. It does not reset at fixed clock times. This is stricter than checking only fixed periods. You cannot dodge it by straddling the gap between two periods. It gives steady, continuous protection. It is common in event and community noise rules. The window length and value come from the local code.','It closes a loophole in fixed-interval limits: because a fixed scheme only averages within set boundaries, an operator could push high levels across a boundary so that no single fixed period breaches while the real, continuous exposure is higher. Requiring compliance in every rolling window means the limit protects listeners and neighbours at all times, not just on the regulator''s clock. It is chosen when continuous, boundary-independent control is the policy goal.','A licensing authority that writes a sliding-window limit expects the venue''s monitoring to compute rolling LAeq continuously and keep every window compliant, so the sound engineer must manage level so no rolling window exceeds the value. Compliance officers reviewing logs check the worst rolling window, not just fixed quarter-hours. Producers plan dynamics so loud finales do not push any rolling window over.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Rolling LAeq','Fixed-interval limit','LAeq','Music noise level (MNL)','Noise-management plan','Compliance margin','Curfew / restricted hours']::text[],ARRAY['Assuming it works like a fixed period with resets; a sliding-window limit is tested on every rolling window, with no reset points.','Thinking loud content can be ''hidden'' across a period boundary; sliding-window assessment specifically catches boundary-straddling peaks.','Believing sliding-window and fixed-interval limits give the same result; for the same numeric value the sliding scheme is stricter.','Ignoring the defined window length; the same policy is much tighter with a short window than a long one.']::text[],ARRAY['A council sets a sliding-window LAeq condition so a venue cannot exploit gaps between fixed quarter-hour periods.','A compliance officer examines the worst rolling 15-minute window in the logs, not just the clock periods.','A tour''s system engineer configures monitoring to alarm on any rolling window nearing the sliding-window limit.']::text[],'advanced',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sliding-window limit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8e14fa8b-e958-5c23-a2b5-a982e3089840','fe939357-1f13-4421-b331-61ce91d66150',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8e14fa8b-e958-5c23-a2b5-a982e3089840') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8e14fa8b-e958-5c23-a2b5-a982e3089840');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fa6c1b74-cb35-5768-9ab8-855c057a9339','Fixed-interval limit','A noise limit assessed over predefined, non-overlapping clock periods, for example each successive 15-minute or 1-hour block, or a defined daytime/night-time period, where the metric (commonly LAeq) is computed separately within each fixed interval and compared to the limit. Assessment ''resets'' at the end of each interval and begins afresh for the next. Fixed-interval limits are simple to specify, monitor and enforce, and align naturally with regulatory reference periods such as the day, evening and night periods used in environmental noise indices. Their weakness is that they only constrain the average within each set boundary: loud content spread across the join between two intervals can keep both intervals'' averages below the limit while continuous exposure is higher, which is why some regimes prefer sliding-window assessment. The interval length, metric, weighting and value are all defined by the applicable regulation, licence or standard, and vary by jurisdiction and time of day.','A fixed-interval limit is checked over set clock periods. Each period might be 15 minutes or one hour. The level is worked out for each period on its own. The check resets when each period ends. This is simple to run and to enforce. It fits normal day, evening, and night periods. But it only controls the average inside each block. Loud sound split across a boundary can slip through. That is why some rules use sliding windows instead.','It provides a clear, easily administered way to set and check noise limits against standard reference periods, which is why it is the traditional form in much environmental and licensing law. Fixing the intervals makes results reproducible and enforcement straightforward, and matches the day/evening/night structure of indices like Lden. Understanding its boundary weakness is what motivates the stricter sliding-window alternative.','A regulator writes a licence condition as an LAeq not to be exceeded in each fixed period; the venue and enforcement officer both compute per-period averages from the logs and compare to the limit. Consultants report compliance interval by interval. Where the boundary loophole matters, an authority may switch to or add a sliding-window condition.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Sliding-window limit','Rolling LAeq','LAeq','Lden','Day-evening-night periods','Noise limit','Compliance margin']::text[],ARRAY['Assuming a fixed-interval pass means the limit was met at all times; it only means each defined period''s average complied.','Overlooking that loud content across a period boundary can keep both intervals compliant while real exposure is higher.','Confusing fixed-interval with sliding-window assessment; only the sliding scheme tests every rolling window.','Ignoring that the interval length and reference period are set by the regulation and change the result.']::text[],ARRAY['A licence caps each 15-minute LAeq at a residential facade, and the officer checks the logs period by period.','An environmental report tabulates day, evening and night LAeq against fixed-period limits for a Lden assessment.','A council upgrades a venue condition from fixed intervals to a sliding window after boundary-straddling complaints.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fixed-interval limit');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fa6c1b74-cb35-5768-9ab8-855c057a9339','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fa6c1b74-cb35-5768-9ab8-855c057a9339') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fa6c1b74-cb35-5768-9ab8-855c057a9339');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f07fde14-4b79-58b3-9ccd-ec0036a49b09','Noise log','A noise log is the running documentary record kept during a noise-generating activity or event, in which the responsible party enters measurement results, operating conditions, times, weather and wind, monitoring positions, complaints received, and actions taken. It is the primary evidence trail used to demonstrate compliance with permit, licence, or noise-management-plan conditions and to reconstruct what happened at a given moment if a dispute arises. Entries typically pair each logged sound level (for example an off-site music noise level in dB LAeq over a stated interval) with the position and method used, so the reading is interpretable later. What must be logged, how often, and how long it is retained vary by jurisdiction, permit, venue licence, and the controlling code or standard; for example, guidance from Manchester City Council for open-air events advises keeping monitoring notes for six months in case a responsible authority requests them.','A noise log is a written record kept while noise is being made. You write down the sound readings you take. You also note the time, place, and weather. You record any complaints and what you did about them. It shows you followed the rules in your permit or plan. If someone disputes an event later, the log is your proof. What you must log depends on the local rules. How long you keep it also varies by place.','It creates a defensible, time-stamped evidence trail that links measured levels to operating conditions, so compliance can be shown and exceedances explained. It exists because memory and single snapshots are not enough to prove what happened across a whole event or shift.','A monitoring technician records each reading, its position, the time, and the wind on a log sheet or app through the show, and notes any complaint and the response. A compliance officer or council later reviews the log to confirm conditions were met or to investigate a breach.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Noise management plan','Corrective action log','Complaint trigger level','Off-site noise monitoring','Music noise level (MNL)','Exceedance event']::text[],ARRAY['Thinking the log only needs the sound numbers — undocumented time, position, and method make a reading hard to defend.','Assuming a log can be filled in afterwards from memory — regulators expect contemporaneous, time-stamped entries.','Believing any level of detail satisfies every jurisdiction — retention periods and required contents differ by permit and code.']::text[],ARRAY['A festival monitoring team logs 15-minute off-site readings, wind direction, and each residential complaint through the night.','A council environmental health officer requests an event''s noise log weeks later to verify licence conditions were met.','A construction site keeps a daily log of boundary noise levels and plant in use to answer future complaints.']::text[],'beginner',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise log');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f07fde14-4b79-58b3-9ccd-ec0036a49b09','fe939357-1f13-4421-b331-61ce91d66150',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f07fde14-4b79-58b3-9ccd-ec0036a49b09') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f07fde14-4b79-58b3-9ccd-ec0036a49b09');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dc17a36f-c7b3-57fd-9708-3c4281b847cd','Complaint trigger level','A complaint trigger level is a pre-agreed sound level or operating condition, set in a noise-management plan, permit, or licence, at which the responsible party must begin a defined response — typically investigating, notifying the regulator, or adjusting the source — often prompted by or in anticipation of community complaints. It functions as an action threshold sitting below or at the enforceable limit, giving a margin to intervene before a breach is confirmed, and it is frequently tied to a specific receiver position and averaging interval. The concept overlaps with the ''action level'' or ''trigger value'' language used in construction and event noise plans. Its value and the response it demands vary by jurisdiction, plan, receiver, and time of day; for example, an outdoor-event plan may treat an off-site music noise level approaching the guideline in the UK Noise Council code (such as a facade level in dB LAeq,15min) as the point to check readings and reduce level.','A complaint trigger level is a set point that starts a response. It is agreed in a noise plan, permit, or licence. When noise reaches it, you must act. You might investigate, tell the regulator, or turn the sound down. It often sits just below the legal limit. That gap lets you fix things before a breach. Complaints from neighbours can also set off this response. The exact level depends on the place, the plan, and the time of day.','It gives operators and regulators an early, agreed point to act, so problems are caught before an enforceable limit is broken and before nuisance escalates. It turns a vague ''respond to complaints'' duty into a concrete, checkable threshold and procedure.','A production manager and council agree in the noise-management plan that a stated off-site level triggers an immediate check and level reduction, then staff act when a reading or complaint reaches it. A compliance officer uses the trigger to decide when to open an investigation rather than waiting for a formal breach.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Noise management plan','Music noise level (MNL)','Hotline protocol','Exceedance event','Off-site noise monitoring','Corrective action log']::text[],ARRAY['Confusing the trigger level with the legal limit — the trigger is usually set lower to give a margin for action.','Assuming one trigger value applies everywhere — it depends on the receiver, the plan, the time of day, and the jurisdiction.','UNSAFE: Believing that meeting a community complaint trigger also protects crew hearing — off-site community limits are far below and unrelated to occupational exposure limits, so staff near the source still need hearing protection.']::text[],ARRAY['A festival''s noise plan states that an off-site reading approaching the agreed limit triggers an immediate call to the mixer to reduce level.','An environmental health officer opens an investigation once monitored levels cross the plan''s agreed trigger, not only after a formal breach.','A venue sets an internal trigger below its licence limit so staff act early when a busy night pushes levels up.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complaint trigger level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dc17a36f-c7b3-57fd-9708-3c4281b847cd','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dc17a36f-c7b3-57fd-9708-3c4281b847cd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dc17a36f-c7b3-57fd-9708-3c4281b847cd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '001cbc78-ab1d-52f1-9f4c-edd9439aae51','Hotline protocol','A hotline protocol is the documented procedure by which an event or venue publishes and staffs a dedicated, attended contact channel — typically a telephone number, and often an email or web form — so affected residents can report noise during an activity, and by which those reports are received, recorded, escalated, and acted on in real time. It specifies who answers, what caller details are taken, how a complaint is passed to the noise consultant or duty manager, the expected response, and how the outcome is logged, sometimes with a set time within which the responsible authority must be notified. It is a core component of event and neighbourhood noise management because it converts community reactions into immediate, traceable operational responses. Whether a hotline is required, how it must be staffed, and any notification timescales vary by jurisdiction, permit, licence, and the controlling code; for example, UK guidance for concerts recommends advertising and operating an attended complaint telephone number for the event.','A hotline protocol is the plan for handling noise complaint calls. The event publishes a phone number that someone actually answers. It says who takes the call and what details to note. It says how the call reaches the sound team or manager. It sets the expected response and how to record it. Some plans set a time to tell the council about each complaint. This turns a neighbour''s call into fast, tracked action. The exact rules depend on the permit, licence, and local code.','It ensures community noise concerns reach the people who can act, quickly and in a recorded way, instead of being lost or delayed. It gives residents a route short of calling enforcement and gives organisers a chance to fix problems before they become breaches.','An event producer prints the hotline number on notices to nearby homes, staffs it during the show, and links it to a script and log. When a resident calls, the operator takes their details, alerts the noise consultant, records the response, and notifies the council within any agreed time.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Noise management plan','Complaint trigger level','Noise log','Corrective action log','Community liaison','Off-site noise monitoring']::text[],ARRAY['Treating the hotline as a voicemail or unstaffed line — codes expect it to be attended and able to respond during the event.','Publishing the number too narrowly — residents who are not told cannot use it, defeating its purpose.','Assuming answering the call ends the duty — the protocol also requires logging the complaint, the action, and often notifying the authority.']::text[],ARRAY['A festival promoter mails nearby households a leaflet with an attended noise hotline number staffed through the event.','A duty manager receiving a hotline call relays it to the noise consultant, who checks off-site levels and lowers the mix.','A council licensing officer reviews the hotline log after an event to see how complaints were handled and within what time.']::text[],'beginner',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hotline protocol');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '001cbc78-ab1d-52f1-9f4c-edd9439aae51','fe939357-1f13-4421-b331-61ce91d66150',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='001cbc78-ab1d-52f1-9f4c-edd9439aae51') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='001cbc78-ab1d-52f1-9f4c-edd9439aae51');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '33aedb0b-50e8-5f8c-9ba2-b5f68b0b1757','Corrective action log','A corrective action log is the record documenting each step taken in response to a noise exceedance, complaint, or trigger event — what happened, when, why, what was done to resolve it (for example reducing level, repositioning speakers, or halting an activity), who acted, and the outcome. It is distinct from a general noise log in that it focuses specifically on the response side, forming the closed-loop evidence that a problem was identified and remedied rather than merely observed. It draws on the wider quality- and environmental-management idea of corrective action, applied to acoustic compliance. What must be captured, and how such records tie into permit or licence conditions, varies by jurisdiction, plan, and controlling code; for example, UK event guidance advises keeping a record of the reason for a breach and the action taken to resolve the problem, which usually means reducing the volume of the music.','A corrective action log records how you fixed a noise problem. It lists what went wrong and when. It says why it happened and what you did. That might be turning the sound down or moving a speaker. It names who acted and how it turned out. It differs from a plain noise log by focusing on the fix. It proves a problem was solved, not just seen. What you must record depends on the plan and local code.','It proves the loop was closed: that an exceedance or complaint led to a real, documented remedy, which is what regulators and licence conditions expect. It also helps organisers learn, spotting recurring problems and improving future noise-management plans.','When monitoring shows a level heading over the limit, the noise consultant tells the engineer to cut the sound, and a staff member logs the exceedance, the instruction, the time, and the result. A council reviewing the event uses this log to confirm breaches were addressed, not ignored.','Sound Law — Assessment, Mapping & Mitigation',ARRAY['Noise log','Exceedance event','Complaint trigger level','Noise management plan','Hotline protocol','Music noise level (MNL)']::text[],ARRAY['Logging that an exceedance happened but not the action taken — the corrective-action record is precisely the response, not just the event.','Treating it as identical to the noise log — one records measurements and conditions, the other records the remedial steps and outcomes.','Assuming an undocumented fix counts — without a recorded action and result, a regulator cannot confirm the problem was actually resolved.']::text[],ARRAY['After an off-site reading exceeds the plan''s limit, a festival logs the time, the order to reduce level, and the confirming lower reading.','A construction site records each complaint-driven change, such as swapping to quieter plant, in its corrective action record.','An environmental health officer checks the corrective action log to verify that breaches during a licensed event were remedied on the night.']::text[],'intermediate',NULL,NULL,'fe939357-1f13-4421-b331-61ce91d66150' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Corrective action log');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '33aedb0b-50e8-5f8c-9ba2-b5f68b0b1757','fe939357-1f13-4421-b331-61ce91d66150',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='33aedb0b-50e8-5f8c-9ba2-b5f68b0b1757') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='33aedb0b-50e8-5f8c-9ba2-b5f68b0b1757');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '46812310-99df-5d03-b775-3a9c842106e6','OSHA noise standard','The U.S. federal occupational-noise rule at 29 CFR 1910.95, enforced by the Occupational Safety and Health Administration for general industry. It sets a permissible exposure limit (PEL) of 90 dBA as an 8-hour time-weighted average (TWA), an action level of 85 dBA TWA that triggers a hearing conservation program, and uses a 5 dB exchange rate (each 5 dBA increase halves the allowed duration). The action level corresponds to a 50% noise dose. Employers at or above the action level must provide audiometric testing, hearing protectors, training, and monitoring. Scope is workplace exposure of covered employees; it does not govern community, entertainment-audience, or environmental noise, and other regimes (NIOSH''s recommended 85 dBA with a 3 dB exchange rate; separate construction rules) differ. Specific applicability and enforcement details vary by industry sector and are periodically revised.','This is the main U.S. workplace noise rule. It is run by OSHA and applies to most industry jobs. The legal limit is 90 dBA averaged over an 8-hour shift. At 85 dBA averaged over 8 hours, an "action level" kicks in. At that point the employer must start a hearing conservation program. That means free hearing tests, ear protection, and training. OSHA uses a 5 dB rule. Every 5 dBA louder cuts the safe time in half. The rule covers workers, not audiences or neighbors. Other guides, like NIOSH, are stricter. Exact duties depend on the job and can change over time.','It exists to prevent noise-induced hearing loss among American workers by capping legal exposure and forcing employers to monitor, protect, and educate staff once risk rises. It converts a health hazard into enforceable duties (measurement, protection, audiometry) so that occupational hearing damage is treated as a controllable, inspectable workplace risk rather than an accepted cost of the job.','A compliance officer at a U.S. manufacturing or touring-production facility uses dosimetry to compute each employee''s 8-hour TWA, then compares it to the 85 dBA action level and 90 dBA PEL. Crossing the action level obliges them to enroll workers in audiometric testing, issue and fit hearing protectors, keep exposure records, and post training, all documented for a possible OSHA inspection.','Sound Law — Standards, Laws & Instruments',ARRAY['Permissible exposure limit','Action level','Exchange rate','Hearing conservation program','NIOSH REL','ANSI sound level meter']::text[],ARRAY['UNSAFE: Assuming that staying under the 90 dBA PEL means hearing is safe; the 90 dBA PEL with a 5 dB exchange rate is less protective than the NIOSH-recommended 85 dBA with a 3 dB exchange rate, and real hearing damage can occur below the PEL.','UNSAFE: Believing no action is needed until 90 dBA; the hearing conservation program is legally triggered at the 85 dBA action level, not the PEL.','Thinking OSHA''s 5 dB exchange rate is the only or the correct one; NIOSH, the EU, and many countries use a 3 dB exchange rate.','Assuming the standard covers concert audiences or neighborhood noise; 1910.95 governs covered workers, not the public.']::text[],ARRAY['An audio company''s safety lead runs shift dosimetry on riggers and stagehands and finds several exceed an 8-hour TWA of 85 dBA, triggering enrollment in a hearing conservation program.','During an OSHA inspection of a factory, the employer must produce audiometric records and proof that hearing protection was offered to everyone at or above the action level.','A new touring technician is trained that the 90 dBA PEL is a legal ceiling, not a safety guarantee, and is fitted with earplugs.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='OSHA noise standard');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '46812310-99df-5d03-b775-3a9c842106e6','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='46812310-99df-5d03-b775-3a9c842106e6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='46812310-99df-5d03-b775-3a9c842106e6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b3b835a6-a91e-5815-abfb-75648440ec90','ANSI sound level meter','A sound level meter conforming to the American National Standards Institute / Acoustical Society of America specification for such instruments, principally ANSI/ASA S1.4. The current edition, ANSI/ASA S1.4-2014/Part 1, is a nationally adopted version of the international standard IEC 61672-1:2013, so U.S. and international specifications are now harmonized. The standard defines performance requirements, tolerances, frequency and time weightings, and accuracy classes: modern editions use Class 1 (precision) and Class 2 (general-purpose), while the older ANSI S1.4-1983 used Type 0/1/2/3 language still seen in some U.S. regulations. Companion parts cover pattern-evaluation and periodic tests, and calibrators follow IEC 60942. Which class a job requires depends on the governing regulation, ordinance, or measurement protocol, and referenced editions vary and are periodically revised.','This is a sound meter that meets a U.S. quality standard. The standard is ANSI/ASA S1.4. Its newest version matches the world standard IEC 61672. So U.S. and global meters now follow the same rules. The standard sets how accurate the meter must be. It defines Class 1 for precision work and Class 2 for general use. Older U.S. rules used "Type 1" and "Type 2" instead. Many noise laws say which class you must use. The right class depends on the local rule you must meet. Meters are checked with a calibrator that meets another standard.','It gives regulators, laboratories, and technicians a common, testable benchmark so that noise measurements are accurate, repeatable, and legally defensible. By fixing tolerances and weightings, the standard ensures two meters measuring the same source agree closely, which is essential when a reading decides compliance with an exposure limit, permit condition, or ordinance.','A compliance technician selects a meter of the class a regulation demands (often Class/Type 1 for enforcement, Class/Type 2 for screening), field-calibrates it before and after with an IEC 60942 calibrator, and records the instrument''s standard and class in the report so the measurement withstands legal or licensing scrutiny.','Sound Law — Standards, Laws & Instruments',ARRAY['IEC 61672','Acoustic calibrator','A-weighting','Class 1 sound level meter','LAeq','OSHA noise standard']::text[],ARRAY['Believing "Type" and "Class" are different instruments; they are the older ANSI and newer IEC/ANSI labels for essentially the same accuracy tiers.','Assuming any smartphone app or cheap meter is ANSI-compliant; conformance requires meeting the standard''s tolerances and pattern-evaluation tests.','Thinking ANSI S1.4 and IEC 61672 conflict; the current ANSI/ASA S1.4-2014 is a nationally adopted version of IEC 61672-1:2013.','Forgetting that field calibration before and after measurement is expected; a reading from an unverified meter may be rejected.']::text[],ARRAY['A city noise-enforcement officer must use a Type/Class 1 meter meeting the referenced ANSI standard for a citation to hold up in court.','A festival''s acoustic consultant screens stage levels with a Class 2 meter, then switches to a Class 1 meter for the boundary compliance measurement.','A lab buys a new meter and confirms it carries ANSI/ASA S1.4-2014 / IEC 61672 Class 1 certification before using it for standardized testing.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ANSI sound level meter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b3b835a6-a91e-5815-abfb-75648440ec90','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b3b835a6-a91e-5815-abfb-75648440ec90') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b3b835a6-a91e-5815-abfb-75648440ec90');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '12831efd-85af-52ea-a6d4-2f0ca15aec5f','FHWA traffic noise','The U.S. Federal Highway Administration framework for analyzing and abating highway traffic noise on federal and federal-aid projects, codified at 23 CFR Part 772. It classifies projects as Type I (new construction or substantial alteration, requiring noise analysis), Type II (retrofit abatement on existing highways), or Type III (no analysis required). Impact is judged against Noise Abatement Criteria (NAC) expressed as hourly Leq(h) or L10(h) for activity categories: for example Category A 57 dBA (lands needing special quiet), Categories B and C 67 dBA exterior (residences and many public/institutional uses), Category D 52 dBA interior, and Category E 72 dBA. A predicted impact occurs when levels approach or exceed the NAC or substantially increase over existing levels; abatement (typically noise barriers) must be both feasible (generally at least a 5 dBA reduction) and reasonable (with a 7–10 dBA design goal, cost limits, and benefited-receptor input). State DOTs set specific numeric policies within this federal framework, so exact triggers vary by state and are periodically revised.','This is the U.S. rule for highway traffic noise. It comes from the Federal Highway Administration. It applies to federal and federal-aid road projects. Projects are sorted into three types. Type I means new or much-changed roads and needs a noise study. Type II fixes noise on existing roads. Type III needs no study. Noise is checked against limits called Noise Abatement Criteria. For homes, the outdoor limit is about 67 dBA over an hour. Quieter uses have lower limits. If a road will be too loud, the state looks at barriers. A barrier must cut noise enough and be worth the cost. Each state sets its own exact numbers within these federal rules.','It provides a consistent national method to predict, judge, and mitigate traffic noise so highway spending accounts for community sound impacts. It defines when a project must study noise, what counts as an impact, and when taxpayer-funded abatement such as barriers is justified, protecting residences and sensitive land uses near highways.','A highway project''s noise analyst models future Leq(h) at nearby receivers with FHWA''s Traffic Noise Model, compares results to the NAC for each activity category, identifies impacted receptors, and then tests candidate noise barriers for feasibility and reasonableness before recommending them in the project''s environmental document.','Sound Law — Standards, Laws & Instruments',ARRAY['Noise Abatement Criteria','Leq','Traffic Noise Model','NEPA noise assessment','Noise barrier','L10']::text[],ARRAY['Treating the 67 dBA Category B/C figure as a universal limit; it is an hourly Leq(h) approach criterion in the U.S. FHWA scheme, not a fixed limit and not applicable to all land uses.','Assuming every highway project must build barriers; abatement is only required where impacts occur and the barrier is both feasible and reasonable.','Confusing Leq(h) and L10(h); a state uses one or the other, not both, and the numeric criteria differ.','Believing FHWA criteria cover construction or nighttime specifically; the NAC are hourly design-hour metrics, and construction noise is handled separately.']::text[],ARRAY['A state DOT widening a freeway runs a Type I noise study and finds several homes exceed the 67 dBA Category B/C criterion, prompting a barrier feasibility analysis.','Residents petition for a Type II retrofit sound wall along an older highway, and the DOT ranks their neighborhood against others using its priority system.','An environmental consultant documents predicted Leq(h) levels in a NEPA document to show whether federal noise abatement is warranted.']::text[],'advanced',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='FHWA traffic noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '12831efd-85af-52ea-a6d4-2f0ca15aec5f','285671a7-e448-4b2c-931f-1e5a43271820',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='12831efd-85af-52ea-a6d4-2f0ca15aec5f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='12831efd-85af-52ea-a6d4-2f0ca15aec5f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7a0df62f-9f96-524b-af1d-70931c086d80','FAA aircraft noise','The U.S. Federal Aviation Administration framework for assessing and regulating aircraft noise. Its primary exposure metric is the Day-Night Average Sound Level (DNL), a 24-hour A-weighted average that adds a 10 dB penalty to nighttime events (10 p.m.–7 a.m.) to reflect greater sleep disturbance. The FAA treats DNL 65 dB as the threshold of significant noise exposure for residential and other noise-sensitive land uses; land-use compatibility and airport noise/land-use planning are handled under 14 CFR Part 150. Under FAA policy (Order 1050.1F), a significant impact generally occurs when an action increases noise by 1.5 dB or more at a noise-sensitive area already at or above DNL 65. Aircraft themselves are certificated for noise under 14 CFR Part 36 (FAR Part 36), which sets stage/chapter limits, and modeling uses the Aviation Environmental Design Tool (AEDT). DNL''s use as the primary metric follows the interagency FICON recommendations; specific thresholds and policy are periodically reviewed and revised.','This is how the U.S. handles aircraft noise. The FAA runs it. Its main measure is called DNL. DNL averages aircraft noise over a full 24 hours. Night flights get a 10 dB penalty because they disturb sleep. The FAA treats 65 dB DNL as the start of serious noise near homes. Land-use planning around airports uses a rule called Part 150. An action is usually "significant" if it adds 1.5 dB or more. This applies where noise is already at 65 DNL or higher. Aircraft must also pass noise tests to be certified. The FAA uses a special computer tool to model the noise. These thresholds are reviewed and can change.','It gives a single, sleep-weighted way to describe cumulative aircraft noise so airports, communities, and planners can identify where noise is incompatible with homes, schools, and hospitals. It underpins land-use compatibility planning, environmental review of airport and airspace changes, and the noise-based certification that pushes manufacturers toward quieter aircraft.','An airport noise consultant models DNL contours with AEDT, overlays the 65 dB DNL contour on land use to flag incompatible residential areas, and uses that map in a Part 150 study or NEPA review to justify measures like sound insulation, or to test whether a new flight procedure causes a significant 1.5 dB increase.','Sound Law — Standards, Laws & Instruments',ARRAY['Day-night average sound level','14 CFR Part 150','FAR Part 36','NEPA noise assessment','AEDT','FICON']::text[],ARRAY['Reading 65 dB DNL as a single loud event; DNL is a 24-hour average with a nighttime penalty, not an instantaneous or single-flight level.','Assuming any noise increase near an airport is legally significant; FAA policy generally uses a 1.5 dB increase at or above DNL 65 as the significance test.','Confusing aircraft noise certification (Part 36) with airport land-use planning (Part 150); they are different instruments.','Believing the 10 dB night penalty makes DNL a nighttime-only metric; it is a full-day average that weights night events more heavily.']::text[],ARRAY['A community group opposing a new runway reviews the airport''s DNL 65 contour to see which neighborhoods fall inside the significant-impact area.','An airport pursuing a Part 150 program uses DNL contours to qualify homes for federally funded sound insulation.','The FAA evaluates a proposed departure procedure and checks whether it raises noise by 1.5 dB or more where residents are already exposed to DNL 65 or above.']::text[],'advanced',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='FAA aircraft noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7a0df62f-9f96-524b-af1d-70931c086d80','285671a7-e448-4b2c-931f-1e5a43271820',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7a0df62f-9f96-524b-af1d-70931c086d80') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7a0df62f-9f96-524b-af1d-70931c086d80');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4d2ef88b-88a1-5c7f-845e-2d2f03d67f71','NEPA noise assessment','The evaluation of noise impacts required under the U.S. National Environmental Policy Act of 1969 (NEPA) when a federal agency proposes an action with potential environmental effects. NEPA is a procedural statute: it does not itself set noise limits, but it requires agencies to disclose and consider a proposal''s noise effects in an Environmental Assessment (EA) or, for significant impacts, an Environmental Impact Statement (EIS), together with alternatives and mitigation. Agencies apply their own or referenced quantitative criteria, for example FHWA''s Noise Abatement Criteria and hourly Leq for highways, FAA''s DNL 65 dB framework for aviation, or HUD guidelines for housing. Noise is one of many environmental factors weighed, and the depth of analysis scales with the project. Exactly which criteria and thresholds apply depends on the lead agency and action type, and guidance is periodically revised.','NEPA is a U.S. law from 1969. It applies when a federal agency plans a project. The law does not set noise limits by itself. Instead, it makes agencies study a project''s effects first. Noise is one of those effects. For smaller projects the agency writes an Environmental Assessment. For big impacts it writes a fuller Environmental Impact Statement. The study must look at options and ways to reduce harm. Agencies borrow noise limits from other rules. Highways use FHWA limits. Airports use FAA''s DNL rule. Which limits apply depends on the agency and the project.','It forces federal decision-makers to identify, disclose, and weigh noise impacts before committing to a project, giving the public and officials information to compare alternatives and adopt mitigation. It embeds noise into environmental transparency and accountability rather than leaving it to be discovered after construction.','An environmental planner preparing an EA or EIS for a federally funded highway, transit line, or airport change quantifies existing and predicted noise using the lead agency''s criteria (FHWA Leq, FAA DNL, or HUD levels), identifies affected receptors and sensitive uses, evaluates alternatives, and documents mitigation such as barriers or insulation for the public record.','Sound Law — Standards, Laws & Instruments',ARRAY['Environmental Impact Statement','FHWA traffic noise','FAA aircraft noise','Noise Abatement Criteria','Day-night average sound level','HUD noise guidelines']::text[],ARRAY['Thinking NEPA sets its own noise limits; it is a procedural disclosure law that borrows quantitative criteria from agencies like FHWA, FAA, or HUD.','Assuming every federal action needs a full EIS; many are covered by an EA or a categorical exclusion, with an EIS reserved for significant impacts.','Believing a NEPA document by itself blocks a noisy project; NEPA requires disclosure and consideration, not a specific outcome.','Confusing NEPA with state ''little NEPA'' laws; state environmental review acts have their own procedures and thresholds.']::text[],ARRAY['A transit agency building a federally funded rail extension prepares an EIS that models future noise and vibration at trackside homes and proposes barriers.','For a small federally aided road project, planners complete an EA showing noise stays below FHWA criteria, supporting a finding of no significant impact.','Community members submit comments during NEPA review arguing the airport''s noise analysis understated nighttime aircraft impacts.']::text[],'advanced',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='NEPA noise assessment');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4d2ef88b-88a1-5c7f-845e-2d2f03d67f71','285671a7-e448-4b2c-931f-1e5a43271820',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4d2ef88b-88a1-5c7f-845e-2d2f03d67f71') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4d2ef88b-88a1-5c7f-845e-2d2f03d67f71');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a692a175-2bce-52f7-8b3b-30ec46692452','Environmental Noise Directive','European Union Directive 2002/49/EC on the assessment and management of environmental noise (the END), which establishes a common EU approach to noise from road, rail, and air traffic and from industry in built-up areas. It defines harmonized indicators: Lden, a day-evening-night annual average level that adds a 5 dB penalty to evening and a 10 dB penalty to night periods, and Lnight, the annual average night-time level. Member States must produce strategic noise maps and then noise action plans, reviewed and revised on a roughly five-year cycle, for agglomerations above about 100,000 inhabitants and for major roads (over 3 million vehicles/year), major railways (over 30,000 trains/year), and major airports (over 50,000 movements/year). It also requires identifying and protecting ''quiet areas''. The END standardizes assessment and public information but leaves binding limit values and remedial measures to individual Member States, so exact thresholds and actions vary by country and are periodically revised.','This is an EU law on environmental noise. Its short name is the END. It covers noise from roads, railways, aircraft, and industry. It sets common ways to measure noise across Europe. One measure, Lden, averages noise over a full day. It adds a penalty for evening and night noise. Another measure, Lnight, covers just the night. Countries must map noise in big towns and near busy roads, railways, and airports. They must then write plans to cut noise. Maps and plans are updated about every five years. Countries must also protect quiet areas. The EU sets the method, but each country sets its own limits.','It creates a shared EU framework so noise exposure is measured the same way everywhere, made public, and managed through action plans. Its jobs are to harmonize assessment, inform citizens about the noise they face, guide reduction where exposure is high, and preserve areas that are still quiet, without dictating a single Europe-wide limit.','A city or national authority uses the END to compile strategic noise maps showing populations exposed to given Lden and Lnight bands, publishes them, and then develops an action plan prioritizing hotspots, for example with quieter road surfaces, traffic management, or protected quiet parks, reporting results to the European Commission each cycle.','Sound Law — Standards, Laws & Instruments',ARRAY['Lden','Lnight','Strategic noise map','Noise action plan','Agglomeration','WHO Environmental Noise Guidelines']::text[],ARRAY['Thinking the END sets binding EU-wide noise limits; it harmonizes indicators, mapping, and planning but leaves limit values to each Member State.','Confusing Lden with a simple average; Lden penalizes evening (+5 dB) and night (+10 dB) noise to reflect greater annoyance and sleep disturbance.','Assuming the END covers workplace or neighbor noise; it targets environmental noise from major transport sources and industry in built-up areas, not occupational exposure.','Believing noise maps by themselves reduce noise; they inform mandatory action plans that carry the actual measures.']::text[],ARRAY['A metropolitan authority publishes END strategic noise maps and holds public consultation on an action plan for its busiest ring road.','A national government reports to the European Commission the number of residents exposed above given Lnight bands near a major airport.','An acoustic consultant advising a developer checks whether a site sits within a mapped high-Lden corridor before designing facade insulation.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Environmental Noise Directive');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a692a175-2bce-52f7-8b3b-30ec46692452','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a692a175-2bce-52f7-8b3b-30ec46692452') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a692a175-2bce-52f7-8b3b-30ec46692452');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '919fa32e-d7e5-5e35-8b54-0de05883ebb0','Directive 2003/10/EC','The EU ''Noise'' Directive under the physical-agents framework, setting minimum health and safety requirements for the exposure of workers to risks from noise. It defines a daily (or weekly) personal noise exposure LEX,8h and a peak sound pressure ppeak in dB(C), and three tiers: a lower exposure action value of LEX,8h 80 dB(A) and peak 135 dB(C); an upper exposure action value of 85 dB(A) and 137 dB(C); and an exposure limit value of 87 dB(A) and 140 dB(C). At the lower action value employers must make hearing protection available and provide information and training; at the upper value protection use is mandatory, areas are marked, and health surveillance/audiometry applies; the exposure limit value must not be exceeded at the ear and, uniquely, is assessed taking the attenuation of hearing protectors into account. It is a minimum-standards directive: Member States transpose it into national law (e.g. the UK Control of Noise at Work Regulations) and may be stricter, so implementation details vary and the instrument is periodically revised.','This is an EU workplace noise law. It sets minimum rules to protect workers'' hearing. It uses two measures. One is daily noise averaged over 8 hours. The other is the peak, or loudest, sound pressure. There are three levels. The lower action level is 80 dB(A) daily, with a 135 dB(C) peak. The upper action level is 85 dB(A), with a 137 dB(C) peak. The exposure limit is 87 dB(A), with a 140 dB(C) peak. At 80 dB employers must offer ear protection and training. At 85 dB workers must wear protection and get hearing checks. The 87 dB limit must never be passed at the ear. That limit counts the protection earplugs give. Each country writes its own version and can be stricter.','It harmonizes a floor of hearing protection across the EU by tying escalating employer duties to measurable exposure tiers. Its function is to ensure that once workers reach defined noise levels, protection, information, health surveillance, and an absolute at-the-ear limit are legally required, preventing occupational noise-induced hearing loss regardless of Member State.','A safety manager at an EU venue or industrial site measures crew LEX,8h and peak dB(C), then acts by tier: at 80 dB(A) issuing earplugs and training; at 85 dB(A) enforcing their use, zoning noisy areas, and arranging audiometry; and ensuring the 87 dB(A) limit is not exceeded at the ear after accounting for protector attenuation, all recorded for inspection.','Sound Law — Standards, Laws & Instruments',ARRAY['Control of Noise at Work Regulations','Lower exposure action value','Upper exposure action value','LEX,8h','Peak sound pressure','Hearing protection derating']::text[],ARRAY['UNSAFE: Assuming the 87 dB(A) exposure limit value can be met by loud environments as long as earplugs are worn without checking real-world attenuation; the limit applies at the ear and over-optimistic protector ratings can leave workers over-exposed.','UNSAFE: Treating the 80 dB(A) lower action value as ''safe'' and skipping protection; it is the point where protection must be offered and information given, and damage risk already exists.','Confusing action values (assessed without hearing protection) with the exposure limit value (assessed with protection); they are measured differently.','Believing 2003/10/EC uses a 5 dB exchange rate like OSHA; EU exposure is based on equal-energy averaging (effectively a 3 dB exchange rate).']::text[],ARRAY['A touring production crossing the EU sets its hearing-protection policy to the directive''s 80/85/87 dB tiers so it complies in every Member State.','A factory occupational-health team measures a workshop at LEX,8h 86 dB(A), above the upper action value, so protection becomes mandatory and audiometry is scheduled.','An enforcement inspector checks whether an employer accounted for real hearing-protector attenuation when demonstrating compliance with the 87 dB(A) exposure limit value.']::text[],'advanced',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directive 2003/10/EC');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '919fa32e-d7e5-5e35-8b54-0de05883ebb0','285671a7-e448-4b2c-931f-1e5a43271820',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='919fa32e-d7e5-5e35-8b54-0de05883ebb0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='919fa32e-d7e5-5e35-8b54-0de05883ebb0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c4f7f601-c569-52dd-b0f2-19f441105422','Control of Noise at Work Regulations','The UK''s Control of Noise at Work Regulations 2005 (SI 2005/1643), which transpose EU Directive 2003/10/EC and are enforced by the Health and Safety Executive. They place duties on employers to assess and control workplace noise risk, keyed to the same tiers: a lower exposure action value of a daily/weekly exposure of 80 dB(A) and peak sound pressure 135 dB(C); an upper exposure action value of 85 dB(A) and 137 dB(C); and an exposure limit value of 87 dB(A) and 140 dB(C). Duties escalate by tier: at the lower value, provide information, training, and hearing protection on request; at the upper value, take engineering/organizational control measures, designate hearing protection zones, mandate protector use, and provide health surveillance; the exposure limit value must not be exceeded, taking protector attenuation into account. They apply to Great Britain (with parallel provisions elsewhere in the UK) and exclude the general public and audiences from the duty holder''s core obligations, with sector guidance for music and entertainment. Details are periodically revised and interpreted through HSE guidance.','These are the UK''s workplace noise rules from 2005. They put EU noise law into UK law. The HSE enforces them. Employers must assess and reduce noise risk to workers. The rules use the same three levels. The lower action level is 80 dB(A) daily, with a 135 dB(C) peak. The upper action level is 85 dB(A), with a 137 dB(C) peak. The exposure limit is 87 dB(A), with a 140 dB(C) peak. At 80 dB, give training and offer ear protection. At 85 dB, control the noise and require protection. The 87 dB limit must not be passed at the ear. That limit counts the protection worn. Separate guidance covers music and entertainment.','They exist to prevent noise-induced hearing loss and tinnitus among UK workers by turning exposure tiers into concrete, enforceable employer duties. They ensure noise risk is assessed, controlled at source where possible, and backed by protection, zoning, and health surveillance once defined levels are reached, giving inspectors a clear compliance benchmark.','A UK sound engineer or venue safety officer measures crew exposure and, on reaching the 85 dB(A) upper action value, designates hearing protection zones, provides and enforces suitable protectors, reduces exposure through controls or rotation, and arranges audiometric health surveillance, documenting the risk assessment for HSE inspection.','Sound Law — Standards, Laws & Instruments',ARRAY['Directive 2003/10/EC','Lower exposure action value','Upper exposure action value','Exposure limit value','Hearing protection zone','HSE']::text[],ARRAY['UNSAFE: Assuming audiences and performers'' own hearing is covered the same way as staff; the core duties protect workers, and audience exposure is handled through separate entertainment guidance and licensing, so relying on these regulations to protect a crowd is mistaken.','UNSAFE: Believing that once earplugs are handed out the employer has met the 87 dB(A) limit; the limit is at the ear and requires realistic derating of protector performance.','Thinking the 80 dB(A) lower action value means no risk below it; it is where duties begin, not a threshold of safety.','Confusing the daily exposure action values with the peak dB(C) values; both a daily average and a peak criterion apply at each tier.']::text[],ARRAY['A live-music venue''s health-and-safety lead completes a noise risk assessment and installs hearing-protection-zone signage where crew exposure exceeds 85 dB(A).','An HSE inspector visiting a factory asks to see the noise risk assessment and audiometry records for staff exposed above the upper action value.','A touring company operating in the UK aligns its ear-protection rules with the 80/85/87 dB(A) tiers to satisfy the regulations.']::text[],'advanced',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Control of Noise at Work Regulations');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c4f7f601-c569-52dd-b0f2-19f441105422','285671a7-e448-4b2c-931f-1e5a43271820',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c4f7f601-c569-52dd-b0f2-19f441105422') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c4f7f601-c569-52dd-b0f2-19f441105422');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d3ce53e-4dca-5141-a74b-0cb18f25dd6b','Lower exposure action value','The first, lower tier of occupational noise exposure at which employer duties begin under EU Directive 2003/10/EC and its national transpositions, such as the UK Control of Noise at Work Regulations 2005. In the UK/EU scheme it is a daily or weekly personal noise exposure (LEX) of 80 dB(A) together with a peak sound pressure of 135 dB(C). Reaching it obliges the employer to assess the risk, provide workers with information and training about noise and hearing damage, and make suitable hearing protection available on request, although its use is not yet mandatory at this level. Action values are assessed on the noise reaching the worker without accounting for any hearing protection worn (unlike the exposure limit value). The concept and the 80 dB(A)/135 dB(C) figures are specific to the EU/UK occupational regime; other jurisdictions such as the U.S. use different structures, and the values are periodically revised.','This is the first noise level where workplace duties start. It comes from EU and UK noise rules. In the UK it is 80 dB(A) noise averaged over a day. It also includes a peak level of 135 dB(C). At this level the employer must assess the risk. They must give workers training about noise and hearing loss. They must offer ear protection if a worker asks. Wearing it is not yet required at this level. This level is measured without counting any earplugs worn. The 80 dB(A) figure belongs to the EU and UK systems. Other countries, like the U.S., use different numbers.','It marks the point at which noise stops being negligible and employers must start informing and equipping workers, catching risk early before it reaches the mandatory-protection tier. It gives regulators a clear, measurable trigger for basic duties (assessment, information, protection on request), building a graduated ladder of protection.','When a noise assessment shows a role reaches a daily exposure of 80 dB(A), a safety officer documents the risk, delivers hearing-awareness training, and makes earplugs or muffs freely available, even though workers are not yet required to wear them, keeping records that the lower-tier duties were met.','Sound Law — Standards, Laws & Instruments',ARRAY['Upper exposure action value','Exposure limit value','Directive 2003/10/EC','Control of Noise at Work Regulations','LEX,8h','Peak sound pressure']::text[],ARRAY['UNSAFE: Treating 80 dB(A) as a ''safe'' level below which hearing cannot be harmed; it is the point where protective duties begin, and prolonged exposure near it still carries hearing-damage risk, so workers should still consider protection.','Assuming hearing protection must be worn at the lower action value; at this tier it must be made available on request, but its use becomes mandatory only at the upper action value.','Believing the value is measured with earplugs factored in; action values are assessed on the noise reaching the ear without protection.','Thinking 80 dB(A) applies worldwide; it is the EU/UK figure, and other regimes (e.g. OSHA''s 85 dBA action level) differ.']::text[],ARRAY['An acoustic assessment of a rehearsal room shows technicians reach a daily exposure of 80 dB(A), so the venue starts hearing-awareness training and stocks earplugs.','A small workshop owner in the UK learns that reaching the lower action value obliges information and training even before protection use is mandatory.','A festival''s welfare team offers free earplugs to bar staff whose exposure sits around the lower action value.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lower exposure action value');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d3ce53e-4dca-5141-a74b-0cb18f25dd6b','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d3ce53e-4dca-5141-a74b-0cb18f25dd6b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d3ce53e-4dca-5141-a74b-0cb18f25dd6b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bf8375f5-1bfc-52cf-bbd6-366d774c55d7','Upper exposure action value','The second, higher tier of occupational noise exposure that triggers stronger employer duties under EU Directive 2003/10/EC and its national transpositions, such as the UK Control of Noise at Work Regulations 2005. In the UK/EU scheme it is a daily or weekly personal noise exposure (LEX) of 85 dB(A) with a peak sound pressure of 137 dB(C). Reaching it obliges the employer to reduce exposure so far as reasonably practicable by engineering and organizational controls, to designate and mark hearing protection zones, to ensure hearing protection is actually worn (not just available), and to provide health surveillance including audiometric testing. Like the lower action value, it is assessed on the noise reaching the worker without accounting for protectors (unlike the exposure limit value of 87 dB(A)/140 dB(C)). The 85 dB(A)/137 dB(C) figures are specific to the EU/UK regime; other jurisdictions differ, and the values are periodically revised.','This is the second, higher noise level in EU and UK workplace rules. It triggers stronger duties than the lower level. In the UK it is 85 dB(A) noise averaged over a day. It also includes a peak level of 137 dB(C). At this level the employer must cut the noise where they reasonably can. They must set up marked hearing protection zones. Workers must now actually wear ear protection. The employer must also arrange regular hearing checks. This level is measured without counting the earplugs worn. The 85 dB(A) figure belongs to the EU and UK systems. Other countries use different numbers.','It defines the point where offering protection is no longer enough and active control becomes mandatory. Its job is to force real risk reduction, compulsory protector use, zoning, and health monitoring once exposure reaches a level clearly capable of causing hearing damage, closing the gap between awareness and enforced protection.','When exposure reaches a daily 85 dB(A), a compliance officer implements controls (quieter equipment, barriers, limited exposure time), posts hearing-protection-zone signs, enforces protector use, and enrolls affected workers in audiometric health surveillance, documenting each step for HSE or equivalent inspection.','Sound Law — Standards, Laws & Instruments',ARRAY['Lower exposure action value','Exposure limit value','Hearing protection zone','Control of Noise at Work Regulations','Directive 2003/10/EC','Audiometry']::text[],ARRAY['UNSAFE: Assuming that reaching the upper action value only means offering earplugs; at 85 dB(A) protector use is mandatory, controls are required, and skipping them leaves workers at real risk of hearing loss.','UNSAFE: Believing the 85 dB(A) upper action value already accounts for hearing protection; action values are measured on unprotected exposure, so relying on it as an ''ear-level'' figure under-protects workers.','Confusing the upper action value (85 dB(A)) with the exposure limit value (87 dB(A)); the limit is higher and is assessed with protection factored in.','Thinking health surveillance is optional at this tier; audiometric testing becomes a duty at the upper action value.']::text[],ARRAY['A stage crew''s exposure is measured at 85 dB(A) over the shift, so the production designates hearing-protection zones and makes earplug use mandatory.','An HSE inspector confirms a factory at the upper action value has both engineering controls and an audiometry program in place.','A recording studio''s manager schedules annual hearing tests for staff after monitoring shows exposure at the upper action value.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Upper exposure action value');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bf8375f5-1bfc-52cf-bbd6-366d774c55d7','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bf8375f5-1bfc-52cf-bbd6-366d774c55d7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bf8375f5-1bfc-52cf-bbd6-366d774c55d7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f02de3ea-2213-5a61-a15c-6c77ac486f46','Premises licence','An authorization under the UK Licensing Act 2003 (England and Wales) permitting a premises to carry on licensable activities such as the sale/supply of alcohol, regulated entertainment (including live and recorded music), and late-night refreshment. Licences are granted by the local licensing authority and must promote four statutory licensing objectives: the prevention of crime and disorder, public safety, the prevention of public nuisance, and the protection of children from harm. Under the public-nuisance objective, authorities can attach conditions controlling noise, for example limits on amplified music, restrictions on hours, keeping doors and windows closed, sound-limiter devices, or bounded noise levels at nearby dwellings. Conditions are set case by case and can be reviewed or varied, so exact sound requirements vary by venue, area, and application. It is the primary English/Welsh mechanism through which entertainment noise is regulated at the point of licensing; Scotland and Northern Ireland have separate regimes.','This is a UK licence for a venue. It comes from the Licensing Act 2003. It lets a place sell alcohol or put on entertainment. Live and recorded music count as entertainment. The local council grants the licence. Every licence must support four legal aims. One aim is preventing public nuisance. Under that aim the council can add noise conditions. These may cap music volume or set closing hours. They may require doors kept shut or a sound limiter. Conditions are set for each venue on its own facts. They can be reviewed and changed later. Scotland and Northern Ireland have their own systems.','It is the point-of-licensing tool that lets local authorities permit entertainment while protecting neighbors, safety, and children. Through tailored conditions it converts the broad public-nuisance objective into specific, enforceable noise controls for a given venue, balancing nightlife and residential amenity without a single national noise limit.','A venue operator applying for or varying a premises licence negotiates noise conditions with the licensing authority and environmental health, such as installing a calibrated sound limiter, agreeing a music cut-off time, or meeting a specified level at the nearest facade, and must then operate within those conditions or face review.','Sound Law — Standards, Laws & Instruments',ARRAY['Licensing Act 2003','Prevention of public nuisance','Sound limiter','Statutory nuisance','BS 4142','Noise Council Code of Practice']::text[],ARRAY['Assuming a premises licence sets one fixed decibel limit; noise conditions are tailored per venue and may use hours, limiters, or facade levels rather than a single national number.','Thinking a licence permanently guarantees the right to make noise; licences can be reviewed and conditions tightened if public nuisance arises.','Believing the Licensing Act 2003 applies UK-wide; it covers England and Wales, with separate regimes in Scotland and Northern Ireland.','Confusing licensing conditions with statutory nuisance law; a venue can comply with its licence yet still face statutory-nuisance action from a council.']::text[],ARRAY['A new nightclub applies for a premises licence and accepts a condition to fit a sound limiter set with environmental health to protect flats above.','Residents trigger a licence review after repeated late-night music complaints, and the authority adds tighter noise conditions.','A festival organizer applies for a time-limited premises licence and agrees music cut-off times and boundary noise levels as conditions.']::text[],'beginner',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Premises licence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f02de3ea-2213-5a61-a15c-6c77ac486f46','285671a7-e448-4b2c-931f-1e5a43271820',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f02de3ea-2213-5a61-a15c-6c77ac486f46') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f02de3ea-2213-5a61-a15c-6c77ac486f46');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '35a12f1c-35e8-516b-9b4b-ade1f318318a','BS 4142','The British Standard BS 4142:2014+A1:2019, ''Methods for rating and assessing industrial and commercial sound'', used in the UK to judge the likely impact of sound of an industrial or commercial character on people at nearby residential (and comparable) receivers. The method compares a rating level with the background sound level. The rating level is the specific sound level of the source (typically expressed as a one-hour LAeq by day and 15-minute LAeq at night) plus corrections for acoustic character such as tonal, impulsive, intermittent, or otherwise distinctive features. The background sound level is the prevailing residual level, measured as LA90 over the relevant period. The greater the excess of the rating level over the background, the greater the likely adverse impact: broadly, around +10 dB or more indicates a significant adverse impact and around +5 dB an adverse impact, while a difference around or below 0 dB suggests low impact, all subject to context. Assessments require professional judgment of the acoustic situation and are periodically revised.','This is a UK standard for judging industrial and commercial noise. Its full name is BS 4142. It looks at noise reaching nearby homes. The method compares two levels. The first is the source''s noise, called the rating level. Extra decibels are added if the sound has a harsh character. That includes tones, bangs, or on-off patterns. The second level is the normal background noise without the source. The bigger the gap between the two, the worse the impact. A gap of about +10 dB suggests a significant problem. About +5 dB suggests an adverse impact. A gap near zero suggests low impact. The result still depends on the local context and expert judgment.','It provides a repeatable UK method to decide whether a factory, plant, or commercial installation is likely to cause a noise problem for neighbors, especially in planning and complaint contexts. By anchoring judgment to the difference between source and background plus character corrections, it lets authorities and consultants assess impact consistently rather than by opinion alone.','An acoustic consultant assessing a proposed or existing installation measures the source''s specific sound level and the LA90 background, adds character corrections for any tonal or impulsive features to get the rating level, and reports the difference and its significance in a planning application or noise-complaint investigation to support conditions or objections.','Sound Law — Standards, Laws & Instruments',ARRAY['Background sound level','Rating level','LA90','LAeq','Statutory nuisance','Premises licence']::text[],ARRAY['Treating the +5 dB and +10 dB figures as fixed pass/fail limits; BS 4142 requires the difference to be interpreted alongside context, uncertainty, and acoustic character, not applied mechanically.','Forgetting the character corrections; ignoring tonal, impulsive, or intermittent features understates the rating level and the assessed impact.','Confusing the background LA90 with an average level; background is the residual level exceeded 90% of the time, not the LAeq.','Applying BS 4142 to entertainment or road-traffic noise; it is intended for industrial and commercial sound, not music venues or traffic.']::text[],ARRAY['A consultant assessing a proposed factory extraction fan uses BS 4142 to show the rating level is only a few decibels above background, supporting the planning application.','During a complaint about a commercial refrigeration unit, an environmental health officer commissions a BS 4142 assessment to gauge the likely adverse impact on nearby homes.','A developer of housing near an industrial estate uses BS 4142 to set glazing and layout that keep the rating-to-background difference low.']::text[],'advanced',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='BS 4142');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '35a12f1c-35e8-516b-9b4b-ade1f318318a','285671a7-e448-4b2c-931f-1e5a43271820',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='35a12f1c-35e8-516b-9b4b-ade1f318318a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='35a12f1c-35e8-516b-9b4b-ade1f318318a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c4e45a89-060c-54d8-9901-718cb0419093','Noise Council Code of Practice','The Noise Council''s ''Code of Practice on Environmental Noise Control at Concerts'' (1995), a UK guidance document for controlling environmental noise from concerts and large outdoor/indoor music events affecting nearby residents. It introduces the Music Noise Level (MNL), the LAeq of the music measured over a set period at a stated location, and offers guideline values that depend on the venue type and the number of concert days per year, assessed typically as an LAeq over a 15-minute period at 1 metre from the facade of the nearest noise-sensitive premises. For example, for venues with a small number of concert days per year the guideline music noise level is on the order of 65 dB(A) (with a higher figure for some existing/urban venues), while for late-night periods the aim is that music noise should not be audible inside noise-sensitive dwellings. It is advisory guidance often used by licensing authorities and event promoters rather than a statutory limit, so its figures are applied case by case and may be superseded by more recent guidance.','This is UK guidance for concert noise. The Noise Council published it in 1995. It helps control noise from concerts that reaches homes. It sets a measure called the Music Noise Level. That is the average music noise over a set time. It is measured near the nearest home''s wall. The guideline values depend on the venue and event days. They are usually judged over a 15-minute period. For venues with few concert days, the guide is about 65 dB(A). Some existing city venues have a higher figure. Late at night, music should not be heard inside homes. It is advice, not a fixed legal limit. Councils and promoters often use it for concert conditions.','It gives licensing authorities, environmental health officers, and event promoters a common yardstick for setting and checking concert noise so events can go ahead while limiting disturbance to residents. By defining the Music Noise Level and offering venue- and frequency-based guideline figures, it translates a vague nuisance concern into measurable targets for licence conditions.','An event''s acoustic consultant uses the code to propose a Music Noise Level limit at the nearest homes, positions a monitoring microphone accordingly, and feeds an agreed 15-minute LAeq target into the licence or permit; during the show they monitor MNL and advise the front-of-house engineer if levels approach the agreed limit.','Sound Law — Standards, Laws & Instruments',ARRAY['Music Noise Level','LAeq','Premises licence','Statutory nuisance','BS 4142','Environmental Noise Directive']::text[],ARRAY['Assuming the code''s figures are legally binding limits; it is advisory guidance, and any enforceable limit comes from a licence condition, permit, or nuisance law.','Treating the 65 dB(A) guideline as universal; the guideline depends on venue type and the number of concert days per year, and other figures apply.','Confusing the Music Noise Level at the nearest home''s facade with the level at the mixing position; the code''s guideline is assessed at noise-sensitive premises, not on stage.','Assuming this concert code protects the audience''s hearing; it targets environmental noise for neighbors, while audience and worker hearing are covered by other guidance and regulations.']::text[],ARRAY['A promoter planning an outdoor concert agrees a Music Noise Level target with the council based on the code, then sets monitoring points at the nearest houses.','An environmental health officer investigating complaints after a stadium show compares measured 15-minute LAeq values at residents'' facades against the code''s guidelines.','A licensing authority attaches a concert noise condition to a premises licence using the code''s approach to define acceptable music noise levels.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise Council Code of Practice');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c4e45a89-060c-54d8-9901-718cb0419093','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c4e45a89-060c-54d8-9901-718cb0419093') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c4e45a89-060c-54d8-9901-718cb0419093');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '513e7e3a-9092-5922-8526-b99e7bf5f4b7','Code de la sante publique','The French Public Health Code (Code de la sante publique) is the national statute whose noise provisions, at articles R.1336-1 to R.1336-3 as introduced by decret no. 2017-1244 of 7 August 2017, govern places open to or receiving the public that diffuse amplified sound at high levels, including concert halls, clubs, festivals, and cinemas. For a general audience it caps exposure at the point of highest public exposure at 102 dB LAeq over any 15-minute interval and 118 dB LCeq over the same interval; for spaces receiving children up to age six the caps drop to 94 dB LAeq,15min and 104 dB LCeq,15min. Operators must also record levels, display them, protect neighbouring areas, provide rest zones for extended events, and make hearing protection available. The exact operational duties, thresholds, and enforcement depend on the venue type, the decree''s implementing order, and the local authority, and the framework is periodically revised.','This is France''s public health law for loud amplified sound. It covers clubs, concerts, festivals, and cinemas. It limits how loud a venue can be for the crowd. For adults the cap is 102 dB(A) over 15 minutes. There is also a 118 dB(C) cap over 15 minutes. Venues for young children have much lower caps. Operators must measure and show the sound level. They must also protect neighbours and offer quiet rest areas. The exact rules depend on the venue and local officials. This is general information, not legal advice.','It exists to protect two groups at once: audiences from hearing damage caused by prolonged high-level amplified sound, and neighbouring residents from nuisance. By fixing measurable dose-style limits (an energy-averaged LAeq plus a C-weighted LCeq to capture bass energy) and attaching duties to the venue operator, it converts a health goal into an auditable compliance obligation.','A French venue''s sound engineer or manager configures a calibrated limiter and logging system to hold the loudest audience position at or below 102 dB LAeq,15min and 118 dB LCeq,15min, keeps the recorded data, and provides earplugs and a quieter rest area. A regulator or local authority can request the stored measurements to check the venue met its obligations.','Sound Law — Standards, Laws & Instruments',ARRAY['LAeq','LCeq','Sound limiter','dB(C) - dB(A)','Sound Levels and Laser Ordinance','DIN 15905-5']::text[],ARRAY['Assuming the 102 dB(A) and 118 dB(C) figures are a universal world standard rather than specifically the French Code de la sante publique limits.','Thinking only the A-weighted limit matters; the separate C-weighted cap exists to control bass energy that A-weighting under-counts.','UNSAFE: Believing that staying under the venue limit means the audience is safe from hearing damage; 102 dB LAeq for 15 minutes is still a large dose, so hearing protection and quieter rest areas remain important.']::text[],ARRAY['A Paris nightclub manager sets the house limiter and logging so the loudest audience spot stays within the code''s LAeq and LCeq caps.','A festival producer in France applies for authorisation and must show measurement records and rest-area provision to the local authority.','A children''s holiday cinema screening is planned, so staff apply the lower 94 dB(A) / 104 dB(C) caps for young audiences.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Code de la sante publique');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '513e7e3a-9092-5922-8526-b99e7bf5f4b7','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='513e7e3a-9092-5922-8526-b99e7bf5f4b7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='513e7e3a-9092-5922-8526-b99e7bf5f4b7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'db927d4f-d4ad-5cc3-8af5-3d7382fb020a','Sound Levels and Laser Ordinance','The Swiss Sound and Laser Ordinance (Verordnung ueber den Schutz des Publikums von Veranstaltungen vor gesundheitsgefaehrdenden Schalleinwirkungen und Laserstrahlen, V-NISSG / the former SLV) is federal law protecting audiences at events from hazardous sound and laser exposure. It scales duties to loudness measured as the A-weighted equivalent level over one hour (LAeq,1h): quieter events sit below a notification threshold, while events above roughly 93 dB(A) LAeq,1h trigger advance notification and audience information, and louder or longer events add duties such as offering hearing protection, providing a quieter recovery zone (for example LAeq,1h at or below about 85 dB(A)), and continuous logging (LAeq typically recorded every five minutes with retention). An overall ceiling of 100 dB(A) LAeq,1h applies, and the momentary A-weighted maximum LAFmax of 125 dB(A) must never be exceeded. Category boundaries, exact thresholds, and duties are set by the ordinance and its annex and are periodically revised.','This is Switzerland''s law protecting event crowds from loud sound and lasers. It sorts events by how loud they are over one hour. Louder events carry more duties for the organiser. Above about 93 dB(A) over an hour, you must notify authorities and inform the audience. Very loud or long events must offer earplugs and a quiet zone. The hourly average may not go above 100 dB(A). No single peak may ever pass 125 dB(A). Organisers must log the sound levels and keep the records. The exact steps depend on the event category. This is general information, not legal advice.','It exists to prevent audience hearing damage and eye injury at concerts, clubs, and festivals by tying escalating protective duties to the actual measured sound dose. Using a one-hour LAeq plus a hard momentary cap addresses both cumulative energy exposure and single dangerous transients.','A Swiss event''s audio engineer measures and logs LAeq,1h, keeps the hourly average within 100 dB(A) and every instant under the 125 dB(A) LAFmax cap, files the required notification, and for loud events supplies free earplugs and a designated quieter recovery area. Authorities can inspect the stored logs.','Sound Law — Standards, Laws & Instruments',ARRAY['LAeq','LAFmax','Code de la sante publique','DIN 15905-5','Sound limiter','Hearing protection']::text[],ARRAY['Treating the ordinance as only about lasers; the sound-level duties for amplified events are a central part of it.','Assuming the 100 dB(A) hourly limit and 125 dB(A) momentary cap are global rules rather than the specific Swiss thresholds.','UNSAFE: Thinking that because an event stays at the 100 dB(A) hourly ceiling no protection is needed; that dose can still harm hearing, so the ordinance requires earplugs and quiet recovery zones for loud events.']::text[],ARRAY['A Zurich club running a five-hour DJ set logs LAeq every five minutes and provides a quieter chill-out room.','A Swiss festival organiser notifies the cantonal authority because expected levels exceed the 93 dB(A) LAeq,1h threshold.','A touring engineer new to Switzerland reconfigures the system limiter to respect the 125 dB(A) LAFmax momentary cap.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound Levels and Laser Ordinance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'db927d4f-d4ad-5cc3-8af5-3d7382fb020a','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='db927d4f-d4ad-5cc3-8af5-3d7382fb020a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='db927d4f-d4ad-5cc3-8af5-3d7382fb020a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c157557f-ecf4-5bcc-aabb-f53dc502130b','DIN 15905-5','DIN 15905-5 is the German standard on entertainment technology and sound engineering titled, in effect, measures to prevent the risk of hearing damage to the audience from high sound exposure by electroacoustic sound systems. It defines how to measure and limit audience exposure at events using electroacoustic reinforcement, setting an A-weighted assessment-level reference value (Beurteilungspegel, LAr) of 99 dB(A) referenced to a 30-minute assessment period. The controlling measurement is taken at the location of highest expected exposure among the audience (the relevant assessment point), or at a defined substitute point when direct measurement there is impractical, with the substitute value corrected back to the audience position. It also addresses calibration, documentation, and responsibilities. DIN 15905-5 is a technical standard rather than a statute, but venue licences, local permits, and immission rules such as TA Larm often reference or require it; the 99 dB(A)/30-min value and procedures are periodically reviewed (current edition 2022-07).','DIN 15905-5 is a German standard to protect concert crowds'' hearing. It applies where speakers and amplifiers reinforce the sound. It says how to measure the loudness for the audience. The main reference level is 99 dB(A) averaged over 30 minutes. You measure at the loudest spot the audience can reach. If that spot is hard to measure, you use a set substitute point. You then correct that reading back to the audience position. The standard also covers calibration and record keeping. It is a technical rule, but permits and licences often require it. Standards like this are updated over time.','It exists to give event operators a repeatable, defensible method for keeping audience sound exposure below a hearing-risk threshold, so that a subjective loud show becomes an objective, documentable measurement. Anchoring the limit to the loudest audience position and a 30-minute average targets the people actually most at risk.','A German show''s system engineer positions a measurement microphone at the defined assessment point (or a corrected substitute), monitors the running 30-minute LAr, and keeps it at or below 99 dB(A), archiving the measurement record as proof for the venue or authority. Local licences frequently make this measurement mandatory.','Sound Law — Standards, Laws & Instruments',ARRAY['LAeq','TA Larm','Code de la sante publique','Sound Levels and Laser Ordinance','Sound limiter','Sound level meter']::text[],ARRAY['Thinking DIN 15905-5 caps the level at the mixing desk; the controlling point is the loudest audience position, not front-of-house.','Confusing the 30-minute assessment level with an instantaneous peak; it is an energy average over half an hour.','UNSAFE: Assuming 99 dB(A) over 30 minutes is comfortably safe for everyone; it is a management threshold, not a guarantee, so audiences and crew still benefit from hearing protection.']::text[],ARRAY['A German festival stage manager sets a calibrated meter at the audience assessment point to hold the 30-minute LAr at or under 99 dB(A).','A club whose licence cites DIN 15905-5 must archive nightly measurement records for possible inspection.','A touring engineer uses a corrected substitute measurement point because the true loudest audience spot is inaccessible during the show.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='DIN 15905-5');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c157557f-ecf4-5bcc-aabb-f53dc502130b','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c157557f-ecf4-5bcc-aabb-f53dc502130b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c157557f-ecf4-5bcc-aabb-f53dc502130b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '30d9f0ee-6066-5d86-ba86-09899a018e68','TA Larm','TA Larm (Technische Anleitung zum Schutz gegen Larm) is the Sixth General Administrative Regulation issued under Germany''s Federal Immission Control Act (BImSchG). It is the binding technical instruction for assessing and controlling noise immissions from installations and commercial/industrial activities (Anlagen), including many venues and event sites. It sets immission reference values (Immissionsrichtwerte) at the nearest affected dwelling that vary by land-use zone and by day/night period, for example, in general residential areas about 55 dB(A) by day and 40 dB(A) at night, in mixed-use areas about 60/45 dB(A), and lower in purely residential areas (about 50/35 dB(A)); it also specifies measurement, assessment (including surcharges for tonal or impulsive character), and how short-term maxima are treated. Because TA Larm implements the BImSchG, its values are used by authorities in permitting and enforcement. Zone values, night hours, and assessment methods are defined in the instruction and are periodically revised.','TA Larm is Germany''s technical rule for controlling noise from businesses and installations. It sits under the federal clean-air and noise law, the BImSchG. It sets noise limits at the nearest home that is affected. The limits change with the type of area and the time of day. A general housing area is about 55 dB(A) by day. At night it drops to about 40 dB(A). Quieter zones have stricter limits, busier zones looser ones. The rule also says how to measure and add penalties for tonal or impulsive noise. Officials use these values when granting permits and enforcing them. The limits are set in the rule and are updated over time.','It exists to give authorities a uniform, legally grounded way to judge whether noise from a commercial or industrial source unreasonably burdens neighbours, protecting residents while giving operators predictable, defensible limits. Zone- and time-based values plus tonal/impulse surcharges translate a general nuisance principle into measurable engineering criteria.','An acoustic consultant assessing a new club, beer garden, or plant predicts or measures the level at the nearest residence, applies any tonal or impulse penalty, and compares it to the relevant TA Larm day/night value to advise whether the permit can be granted or conditions (hours, limiter settings, screening) are needed. Enforcement officers use the same values in complaint cases.','Sound Law — Standards, Laws & Instruments',ARRAY['BImSchG','DIN 15905-5','LAeq','Immission reference value','Environmental Quality Standards for Noise','Rating level']::text[],ARRAY['Assuming TA Larm limits are measured at the noise source or property line of the venue, when they apply at the nearest affected dwelling.','Treating the daytime value as applying all night; night-time limits are far stricter and drive most disputes.','Thinking the reference value is compared to the raw measured level, ignoring the required surcharges for tonal and impulsive noise.']::text[],ARRAY['A German city licensing office assesses a proposed open-air bar against TA Larm night values for the adjoining residential street.','An acoustic consultant recommends limiter settings and a closing time so a live-music venue meets the 40 dB(A) night value at nearby flats.','An enforcement officer investigating a neighbour complaint measures at the affected dwelling and applies an impulse surcharge before comparing to the TA Larm value.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='TA Larm');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '30d9f0ee-6066-5d86-ba86-09899a018e68','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='30d9f0ee-6066-5d86-ba86-09899a018e68') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='30d9f0ee-6066-5d86-ba86-09899a018e68');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '33df1d2b-4544-5973-b264-a06255ae3c61','BImSchG','The BImSchG (Bundes-Immissionsschutzgesetz, Federal Immission Control Act) is the German federal statute that protects people, animals, plants, soil, water, the atmosphere, and property from harmful environmental effects (schadliche Umwelteinwirkungen) caused by air pollution, noise, vibration, light, heat, radiation, and similar immissions. It is the framework law under which installations requiring a permit are licensed and operated, imposing duties to avoid and minimise harmful effects using the state of technology. For noise, the Act does not itself list numeric limits; instead it authorises implementing instruments such as the administrative regulation TA Larm and ordinances (for example the Sports Facility Noise Ordinance and the equipment/machinery noise ordinance) that set the operative reference values and procedures. Because it is a framework act, the practical noise limits a venue or plant must meet are found in the instruments made under it, and both the Act and those instruments are periodically amended.','The BImSchG is Germany''s federal law against harmful environmental effects. It covers air pollution, noise, vibration, light, heat, and radiation. Its job is to protect people and the environment from these effects. It is the main law for permitting and running polluting or noisy installations. The law itself does not list noise numbers in decibels. Instead it lets other rules set the actual limits. TA Larm is the main noise rule made under it. So a venue''s real noise limit sits in those lower rules. The Act and its rules are updated over time. This is general information, not legal advice.','It exists to provide a single federal legal basis for preventing and reducing environmental immissions, including noise, and for licensing installations, so that protection is consistent nationwide rather than left to ad hoc local rules. As a framework, it delegates the detailed, technically specific limits to ordinances and administrative regulations that can be updated as technology changes.','A developer or operator planning a permit-requiring facility (and, indirectly, many event and entertainment operations) works within the BImSchG''s duties and relies on its implementing instruments, chiefly TA Larm, to know the noise levels that must be met at neighbouring receivers; lawyers and consultants cite the Act as the statutory hook when advising on or challenging a permit condition.','Sound Law — Standards, Laws & Instruments',ARRAY['TA Larm','Immission reference value','DIN 15905-5','Environmental Noise Regulations','Noise Regulation Law','Rating level']::text[],ARRAY['Expecting the BImSchG to state decibel limits itself; the numbers live in its implementing regulations like TA Larm.','Assuming it only concerns air pollution; noise, vibration, light, and other immissions are equally within its scope.','Thinking it applies only to heavy industry; it underpins noise permitting and enforcement for many everyday commercial and event sources.']::text[],ARRAY['A German environmental lawyer cites the BImSchG as the statutory basis when a neighbour challenges a venue''s operating permit over noise.','A plant operator''s permit application is assessed under the BImSchG, with noise judged via TA Larm at nearby homes.','A touring production company in Germany learns that the decibel limits it must meet come from ordinances made under the BImSchG, not the Act directly.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='BImSchG');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '33df1d2b-4544-5973-b264-a06255ae3c61','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='33df1d2b-4544-5973-b264-a06255ae3c61') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='33df1d2b-4544-5973-b264-a06255ae3c61');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c4edff6e-0e84-5432-be98-d2ae50e04029','WHS exposure standard for noise','In Australia the exposure standard for noise is the legal exposure limit defined in the model Work Health and Safety (WHS) Regulations (regulation 56), consisting of two parts: an eight-hour equivalent continuous A-weighted level LAeq,8h of 85 dB(A), and a C-weighted peak level LC,peak of 140 dB(C). A worker''s noise exposure at the workplace must not exceed either. The LAeq,8h part uses a 3 dB exchange rate, meaning each 3 dB increase halves the permitted duration (85 dB(A) for 8 hours, 88 dB(A) for 4 hours, and so on), addressing gradual noise-induced hearing loss; the 140 dB(C) peak part addresses instantaneous damage from impulses such as gunshots or pyrotechnics. The standard is a ceiling that duty holders must not exceed, not a safe target, and it is implemented across the states and territories that have adopted the model WHS laws, with Victoria operating a comparable OHS regime; the values and code of practice are periodically reviewed.','This is Australia''s legal noise exposure limit for workers. It has two parts you must not pass. The first is 85 dB(A) averaged over an 8-hour day. The second is a peak of 140 dB(C) for sudden bangs. Every 3 dB louder halves the safe time. So 88 dB(A) is allowed for only 4 hours. The average limit targets slow hearing loss over years. The peak limit targets instant damage from things like pyrotechnics. This is a ceiling, not a safe goal. It applies in states that adopted the model WHS laws. The numbers are reviewed over time.','It exists to set an enforceable upper boundary on workplace noise so employers must control exposure and prevent noise-induced hearing loss and acoustic trauma. Splitting the standard into an averaged dose and a peak captures the two distinct injury mechanisms: cumulative energy over a shift and single dangerous transients.','A workplace (including live-sound and event crews) uses noise measurements or dosimetry to check whether crew exposure exceeds 85 dB(A) LAeq,8h or 140 dB(C) peak; if it does, the PCBU must apply controls, provide hearing protection, and arrange audiometric testing. Consultants cite the standard when writing noise-management plans and control recommendations.','Sound Law — Standards, Laws & Instruments',ARRAY['PCBU','AS/NZS 1269','Exchange rate','LC,peak','LAeq','Liquor licence noise condition']::text[],ARRAY['UNSAFE: Treating 85 dB(A) LAeq,8h as a safe level rather than a legal ceiling; it is an upper limit, and control and hearing protection are still needed as exposure approaches it.','UNSAFE: Ignoring the 140 dB(C) peak limit because the 8-hour average looks fine; a single impulse like a pyrotechnic or gunshot can cause instant permanent damage on its own.','Assuming Australia uses the same numbers or exchange rate as OSHA in the US; OSHA''s permissible level and 5 dB exchange rate differ from the Australian 85 dB(A) / 3 dB approach.']::text[],ARRAY['An event production company measures front-of-house crew exposure over a festival day to check it against the 85 dB(A) LAeq,8h standard.','A pyrotechnics operator confirms crew are protected because firing produces peaks approaching or exceeding 140 dB(C).','A workplace safety inspector reviews a factory''s dosimetry results and audiometric records against the WHS exposure standard.']::text[],'intermediate','LAeq,8h <= 85 dB(A) and LC,peak <= 140 dB(C); T = 8 h / 2^((LAeq - 85)/3)','A worker''s exposure must keep the eight-hour equivalent A-weighted level at or below 85 decibels A-weighted and the C-weighted peak at or below 140 decibels C-weighted; with a 3 decibel exchange rate, the permitted time equals eight hours divided by two raised to the power of the level minus 85, all over 3.','285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='WHS exposure standard for noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c4edff6e-0e84-5432-be98-d2ae50e04029','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c4edff6e-0e84-5432-be98-d2ae50e04029') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c4edff6e-0e84-5432-be98-d2ae50e04029');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '983ffd50-409e-5d62-afb2-c3d36fc06d96','AS/NZS 1269','AS/NZS 1269 is the joint Australian/New Zealand standard series on occupational noise management, providing the recognised methodology behind workplace noise control and hearing conservation. It is published in parts: Part 0 gives an overview and management framework; Part 1 covers measurement and assessment of noise emission and exposure; Part 2 covers noise control and hearing conservation programs; Part 3 covers the hearing protector program (selection, fit, use, and attenuation/derating of protectors); and Part 4 covers auditory warning signals. The series supports compliance with the WHS exposure standard (LAeq,8h 85 dB(A) and LC,peak 140 dB(C)) by standardising how exposure is measured, how controls are prioritised, and how hearing protectors are chosen and their real-world attenuation estimated. It is a technical standard, not legislation, but WHS codes of practice reference it; editions and referenced methods are periodically revised.','AS/NZS 1269 is the Australian and New Zealand standard for managing workplace noise. It comes in several parts. One part is an overview and plan. One part covers how to measure noise and exposure. One part covers noise control and hearing programs. One part covers choosing and fitting hearing protectors. One part covers audible warning signals. Together they show how to meet the legal noise limits. They set out how to measure exposure the same way each time. They also show how to pick earplugs and estimate real protection. It is a technical standard, not a law itself. Safety codes point to it, and it is updated over time.','It exists to give employers, consultants, and hygienists a consistent, defensible method for assessing and controlling occupational noise, so that compliance with the legal exposure standard rests on repeatable measurement and proven control and protection practices rather than guesswork. Standardising hearing-protector selection and derating is central to actually reducing exposure at the ear.','An occupational hygienist follows AS/NZS 1269.1 to measure and assess a workplace''s noise exposure, uses Part 2 to plan controls, and Part 3 to select hearing protectors and apply a derating so the protected level really falls below 85 dB(A); the results feed the site''s hearing-conservation program and WHS compliance record.','Sound Law — Standards, Laws & Instruments',ARRAY['WHS exposure standard for noise','PCBU','LAeq','Hearing protection','Exchange rate','Sound level meter']::text[],ARRAY['Thinking AS/NZS 1269 sets the legal exposure limit; the limit is in the WHS Regulations, and the standard provides the methods to assess and control against it.','UNSAFE: Assuming a hearing protector''s laboratory rating equals real workplace protection; Part 3 requires derating, and skipping it can leave workers over-exposed while believing they are safe.','Treating it as a single document rather than a multi-part series covering measurement, control, protectors, and warning signals.']::text[],ARRAY['A consultant measuring a manufacturing plant follows AS/NZS 1269.1 so the exposure result is comparable and defensible.','A safety manager selects and derates earplugs for a loud production floor using AS/NZS 1269.3.','An event company builds its hearing-conservation program around the AS/NZS 1269 series to support WHS compliance.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AS/NZS 1269');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '983ffd50-409e-5d62-afb2-c3d36fc06d96','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='983ffd50-409e-5d62-afb2-c3d36fc06d96') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='983ffd50-409e-5d62-afb2-c3d36fc06d96');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'af728c80-dacb-56fb-80ad-e7fed3b5651f','PCBU','PCBU stands for ''person conducting a business or undertaking'', the central duty-holder concept in Australia''s model Work Health and Safety (WHS) Act. A PCBU is the entity (commonly a company, but also a sole trader, partnership, association, or other body) that operates a business or undertaking, whether for profit or not. The PCBU carries the primary duty of care: it must ensure, so far as is reasonably practicable, the health and safety of its workers and of other people (such as visitors or the public) who may be affected by its work. For noise, this means identifying and controlling noise risks and keeping worker exposure within the exposure standard. Individual workers and volunteers are generally not PCBUs, and an individual acting purely as a private householder is excluded; the duty cannot be transferred or contracted out, and where several PCBUs share a matter each retains its duty. Definitions and duties come from the WHS Act as adopted in each jurisdiction.','PCBU means ''person conducting a business or undertaking''. It is the main duty holder in Australia''s work safety law. Usually it is a company, but it can be a sole trader or group. The PCBU holds the primary duty of care. It must keep its workers safe, so far as is reasonably practicable. It must also protect others affected by the work, like visitors. For noise, that means controlling loud exposure at work. A single worker or volunteer is usually not a PCBU. A private householder is not one either. The duty cannot be handed off to someone else. If duties overlap, each PCBU still keeps its own.','It exists to place the primary safety duty on whoever actually controls the business or undertaking, rather than only on a narrowly defined ''employer'', so the law reaches modern arrangements like contractors, labour hire, and gig work. Making the duty non-transferable ensures responsibility cannot be shifted away by contract.','On a live event or worksite, the PCBU (for example the production company or venue operator) is the party that must assess noise risks, provide and enforce hearing protection, keep exposure within the WHS standard, and arrange audiometric testing; regulators direct enforcement notices and prosecutions at the PCBU. Techs and officers identify who the PCBU is to know who owns each safety obligation.','Sound Law — Standards, Laws & Instruments',ARRAY['WHS exposure standard for noise','AS/NZS 1269','Liquor licence noise condition','Hearing protection','Vibrancy Reforms','Duty of care']::text[],ARRAY['Equating PCBU exactly with ''employer''; a PCBU can exist without traditional employees, covering contractors and other arrangements.','Thinking a PCBU can transfer or contract its duty to a subcontractor; the primary duty cannot be handed off, though duties can be shared.','Assuming only one PCBU applies to a job; at a shared worksite multiple PCBUs can each hold overlapping duties at once.']::text[],ARRAY['A festival''s production company, as the PCBU, must ensure crew noise exposure stays within the WHS exposure standard.','A labour-hire firm and the host venue are both PCBUs for the same workers and must consult and coordinate on hearing safety.','A WHS regulator issues an improvement notice to the PCBU after finding stage crew exposed above 85 dB(A) without controls.']::text[],'beginner',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='PCBU');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'af728c80-dacb-56fb-80ad-e7fed3b5651f','285671a7-e448-4b2c-931f-1e5a43271820',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='af728c80-dacb-56fb-80ad-e7fed3b5651f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='af728c80-dacb-56fb-80ad-e7fed3b5651f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d9a9fdd-5d87-5c6c-a168-bc0515111483','Liquor licence noise condition','A liquor-licence noise condition is a noise- or sound-related term attached to a venue''s liquor licence, enforced through liquor-licensing law rather than (or as well as) planning or environmental law. In New South Wales, for example, sound from licensed venues is regulated by Liquor & Gaming NSW, and licences may carry conditions limiting disturbance to neighbours, with a defined disturbance-complaint process and thresholds. Such conditions can address matters like patron and amplified-music noise affecting nearby residences, and breaching them can trigger regulatory action against the licence. Following the NSW Vibrancy Reforms, many older development-consent style restrictions (fixed decibel caps, limiter requirements, genre or instrument bans) were switched off for licensed venues and entertainment sound was consolidated under the liquor-licensing regulator. The precise conditions, thresholds, and complaint procedures vary by jurisdiction, venue, and licence, and are periodically reformed.','This is a noise rule attached to a venue''s liquor licence. It is enforced through liquor-licensing law, not just planning law. In New South Wales, Liquor & Gaming NSW handles sound from licensed venues. A licence can carry conditions to limit disturbance to neighbours. There is a set process for handling disturbance complaints. Breaking a condition can put the licence at risk. Recent NSW reforms removed many old fixed limits from licensed venues. Entertainment sound was moved under the liquor regulator instead. The exact conditions and thresholds depend on the place and the licence. These rules are reformed from time to time.','It exists to manage the noise impact of licensed hospitality venues on surrounding residents through the licensing system, giving regulators a lever (the licence itself) to require quieter operation or impose conditions without needing separate planning action. Tying noise control to the licence links a venue''s ability to trade to how it manages disturbance.','A licensed venue operator checks the noise conditions on its liquor licence and the applicable disturbance-complaint process, and a sound engineer sets levels to avoid triggering a complaint or breaching a condition; if neighbours complain, the licensing regulator assesses the venue against those conditions and can impose or vary them. Compliance staff track which conditions still apply after reforms.','Sound Law — Standards, Laws & Instruments',ARRAY['Vibrancy Reforms','PCBU','WHS exposure standard for noise','Sound limiter','Disturbance complaint','Development consent condition']::text[],ARRAY['Assuming a liquor-licence noise condition is the same as a planning or environmental-noise limit; it is enforced through the licensing system and can differ.','Thinking every licensed venue still has a fixed decibel cap or mandatory limiter; NSW reforms switched many such conditions off for licensed venues.','Believing a single neighbour complaint automatically triggers action; jurisdictions set thresholds and complaint procedures that must be met first.']::text[],ARRAY['A Sydney live-music pub reviews which noise conditions remain on its liquor licence after the Vibrancy Reforms.','Neighbours lodge a disturbance complaint, and Liquor & Gaming NSW assesses the venue against its licence conditions.','A venue applying for a new liquor licence negotiates the noise conditions that will govern its late-night trading.']::text[],'beginner',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Liquor licence noise condition');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d9a9fdd-5d87-5c6c-a168-bc0515111483','285671a7-e448-4b2c-931f-1e5a43271820',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d9a9fdd-5d87-5c6c-a168-bc0515111483') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d9a9fdd-5d87-5c6c-a168-bc0515111483');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bd994a71-2c46-569f-9f18-6b19d7e1b228','Vibrancy Reforms','The Vibrancy Reforms are a package of New South Wales legislative and policy changes, with a significant tranche commencing 1 July 2024, intended to support the night-time economy and live music and entertainment. In relation to sound, they consolidated regulation of entertainment sound from licensed venues under Liquor & Gaming NSW and switched off many older restrictions previously imposed through development consents, such as fixed decibel-based limits, rules on when live or amplified music may be played, mandatory noise limiters, and conditions on speaker placement, as well as conditions banning particular genres, instruments, dancefloors, or numbers of performers. They also revised the disturbance-complaint process, including raising the threshold of complainants from different households and requiring complainants to first attempt resolution with the licensee. Noise management for unlicensed venues remained with local councils. The reforms are NSW-specific and continue to be developed, so current details should be checked against Liquor & Gaming NSW.','The Vibrancy Reforms are New South Wales changes to help nightlife and live music. A major part started on 1 July 2024. They moved sound rules for licensed venues under Liquor & Gaming NSW. They switched off many old planning restrictions on those venues. This included fixed decibel caps and required noise limiters. It also removed bans on certain genres, instruments, or dancefloors. The complaint process changed too. More households must now complain before action is taken. Complainants must first try to resolve it with the venue. Unlicensed venues stayed under local council rules. The reforms are specific to New South Wales.','They exist to reduce regulatory barriers that were seen to suppress live music and nightlife in NSW, by removing duplicative or outdated noise conditions and centralising entertainment-sound regulation in one body. Raising complaint thresholds and requiring prior resolution aim to balance venue viability against genuine, shared neighbour concerns.','A NSW venue operator or promoter uses the reforms to identify which historic development-consent noise conditions no longer apply and deals with Liquor & Gaming NSW as the single sound regulator; a compliance officer updates the venue''s conditions register and its response process for disturbance complaints accordingly.','Sound Law — Standards, Laws & Instruments',ARRAY['Liquor licence noise condition','Development consent condition','Disturbance complaint','Sound limiter','PCBU','WHS exposure standard for noise']::text[],ARRAY['Assuming the reforms removed all noise controls; they consolidated regulation and switched off specific conditions, but disturbance controls and other laws still apply.','Thinking they apply to unlicensed venues too; noise management for unlicensed venues stayed with local councils.','Treating them as national; the Vibrancy Reforms are specific to New South Wales.']::text[],ARRAY['A Newtown live-music venue confirms that its old development-consent decibel cap was switched off under the reforms.','A promoter checks the revised NSW disturbance-complaint threshold before booking a late-night amplified event.','A council officer clarifies that an unlicensed community-hall gig is still assessed under council noise rules, not the reforms.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vibrancy Reforms');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bd994a71-2c46-569f-9f18-6b19d7e1b228','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bd994a71-2c46-569f-9f18-6b19d7e1b228') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bd994a71-2c46-569f-9f18-6b19d7e1b228');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd488c4ab-f5fc-5cc3-a149-ec36a83e2ea5','Environmental Quality Standards for Noise','Japan''s Environmental Quality Standards for Noise are national administrative targets for ambient community noise set under the Basic Environment Law (Law No. 91 of 1993), established by Environment Agency notification and effective from 1 April 1999. They express desirable levels using the A-weighted equivalent continuous level LAeq for a daytime period (06:00-22:00) and a night-time period (22:00-06:00), differentiated by area classification: for example, category AA (areas needing particular quiet, such as around hospitals and welfare facilities) 50 dB day / 40 dB night; categories A and B (mainly residential) 55 dB day / 45 dB night; and category C (commercial/industrial with residences) 60 dB day / 50 dB night, with separate, higher values for areas facing roads. They are environmental target standards rather than direct penalty limits on individual sources (those are handled by the Noise Regulation Law), and prefectural governors classify the areas. The values, categories, and hours are set in the standard and may be revised.','These are Japan''s national targets for outdoor community noise. They sit under the Basic Environment Law and took effect in 1999. They use the average A-weighted level over day and night. Daytime runs from 6 a.m. to 10 p.m. Night runs from 10 p.m. to 6 a.m. The target depends on the type of area. Quiet areas near hospitals aim for 50 dB day and 40 dB night. Mainly residential areas aim for 55 dB day and 45 dB night. Commercial areas with homes aim for 60 dB day and 50 dB night. Areas beside busy roads have higher values. These are targets, not direct fines on one source. Local governors classify the areas.','They exist to define what ambient noise environment Japan aims to maintain to protect human health and living conditions, giving authorities a benchmark for policy, planning, and assessing whether an area''s soundscape is acceptable. Splitting by area type and day/night reflects that acceptable noise depends on land use and time.','A Japanese prefectural or municipal authority measures area LAeq and compares it against the standard for that area''s classification to judge whether the noise environment meets the target and whether action (traffic measures, planning controls) is needed; consultants use the values as the yardstick in environmental assessments.','Sound Law — Standards, Laws & Instruments',ARRAY['Noise Regulation Law','LAeq','TA Larm','Environmental Noise Regulations','Immission reference value','Lden']::text[],ARRAY['Treating the Environmental Quality Standards as enforceable limits on individual noise sources; direct source limits come from the Noise Regulation Law, while these are area targets.','Assuming one value applies everywhere; the target changes with area classification and with day versus night.','Confusing Japan''s LAeq-based ambient targets with Europe''s Lden long-term indicator; they use different time bases.']::text[],ARRAY['A Tokyo ward measures roadside LAeq to check it against the standard for that area classification.','An environmental consultant assessing a new development compares predicted ambient noise to the day and night targets.','A prefectural government reviews area classifications and whether local noise meets the AA quiet-zone targets near a hospital.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Environmental Quality Standards for Noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd488c4ab-f5fc-5cc3-a149-ec36a83e2ea5','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d488c4ab-f5fc-5cc3-a149-ec36a83e2ea5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d488c4ab-f5fc-5cc3-a149-ec36a83e2ea5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4ff9cdb0-e540-5238-abe7-9953ce145313','Noise Regulation Law','Japan''s Noise Regulation Law (Law No. 98 of 1968, as amended) is the national statute that controls noise from specific sources to preserve the living environment and protect health. It regulates ''specified factories/business establishments'' using designated noisy equipment (such as compressors, metal-working machines, and crushers), ''specified construction work'' involving designated machinery (such as pile drivers and rock drills), and motor-vehicle traffic noise (for which permissible limits link to road-traffic measures). Prefectural governors (and certain city mayors) designate the areas where controls apply and, within nationally set frameworks, fix permissible levels that vary by area type and by time of day, typically measured at the site boundary; construction work is also subject to hours and duration restrictions. It provides for notification of specified facilities and construction, plus improvement recommendations and orders. It complements the Environmental Quality Standards for Noise, which set ambient targets; the framework and area limits are periodically revised.','This is Japan''s national law controlling noise from set sources. It took effect in 1968 and has been amended. It covers noisy factories using listed machines. It also covers construction work with listed equipment. It covers motor-vehicle traffic noise as well. Local governors choose the areas where the controls apply. They set allowed noise levels for each area and time of day. Levels are usually measured at the site boundary. Construction work also has limits on hours and length. Operators must notify officials about covered facilities and work. Authorities can recommend or order improvements. It works alongside Japan''s ambient noise targets.','It exists to give authorities enforceable control over the main sources of community noise, factories, construction, and traffic, so that operators must limit emissions at the boundary and residents have a remedy. Delegating area designation and limit-setting to local government lets controls fit local land use while staying within a national framework.','A Japanese factory or construction contractor notifies the local authority about covered equipment or work, keeps boundary noise within the permissible level for the area and time, and observes construction hour limits; if levels are exceeded, the authority can issue improvement recommendations or orders. Consultants use the boundary limits when planning site noise controls.','Sound Law — Standards, Laws & Instruments',ARRAY['Environmental Quality Standards for Noise','TA Larm','BImSchG','Immission reference value','LAeq','Environmental Noise Regulations']::text[],ARRAY['Confusing the Noise Regulation Law with the Environmental Quality Standards; the Law sets enforceable source limits, while the standards are ambient targets.','Assuming national fixed limits; permissible levels and designated areas are set locally within the national framework and vary by place and time.','Thinking it measures at the receiver''s home; specified-source limits are typically assessed at the site boundary.']::text[],ARRAY['An Osaka contractor files construction notification and observes the boundary noise limit and permitted hours for the area.','A factory installing a listed compressor notifies the municipality and checks boundary levels against the area''s permissible value.','A local authority responds to a resident complaint by measuring at a factory boundary and issuing an improvement recommendation.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise Regulation Law');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4ff9cdb0-e540-5238-abe7-9953ce145313','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4ff9cdb0-e540-5238-abe7-9953ce145313') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4ff9cdb0-e540-5238-abe7-9953ce145313');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7afadef0-579f-5d2d-82ca-13f9296f6edd','Environmental Noise Regulations','The Environmental Noise Regulations are the national instruments by which an EU member state transposes the Environmental Noise Directive (2002/49/EC) into domestic law. In Ireland, the current instrument is the European Communities (Environmental Noise) Regulations 2018 (S.I. No. 549 of 2018, as amended by S.I. No. 663 of 2021), which revoked the earlier 2006 regulations. They require designated authorities to produce strategic noise maps for major roads, railways, airports, and large agglomerations using the harmonised long-term indicators Lden (day-evening-night level) and Lnight, and then to draw up noise action plans to manage and reduce noise and preserve quiet areas. The maps and action plans are reviewed and, where necessary, revised on a five-year cycle, with results reported to the European Commission; in Ireland the EPA is the national supervisory authority overseeing implementation. The directive provides a common assessment and management framework rather than fixed EU-wide limit values, so specific thresholds and duties depend on the member state and are periodically revised.','These regulations put the EU Environmental Noise Directive into a country''s own law. In Ireland the current version is from 2018. It replaced the older 2006 regulations. Authorities must make strategic noise maps of big noise sources. These cover major roads, railways, airports, and large towns. The maps use the common indicators Lden and Lnight. Authorities then write noise action plans to manage the noise. Maps and plans are reviewed every five years. The results are reported to the European Commission. In Ireland the EPA oversees the whole process. The directive sets a common method, not one EU-wide limit. Exact thresholds depend on the country.','They exist to create a consistent, comparable way of assessing and managing environmental noise across the EU, so that exposure is mapped with common indicators and reduced through action plans, while informing the public. The five-year cycle keeps the picture current and lets authorities track progress and protect quiet areas.','A national or local authority (and its acoustic consultants) uses the regulations to build strategic noise maps in Lden and Lnight, identify the most exposed populations, and prepare action plans; the maps and plans then guide traffic, planning, and mitigation decisions and are reported on the five-year cycle. Developers consult the mapping when assessing a site''s noise context.','Sound Law — Standards, Laws & Instruments',ARRAY['Lden','Lnight','Strategic noise map','Noise action plan','Environmental Quality Standards for Noise','TA Larm']::text[],ARRAY['Assuming the regulations set enforceable EU-wide decibel limits; the directive provides a mapping and action-planning framework, not fixed limit values.','Thinking noise maps cover every source; strategic mapping targets major roads, railways, airports, and large agglomerations above set thresholds.','Confusing Lden and Lnight with short-term event levels; they are long-term, annually averaged exposure indicators.']::text[],ARRAY['An Irish local authority prepares strategic noise maps for a major road corridor using Lden and Lnight.','A consultant drafts a noise action plan identifying quiet areas to preserve near a large agglomeration.','A developer reviews published END noise mapping to understand the existing noise exposure at a proposed housing site.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Environmental Noise Regulations');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7afadef0-579f-5d2d-82ca-13f9296f6edd','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7afadef0-579f-5d2d-82ca-13f9296f6edd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7afadef0-579f-5d2d-82ca-13f9296f6edd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ee17619-9540-5549-8bb4-b9eb6b15b2d4','ISO 1996','ISO 1996 is the international standard series ''Acoustics — Description, measurement and assessment of environmental noise'', maintained by ISO technical committee TC 43/SC 1. It provides the common technical framework that regulators and consultants use to describe outdoor community noise from sources such as road, rail, air traffic and industry, and to relate measured or predicted levels to expected community response. The series is currently issued in two parts: Part 1 (basic quantities and assessment procedures) and Part 2 (determination of sound pressure levels); an earlier Part 3 on application to noise limits was withdrawn. A key principle of the series is that it standardises how noise is characterised and assessed but does not itself set numeric limit values — permissible levels, averaging periods, receiver positions and penalty schemes are fixed by each jurisdiction''s laws, ordinances or licence conditions, which frequently reference ISO 1996 as the measurement/assessment method. Because it underpins many national regulations, exactly how its quantities are applied still varies by country, region, source type and time of day.','ISO 1996 is a global standard for outdoor noise. It covers noise from roads, trains, planes and industry. It says how to measure and describe such noise. It also links noise levels to how people react. The series has two parts today. Part 1 gives the basic measures and rules. Part 2 says how to find sound levels. An older Part 3 on limits was dropped. ISO 1996 does not set the actual limits itself. Each country sets its own limits in law. Many national rules point to ISO 1996 as the method. So the exact use still varies by place and time.','The series exists to give countries, courts and consultants one agreed, technically defensible vocabulary and procedure for environmental noise, so that assessments made in different places or by different people are comparable and reproducible. By separating the neutral technical framework (what to measure and how) from the political choice of limit values (left to each jurisdiction), it lets regulators write laws that simply reference the standard rather than re-inventing measurement methods, and it supports fair enforcement, planning decisions and dose–response estimates of community annoyance.','A noise consultant preparing a planning or environmental-impact assessment states that survey and rating-level calculations follow ISO 1996, then applies the local authority''s own limit values on top of that method. An enforcement officer or expert witness cites the series to justify why a measurement position, averaging time or tonal penalty was chosen, showing the assessment used a recognised international procedure rather than an ad-hoc one.','Sound Law — Standards, Laws & Instruments',ARRAY['ISO 1996-1','ISO 1996-2','Rating level (LR)','Day-evening-night level (Lden)','Environmental Noise Directive (2002/49/EC)','LAeq','Community response / annoyance']::text[],ARRAY['Assuming ISO 1996 sets the legal noise limits — it standardises description, measurement and assessment, while limit values are set by national or local law that may cite it.','Thinking it is a single document; it is a multi-part series (Part 1 and Part 2 current, former Part 3 withdrawn).','Confusing it with occupational noise standards; ISO 1996 concerns community/environmental noise and annoyance, not workplace hearing-damage exposure limits.','Treating a citation of ISO 1996 as proof of compliance by itself, when compliance depends on the specific limit and conditions in the governing regulation or permit.']::text[],ARRAY['A consultant scoping an environmental noise survey for a proposed wind farm states that the rating-level method follows ISO 1996.','A municipality drafting a noise ordinance references ISO 1996 as the measurement and assessment method, then inserts its own local limit values.','An expert witness in a nuisance case explains that the survey used the internationally recognised ISO 1996 procedure.','A transport authority modelling road-traffic noise for a new bypass adopts ISO 1996 quantities to estimate community exposure.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ISO 1996');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ee17619-9540-5549-8bb4-b9eb6b15b2d4','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ee17619-9540-5549-8bb4-b9eb6b15b2d4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ee17619-9540-5549-8bb4-b9eb6b15b2d4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7b22531f-49f1-59a6-9a19-27698a6f0f2d','ISO 1996-1','ISO 1996-1 is Part 1 of the ISO 1996 series, subtitled ''Basic quantities and assessment procedures'', with the current third edition being ISO 1996-1:2016 (which replaced ISO 1996-1:2003 and was confirmed in 2021). It defines the physical and rating quantities used to describe environmental noise and specifies procedures for assessing it. Central to the part is the concept of the rating level: an A-weighted equivalent continuous sound level to which adjustments (penalties) are added for the added annoyance of tonal, impulsive or, in some cases, low-frequency or specific-character sounds. It also defines long-term time-weighted descriptors — notably the day-evening-night level (Lden), which adds a penalty of about 5 dB to the evening period and about 10 dB to the night period to reflect greater sensitivity at those times — and provides a framework for predicting community response and annoyance from long-term exposure. Consistent with the whole series, Part 1 does not itself prescribe numeric limits; the size of adjustments actually applied, the reference time periods and any limit values depend on the governing national or local regulation.','ISO 1996-1 is Part 1 of the ISO 1996 series. It is called ''basic quantities and assessment procedures''. The current version is from 2016. It sets out the measures used to describe outdoor noise. A key idea is the rating level. This starts from an A-weighted average noise level. Then it adds a penalty for extra-annoying sounds. Tonal, banging or impulsive sounds get such a penalty. It also defines the day-evening-night level, called Lden. Lden adds about 5 dB to evening noise. It adds about 10 dB to night noise. This reflects that noise annoys more at night. Part 1 does not set the limits itself. The exact penalties and limits depend on local law.','Part 1 exists to fix a shared, reproducible way of turning raw sound measurements into an assessment that reflects how much noise actually annoys people. By formalising the rating level and its character adjustments, it lets an assessor account for the fact that two sounds of equal A-weighted level can differ greatly in nuisance value (for example a steady hum versus a tonal whine or a hammering). By defining Lden and time-of-day weighting, it gives regulators a single long-term indicator to attach limits to and to use in dose–response and mapping work.','An acoustic consultant computes a rating level for an industrial site by measuring the A-weighted equivalent level at the receiver and then adding the tonal or impulsive adjustment defined in Part 1, before comparing the result against the local authority''s limit. Strategic noise mappers and planners use the Part 1 Lden and night indicators as the exposure metric on which regulatory limit checks, façade assessments and annoyance estimates are based.','Sound Law — Standards, Laws & Instruments',ARRAY['ISO 1996','ISO 1996-2','Rating level (LR)','Day-evening-night level (Lden)','Tonal / impulsive adjustment (penalty)','LAeq','Environmental Noise Directive (2002/49/EC)']::text[],ARRAY['Reporting a plain LAeq as if it were the rating level; the rating level requires adding the tonal, impulsive or other character adjustments defined in Part 1.','Assuming the evening and night penalties (about +5 dB and +10 dB in Lden) are fixed limits rather than weightings applied before comparison with a jurisdiction''s limit.','Believing ISO 1996-1 sets legal limit values — it defines the quantities and assessment method, while limits come from national or local regulation.','UNSAFE: Treating an ISO 1996-1 environmental assessment as a hearing-safety check; community-annoyance rating levels are not occupational exposure limits and do not certify a place safe for prolonged loud-noise exposure.']::text[],ARRAY['A consultant adds a tonal penalty from ISO 1996-1 to a factory''s measured level before comparing it with the town''s night-time noise limit.','A national mapping agency computes Lden values under ISO 1996-1 to produce strategic noise maps for a large city.','An enforcement officer explains in a report why an impulsive-noise adjustment was applied to a complaint measurement.','A planner assessing a new logistics depot uses the ISO 1996-1 rating-level procedure to predict community annoyance.']::text[],'advanced',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ISO 1996-1');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7b22531f-49f1-59a6-9a19-27698a6f0f2d','285671a7-e448-4b2c-931f-1e5a43271820',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7b22531f-49f1-59a6-9a19-27698a6f0f2d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7b22531f-49f1-59a6-9a19-27698a6f0f2d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9c803fda-d844-545f-a701-0a8bcea2dd69','ISO 1996-2','ISO 1996-2 is Part 2 of the ISO 1996 series, subtitled ''Determination of sound pressure levels'', with the current edition ISO 1996-2:2017. Whereas Part 1 defines the quantities and assessment framework, Part 2 specifies how the sound pressure levels feeding that assessment are actually obtained — chiefly by measurement in the field, with provisions for extending results by calculation. It describes instrumentation requirements (sound level meters and calibrators to the relevant IEC standards), microphone positioning and measurement conditions, the influence of the source, ground and propagation path, and — importantly — the effect of meteorological conditions such as wind and temperature gradients on outdoor sound. A distinctive feature is its detailed treatment of measurement uncertainty, giving methods to estimate and report the uncertainty budget so that a measured environmental noise level can be compared meaningfully against a regulatory limit. The precise measurement positions, valid weather windows and how uncertainty is handled in a compliance decision still depend on the governing regulation, guidance or licence.','ISO 1996-2 is Part 2 of the ISO 1996 series. It is called ''determination of sound pressure levels''. Part 1 defines the measures to use. Part 2 says how to get the actual sound levels. Most of these levels come from field measurement. Some can be extended by calculation. It sets rules for meters and calibrators. It covers where to place the microphone. It covers the source, ground and sound path. It also covers weather effects like wind. Wind and temperature can bend outdoor sound. A key part is measurement uncertainty. It shows how to estimate and report that uncertainty. This lets a level be compared fairly with a limit. The exact positions and weather rules depend on local law.','Part 2 exists to make environmental noise measurements repeatable, defensible and comparable by pinning down the practical details that most affect the answer: what instruments to use, where and when to measure, how weather bends outdoor sound, and how much confidence to place in the number. Its uncertainty methodology is central to fair enforcement — it lets an assessor state a level together with its margin of error, so a regulator or court can judge whether a limit is genuinely exceeded rather than acting on a single unqualified figure.','A compliance officer measuring a factory or wind-farm noise level follows Part 2 to choose microphone positions, reject data taken in unsuitable wind conditions, and calculate an uncertainty budget, then reports the level with its uncertainty against the site''s permit limit. Expert witnesses and consultants rely on the Part 2 procedure to show a measurement was made under valid, standardised conditions if the result is challenged.','Sound Law — Standards, Laws & Instruments',ARRAY['ISO 1996','ISO 1996-1','Measurement uncertainty','IEC 61672 (sound level meters)','IEC 60942 (sound calibrators)','LAeq','Meteorological conditions / propagation']::text[],ARRAY['Assuming any reading taken with a good meter is valid; Part 2 requires suitable meteorological conditions and defined positions, and results taken in strong wind or unfavourable gradients may be invalid.','Ignoring measurement uncertainty and reporting a bare number, when Part 2 expects the level to be stated with its uncertainty for a fair comparison with a limit.','Confusing Part 2 with Part 1; Part 2 determines the sound pressure levels, while Part 1 defines the quantities and assessment procedures.','Believing Part 2 sets the pass/fail limit — it standardises how the level is determined, but the limit and how uncertainty is applied come from the governing regulation.']::text[],ARRAY['A consultant measuring wind-farm noise follows ISO 1996-2 to reject data collected during high winds and to compute an uncertainty budget.','An environmental-health officer positions the microphone and records weather data per ISO 1996-2 before assessing an industrial complaint.','An expert witness defends a noise measurement by showing it met the ISO 1996-2 conditions for instruments, positions and weather.','A permit review requires the applicant''s baseline survey to determine levels using the ISO 1996-2 method with stated uncertainty.']::text[],'advanced',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ISO 1996-2');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9c803fda-d844-545f-a701-0a8bcea2dd69','285671a7-e448-4b2c-931f-1e5a43271820',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9c803fda-d844-545f-a701-0a8bcea2dd69') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9c803fda-d844-545f-a701-0a8bcea2dd69');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c9a565e0-a8d0-5656-858a-70f8ebeb2c62','ISO 12913','ISO 12913 is the international standard series ''Acoustics — Soundscape'', which formalises the soundscape approach: assessing an outdoor acoustic environment by how people perceive, experience and understand it in context, rather than by sound level alone. Part 1 (ISO 12913-1:2014) provides the definition and conceptual framework, defining a soundscape as the ''acoustic environment as perceived or experienced and/or understood by a person or people, in context'', and distinguishing it from the physical ''acoustic environment'' (the sound at the receiver from all sources as modified by the environment). Two further parts, published as Technical Specifications, standardise method: ISO/TS 12913-2:2018 covers data collection and reporting requirements (for example questionnaires, soundwalks and binaural measurement protocols), and ISO/TS 12913-3:2019 covers data analysis (including the perceptual dimensions often summarised as pleasantness and eventfulness). The series complements level-based standards such as ISO 1996 by adding perceptual and contextual assessment, and it informs planning, design and management rather than setting numeric limits.','ISO 12913 is a global standard series on soundscape. A soundscape is how people hear a place in context. It is not judged by loudness alone. Part 1 came out in 2014. It gives the definition and the framework. It defines a soundscape as the acoustic environment as people perceive it. The acoustic environment is the physical sound itself. The soundscape is how people experience that sound. Two more parts set out the method. Part 2, from 2018, covers how to collect data. This includes surveys, soundwalks and recordings. Part 3, from 2019, covers how to analyse the data. The series adds human perception to plain level measures. It guides planning and design, not legal limits.','The series exists because sound level metrics alone do not capture whether a place sounds good or bad to the people in it; a quiet street can feel unpleasant and a lively square pleasant. ISO 12913 gives researchers, planners and designers a shared definition and repeatable methods to gather and analyse people''s perceptual responses, so that soundscape quality can be studied, compared and designed for. It reframes noise management from only reducing decibels toward shaping acoustic environments that support the intended use of a space.','An urban planner or acoustician designing a park or public square uses ISO 12913 to run soundwalks and questionnaires (Part 2) and to analyse the results along perceptual dimensions (Part 3), informing choices such as adding water features or masking traffic rather than only chasing a lower level. Consultants cite the series to justify a perception-based assessment alongside a conventional ISO 1996 level survey in a planning submission.','Sound Law — Standards, Laws & Instruments',ARRAY['ISO 1996','Acoustic environment','Soundwalk','Binaural measurement','Environmental Noise Directive (2002/49/EC)','Community response / annoyance','LAeq']::text[],ARRAY['Equating soundscape with noise level; ISO 12913 defines soundscape as the perceived acoustic environment in context, not simply how many decibels are present.','Assuming lower level always means a better soundscape, when the series recognises that pleasantness depends on source type, context and expectation, not loudness alone.','Thinking ISO 12913 sets noise limits or replaces ISO 1996; it adds perceptual assessment methods and does not prescribe limit values.','Overlooking that Parts 2 and 3 are Technical Specifications giving data-collection and analysis methods, not just conceptual guidance.']::text[],ARRAY['A city landscape team runs ISO 12913 soundwalks to evaluate how a redesigned plaza is perceived before and after adding a fountain.','A researcher collects binaural recordings and questionnaire responses under ISO/TS 12913-2 to study perception of a busy waterfront.','A planning consultant supplements a conventional level survey with an ISO 12913 soundscape assessment in an environmental statement.','A transport authority uses soundscape analysis to prioritise which quiet urban areas to protect beyond simple level thresholds.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ISO 12913');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c9a565e0-a8d0-5656-858a-70f8ebeb2c62','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c9a565e0-a8d0-5656-858a-70f8ebeb2c62') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c9a565e0-a8d0-5656-858a-70f8ebeb2c62');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6bed40a8-08bb-5636-b464-ba0bcc8d31c0','IEC 60942','IEC 60942 is the international standard ''Electroacoustics — Sound calibrators'', with the current fourth edition IEC 60942:2017. It specifies the performance requirements, tolerances and test methods for the acoustic calibrators used to check and adjust the sensitivity of measuring instruments such as sound level meters. It defines three performance classes — class LS (laboratory standard, the tightest), class 1 and class 2 — with a class 1 calibrator primarily intended for use with a class 1 sound level meter and a class 2 calibrator with a class 2 meter, matching the meter classes of IEC 61672-1; it also addresses pistonphone variants (class LS/M and class 1/M). A sound calibrator conforming to the standard produces a stable, known sound pressure level at a defined frequency — commonly 94 dB and/or 114 dB re 20 µPa at 1 kHz — so a technician can verify that a meter reads correctly before and after a survey. The standard is instrumentation-focused; how often a calibrator is periodically verified and how field checks are used in a compliance procedure are set by the relevant measurement standard, accreditation scheme or national guidance.','IEC 60942 is a global standard for sound calibrators. A sound calibrator is a small device you fit over a microphone. It makes a known, steady sound. This checks that a sound level meter reads correctly. The current edition is from 2017. It sets the performance rules and tests for these devices. It defines three classes: LS, class 1 and class 2. Class LS is the strictest, for the laboratory. A class 1 calibrator suits a class 1 meter. A class 2 calibrator suits a class 2 meter. A typical calibrator gives 94 dB or 114 dB. It does this at a frequency of 1 kHz. Technicians use it before and after a survey. The standard covers the device, not how often you must check it.','The standard exists to make the reference sound calibrators traceable, accurate and interchangeable, so that a field check of a sound level meter actually means something. Because almost every legally significant noise measurement begins and ends with a calibrator check, IEC 60942 protects the integrity of the whole measurement chain: it ensures the known level applied to the microphone is within tight, defined tolerances, which lets a technician detect drift or faults and lets a regulator trust that a reported level is anchored to a verified reference.','A noise technician places an IEC 60942 calibrator on the sound level meter''s microphone at the start and end of a survey, confirms the meter reads the expected level (for example 94 dB at 1 kHz), and records the check; a discrepancy beyond tolerance invalidates the intervening data. Laboratories and accredited calibration houses use higher-class (LS) calibrators as references and hold traceable calibration certificates for the calibrators themselves.','Sound Law — Standards, Laws & Instruments',ARRAY['IEC 61672 (sound level meters)','Field calibration check','ISO 1996-2','Traceability / metrology','Class 1 / Class 2 instrument','Pistonphone','Acoustic calibrator']::text[],ARRAY['Confusing a field calibration check with a full laboratory calibration; the on-site check verifies the meter against the calibrator, but both instruments still need periodic laboratory calibration and traceability.','Pairing instrument classes incorrectly; a class 1 meter should be checked with a class 1 (or LS) calibrator, not a lower-class class 2 device, for a class 1 result.','Assuming the calibrator''s output level is arbitrary; conforming calibrators produce defined levels such as 94 dB or 114 dB at 1 kHz within tight tolerances.','UNSAFE: Believing that because a meter is calibrated the measured place is therefore safe to be in; calibration only verifies the instrument''s accuracy and says nothing about whether the sound level is within a hearing-safe exposure limit.']::text[],ARRAY['A festival noise officer runs an IEC 60942 calibrator check on the logging meter before doors open and again after the show.','An accredited acoustics lab uses a class LS calibrator as its reference to verify field calibrators for touring technicians.','An occupational-hygiene technician documents a start-of-shift calibration check on a dosimeter to keep the day''s data legally defensible.','An enforcement officer''s measurement is challenged, and the calibration-check records to IEC 60942 are used to show the meter was reading correctly.']::text[],'intermediate',NULL,NULL,'285671a7-e448-4b2c-931f-1e5a43271820' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='IEC 60942');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6bed40a8-08bb-5636-b464-ba0bcc8d31c0','285671a7-e448-4b2c-931f-1e5a43271820',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6bed40a8-08bb-5636-b464-ba0bcc8d31c0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6bed40a8-08bb-5636-b464-ba0bcc8d31c0');
